std::size_t Engine::ActionPlayDynamicBytes() const noexcept {
    const auto column = []<class T>(const std::vector<T>& values) noexcept {
        return values.capacity() * sizeof(T);
    };
    std::size_t bytes = ordinarySingleVoiceBacking.RequestedBytes();
    for (const auto& storage : actionPlayStorage) {
        bytes += column(storage.variableControlRollbackEdges) + column(storage.pendingInitialVcRetirement) +
            column(storage.pendingInitialVcRows) + column(storage.retiredInitialVcArms) +
            column(storage.privateInitialVcLaneMembers) + column(storage.privateInitialVcLaneGroups) +
            column(storage.privateInitialVcArmPreparations) + storage.ownerLedger.StorageBytes() +
            column(storage.frontierServices) + storage.frontierQueues.StorageBytes() +
            column(storage.queueFutureAttempts) + column(storage.queueFutureOwners) + column(storage.frontierPolicies) +
            column(storage.initialControlSlices) + column(storage.initialFrontierSides) +
            column(storage.initialFrontierParticipants) + column(storage.nestedContinuousDecisions) +
            column(storage.nestedContinuousDecisionOwners) + column(storage.variableControlChildren) +
            column(storage.variableControlChildKinds) + column(storage.variableControlLeafChildren) +
            column(storage.variableControlContainerRows) + column(storage.variableControlNestedParentIndices) +
            column(storage.variableControlNestedPathOrdinals) + column(storage.variableControlNestedModes) +
            (storage.playableTreeExecutor ? storage.playableTreeExecutor->StorageBytes() : 0u);
    }
    for (const auto& scratch : actionPlayScratch) {
        bytes += scratch.voiceStarts.RequestedBytes() + scratch.queueSuccessorVoiceStarts.RequestedBytes() +
            column(scratch.pendingVariableReplacementControls) + column(scratch.pendingVariableReplacementGroups) +
            column(scratch.pendingVariableReplacementQueueLanes);
        if (scratch.initialQueueSignalAdmission != nullptr) {
            const auto& signal = *scratch.initialQueueSignalAdmission;
            bytes += sizeof(signal) + column(signal.members) + column(signal.cancellationArms) +
                column(signal.voices) + column(signal.owners) + column(signal.sources);
        }
        bytes += column(scratch.initialQueueEntryAdmissions);
        for (const auto& pointer : scratch.initialQueueEntryAdmissions) {
            if (pointer == nullptr) continue;
            const auto& native = *pointer;
            bytes += sizeof(native) + column(native.members) + column(native.cancellationArms) +
                column(native.voices) + column(native.owners) + column(native.sources);
        }
    }
    for (const auto& source : ordinaryRetiringSources)
        if (source.queueCurrent != nullptr) bytes += sizeof(*source.queueCurrent);
    for (const auto& scratch : actionQueueReplacementScratch) {
        bytes += column(scratch.successorMembers) + column(scratch.successorVoices) + column(scratch.successorLeaves) +
            column(scratch.successorStarts) + column(scratch.successorLeafOccurrences) +
            column(scratch.successorLeafCompletions) + column(scratch.successorStartFrames) +
            column(scratch.successorLeafEventCounts) + column(scratch.sourceRenderHandles) +
            column(scratch.sourceTargets) + column(scratch.sourceArms) + column(scratch.sourceCommands) +
            column(scratch.sourceLeafEventCounts) + column(scratch.replacementGroupArms);
    }
    for (const auto& row : playableServices) {
        bytes += row.FeatureArrayStorageBytes() + column(row.memberPrograms) + column(row.members) +
            (row.HasFeatureArrays() ? column(row.VariablePayload().variableControlRetargetMembers) +
                row.VariablePayload().variableControlMemberWeights.StorageBytes() : 0u) +
            row.variableControlInitialArms.StorageBytes() +
            (row.HasFeatureArrays() ? row.VariableControlRetargetIncoming().StorageBytes() : 0u) +
            column(row.variableControlControllers) + column(row.variableControlContainers) +
            (row.HasFeatureArrays() ?
                column(row.DiscreteRetargetStorage().groupArms) +
                column(row.DiscreteRetargetStorage().payloads) +
                column(row.DiscreteRetargetStorage().enteringPayloads) +
                column(row.DiscreteRetargetStorage().events) +
                column(row.DiscreteRetargetStorage().enteringEvents) +
                column(row.DiscreteRetargetStorage().runtimePrograms) +
                column(row.DiscreteRetargetStorage().enteringRuntimePrograms) +
                column(row.DiscreteRetargetStorage().schedules) +
                column(row.DiscreteRetargetStorage().enteringSchedules) : 0u);
    }
    return bytes + memberProgramRecords.RequestedBytes() +
        playableMemberRecords.RequestedBytes() + memberRelations.RequestedBytes() +
        variableControlRetargetPrograms.RequestedBytes();
}

std::size_t Engine::PendingSelectionStorageBytes() const noexcept {
    const auto column = []<class T>(const std::vector<T>& values) noexcept {
        return values.capacity() * sizeof(T);
    };
    auto bytes = pendingOrdinarySelections.RequestedBytes() + pendingOrdinarySelections.DirectoryBytes() +
        preparedPendingVariableGroups.RequestedBytes() + preparedPendingVariableGroups.DirectoryBytes() +
        acceptedPendingVariableGroups.RequestedBytes() +
        acceptedPendingVariableGroups.DirectoryBytes() + pendingVariableLeafSources.RequestedBytes() +
        pendingVariableFutureSources.RequestedBytes() + pendingVariableFutureNodes.RequestedBytes() +
        pendingVariableQueueNativeOrigins.RequestedBytes() + originalPlayableServiceLifetimeHolders.RequestedBytes() +
        PrivateImmediateEntryResultStorageBytes();
    for (const auto& ordinary : pendingOrdinarySelections) bytes += ordinary.nativeReplacement.RequestedBytes();
    const auto addGroups = [&](const auto& groups) noexcept {
        for (const auto& group : groups) {
            bytes += column(group.nestedInitialSides) + column(group.leafArms) + column(group.leafRetained) +
                column(group.leafRetirementReceipts) + column(group.queueNativeMembers) +
                column(group.boundAbort.queues) + column(group.topology_.nodes) + column(group.topology_.topNodes) +
                column(group.topology_.leafNodes) + column(group.topology_.leafTops) + group.reprepare_.StorageBytes() +
                column(group.nativeReplacementSlots) + column(group.queueRoleReservations);
            for (const auto& slot : group.nativeReplacementSlots) bytes += slot.side.RequestedBytes();
            for (const auto& slot : group.queueRoleReservations) {
                bytes += slot.directory.StorageBytes() + column(slot.controls) + column(slot.groups) + column(slot.lanes);
            }
            // Member payload stays charged to its native issuer, including prepared allowances.
            if (group.nativeRuntimeBacking) {
                const auto& backing = *group.nativeRuntimeBacking;
                bytes += sizeof(NativeRuntimeBacking) + backing.groups.DirectoryBytes() +
                    backing.laneGroups.DirectoryBytes() + column(backing.reprepareProducers) +
                    column(backing.selections) + column(backing.publicationProducers) +
                    column(backing.publicationChildren) + column(backing.publicationOwners) +
                    column(backing.rootMemberWeights) + column(backing.memberWeights) +
                    column(backing.rootInitialArms) + column(backing.initialArms);
                const auto addWeights = [&](const EngineVariableMemberWeights& weights) noexcept {
                    if (weights.storage.use_count() == 1) bytes += weights.MemberStorageBytes();
                    if (weights.childStorage.use_count() == 1) bytes += weights.ChildStorageBytes();
                };
                for (const auto& root : backing.rootMemberWeights) addWeights(root.weights);
                for (const auto& weights : backing.memberWeights) addWeights(weights);
                for (const auto& root : backing.rootInitialArms)
                    if (root.arms.storage.use_count() == 1) bytes += root.arms.StorageBytes();
                for (const auto& arms : backing.initialArms)
                    if (arms.storage.use_count() == 1) bytes += arms.StorageBytes();
            }
        }
    };
    addGroups(preparedPendingVariableGroups);
    addGroups(acceptedPendingVariableGroups);
    return bytes;
}

std::size_t Engine::CapturedVoiceStorageBytes() const noexcept {
    if (++capturedVoiceAccountingEpoch == 0) ++capturedVoiceAccountingEpoch;
    const auto charge = [&](const CapturedTimelineVoiceInstall& voice) noexcept {
        return voice.AllocationBytesForAccounting(capturedVoiceAccountingEpoch);
    };
    const auto sideBytes = [&](const auto& side) noexcept {
        std::size_t bytes = 0;
        for (const auto& capture : side.Captures()) bytes += charge(capture.voice);
        return bytes;
    };
    std::size_t bytes = 0;
    for (const auto& set : timelineProgramSets) {
        if (set != nullptr)
            for (const auto& occurrence : set->occurrences) bytes += charge(occurrence.voice);
    }
    for (const auto& service : playableServices) {
        bytes += charge(service.capturedVoice) +
            service.capturedScheduleVoices.capacity() * sizeof(CapturedTimelineVoiceInstall);
        if (service.HasFeatureArrays())
            bytes += charge(service.QueueRuntimeViews().canonicalInitialQueueTargetVoice);
        for (const auto& voice : service.capturedScheduleVoices) bytes += charge(voice);
    }
    for (const auto& member : playableMemberRecords) bytes += charge(member.voice);
    for (const auto& scratch : actionPlayScratch)
        bytes += sideBytes(scratch.voiceStarts) + sideBytes(scratch.queueSuccessorVoiceStarts);
    for (const auto& replacement : actionQueueReplacementScratch) {
        for (const auto& voice : replacement.successorVoices) bytes += charge(voice);
    }
    for (const auto& ordinary : pendingOrdinarySelections)
        bytes += charge(ordinary.replacementVoice) + sideBytes(ordinary.nativeReplacement);
    const auto groupBytes = [&](const auto& groups) noexcept {
        std::size_t result = 0;
        for (const auto& group : groups)
            for (const auto& slot : group.nativeReplacementSlots) result += sideBytes(slot.side);
        return result;
    };
    bytes += groupBytes(preparedPendingVariableGroups) + groupBytes(acceptedPendingVariableGroups);
    return bytes;
}

std::size_t Engine::PreparationStorageBytes() const noexcept {
    const auto column = [](const auto& storage) noexcept {
        return storage.capacity() * sizeof(typename std::decay_t<decltype(storage)>::value_type);
    };
    std::size_t bindingBytes = 0;
    for (const auto& pending : pendingStarts) bindingBytes += column(pending.preparedBindings);
    for (const auto& parked : parkRecords) bindingBytes += column(parked.preparedBindings);
    return ActionPlayStorageBytes() + ActionPlayDirectoryBytes() + ActionPlayDynamicBytes() +
        memberProgramRecords.DirectoryBytes() + playableMemberRecords.DirectoryBytes() + column(sourcePlayableMembers) +
        column(actionFiringPlanScratch) + column(actionStepPlanScratch) + column(actionVariableWriteScratch) +
        column(actionSelectionResetScratch) + column(actionFixedSelectionCommitInputs) + column(actionQueueResetScratch) +
        column(actionQueueCheckpointResetScratch) + column(actionPlayAttemptTokens) +
        column(initialPendingVariableOwnerScratch) +
        ImmediateEntryAttemptStorageBytes() + PendingSelectionStorageBytes() + CapturedVoiceStorageBytes() +
        queueProgramBanks.RequestedBytes() + queueProgramBanks.DirectoryBytes() +
        queueScheduleStorage.StorageBytes() + bindingBytes +
        timelineStartScratch.starts.RequestedBytes() + timelineStartScratch.transactions.RequestedBytes() +
        timelineStartScratch.extraCommands.RequestedBytes() + timelineStartScratch.queueEvents.RequestedBytes() +
        originalSourceSubmissions.StorageBytes() + originalSinglePreparationHolders.RequestedBytes() +
        originalSinglePreparationHolders.DirectoryBytes() + originalQueueSourcePreparationHolders.RequestedBytes() +
        originalQueueSourcePreparationHolders.DirectoryBytes();
}

