bool ReleaseUnpublishedSourceTerminal(
    harken::Engine& engine, harken::SourceTerminalToken& token) noexcept {
    if (!token.Valid()) return true;
    const auto* source = engine.sourceTerminals.Resolve(token);
    if (source == nullptr || !engine.voices.ReleaseObserved(source->release) ||
        !engine.playableInstances.ReleaseSourceRetirementHold(source->leaf)) return false;
    if (!engine.sourceTerminals.Release(token)) return false;
    token = {};
    return true;
}

