bool ValidatePreparedSelectionOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedSelectionOwnerContext*>(opaque);
    return context != nullptr && context->table != nullptr &&
           context->token != nullptr && context->token->Valid();
}

bool CommitPreparedSelectionOwner(void* opaque,
                                  std::uint64_t ticket) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedSelectionOwnerContext*>(opaque);
    if (context == nullptr || context->table == nullptr ||
        context->token == nullptr || !context->token->Valid()) {
        return true;
    }
    const bool committed =
        context->table->CommitPreparedPlayTransactional(
            context->token, ticket) == harken::SelectionMemoryStatusV1::Ok;
    context->committed = committed;
    return committed;
}

bool CancelPreparedSelectionOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedSelectionOwnerContext*>(opaque);
    if (context == nullptr || context->table == nullptr ||
        context->token == nullptr) {
        return true;
    }
    if (context->committed) {
        const bool rolledBack =
            context->table->RollbackCommittedPlay(context->token) ==
            harken::SelectionMemoryStatusV1::Ok;
        if (rolledBack) context->committed = false;
        return rolledBack;
    }
    if (!context->token->Valid()) {
        return true;
    }
    return context->table->CancelPreparedPlay(context->token) ==
           harken::SelectionMemoryStatusV1::Ok;
}

bool ValidatePreparedOccurrenceOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedOccurrenceOwnerContext*>(opaque);
    return context != nullptr && context->pool != nullptr &&
           context->token != nullptr && context->token->generation != 0 &&
           (context->prepared == nullptr || *context->prepared);
}

bool CommitPreparedOccurrenceOwner(void* opaque,
                                   std::uint64_t) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedOccurrenceOwnerContext*>(opaque);
    if (!ValidatePreparedOccurrenceOwner(context)) return false;
    if (!context->pool->CommitPreparedAcquire(*context->token)) return false;
    if (context->prepared != nullptr) *context->prepared = false;
    return true;
}

