harken::MonitorContentIdentity MonitorVariableControlContentFor(
    const harken::Engine& engine, const harken::EnginePlayableServiceRow& row,
    const harken::PlayableRefV1& content) noexcept {
    if (!row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0) {
        return MonitorContentFor(row.Invocation().packPlaybackView, content);
    }
    return MonitorContentFor(row.variableControlWorldUsesCurrentAuthority
        ? engine.variables.CurrentPlayableWorld() : row.VariableControlWorld(), content);
}

// Runtime-owned frontier materialization for every playback adapter.  The
// adapter supplies only its read-only authority view and authored ordinals;
// edge resolution, canonical identity, and instance topology are shared here.
template <typename AuthorityView, typename LoopLimitFn>
bool PrepareSharedPlayableFrontier(
    harken::Engine& engine, harken::PlayableTreeExecutor& executor,
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view, harken::PlayableRefV1 root,
    const std::uint32_t* selectedOrdinals, std::uint32_t selectedCount,
    harken::PlayableInstanceHandle rootInstance,
    std::uint64_t rootScheduleEpoch, LoopLimitFn&& loopLimitFor,
    std::uint32_t* outContainerCount = nullptr,
    harken::PlayableKind* outLastChildKind = nullptr) noexcept {
    if (rootInstance == 0 || rootScheduleEpoch == 0 ||
        selectedCount > harken::kSelectionPathNodeCapacity ||
        (selectedCount != 0 && selectedOrdinals == nullptr)) {
        return false;
    }
    std::array<harken::PlayableRefV1,
               harken::kSelectionPathNodeCapacity> containers{};
    std::array<const harken::ContainerProgramViewV3*,
               harken::kSelectionPathNodeCapacity> programs{};
    std::array<harken::PlayableKind,
               harken::kSelectionPathNodeCapacity> childKinds{};
    std::array<std::uint32_t,
               harken::kSelectionPathNodeCapacity> loopLimits{};
    std::array<harken::MonitorContentIdentity, harken::kSelectionPathNodeCapacity> childIdentities{};
    std::uint32_t containerCount = 0;
    harken::PlayableRefV1 current = root;
    for (std::uint32_t index = 0;
         index < selectedCount &&
         current.kind == harken::PlayableKindV1::Container; ++index) {
        if (containerCount >= containers.size()) return false;
        const harken::ContainerProgramViewV3* program = nullptr;
        const harken::ContainerChildProgramViewV2* child = nullptr;
        harken::PlayableRefV1 canonicalParent{};
        harken::PlayableRefV1 canonicalChild{};
        if (!ResolveSharedContainerChild(
                authority, view, current, selectedOrdinals[index], &program,
                &child, &canonicalParent, &canonicalChild) ||
            program == nullptr || child == nullptr) {
            return false;
        }
        if (child->playable.kind != harken::PlayableKindV1::Container &&
            child->playable.kind != harken::PlayableKindV1::Track &&
            child->playable.kind != harken::PlayableKindV1::Segment &&
            child->playable.kind != harken::PlayableKindV1::Sound) {
            return false;
        }
        containers[containerCount] = canonicalParent;
        childIdentities[containerCount] = MonitorContentFor(view, canonicalChild);
        programs[containerCount] = program;
        childKinds[containerCount] =
            child->playable.kind == harken::PlayableKindV1::Container
                ? harken::PlayableKind::Container
                : child->playable.kind == harken::PlayableKindV1::Track
                    ? harken::PlayableKind::Track
                    : child->playable.kind == harken::PlayableKindV1::Segment
                        ? harken::PlayableKind::Segment
                        : harken::PlayableKind::Sound;
        loopLimits[containerCount] =
            static_cast<std::uint32_t>(loopLimitFor(canonicalParent.stableId));
        if (outLastChildKind != nullptr) {
            *outLastChildKind = childKinds[containerCount];
        }
        ++containerCount;
        current = canonicalChild;
    }
    if (outContainerCount != nullptr) *outContainerCount = containerCount;
    ObservePreparedContent(engine, executor, rootInstance, MonitorContentFor(view, root));
    if (containerCount == 0) return true;
    return PrepareSharedPlayablePath(
        engine, executor, rootInstance, rootScheduleEpoch, containers,
        programs, childKinds, loopLimits, containerCount, childIdentities);
}

enum class ContainerTraversalMode : std::uint8_t {
    Selection,
    Queue,
    VariableControl,
};

enum class ContainerTraversalOwnership : std::uint8_t {
    DirectDelta,
    PreparedToken,
};

enum class ContainerTraversalStatus : std::uint8_t {
    Ok,
    UnknownProgram,
    UnsupportedMode,
    EmitterRequired,
    InvalidMemoryScope,
    SelectionFailed,
    ChildResolutionFailed,
};

struct ContainerTraversalRequest {
    std::uint64_t worldGeneration = 0;
    std::uint64_t worldSemanticFingerprint = 0;
    VnObjectId rootStableId{};
    VnEmitterHandle emitter = 0;
    std::uint64_t callerSeed = 0;
    std::uint64_t acceptedPostOrdinal = 0;
    std::uint32_t pathCount = 0;
    const harken::SelectionPathNodeV1* path = nullptr;
    std::uint32_t occurrenceOrdinal = 0;
    std::uint64_t ticket = 0;
    std::uint32_t eventIndex = 0;
    std::uint64_t executeFrame = 0;
    std::uint32_t loopIteration = 0;
    ContainerTraversalOwnership ownership =
        ContainerTraversalOwnership::DirectDelta;
    harken::SelectionDeltaRefV1* delta = nullptr;
    harken::PreparedSelectionPlayV1* prepared = nullptr;
    harken::EngineSelectionPreparation preparation{};
    std::uint32_t* materializedOrdinal = nullptr;
};

struct ContainerTraversalStep {
    ContainerTraversalMode mode = ContainerTraversalMode::Selection;
    ContainerTraversalStatus status = ContainerTraversalStatus::UnknownProgram;
    harken::SelectionMemoryStatusV1 selectionStatus =
        harken::SelectionMemoryStatusV1::InvalidInput;
    const harken::ContainerProgramViewV3* program = nullptr;
    const harken::ContainerChildProgramViewV2* child = nullptr;
    harken::PlayableRefV1 canonicalParent{};
    harken::PlayableRefV1 canonicalChild{};
    harken::SelectionPathNodeV1 pathNode{};
    std::uint32_t selectedChildOrdinal = 0;
};

harken::SelectionPathNodeV1 MakeContainerSelectionPathNode(
    VnObjectId containerStableId,
    std::uint32_t childOrdinal) noexcept {
    harken::SelectionPathNodeV1 out{};
    out.kind = harken::PlayableKindV1::Container;
    out.objectId = containerStableId;
    out.childOrdinal = childOrdinal;
    return out;
}

template <typename AuthorityView>
ContainerTraversalStep ClassifySharedContainerTraversalStep(
    harken::Engine& engine,
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view,
    const harken::PlayableRefV1& current) noexcept {
    ContainerTraversalStep out{};
    if (!ResolveSharedContainerProgram(
            authority, view, current, &out.program,
            &out.canonicalParent) || out.program == nullptr) {
        out.status = ContainerTraversalStatus::UnknownProgram;
        return out;
    }
    if (out.program->mode == harken::ContainerModeV1::VariableControl) {
        out.mode = ContainerTraversalMode::VariableControl;
        out.status = ContainerTraversalStatus::Ok;
        return out;
    }
    if (out.program->mode == harken::ContainerModeV1::SequenceQueue ||
        out.program->mode == harken::ContainerModeV1::RandomQueue) {
        out.mode = ContainerTraversalMode::Queue;
        out.status = ContainerTraversalStatus::Ok;
        return out;
    }
    if (out.program->mode != harken::ContainerModeV1::Random &&
        out.program->mode != harken::ContainerModeV1::Sequence) {
        out.status = ContainerTraversalStatus::UnsupportedMode;
        return out;
    }
    out.mode = ContainerTraversalMode::Selection;
    out.status = ContainerTraversalStatus::Ok;
    return out;
}

template <typename AuthorityView>
ContainerTraversalStep PrepareSharedContainerSelectionStep(
    harken::Engine& engine,
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view, ContainerTraversalStep out,
    const ContainerTraversalRequest& request) noexcept {
    if (out.status != ContainerTraversalStatus::Ok ||
        out.mode != ContainerTraversalMode::Selection ||
        out.program == nullptr ||
        request.pathCount > harken::kSelectionPathNodeCapacity ||
        (request.pathCount != 0 && request.path == nullptr)) {
        out.status = ContainerTraversalStatus::SelectionFailed;
        return out;
    }

    harken::SelectionMemoryKeyV1 key{};
    key.world = request.worldGeneration;
    key.containerStableId = out.program->containerStableId;
    key.programSemanticFingerprint =
        out.program->programSemanticFingerprint;
    key.memoryScope = out.program->memoryScope;
    if (out.program->memoryScope == harken::MemoryScopeV1::Emitter) {
        if (request.emitter == 0) {
            out.status = ContainerTraversalStatus::EmitterRequired;
            return out;
        }
        key.emitterSlot = static_cast<std::uint32_t>(request.emitter);
        key.emitterGeneration =
            static_cast<std::uint32_t>(request.emitter >> 32);
    } else if (out.program->memoryScope == harken::MemoryScopeV1::Global) {
        key.emitterSlot = UINT32_MAX;
    } else {
        out.status = ContainerTraversalStatus::InvalidMemoryScope;
        return out;
    }

    if (request.ownership == ContainerTraversalOwnership::DirectDelta) {
        if (request.delta == nullptr) {
            out.status = ContainerTraversalStatus::SelectionFailed;
            return out;
        }
        const harken::SelectionAppendResultV1 appended =
            AppendSharedSelectionPlay(
                engine, key, out.program,
                request.worldSemanticFingerprint, request.rootStableId,
                request.callerSeed, request.acceptedPostOrdinal,
                request.pathCount, request.path,
                request.occurrenceOrdinal, request.ticket,
                request.eventIndex, request.executeFrame);
        out.selectionStatus = appended.status;
        if (appended.status != harken::SelectionMemoryStatusV1::Ok ||
            !appended.delta) {
            out.status = ContainerTraversalStatus::SelectionFailed;
            return out;
        }
        *request.delta = appended.delta;
        const harken::SelectionDeltaViewV1 selected =
            engine.selectionMemory.Delta(appended.delta);
        if (!selected.live ||
            selected.status != harken::SelectionMemoryStatusV1::Ok) {
            (void)engine.selectionMemory.CancelDelta(appended.delta);
            *request.delta = {};
            out.status = ContainerTraversalStatus::SelectionFailed;
            return out;
        }
        out.selectedChildOrdinal = selected.selectedChildOrdinal;
    } else {
        if (request.prepared == nullptr && request.preparation.mode !=
                harken::EngineSelectionPreparationMode::PendingReplacement) {
            out.status = ContainerTraversalStatus::SelectionFailed;
            return out;
        }
        out.selectionStatus = PrepareSharedSelectionPlay(
            engine, key, out.program,
            request.worldSemanticFingerprint, request.rootStableId,
            request.callerSeed, request.acceptedPostOrdinal,
            request.pathCount, request.path,
            request.occurrenceOrdinal, request.ticket,
            request.eventIndex, request.executeFrame, request.prepared,
            &out.selectedChildOrdinal, request.loopIteration, request.preparation);
        if (out.selectionStatus != harken::SelectionMemoryStatusV1::Ok) {
            out.status = ContainerTraversalStatus::SelectionFailed;
            return out;
        }
    }

    const harken::ContainerProgramViewV3* resolvedProgram = nullptr;
    if (!ResolveSharedContainerChild(
            authority, view, out.canonicalParent,
            out.selectedChildOrdinal, &resolvedProgram, &out.child,
            &out.canonicalParent, &out.canonicalChild) ||
        resolvedProgram != out.program || out.child == nullptr) {
        if (request.ownership == ContainerTraversalOwnership::DirectDelta) {
            (void)engine.selectionMemory.CancelDelta(*request.delta);
            *request.delta = {};
        } else {
            if (!request.preparation.Cancel(engine.selectionMemory, request.prepared))
                out.selectionStatus = harken::SelectionMemoryStatusV1::RuntimeRecreateRequired;
        }
        out.status = ContainerTraversalStatus::ChildResolutionFailed;
        return out;
    }
    if (request.materializedOrdinal != nullptr)
        *request.materializedOrdinal = out.selectedChildOrdinal;
    out.pathNode = MakeContainerSelectionPathNode(
        out.canonicalParent.stableId, out.selectedChildOrdinal);
    out.status = ContainerTraversalStatus::Ok;
    return out;
}

enum class ContainerTraversalDirective : std::uint8_t {
    Advance,
    Stop,
    Fail,
};

template <typename AuthorityView, typename RequestFactory,
          typename FailureHandler, typename SelectionHandler,
          typename QueueHandler, typename VariableControlHandler>
bool DriveSharedContainerTraversal(
    harken::Engine& engine,
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view, harken::PlayableRefV1* current,
    RequestFactory&& makeRequest, FailureHandler&& onFailure,
    SelectionHandler&& onSelection, QueueHandler&& onQueue,
    VariableControlHandler&& onVariableControl) noexcept {
    if (current == nullptr) return false;
    while (current->kind == harken::PlayableKindV1::Container) {
        ContainerTraversalStep step = ClassifySharedContainerTraversalStep(
            engine, authority, view, *current);
        if (step.status != ContainerTraversalStatus::Ok) {
            onFailure(step);
            return false;
        }
        if (step.mode == ContainerTraversalMode::Selection) {
            ContainerTraversalRequest request{};
            if (!makeRequest(&request)) return false;
            step = PrepareSharedContainerSelectionStep(
                engine, authority, view, step, request);
            if (step.status != ContainerTraversalStatus::Ok) {
                onFailure(step);
                return false;
            }
        }

        ContainerTraversalDirective directive =
            ContainerTraversalDirective::Fail;
        switch (step.mode) {
        case ContainerTraversalMode::Selection:
            directive = onSelection(step);
            break;
        case ContainerTraversalMode::Queue:
            directive = onQueue(step);
            break;
        case ContainerTraversalMode::VariableControl:
            directive = onVariableControl(step);
            break;
        }
        if (directive == ContainerTraversalDirective::Fail) return false;
        if (directive == ContainerTraversalDirective::Stop) return true;
    }
    return true;
}

// Resolve one queue frontier through the shared runtime decision surface.
// Entry adapters provide the authored program, seed, and current state; this
// helper owns permutation materialization, reset state, successor resolution,
// and selected-child lookup for every entry path.
bool ResolveSharedQueueFrontier(
    harken::Engine& engine, const harken::ContainerProgramViewV3& program,
    const harken::RandomQueueSeedContext& seed, bool randomQueue,
    harken::EffectiveQueueState* initial,
    harken::EffectiveQueueState* resetInitial,
    harken::EffectiveQueueState* next,
    const harken::ContainerChildProgramViewV2** selected,
    harken::QueueSequenceStepStatus* step) noexcept {
    if (initial == nullptr || resetInitial == nullptr || next == nullptr ||
        selected == nullptr || step == nullptr || program.childCount == 0 ||
        program.childCount > engine.queueSelectionChildScratch.size() ||
        program.childCount > engine.queueRemainingScratch.size() ||
        program.childCount > engine.queuePermutationScratch.size()) {
        return false;
    }
    const auto buildPermutation = [&](harken::EffectiveQueueState& state) {
        return !randomQueue ||
               harken::BuildRandomQueuePermutationV1(
                   program, seed, state,
                   engine.queueSelectionChildScratch.data(),
                   engine.queueRemainingScratch.data(),
                   engine.queuePermutationScratch.data(),
                   static_cast<std::uint32_t>(
                       engine.queuePermutationScratch.size())) ==
                   harken::SelectionStatusV1::Ok;
    };
    if (engine.queueInputHookForTest != nullptr)
        engine.queueInputHookForTest(program, seed, *initial, engine.selectionInputContextForTest);
    if (!buildPermutation(*initial)) {
        return false;
    }
    if (initial->cursor >= program.childCount) {
        return false;
    }
    if (randomQueue) {
        if (initial->currentChildOrdinal == 0) {
            initial->currentChildOrdinal =
                engine.queuePermutationScratch[initial->cursor];
        }
        if (engine.queuePermutationScratch[initial->cursor] !=
            initial->currentChildOrdinal) {
            return false;
        }
    } else if (initial->cursor >= program.childCount ||
               program.children[initial->cursor].stableChildOrdinal !=
                   initial->currentChildOrdinal) {
        return false;
    }

    resetInitial->version = 1;
    resetInitial->cursor = randomQueue ? 0u : program.initialSequenceCursor;
    resetInitial->selectionOrdinal = 1;
    if (!randomQueue) {
        if (resetInitial->cursor >= program.childCount) {
            return false;
        }
        resetInitial->currentChildOrdinal =
            program.children[resetInitial->cursor].stableChildOrdinal;
    } else {
        if (!buildPermutation(*resetInitial)) {
            return false;
        }
        resetInitial->currentChildOrdinal = engine.queuePermutationScratch[0];
    }

    *selected = FindQueueChild(program, initial->currentChildOrdinal);
    if (*selected == nullptr) {
        return false;
    }
    *step = ResolveQueueStep(engine, program, seed, *initial, next);
    if (*step == harken::QueueSequenceStepStatus::Invalid) {
        return false;
    }
    return true;
}

struct QueueFrontierPlan {
    harken::EffectiveQueueState initial{};
    harken::EffectiveQueueState resetInitial{};
    harken::EffectiveQueueState next{};
    const harken::ContainerChildProgramViewV2* selected = nullptr;
    harken::QueueSequenceStepStatus status =
        harken::QueueSequenceStepStatus::Invalid;
};

enum class QueueRootPlanStatus : std::uint8_t {
    Ok,
    CapabilityUnavailable,
    EmitterRequired,
    RuntimeRecreateRequired,
};

struct QueueEmitterIdentity {
    std::uint32_t slot = UINT32_MAX;
    std::uint32_t generation = 0;
};

QueueRootPlanStatus ResolveQueueEmitterIdentity(
    harken::ContainerModeV1 mode, harken::MemoryScopeV1 memoryScope,
    bool resumePosition, std::uint64_t emitter,
    QueueEmitterIdentity* out) noexcept {
    if (out == nullptr) {
        return QueueRootPlanStatus::CapabilityUnavailable;
    }
    *out = {};
    if (mode == harken::ContainerModeV1::SequenceQueue &&
        memoryScope == harken::MemoryScopeV1::Global) {
        return QueueRootPlanStatus::Ok;
    }
    if (mode == harken::ContainerModeV1::SequenceQueue &&
        memoryScope == harken::MemoryScopeV1::Emitter && emitter == 0 &&
        !resumePosition) {
        return QueueRootPlanStatus::Ok;
    }
    if ((mode != harken::ContainerModeV1::SequenceQueue &&
         mode != harken::ContainerModeV1::RandomQueue) ||
        memoryScope != harken::MemoryScopeV1::Emitter) {
        return QueueRootPlanStatus::CapabilityUnavailable;
    }
    if (emitter == 0) {
        return QueueRootPlanStatus::EmitterRequired;
    }
    out->slot = static_cast<std::uint32_t>(emitter);
    out->generation = static_cast<std::uint32_t>(emitter >> 32);
    return QueueRootPlanStatus::Ok;
}

struct QueueRootPlanRequest {
    std::uint64_t worldGeneration = 0;
    std::uint64_t worldSemanticFingerprint = 0;
    VnObjectId rootStableId{};
    VnEmitterHandle emitter = 0;
    std::uint64_t callerSeed = 0;
    std::uint64_t acceptedPostOrdinal = 0;
};

struct QueueRootPlan {
    QueueFrontierPlan frontier{};
    harken::QueueCheckpointKey checkpointKey{};
    harken::RandomQueueSeedContext randomSeed{};
    bool randomQueue = false;
    bool checkpointLoaded = false;
};

bool PrepareSharedQueueFrontierPlan(
    harken::Engine& engine, const harken::ContainerProgramViewV3& program,
    const harken::RandomQueueSeedContext& seed, bool randomQueue,
    const harken::EffectiveQueueState& initial,
    QueueFrontierPlan* out) noexcept {
    if (out == nullptr) return false;
    *out = {};
    out->initial = initial;
    return ResolveSharedQueueFrontier(
        engine, program, seed, randomQueue, &out->initial,
        &out->resetInitial, &out->next, &out->selected, &out->status);
}

QueueRootPlanStatus PrepareSharedQueueRootPlan(
    harken::Engine& engine, const harken::ContainerProgramViewV3& program,
    const QueueRootPlanRequest& request, QueueRootPlan* out) noexcept {
    if (out == nullptr) {
        return QueueRootPlanStatus::CapabilityUnavailable;
    }
    *out = {};
    out->randomQueue =
        program.mode == harken::ContainerModeV1::RandomQueue;
    if ((!out->randomQueue &&
         program.mode != harken::ContainerModeV1::SequenceQueue) ||
        program.childCount == 0 ||
        (program.queueSplice != harken::QueueSpliceV1::Butt &&
         program.queueSplice != harken::QueueSpliceV1::MarkerAligned) ||
        (!out->randomQueue &&
         program.initialSequenceCursor >= program.childCount)) {
        return QueueRootPlanStatus::CapabilityUnavailable;
    }
    QueueEmitterIdentity emitterIdentity{};
    const QueueRootPlanStatus identityStatus = ResolveQueueEmitterIdentity(
        program.mode, program.memoryScope, program.resumePosition != 0,
        request.emitter, &emitterIdentity);
    if (identityStatus != QueueRootPlanStatus::Ok) {
        return identityStatus;
    }

    out->checkpointKey.world = request.worldGeneration;
    out->checkpointKey.containerStableId = program.containerStableId;
    out->checkpointKey.programSemanticFingerprint =
        program.programSemanticFingerprint;
    out->checkpointKey.resetEpoch = engine.transportEpochOwner.Current();
    out->checkpointKey.emitterSlot = emitterIdentity.slot;
    out->checkpointKey.emitterGeneration = emitterIdentity.generation;
    if (out->randomQueue) {
        out->randomSeed.worldSemanticFingerprint =
            request.worldSemanticFingerprint;
        out->randomSeed.rootStableId = request.rootStableId;
        out->randomSeed.callerSeed = request.callerSeed;
        out->randomSeed.acceptedPostOrdinal = request.acceptedPostOrdinal;
        out->randomSeed.emitterSlot = out->checkpointKey.emitterSlot;
        out->randomSeed.emitterGeneration =
            out->checkpointKey.emitterGeneration;
        out->randomSeed.resetEpoch = out->checkpointKey.resetEpoch;
    }

    harken::EffectiveQueueState initial{};
    harken::QueueCheckpointImage checkpoint{};
    if (program.resumePosition != 0) {
        out->checkpointLoaded = engine.queueCheckpoints.Load(
            out->checkpointKey, &checkpoint);
        if (out->checkpointLoaded) {
            if (out->randomQueue) {
                if (!checkpoint.randomSeedValid ||
                    checkpoint.randomSeed.worldSemanticFingerprint !=
                        out->randomSeed.worldSemanticFingerprint ||
                    checkpoint.randomSeed.rootStableId !=
                        out->randomSeed.rootStableId ||
                    checkpoint.randomSeed.emitterSlot !=
                        out->randomSeed.emitterSlot ||
                    checkpoint.randomSeed.emitterGeneration !=
                        out->randomSeed.emitterGeneration ||
                    checkpoint.randomSeed.resetEpoch !=
                        out->randomSeed.resetEpoch) {
                    return QueueRootPlanStatus::RuntimeRecreateRequired;
                }
                out->randomSeed = checkpoint.randomSeed;
            }
            if (!checkpoint.replayCurrent ||
                checkpoint.effective.cursor >= program.childCount) {
                return QueueRootPlanStatus::RuntimeRecreateRequired;
            }
            initial = checkpoint.effective;
        }
    }
    if (!out->checkpointLoaded) {
        initial.version = 1;
        initial.cursor = out->randomQueue
            ? 0u : program.initialSequenceCursor;
        initial.selectionOrdinal = 1;
        if (!out->randomQueue) {
            initial.currentChildOrdinal =
                program.children[initial.cursor].stableChildOrdinal;
        }
    }
    if (!PrepareSharedQueueFrontierPlan(
            engine, program, out->randomSeed, out->randomQueue, initial,
            &out->frontier)) {
        return QueueRootPlanStatus::RuntimeRecreateRequired;
    }
    return QueueRootPlanStatus::Ok;
}

// Resolve one authored Container edge through the same authority and
// identity gate used by every playback entry.  Queue state is supplied by the
// caller, while program and child lookup remain owned by this runtime seam.
template <typename AuthorityView>
bool ResolveSharedContainerProgram(
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view, const harken::PlayableRefV1& parent,
    const harken::ContainerProgramViewV3** programOut,
    harken::PlayableRefV1* canonicalParent) noexcept {
    if (programOut == nullptr || parent.kind !=
        harken::PlayableKindV1::Container) {
        return false;
    }
    *programOut = nullptr;
    const auto resolvedParent =
        harken::ResolvePlayableExecutionEntry(authority, {parent});
    if (resolvedParent.status !=
            harken::PlayableExecutionResolveStatus::Ok ||
        resolvedParent.root.kind != harken::PlayableKindV1::Container) {
        return false;
    }
    const auto* program = [&]() noexcept
        -> const harken::ContainerProgramViewV3* {
        if constexpr (std::is_same_v<AuthorityView,
                                     harken::PackPlaybackView>) {
            return view.ResolveContainer(
                resolvedParent.root.stableId,
                resolvedParent.root.expectedProgramSemanticFingerprint).programView;
        } else {
            for (std::uint32_t index = 0; index < view.containerCount;
                 ++index) {
                const auto& candidate = view.containers[index];
                if (candidate.containerStableId ==
                        resolvedParent.root.stableId &&
                    candidate.programSemanticFingerprint ==
                        resolvedParent.root.expectedProgramSemanticFingerprint) {
                    return &candidate;
                }
            }
            return nullptr;
        }
    }();
    if (program == nullptr) return false;
    if (canonicalParent != nullptr) *canonicalParent = resolvedParent.root;
    *programOut = program;
    return true;
}

template <typename AuthorityView>
bool ResolveSharedContainerChild(
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view, const harken::PlayableRefV1& parent,
    std::uint32_t childOrdinal,
    const harken::ContainerProgramViewV3** programOut,
    const harken::ContainerChildProgramViewV2** childOut,
    harken::PlayableRefV1* canonicalParent,
    harken::PlayableRefV1* canonicalChild) noexcept {
    if (programOut == nullptr || childOut == nullptr) return false;
    if (!ResolveSharedContainerProgram(
            authority, view, parent, programOut, canonicalParent)) {
        return false;
    }
    const auto* program = *programOut;
    const auto* child = FindQueueChild(*program, childOrdinal);
    if (child == nullptr) return false;
    const auto resolvedChild =
        harken::ResolvePlayableExecutionEntry(authority,
                                              {child->playable});
    if (resolvedChild.status != harken::PlayableExecutionResolveStatus::Ok) {
        return false;
    }
    if (canonicalChild != nullptr) *canonicalChild = resolvedChild.root;
    *childOut = child;
    return true;
}

// Shared resolver entry for one authored Container step.  Playback adapters
// provide only authority/view data; canonical parent and child identities are
// resolved together at this runtime seam.
template <typename AuthorityView>
bool ResolveSharedContainerStep(
    const harken::PlayableExecutionAuthority& authority,
    const AuthorityView& view, const harken::PlayableRefV1& parent,
    std::uint32_t childOrdinal,
    const harken::ContainerProgramViewV3** programOut,
    const harken::ContainerChildProgramViewV2** childOut,
    harken::PlayableRefV1* canonicalParent,
    harken::PlayableRefV1* canonicalChild) noexcept {
    return ResolveSharedContainerChild(
        authority, view, parent, childOrdinal, programOut, childOut,
        canonicalParent, canonicalChild);
}

bool ResolveSharedContainerChild(
    const harken::PlayableExecutionAuthority& authority,
    const harken::ContainerProgramViewV3& program, std::uint32_t childOrdinal,
    const harken::ContainerChildProgramViewV2** childOut,
    harken::PlayableRefV1* canonicalChild = nullptr) noexcept {
    if (childOut == nullptr) return false;
    *childOut = FindQueueChild(program, childOrdinal);
    if (*childOut == nullptr) return false;
    const auto resolved = harken::ResolvePlayableExecutionEntry(
        authority, {(*childOut)->playable});
    if (resolved.status != harken::PlayableExecutionResolveStatus::Ok) {
        *childOut = nullptr;
        return false;
    }
    if (canonicalChild != nullptr) *canonicalChild = resolved.root;
    return true;
}

bool CancelPreparedOccurrenceOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedOccurrenceOwnerContext*>(opaque);
    if (context == nullptr || context->pool == nullptr ||
        context->token == nullptr || context->token->generation == 0) {
        return true;
    }
    // A failed voice rollback retains this exact progress record for retry.
    // Keep both owner callbacks until the dependent voice has unbound it.
    if (context->pool->CompletionProgressOf(*context->token) != nullptr) {
        return false;
    }
    if (context->prepared != nullptr && *context->prepared) {
        const bool cancelled =
            context->pool->CancelPreparedAcquire(*context->token);
        if (cancelled) {
            *context->prepared = false;
            *context->token = {};
            if (context->completionOwner != nullptr) {
                *context->completionOwner = {};
            }
            return true;
        }
        // A prepared occurrence with owner/fence state still follows the
        // exact rollback path below after all dependent voices are unbound.
    }
    auto& pool = *context->pool;
    const auto token = *context->token;
    harken::CompletionOwnerRef capturedOwner{};
    if (context->completionOwner != nullptr) {
        if (pool.CaptureCompletionOwner(token, &capturedOwner) &&
            capturedOwner.kind != harken::CompletionOwnerKind::None &&
            !pool.RollbackCompletionOwnerPinExact(token,
                                                   *context->completionOwner)) {
            return false;
        }
    } else if (pool.CaptureCompletionOwner(token, &capturedOwner) &&
               capturedOwner.kind != harken::CompletionOwnerKind::None) {
        if (!pool.RollbackCompletionOwnerPinExact(token, capturedOwner)) {
            return false;
        }
    }
    if (pool.StageOf(token) == harken::OccurrenceStage::Preparing)
        (void)pool.Advance(token, harken::OccurrenceStage::Active);
    if (pool.StageOf(token) == harken::OccurrenceStage::Active)
        (void)pool.Advance(token, harken::OccurrenceStage::LogicalDone);
    if (pool.StageOf(token) == harken::OccurrenceStage::LogicalDone)
        (void)pool.Advance(token, harken::OccurrenceStage::AwaitingEventFence);
    const bool released = pool.ReleaseAfterFence(
        token, context->observedCompletionBlockSequence);
    if (released) {
        *context->token = {};
        if (context->prepared != nullptr) {
            *context->prepared = false;
        }
        if (context->completionOwner != nullptr) {
            *context->completionOwner = {};
        }
    }
    return released;
}

bool ValidatePreparedServiceOwner(harken::Engine* engine,
                                  const harken::EnginePlayableServiceRow* row) noexcept {
    return row == nullptr || (engine != nullptr && row->InvocationValid() &&
        engine->ResolvePlayableService(row->identity, row->ownerInstance, row->ownerEpoch) == row);
}

bool ValidatePreparedServiceCommitRouting(harken::Engine* engine,
                                harken::EnginePlayableServiceRow* row) noexcept {
    if (row == nullptr) return true;
    if (!ValidatePreparedServiceOwner(engine, row)) return false;
    const auto owner = engine->playableInstances.Classify(row->ownerInstance);
    if (!owner.live || owner.scheduleEpoch != row->ownerEpoch) return false;
    if (row->variableControlInstance.Valid() || row->queueMode) {
        harken::ContainerPlaybackRow container{};
        if (owner.kind != harken::PlayableKind::Container ||
            !engine->containerPlayback.Capture(row->ownerInstance, &container) ||
            container.expectedScheduleEpoch != row->ownerEpoch) return false;
    }
    return true;
}

bool CommitPreparedServiceOwner(harken::Engine* engine,
                                harken::EnginePlayableServiceRow* row) noexcept {
    return ValidatePreparedServiceCommitRouting(engine, row) &&
        (row == nullptr || engine->playablePartitions.Commit(row->partition, row->identity));
}

bool CancelPreparedServiceOwner(harken::Engine* engine,
                                harken::EnginePlayableServiceRow* row) noexcept {
    return row == nullptr || (engine != nullptr &&
        engine->playablePartitions.RollbackCommit(row->partition, row->identity));
}

bool ValidateFrontierServiceOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineFrontierServiceOwnerContext*>(opaque);
    return context != nullptr && context->engine != nullptr &&
        context->engine->ResolvePlayableService(context->service) != nullptr;
}

bool CommitFrontierServiceOwner(void* opaque, std::uint64_t) noexcept {
    auto* context = static_cast<harken::EngineFrontierServiceOwnerContext*>(opaque);
    return ValidateFrontierServiceOwner(opaque) && CommitPreparedServiceOwner(context->engine,
        context->engine->ResolvePlayableService(context->service));
}

bool CancelFrontierServiceOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineFrontierServiceOwnerContext*>(opaque);
    return ValidateFrontierServiceOwner(opaque) && CancelPreparedServiceOwner(context->engine,
        context->engine->ResolvePlayableService(context->service));
}

void PublishPlayableServiceOwnership(harken::Engine& engine,
                                     harken::EnginePlayableServiceRow* row) noexcept {
    if (row == nullptr) return;
    if (!engine.playablePartitions.Publish(row->partition, row->identity)) {
        engine.runtimeRecreateRequired = true;
        return;
    }
    for (auto& child : engine.playableServices) {
        if (&child == row || !child.actionPrepared || !child.parentService.Valid() || !child.InvocationValid() ||
            child.invocation != row->invocation || child.invocationGeneration != row->invocationGeneration)
            continue;
        if (engine.forceDeferredFrontierChildPublishFailureForTest) {
            engine.forceDeferredFrontierChildPublishFailureForTest = false;
            engine.deferredFrontierRejectedChildForTest = child.identity;
            engine.runtimeRecreateRequired = true;
            continue;
        }
        if (!engine.playablePartitions.Publish(child.partition, child.identity)) {
engine.runtimeRecreateRequired = true;
            continue;
        }
        child.actionPrepared = false;
        const bool awaitsOwnArms = child.ordinaryLifecycleOwned ||
            child.variableControlIndependentFrontier;
        child.phase = child.pendingImmediateEntry
            ? harken::EnginePlayableStartPhase::PendingImmediateEntry
            : awaitsOwnArms ? harken::EnginePlayableStartPhase::AwaitingArmAck
                : child.variableControlInstance.Valid() ? harken::EnginePlayableStartPhase::Filed
                    : harken::EnginePlayableStartPhase::Started;
        child.controlLifecycle = awaitsOwnArms || child.variableControlInstance.Valid()
            ? harken::PlayableControlLifecycle::Preparing : harken::PlayableControlLifecycle::Active;
    }
}

bool ValidatePreparedActionResourceOwner(void* opaque) noexcept;
bool CommitPreparedActionResourceOwner(void* opaque, std::uint64_t ticket) noexcept;
bool CancelPreparedActionResourceOwner(void* opaque) noexcept;
bool ValidateQueueFutureAttemptOwner(void* opaque) noexcept;
bool CommitQueueFutureAttemptOwner(void* opaque, std::uint64_t ticket) noexcept;
bool CancelQueueFutureAttemptOwner(void* opaque) noexcept;
harken::EngineActionPlayScratch* FindFrontierAttempt(harken::Engine& engine,
    harken::EngineFrontierAttemptToken token) noexcept;
bool CancelPreparedQueueCompletionBindings(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept;

bool ValidatePreparedQueueInstanceOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedQueueInstanceOwnerContext*>(opaque);
    return context != nullptr && context->table != nullptr &&
           context->prepared != nullptr && context->prepared->Valid() &&
           ValidatePreparedServiceOwner(context->engine, context->service) &&
           (context->resources == nullptr || ValidatePreparedActionResourceOwner(context->resources));
}

bool CommitPreparedQueueInstanceOwner(void* opaque,
                                      std::uint64_t ticket) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedQueueInstanceOwnerContext*>(opaque);
    if (!ValidatePreparedQueueInstanceOwner(context) ||
        context->output == nullptr) {
        return false;
    }
    if (context->resources != nullptr &&
        !CommitPreparedActionResourceOwner(context->resources, ticket)) return false;
    context->committed = context->table->CommitPreparedAcquire(
        context->prepared, context->output);
    return context->committed && CommitPreparedServiceOwner(context->engine, context->service);
}

bool CancelPreparedQueueInstanceOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedQueueInstanceOwnerContext*>(opaque);
    if (context == nullptr || context->table == nullptr ||
        context->prepared == nullptr) {
        return true;
    }
    if (context->engine != nullptr &&
        context->table != &context->engine->queueInstances) return false;
    if (context->resources != nullptr &&
        (!CancelPreparedActionResourceOwner(context->resources) ||
         !CancelPreparedQueueCompletionBindings(*context->engine, *context->resources->scratch))) return false;
    if (context->committed) {
        if (context->cancelAttemptsForTest != nullptr) {
            ++*context->cancelAttemptsForTest;
        }
        const bool released = context->output != nullptr &&
                              context->output->Valid() &&
                              (context->engine != nullptr
                                  ? context->engine->ReleaseOriginalQueue(*context->output)
                                  : context->table->Release(*context->output));
        if (released) {
            *context->output = {};
            context->committed = false;
        }
        return released && CancelPreparedServiceOwner(context->engine, context->service);
    }
    if (context->prepared->Valid() &&
        !(context->engine != nullptr
            ? context->engine->CancelOriginalQueueAcquire(context->prepared)
            : context->table->CancelPreparedAcquire(context->prepared))) return false;
    return CancelPreparedServiceOwner(context->engine, context->service);
}

bool ValidateQueueInstanceOwner(const harken::EngineQueueInstanceOwnerContext* context) noexcept {
    return context != nullptr && context->engine != nullptr && context->prepared.Valid() &&
        context->engine->ResolvePlayableService(context->service) != nullptr;
}

bool CommitQueueInstanceOwner(harken::EngineQueueInstanceOwnerContext* context) noexcept {
    if (!ValidateQueueInstanceOwner(context)) return false;
    auto* service = context->engine->ResolvePlayableService(context->service);
    context->committed = context->engine->queueInstances.CommitPreparedAcquire(
        &context->prepared, &service->queueInstance);
    return context->committed;
}

bool CancelQueueInstanceOwner(harken::EngineQueueInstanceOwnerContext* context) noexcept {
    if (context == nullptr || context->engine == nullptr) return false;
    auto* service = context->engine->ResolvePlayableService(context->service);
    if (service == nullptr) return false;
    if (context->committed) {
        if (!context->engine->ReleaseOriginalQueue(service->queueInstance)) return false;
        service->queueInstance = {};
        context->committed = false;
        return true;
    }
    if (context->prepared.Valid() &&
        !context->engine->CancelOriginalQueueAcquire(&context->prepared)) return false;
    service->queueInstance = {};
    return true;
}

bool ValidateFrontierQueueOwner(void* opaque) noexcept {
    return ValidateQueueInstanceOwner(static_cast<harken::EngineFrontierQueueOwnerContext*>(opaque));
}

bool CommitFrontierQueueOwner(void* opaque, std::uint64_t) noexcept {
    return CommitQueueInstanceOwner(static_cast<harken::EngineFrontierQueueOwnerContext*>(opaque));
}

bool CancelFrontierQueueOwner(void* opaque) noexcept {
    return CancelQueueInstanceOwner(static_cast<harken::EngineFrontierQueueOwnerContext*>(opaque));
}

bool ValidatePreparedVariableControlOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedVariableControlOwnerContext*>(opaque);
    return context != nullptr && context->table != nullptr &&
           context->prepared != nullptr && context->prepared->Valid() &&
           context->output != nullptr &&
            (!context->ServiceCommitProofRequired() ||
             (context->OriginalServiceAssociationMatches(context->engine, context->service) &&
              context->serviceCommitProof.Associated(context->OriginalServiceInput()))) &&
           (!context->commitProofRequired ||
            (context->commitProof.Associated(context->table, context->prepared) &&
             context->output->slot == context->commitProof.Token().slot &&
             context->output->generation == context->commitProof.Token().generation)) &&
           ValidatePreparedServiceOwner(context->engine, context->service);
}

bool CommitPreparedVariableControlOwner(void* opaque,
                                       std::uint64_t) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedVariableControlOwnerContext*>(opaque);
    if (!ValidatePreparedVariableControlOwner(context)) return false;
    if (context->commitProofRequired) {
        const auto originalToken = context->commitProof.Token();
        harken::VariableControlInstanceTable::ConsumePreparedAcquire(std::move(context->commitProof));
        *context->output = originalToken;
    } else if (!context->table->CommitPreparedAcquire(
            context->prepared, context->output)) {
        return false;
    }
    context->committed = true;
    if (context->ServiceCommitProofRequired()) {
        if (!ValidatePreparedServiceCommitRouting(context->engine, context->service)) {
            context->serviceCommitProof.Release();
            return false;
        }
        harken::EnginePlayablePartitionPool::ConsumePreparedCommit(std::move(context->serviceCommitProof));
    } else if (!CommitPreparedServiceOwner(context->engine, context->service)) return false;
    if (context->nestedIndex != UINT32_MAX && context->row != nullptr &&
        context->nestedCount != nullptr) {
        const std::uint32_t index = context->nestedIndex;
        context->row->variableControlControllers[index].instance =
            *context->output;
        context->row->variableControlControllers[index].service =
            {context->service->identity, context->service->ownerInstance,
             context->service->ownerEpoch, context->service->invocationGeneration};
        context->row->variableControlControllers[index].decision = *context->activationDecision;
        context->row->variableControlControllers[index].continuous =
            context->activationSide == harken::VariableControlSide::Continuous;
        *context->nestedCount = std::max(*context->nestedCount, index + 1u);
    }
    if (context->activate) {
        if (context->activationDecision == nullptr ||
            context->activationBank == nullptr ||
            !context->activationDecision->Valid() ||
            !context->activationBank->Valid() ||
            !context->table->ActivateSide(
                *context->output, context->activationSide,
                *context->activationDecision, *context->activationBank)) {
            return false;
        }
        context->activated = true;
    }
    return true;
}

bool CancelPreparedVariableControlOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedVariableControlOwnerContext*>(opaque);
    if (context != nullptr) {
        context->serviceCommitProof.Release();
        context->commitProof.Release();
    }
    if (context == nullptr || context->table == nullptr ||
        context->prepared == nullptr) {
        return true;
    }
    if (!context->committed) {
        if (context->prepared->Valid()) {
            const bool childOnly = context->nestedIndex != UINT32_MAX && context->row == nullptr;
            const auto token = context->prepared->Token();
            if (childOnly && (context->output == nullptr || context->output->slot != token.slot ||
                context->output->generation != token.generation)) return false;
            if (!context->table->CancelPreparedAcquire(context->prepared)) return false;
            if (childOnly) *context->output = {};
        }
        return CancelPreparedServiceOwner(context->engine, context->service);
    }
    bool resolved = true;
    const auto cancelSide = [&](harken::VariableControlSide side,
                                harken::DecisionToken decision,
                                const harken::BankVersionToken* privatelyAppliedBank) noexcept {
        harken::VariableControlInstanceSnapshot snapshot{};
        if (context->output == nullptr ||
            !context->table->Capture(*context->output, &snapshot)) return false;
        const auto& captured = side == harken::VariableControlSide::Discrete
            ? snapshot.discrete : snapshot.continuous;
        if (captured.decision.slot != decision.slot ||
            captured.decision.generation != decision.generation) return false;
        if (captured.state == harken::VariableControlSideState::Pending)
            return context->table->CancelSide(*context->output, side, decision);
        if (captured.state == harken::VariableControlSideState::Terminal) return true;
        // Nested initial activation is private promotion; Release can unwind
        // its exact committed side after all exposure owners have cancelled.
        return privatelyAppliedBank != nullptr &&
            captured.state == harken::VariableControlSideState::Committed &&
            captured.lastApplied.slot == privatelyAppliedBank->slot &&
            captured.lastApplied.generation == privatelyAppliedBank->generation;
    };
    if (context->output != nullptr &&
        context->activationDecision != nullptr &&
        context->activationDecision->Valid()) {
        resolved = cancelSide(context->activationSide,
                       *context->activationDecision, context->activated ? context->activationBank : nullptr) &&
                   resolved;
    }
    if (context->discreteDecision != nullptr &&
        context->discreteDecision->Valid()) {
        resolved = cancelSide(harken::VariableControlSide::Discrete,
                       *context->discreteDecision, nullptr) &&
                   resolved;
    }
    if (context->continuousDecision != nullptr &&
        context->continuousDecision->Valid()) {
        resolved = cancelSide(harken::VariableControlSide::Continuous,
                       *context->continuousDecision, nullptr) &&
                   resolved;
    }
    if (resolved && context->output != nullptr && context->output->Valid()) {
        resolved = context->table->Release(*context->output);
    }
    if (resolved) {
        if (context->output != nullptr) *context->output = {};
        context->committed = false;
        context->activated = false;
        if (context->nestedIndex != UINT32_MAX &&
            context->row != nullptr && context->nestedCount != nullptr &&
            *context->nestedCount > context->nestedIndex) {
            context->row->variableControlControllers[
                context->nestedIndex].instance = {};
        }
    }
    return resolved && CancelPreparedServiceOwner(context->engine, context->service);
}

bool ValidatePreparedCompositeOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedCompositeOwnerContext*>(opaque);
    return context != nullptr && context->pool != nullptr &&
           context->occurrences != nullptr && context->token != nullptr &&
           context->token->Valid() && context->preparedFlag != nullptr &&
           *context->preparedFlag;
}

bool CommitPreparedCompositeOwner(void* opaque,
                                  std::uint64_t) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedCompositeOwnerContext*>(opaque);
    if (!ValidatePreparedCompositeOwner(context)) return false;
    const auto status = context->pool->CommitPrepared(
        *context->token, *context->occurrences);
    context->committed = status == harken::CompositeCompletionAcquireStatus::Ok;
    if (context->committed) *context->preparedFlag = false;
    return context->committed;
}

bool CancelPreparedCompositeOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedCompositeOwnerContext*>(opaque);
    if (context == nullptr || context->pool == nullptr ||
        context->occurrences == nullptr || context->token == nullptr ||
        !context->token->Valid()) {
        return true;
    }
    bool released = true;
    if (context->preparedFlag != nullptr && *context->preparedFlag) {
        released = context->pool->CancelPrepared(*context->token);
    } else if (context->committed) {
        released = context->pool->RollbackBeforePublication(
            *context->token, *context->occurrences);
        if (!released) {
            released = context->pool->Release(
                *context->token, *context->occurrences, 0);
        }
    }
    if (released) {
        *context->token = {};
        if (context->preparedFlag != nullptr) {
            *context->preparedFlag = false;
        }
        context->committed = false;
    }
    return released;
}

bool ValidatePreparedTimelineVoiceOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedTimelineVoiceOwnerContext*>(opaque);
    return context != nullptr && context->engine != nullptr && context->token != nullptr &&
           harken::ValidatePreparedTimelineVoiceStartRoutingV1(*context->engine, *context->token);
}

bool ValidatePreparedAuthorityOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedAuthorityOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr) return false;
    if (!ValidatePreparedServiceOwner(context->engine, context->service)) return false;
    if (context->pack) {
        return context->packLease.leaseToken != 0 &&
               context->engine->packComposition.ValidateLease(
                   context->packLease) == VN_OK;
    }
    return context->worldGeneration != 0 && (context->frozen ||
           context->engine->variables.CurrentWorldGeneration() ==
               context->worldGeneration);
}

bool CommitPreparedAuthorityOwner(void* opaque, std::uint64_t) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::PreparedAuthorityOwnerContext*>(opaque);
    return context != nullptr && CommitPreparedServiceOwner(context->engine, context->service);
}

bool CancelPreparedAuthorityOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::PreparedAuthorityOwnerContext*>(opaque);
    return context != nullptr &&
        (context->dependencies == nullptr || context->dependencies->Empty()) &&
        CancelPreparedServiceOwner(context->engine, context->service);
}

bool CommitPreparedTimelineVoiceOwner(void* opaque,
                                      std::uint64_t sequence) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedTimelineVoiceOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr ||
        context->token == nullptr || !context->token->prepared) {
        if (context != nullptr) context->ReleaseCommitProofs();
        return false;
    }
    const bool originalSingleLedger = context->engine->HasOriginalQueueLedgerCommit(*context->token);
    if (context->preparedCommitProofsRequired &&
        (!context->armCommitProof.Valid() ||
         (!context->ledgerCommitProof.Valid() && !originalSingleLedger) ||
         (context->ledgerCommitProof.Valid() && originalSingleLedger) ||
         !context->voiceCommitProof.Valid() || !context->EffectsProved())) {
        context->ReleaseCommitProofs();
        return false;
    }
    if (context->engine->forceActionTimelineVoiceOwnerCommitFailureForTest) {
        context->engine->forceActionTimelineVoiceOwnerCommitFailureForTest =
            false;
        context->ReleaseCommitProofs();
        return false;
    }
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (harken::detail::RefuseTimelineVoiceOwnerCommitForTest(*context->engine, *context->token)) {
        context->ReleaseCommitProofs();
        return false;
    }
#endif
    const bool committed = CommitPreparedTimelineVoiceStart(
        *context->engine, context->token, sequence,
        context->preparedCommitProofsRequired ? &context->armCommitProof : nullptr, true,
        context->preparedCommitProofsRequired && !originalSingleLedger ? &context->ledgerCommitProof : nullptr,
        context->preparedCommitProofsRequired ? &context->voiceCommitProof : nullptr,
        context->preparedCommitProofsRequired ? &context->effectCommitProofs : nullptr);
    context->committed = committed;
    return committed;
}

bool CancelPreparedTimelineVoiceOwnerImpl(void* opaque,
    const harken::UnpublishedGroupArmCancellationProof* jointCancellation) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedTimelineVoiceOwnerContext*>(opaque);
    if (context != nullptr) context->ReleaseCommitProofs();
    if (context == nullptr || context->engine == nullptr ||
        context->token == nullptr) {
        return true;
    }
    if (!context->engine->CanCancelPendingVariableReplacementVoiceOwner(*context)) return false;
    if (context->committed) {
        ++context->engine->actionTimelineVoiceOwnerRollbackAttemptsForTest;
        if (context->engine->
                forceActionTimelineVoiceOwnerRollbackFailureForTest) {
            context->engine->
                forceActionTimelineVoiceOwnerRollbackFailureForTest = false;
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
            harken::detail::ObserveTimelineVoiceOwnerRollbackRefusalForTest(*context->engine, *context->token);
#endif
            return false;
        }
        const bool rolledBack = RollbackCommittedTimelineVoiceStart(
            *context->engine, context->token, jointCancellation);
        if (rolledBack && jointCancellation == nullptr) context->committed = false;
        return rolledBack;
    }
    if (!context->token->prepared) {
        return jointCancellation == nullptr || RollbackCommittedTimelineVoiceStart(
            *context->engine, context->token, jointCancellation);
    }
    return CancelPreparedTimelineVoiceStart(*context->engine, context->token, jointCancellation);
}

bool CancelPreparedTimelineVoiceOwner(void* opaque) noexcept {
    return CancelPreparedTimelineVoiceOwnerImpl(opaque, nullptr);
}

void ReleasePreparedTimelineVoiceProofs(harken::EngineActionPlayScratch& scratch) noexcept {
    scratch.privateInitialVcPageCohort.ReleasePageTransferProofs();
    scratch.privateInitialVcPageCohort.ReleaseLaneTransferProofs();
    scratch.variableControlOwnerContext.serviceCommitProof.Release();
    scratch.playableTreeExecutor.ReleaseCommitProofs();
    scratch.queueDecisionOwnerContext.ticketCommitProof.Release();
    for (std::uint32_t i = 0; i < scratch.frontierQueueCount; ++i)
        scratch.storage.frontierQueues[i].current.originalSingleDecisionCommitProof.Release();
    for (const auto side : scratch.VoiceOwnerContextSides()) {
        for (auto& owner : side) {
            owner.ReleaseCommitProofs();
            if (owner.engine != nullptr && owner.token != nullptr)
                (void)owner.engine->ReleaseOriginalQueuePreparationProofs(*owner.token);
        }
    }
    scratch.variableControlDiscreteDecisionOwnerContext.ticketCommitProof.Release();
    scratch.variableControlContinuousDecisionOwnerContext.ticketCommitProof.Release();
    scratch.variableControlOwnerContext.commitProof.Release();
}

bool ValidatePreparedDecisionOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedDecisionOwnerContext*>(opaque);
    return context != nullptr && context->table != nullptr &&
           context->reservation != nullptr && context->reservation->Valid() &&
           (!context->ticketCommitProofRequired ||
            (context->ticketCommitProof.Associated(context->table, context->reservation) &&
             context->output != nullptr && context->committedTicket != nullptr));
}

bool CommitPreparedDecisionOwner(void* opaque,
                                 std::uint64_t ticket) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedDecisionOwnerContext*>(opaque);
    if (context != nullptr && context->ticketCommitProofRequired) {
        if (!ValidatePreparedDecisionOwner(context) || context->ticketCommitProof.Sequence() != ticket) {
            context->ticketCommitProof.Release();
            return false;
        }
        const auto originalToken = context->ticketCommitProof.Token();
        harken::DecisionTable::ConsumePreparedReservationCommit(std::move(context->ticketCommitProof));
        *context->output = originalToken;
        *context->committedTicket = ticket;
        context->committed = true;
        return true;
    }
    if (context == nullptr || context->table == nullptr ||
        context->reservation == nullptr || !context->reservation->Valid()) {
        return true;
    }
    harken::DecisionToken committed{};
    if (!context->table->CommitPreparedReservation(
            context->reservation, ticket, &committed)) {
        return false;
    }
    if (context->output != nullptr) *context->output = committed;
    if (context->committedTicket != nullptr) {
        *context->committedTicket = ticket;
    }
    context->committed = true;
    return true;
}

bool CancelPreparedDecisionOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedDecisionOwnerContext*>(opaque);
    if (context != nullptr) context->ticketCommitProof.Release();
    if (context == nullptr || context->table == nullptr ||
        context->reservation == nullptr) {
        return true;
    }
    if (context->committed) {
        if (context->output == nullptr || !context->output->Valid()) {
            return false;
        }
        bool reclaimed = context->table->ReclaimCancelled(*context->output);
        if (!reclaimed) {
            reclaimed = context->table->Cancel(*context->output) &&
                context->table->ReclaimCancelled(*context->output);
        }
        if (!reclaimed) return false;
        *context->output = {};
        if (context->committedTicket != nullptr) {
            *context->committedTicket = {};
        }
        context->committed = false;
        return true;
    }
    if (!context->reservation->Valid()) {
        return true;
    }
    return context->table->CancelPreparedReservation(context->reservation);
}

bool SameCanonicalDecision(harken::DecisionToken a, harken::DecisionToken b) noexcept {
    return a.slot == b.slot && a.generation == b.generation;
}
bool SameCanonicalQueueState(const harken::EffectiveQueueState& a,
    const harken::EffectiveQueueState& b) noexcept;
bool CancelFrontierQueueInitialDecision(void* opaque) noexcept;
bool CancelQueueFutureAttemptOwner(void* opaque) noexcept;
harken::EngineActionPlayScratch* FindFrontierAttempt(harken::Engine& engine,
    harken::EngineFrontierAttemptToken token) noexcept;
bool ValidateFrontierQueueInitialDecision(void* opaque) noexcept;
bool CommitFrontierQueueInitialDecision(void* opaque, std::uint64_t ticket) noexcept;
bool ExitCanonicalQueueChildResources(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept;

bool ValidateFrontierQueueCurrentOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineFrontierQueueCurrentOwnerContext*>(opaque);
    return context != nullptr && context->engine != nullptr && context->decision.Valid() &&
        context->occurrencePrepared && context->engine->ResolvePlayableService(context->service) != nullptr;
}

bool CommitFrontierQueueCurrentOwner(void* opaque, std::uint64_t ticket) noexcept {
    auto& current = *static_cast<harken::EngineFrontierQueueCurrentOwnerContext*>(opaque);
    auto& engine = *current.engine;
    auto* row = engine.ResolvePlayableService(current.service);
    if (row == nullptr) return false;
    harken::EngineActionPlayScratch::PreparedDecisionOwnerContext decision{
        &engine.decisions, &current.decision, &row->QueueFiling().queueDecision, &row->ticket, current.decisionCommitted};
    if (current.originalSingleDecisionCommitProof.Valid()) {
        decision.ticketCommitProof = std::move(current.originalSingleDecisionCommitProof);
        decision.ticketCommitProofRequired = true;
    }
    const bool decisionOk = CommitPreparedDecisionOwner(&decision, ticket);
    current.decisionCommitted = decision.committed;
    if (!decisionOk) return false;
    if (current.canonicalInitial) {
        if (row->QueuePayload().privateInitialQueueCurrent != &current ||
            !SameCanonicalDecision(row->QueueFiling().queueDecision, current.canonicalDecision) ||
            !SameCanonicalDecision(row->initialQueueEntryDecision, current.canonicalDecision)) return false;
        current.canonicalTicket = ticket;
        current.canonicalRequest.ticket = {ticket};
        row->CanonicalInitialQueueRequest() = current.canonicalRequest;
        current.canonicalProgress = harken::EngineInitialQueueDecisionProgress::PrivateOpen;
    }
    row->QueuePayload().queueTicket = ticket;
    const auto commitOccurrence = [&](auto& token, bool& prepared) {
        harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext owner{
            &engine.timelineOccurrences, &token, &prepared};
        return CommitPreparedOccurrenceOwner(&owner, ticket);
    };
    if (!commitOccurrence(current.occurrence, current.occurrencePrepared)) return false;
    for (std::uint32_t index = 0; index < current.leafCount; ++index)
        if (current.leafOccurrences[index].generation != 0 &&
            !commitOccurrence(current.leafOccurrences[index], current.leafPrepared[index])) return false;
    if (current.compositePrepared) {
        if (engine.compositeCompletionOwners.CommitPrepared(current.composite, engine.timelineOccurrences) !=
            harken::CompositeCompletionAcquireStatus::Ok) return false;
        current.compositePrepared = false;
    }
    return true;
}

bool CancelFrontierQueueBindings(void* opaque) noexcept {
    auto* binding = static_cast<harken::EngineFrontierQueueBindingOwnerContext*>(opaque);
    if (binding == nullptr || binding->current == nullptr) return true;
    auto& current = *binding->current;
    auto& engine = *current.engine;
    current.originalSingleDecisionCommitProof.Release();
    if (current.compositePrepared && !engine.ReleaseOriginalCompositeLeafPreparationProofs(current.composite)) return false;
    for (std::uint32_t i = 0; i < current.leafCount; ++i)
        if (current.voices[i] != nullptr && !engine.ReleaseOriginalQueuePreparationProofs(*current.voices[i])) return false;
    while (current.mutationCount != 0) {
        const auto index = current.mutationCount - 1u;
        harken::CompletionMutationBinding mutation{current.occurrence, current.owner};
        if (current.composite.Valid()) {
            harken::KnownScheduleLeafV1 leaf{};
            const bool captured = current.compositePrepared
                ? engine.compositeCompletionOwners.CapturePreparedLeaf(current.composite, index, &leaf)
                : engine.compositeCompletionOwners.CaptureLeaf(current.composite, index, &leaf);
            if (!captured) return false;
            mutation = {leaf.occurrence, leaf.predicate.owner};
        }
        if (!engine.ledger.ClearCompletionMutationExact(current.voices[index]->ledgerSlot, mutation)) return false;
        --current.mutationCount;
    }
    if (current.ownerPinned) {
        if (!engine.timelineOccurrences.RollbackCompletionOwnerPinExact(current.occurrence, current.owner)) return false;
        current.ownerPinned = false;
    }
    return true;
}

bool ValidateFrontierQueueBindings(void* opaque) noexcept {
    auto* binding = static_cast<harken::EngineFrontierQueueBindingOwnerContext*>(opaque);
    return binding != nullptr && binding->current != nullptr && binding->current->engine != nullptr;
}

bool CommitFrontierQueueBindings(void* opaque, std::uint64_t) noexcept {
    return ValidateFrontierQueueBindings(opaque);
}

bool CancelFrontierQueueCurrentOwner(void* opaque) noexcept {
    auto& current = *static_cast<harken::EngineFrontierQueueCurrentOwnerContext*>(opaque);
    auto& engine = *current.engine;
    current.originalSingleDecisionCommitProof.Release();
    if (current.mutationCount != 0 || current.ownerPinned) return false;
    if (current.sourceCompletionExited) return true;
    harken::EngineActionPlayScratch::PreparedCompositeOwnerContext composite{
        &engine.compositeCompletionOwners, &current.composite, &engine.timelineOccurrences,
        &current.compositePrepared, !current.compositePrepared && current.composite.Valid()};
    if (!CancelPreparedCompositeOwner(&composite)) return false;
    const auto cancelOccurrence = [&](auto& token, bool& prepared) {
        harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext owner{
            &engine.timelineOccurrences, &token, &prepared};
        return CancelPreparedOccurrenceOwner(&owner);
    };
    for (std::uint32_t index = current.leafCount; index-- > 0;)
        if (!cancelOccurrence(current.leafOccurrences[index], current.leafPrepared[index])) return false;
    if (!cancelOccurrence(current.occurrence, current.occurrencePrepared)) return false;
    if (current.canonicalInitial) {
        current.sourceCompletionExited = true;
        return true;
    }
    auto* row = engine.ResolvePlayableService(current.service);
    if (row == nullptr) return false;
    harken::EngineActionPlayScratch::PreparedDecisionOwnerContext decision{
        &engine.decisions, &current.decision, &row->QueueFiling().queueDecision, &row->ticket, current.decisionCommitted};
    const bool cancelled = CancelPreparedDecisionOwner(&decision);
    current.decisionCommitted = decision.committed;
    return cancelled;
}

bool CommitRetargetQueueCurrent(harken::EngineRetargetQueueOwnerContext& queue, std::uint64_t ticket) noexcept {
    auto& engine = *queue.engine;
    auto& current = queue.current;
    auto* row = engine.ResolvePlayableService(queue.service);
    if (row == nullptr) return false;
    harken::EngineActionPlayScratch::PreparedDecisionOwnerContext decision{
        &engine.decisions, &current.decision, &row->QueueFiling().queueDecision, &row->ticket, current.decisionCommitted};
    const bool committed = CommitPreparedDecisionOwner(&decision, ticket);
    current.decisionCommitted = decision.committed;
    if (!committed) return false;
    row->QueuePayload().queueTicket = ticket;
    harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext occurrence{
        &engine.timelineOccurrences, &current.occurrence, &current.occurrencePrepared};
    return CommitPreparedOccurrenceOwner(&occurrence, ticket);
}

bool CancelRetargetQueueCurrent(harken::EngineRetargetQueueOwnerContext& queue) noexcept {
    auto& engine = *queue.engine;
    auto& current = queue.current;
    harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext occurrence{
        &engine.timelineOccurrences, &current.occurrence, &current.occurrencePrepared};
    if (!CancelPreparedOccurrenceOwner(&occurrence)) return false;
    auto* row = engine.ResolvePlayableService(queue.service);
    if (row == nullptr) return false;
    harken::EngineActionPlayScratch::PreparedDecisionOwnerContext decision{
        &engine.decisions, &current.decision, &row->QueueFiling().queueDecision, &row->ticket, current.decisionCommitted};
    const bool cancelled = CancelPreparedDecisionOwner(&decision);
    current.decisionCommitted = decision.committed;
    return cancelled;
}

bool CancelPreparedQueueCompletionBindings(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    const auto clearSide = [&](auto& voices, std::uint32_t& mutationCount,
                               harken::OccurrenceToken occurrence,
                               harken::CompletionOwnerRef owner, bool& pinned,
                               harken::CompositeCompletionOwnerToken composite,
                               bool compositePrepared) noexcept {
        if (compositePrepared && !engine.ReleaseOriginalCompositeLeafPreparationProofs(composite)) return false;
        for (std::uint32_t i = 0; i < mutationCount; ++i)
            if (i >= voices.size() || !engine.ReleaseOriginalQueuePreparationProofs(voices[i])) return false;
        while (mutationCount != 0) {
            const auto index = mutationCount - 1u;
            if (index >= voices.size()) return false;
            harken::CompletionMutationBinding binding{occurrence, owner};
            if (composite.Valid()) {
                harken::KnownScheduleLeafV1 leaf{};
                const bool captured = compositePrepared
                    ? engine.compositeCompletionOwners.CapturePreparedLeaf(composite, index, &leaf)
                    : engine.compositeCompletionOwners.CaptureLeaf(composite, index, &leaf);
                if (!captured) return false;
                binding = {leaf.occurrence, leaf.predicate.owner};
            }
            if (!engine.ledger.ClearCompletionMutationExact(voices[index].ledgerSlot, binding)) return false;
            --mutationCount;
        }
        if (pinned) {
            if (!engine.timelineOccurrences.RollbackCompletionOwnerPinExact(occurrence, owner)) return false;
            pinned = false;
        }
        return true;
    };
    const bool successor = clearSide(scratch.queueSuccessorVoiceStarts,
        scratch.queueSuccessorCompletionMutationCount, scratch.queueSuccessorOccurrence,
        scratch.queueSuccessorOwner, scratch.queueSuccessorCompletionOwnerPinned,
        scratch.queueSuccessorCompositeOwner, scratch.queueSuccessorCompositeOwnerPrepared);
    if (scratch.queueFutureExecution) return successor;
    return clearSide(scratch.voiceStarts, scratch.queueCompletionMutationCount,
        scratch.queueCurrentOccurrence, scratch.queueCurrentOwner, scratch.queueCompletionOwnerPinned,
        scratch.queueCurrentCompositeOwner, scratch.queueCurrentCompositeOwnerPrepared) && successor;
}

bool ValidatePreparedActionResourceOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedActionResourceOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr ||
        context->scratch == nullptr || context->row == nullptr) {
        return false;
    }
    const auto& scratch = *context->scratch;
    if (scratch.queueTransitionPrepared &&
        !scratch.queueTransition.Valid()) {
        return false;
    }
    for (std::uint32_t index = 0;
         index < scratch.queueSourceControlArmCount; ++index) {
        if (!context->row->QueueFiling().queueTransitionGroupArms[index].Valid()) {
            return false;
        }
    }
    if (scratch.queueArmGroupPrepared &&
        !scratch.queueArmGroup.Valid()) {
        return false;
    }
    if (scratch.queueInitialLaneArmGroupPrepared &&
        !scratch.queueInitialLaneArmGroup.Valid()) return false;
    if (scratch.queueConditional.Valid() == false && context->row->HasFeatureArrays() &&
        context->row->QueueFiling().queueConditional.Valid()) {
        return false;
    }
    for (std::uint32_t index = 0;
         index < scratch.queueGroupSliceCount; ++index) {
        if (!scratch.queueGroupSlices[index].Valid()) return false;
    }
    return true;
}

bool CommitPreparedActionResourceOwner(
    void* opaque, std::uint64_t ticket) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedActionResourceOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr ||
        context->scratch == nullptr || context->row == nullptr) {
        return false;
    }
    auto& engine = *context->engine;
    auto& scratch = *context->scratch;
    auto& row = *context->row;
    if (scratch.queueTransitionPrepared) {
        if (!engine.transitionInstances.CommitPreparedAcquire(
                scratch.queueTransition)) {
            return false;
        }
        scratch.queueTransitionPrepared = false;
        context->transitionCommitted = true;
    }
    for (std::uint32_t index = 0;
         index < scratch.queueSourceControlArmCount; ++index) {
        if (!engine.timelineArms.CommitPrepared(
                row.QueueFiling().queueTransitionGroupArms[index])) {
            return false;
        }
        context->sourceArmsCommitted = index + 1u;
    }
    if (scratch.queueArmGroupPrepared) {
        if (!engine.armGroups.CommitPrepared(scratch.queueArmGroup)) {
            return false;
        }
        scratch.queueArmGroupPrepared = false;
        context->armGroupCommitted = true;
    }
    if (scratch.queueInitialLaneArmGroupPrepared) {
        if (!engine.armGroups.CommitPrepared(
                scratch.queueInitialLaneArmGroup)) return false;
        scratch.queueInitialLaneArmGroupPrepared = false;
        context->queueInitialLaneArmGroupCommitted = true;
    }
    if (scratch.queueConditional.Valid()) {
        if (context->preparedQueue == nullptr) {
            context->preparedQueue = &scratch.queueInstance;
            context->conditionalQueue = scratch.queueInstance.Token();
            context->conditionalDecision = row.QueueFiling().queueDecision;
        }
        if (!context->preparedQueue->Valid() ||
            !context->conditionalQueue.Valid() ||
            !context->conditionalDecision.Valid()) {
            return false;
        }
        harken::ConditionalQueueVersionToken conditional{};
        if (!engine.queueInstances.CommitPreparedConditional(
                &scratch.queueConditional, &conditional)) {
            return false;
        }
        row.QueueFiling().queueConditional = conditional;
        context->conditionalVersion = conditional;
        context->conditionalCommitted = true;
    }
    for (std::uint32_t index = 0;
         index < scratch.queueGroupSliceCount; ++index) {
        if (!engine.timelinePool.CommitPreparedPlan03GroupSlice(
                &scratch.queueGroupSlices[index],
                &scratch.queueCommittedGroupSlices[index])) {
            return false;
        }
        context->groupSlicesCommitted = index + 1u;
    }
    // The selected VC batch remains private until its real Frontier bindings exist.
    if (!scratch.initialForestPublication && !scratch.privateInitialVcPageCohort.pageBatchSelected &&
        scratch.queueTransactions.Valid()) {
        if (!engine.timelinePool.CommitPreparedTransactionBatch(
                &scratch.queueTransactions, ticket)) {
            return false;
        }
        context->transactionsCommitted = true;
    }
    return true;
}

template<class Visitor>
bool VisitInitialScheduleAttempts(harken::Engine& engine,
    harken::EngineActionPlayScratch& root, Visitor&& visit, std::size_t depth = 0) noexcept {
    if (depth >= engine.actionPlayScratch.size() || !visit(root)) return false;
    if (root.storage.scheduleChildren == nullptr) return true;
    const auto& children = *root.storage.scheduleChildren;
    if (children.count > children.owners.size()) return false;
    for (std::uint32_t index = 0; index < children.count; ++index) {
        const auto& owner = children.owners[index];
        auto* child = FindFrontierAttempt(engine, owner.child);
        if (owner.engine != &engine || child == nullptr ||
            FindFrontierAttempt(engine, owner.parent) != &root ||
            !VisitInitialScheduleAttempts(engine, *child, visit, depth + 1u)) return false;
    }
    return true;
}

bool HasPendingNativeScheduleChildren(const harken::EnginePlayableServiceRow& row) noexcept {
    if (row.scheduleTerminalChild != nullptr && row.scheduleTerminalChild->pendingEntry) return true;
    if (row.scheduleAggregate != nullptr)
        for (const auto& child : row.scheduleAggregate->children)
            if (child.pendingEntry) return true;
    return false;
}

template <typename Visitor>
bool VisitInitialAttemptServices(harken::Engine& engine,
    harken::EngineActionPlayScratch& attempt, Visitor&& visit) noexcept {
    if (attempt.frontierServiceCount > attempt.storage.frontierServices.size()) return false;
    if (attempt.row != nullptr && !visit(*attempt.row)) return false;
    for (std::uint32_t index = 0; index < attempt.frontierServiceCount; ++index) {
        auto* service = engine.ResolvePlayableService(attempt.storage.frontierServices[index].service);
        if (service == nullptr || service == attempt.row || !visit(*service)) return false;
    }
    return true;
}

bool ReleaseNativeEntryDependency(harken::EnginePlayableServiceRow& row,
    std::uint64_t completedAudioSequence) noexcept {
    auto* owned = row.nativeEntryDependency.get();
    if (owned == nullptr) return true;
    if (owned->appliedSignal != nullptr && owned->entryBound) return false;
    // Both group loans precede the receipt loan; partial release remains owned.
    if (!owned->memberPin.Release(completedAudioSequence) ||
        !owned->primaryPin.Release(completedAudioSequence) ||
        !owned->coordinatorPin.Release()) return false;
    row.nativeEntryDependency.reset();
    return true;
}

bool ReleaseUnusedNativeEntrySeed(harken::EnginePlayableServiceRow& row,
    std::uint64_t completedAudioSequence) noexcept {
    return row.nativeEntryDependency == nullptr || row.nativeEntryDependency->entryBound ||
        HasPendingNativeScheduleChildren(row) || ReleaseNativeEntryDependency(row, completedAudioSequence);
}

bool MatchesNativeEntryDependency(harken::Engine& engine,
    const harken::EngineNativeEntryDependency& owned,
    const harken::EnginePlayableServiceRow& child) noexcept {
    const auto* parent = engine.ResolvePlayableService(owned.parentService);
    if (parent == nullptr || !parent->InvocationValid() || !child.InvocationValid() ||
        parent->partition.slot != owned.parentPartition.slot ||
        parent->partition.generation != owned.parentPartition.generation ||
        parent->invocationGeneration != owned.invocationGeneration ||
        parent->invocation != child.invocation || child.invocationGeneration != owned.invocationGeneration ||
        !owned.entry.Valid() || !owned.primary.Exact() || !owned.member.Exact() ||
        !owned.coordinatorPin.Valid() || owned.coordinatorPin.Owner() != &engine.decisions ||
        !SameCanonicalDecision(owned.coordinatorPin.Token(), owned.entry.coordinator)) return false;
    if (owned.appliedSignal != nullptr) {
        if (!engine.decisions.IsAppliedSignalDependencyFor(*owned.appliedSignal,
                owned.entry, owned.primary, owned.member, engine.mixer.BlocksRendered())) return false;
    } else if (!engine.timelinePool.IsPlan03GroupReaderFor(owned.primaryPin, owned.primary) ||
        !engine.timelinePool.IsPlan03GroupReaderFor(owned.memberPin, owned.member)) return false;
    // Preserve every actual service edge. The outer signal is not the immediate parent.
    const auto* current = &child;
    for (std::size_t depth = 0; depth < engine.playableServices.size(); ++depth) {
        if (current == parent) return true;
        if (!current->parentService.Valid()) return false;
        const auto* next = engine.ResolvePlayableService(current->parentService);
        if (next == nullptr || next == current || next->invocation != child.invocation ||
            next->invocationGeneration != child.invocationGeneration) return false;
        current = next;
    }
    return false;
}

bool CloneNativeEntryDependency(harken::Engine& engine,
    const harken::EngineNativeEntryDependency& original,
    harken::EnginePlayableServiceRow& child) noexcept {
    if (child.nativeEntryDependency != nullptr) return false;
    try {
        child.nativeEntryDependency = std::make_unique<harken::EngineNativeEntryDependency>();
    } catch (const std::bad_alloc&) { return false; }
    auto& owned = *child.nativeEntryDependency;
    owned.parentService = original.parentService;
    owned.parentPartition = original.parentPartition;
    owned.invocationGeneration = original.invocationGeneration;
    owned.entry = original.entry;
    owned.primary = original.primary;
    owned.member = original.member;
    // Clone keeps the actual original receipt alive, including after its Decision retires.
    if (!engine.decisions.CloneFuturePin(original.coordinatorPin, &owned.coordinatorPin)) return false;
    if (original.appliedSignal != nullptr) {
        try {
            owned.appliedSignal = std::make_unique<harken::FrontierAppliedSignalDependency>(*original.appliedSignal);
        } catch (const std::bad_alloc&) { return false; }
    } else if (!engine.timelinePool.ClonePlan03GroupReader(original.primaryPin, &owned.primaryPin) ||
        !engine.timelinePool.ClonePlan03GroupReader(original.memberPin, &owned.memberPin)) return false;
    return MatchesNativeEntryDependency(engine, owned, child);
}

enum class NativeEntryRetentionStatus : std::uint8_t { Ready, Waiting, Failed };

NativeEntryRetentionStatus RetainAppliedNativeEntryDependency(harken::Engine& engine,
    harken::EnginePlayableServiceRow& row) noexcept {
    using Status = NativeEntryRetentionStatus;
    auto* owned = row.nativeEntryDependency.get();
    if (owned == nullptr) return Status::Ready;
    // A published child still using the original page binding retains both readers.
    if (owned->entryBound) return Status::Waiting;
    if (!MatchesNativeEntryDependency(engine, *owned, row)) return Status::Failed;
    const auto completed = engine.mixer.BlocksRendered();
    if (owned->appliedSignal == nullptr) {
        const auto* activation = engine.decisions.ResolveFrontierActivation(owned->entry.coordinator);
        harken::FrontierActivationReceipt receipt{};
        if (activation == nullptr) return Status::Failed;
        const auto read = activation->Read(owned->entry, completed, &receipt);
        if (read == harken::FrontierReceiptRead::InFlight) return Status::Waiting;
        if (read != harken::FrontierReceiptRead::Ready ||
            receipt.outcome != harken::FrontierReceiptOutcome::Applied) return Status::Failed;
        std::unique_ptr<harken::FrontierAppliedSignalDependency> proof;
        try {
            proof = std::make_unique<harken::FrontierAppliedSignalDependency>();
        } catch (const std::bad_alloc&) { return Status::Waiting; }
        if (!engine.decisions.CaptureAppliedSignalDependency(owned->coordinatorPin,
                owned->primaryPin, owned->memberPin, engine.timelinePool, completed, proof.get())) return Status::Failed;
        owned->appliedSignal = std::move(proof);
    }
    // Release checks the strict-greater actual read fence. A partial release stays owned.
    if (!owned->memberPin.Release(completed) || !owned->primaryPin.Release(completed)) return Status::Waiting;
    return Status::Ready;
}

template<class Visitor>
bool VisitPrivateInitialForest(harken::Engine& engine,
    harken::EngineActionPlayScratch& root, Visitor&& visit, std::size_t depth = 0) noexcept {
    if (depth >= engine.actionPlayScratch.size() || !visit(root)) return false;
    if (root.storage.scheduleChildren == nullptr) return true;
    const auto& children = *root.storage.scheduleChildren;
    if (children.count > children.owners.size()) return false;
    for (std::uint32_t index = 0; index < children.count; ++index) {
        const auto& owner = children.owners[index];
        if (owner.engine != &engine || FindFrontierAttempt(engine, owner.parent) != &root) return false;
        if (!owner.child.Valid()) continue;
        auto* child = FindFrontierAttempt(engine, owner.child);
        if (child == nullptr || !VisitPrivateInitialForest(engine, *child, visit, depth + 1u)) return false;
    }
    return true;
}

bool SealPrivateInitialForest(harken::Engine& engine,
    harken::EngineActionPlayScratch& root) noexcept {
    const auto privateGroup = [&](const harken::Plan03GroupSliceIdentity& identity) noexcept {
        if (!identity.Exact()) return true;
        harken::Plan03ExactGroupSnapshot snapshot{};
        return engine.timelinePool.CaptureExactPlan03Group(identity, &snapshot) &&
            snapshot.publicationHeld && snapshot.pagePublicationHolds != 0 &&
            !snapshot.page.frozen && snapshot.lastAudioSequence == 0 &&
            snapshot.effectiveLease.state == harken::AudioSliceState::Ready;
    };
    // First seal the complete producer graph. No dependency is released until
    // every still-owned attempt is unable to publish or expose a transaction.
    if (!VisitPrivateInitialForest(engine, root, [&](auto& attempt) noexcept {
        if (attempt.initialForestCancellationSealed) return true;
        const auto phase = attempt.storage.phase;
        if (phase != harken::EngineFrontierAttemptPhase::Preparing &&
            phase != harken::EngineFrontierAttemptPhase::PrivateCommitted &&
            phase != harken::EngineFrontierAttemptPhase::CancelPending) return false;
        const auto* activation = engine.decisions.ResolveFrontierActivation(attempt.frontierCoordinator);
        if (activation != nullptr && activation->State() != harken::FrontierReceiptState::Prepared) return false;
        if (!privateGroup(attempt.frontierDescriptor.primary) ||
            (activation != nullptr && attempt.queueTransactions.Valid() &&
             !engine.timelinePool.CanReleasePreparedTransactionPublication(attempt.queueTransactions))) return false;
        attempt.initialForestCancellationSealed = true;
        return true;
    })) return false;
    return VisitPrivateInitialForest(engine, root, [&](auto& attempt) noexcept {
        if (!attempt.initialForestCancellationSealed) return false;
        return VisitInitialAttemptServices(engine, attempt, [&](auto& row) noexcept {
            if (row.nativeEntryDependency == nullptr) return true;
            const auto& owned = *row.nativeEntryDependency;
            const auto* parent = engine.decisions.ResolveFrontierActivation(owned.entry.coordinator);
            if (parent == nullptr || !(parent->Descriptor().entry == owned.entry) ||
                !(parent->Descriptor().primary == owned.primary)) return false;
            if (parent->State() == harken::FrontierReceiptState::Prepared &&
                ((owned.primaryPin.Valid() && !privateGroup(owned.primary)) ||
                 (owned.memberPin.Valid() && !privateGroup(owned.member)))) return false;
            // A private child with applied evidence keeps its holder until the
            // direct exposure owner detaches that exact child binding.
            if (owned.appliedSignal != nullptr && owned.entryBound) return true;
            // Every child binding is sealed and private. An earlier applied parent
            // keeps its original read fence; a legal fence wait retains these loans.
            return ReleaseNativeEntryDependency(row, engine.mixer.BlocksRendered());
        });
    });
}

bool SealNativeEntryPrivateOwner(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    if (scratch.initialNativeForestOwner.Valid()) {
        auto* root = FindFrontierAttempt(engine, scratch.initialNativeForestOwner);
        return root != nullptr && root->initialForestPublication &&
            (root->initialQueueSignalAdmission != nullptr || root->nativeEntrySeedService.Valid() ||
             root->initialForestCancellationSealed) && SealPrivateInitialForest(engine, *root);
    }
    // A delayed entry owns a fresh attempt; its prerequisite can already be
    // applied. Its own unpublished binding must be detached before the loans.
    return true;
}

bool IsInitialNativeAdmissionDecision(harken::Engine& engine,
    harken::EngineActionPlayScratch& root, harken::DecisionToken decision) noexcept {
    bool found = false;
    const bool valid = VisitInitialScheduleAttempts(engine, root, [&](auto& attempt) noexcept {
        if (attempt.row == nullptr) return false;
        const auto owns = [&](const harken::EnginePlayableServiceRow& row) noexcept {
            return SameCanonicalDecision(decision, row.variableControlDiscreteDecision) ||
                SameCanonicalDecision(decision, row.variableControlContinuousDecision);
        };
        found = found || owns(*attempt.row);
        for (std::uint32_t index = 0; index < attempt.variableControlNestedVariableControlCount; ++index) {
            const auto* row = engine.ResolvePlayableService(attempt.variableControlNestedServices[index]);
            if (row == nullptr) return false;
            found = found || owns(*row);
        }
        for (const auto& queue : attempt.initialQueueEntryAdmissions)
            found = found || (queue != nullptr && SameCanonicalDecision(decision, queue->decision));
        return true;
    });
    return decision.Valid() && valid && found;
}

bool CollectVariableScheduleInitialArms(harken::Engine& engine,
    harken::EngineActionPlayScratch& parent) noexcept {
    auto& row = *parent.row;
    if (!parent.initialNativeForestOwner.Valid() || row.scheduleVariableChildren == nullptr) return true;
    std::uint32_t discrete = 0, continuous = 0;
    const bool valid = VisitInitialScheduleAttempts(engine, parent, [&](auto& attempt) noexcept {
        if (&attempt == &parent) return true;
        for (std::uint32_t index = 0; index < attempt.voiceStartCount; ++index) {
            const auto token = attempt.voiceStarts[index].arm;
            harken::TimelineArmObservation arm{};
            if (!engine.timelineArms.Observe(token, &arm)) return false;
            const bool discreteArm = row.variableControlDiscreteDecision.Valid() &&
                SameCanonicalDecision(arm.parentGroup.decision, row.variableControlDiscreteDecision);
            const bool continuousArm = row.variableControlContinuousDecision.Valid() &&
                SameCanonicalDecision(arm.parentGroup.decision, row.variableControlContinuousDecision);
            if (!discreteArm && !continuousArm) {
                if (!IsInitialNativeAdmissionDecision(engine, parent, arm.parentGroup.decision)) return false;
                continue;
            }
            auto storage = discreteArm ? row.variableControlInitialArms.Discrete()
                : row.variableControlInitialArms.Continuous();
            const auto expected = discreteArm ? row.variableControlInitialDiscreteMemberCount
                : row.variableControlInitialContinuousMemberCount;
            if (arm.memberIndex >= expected || arm.memberIndex >= storage.size() || storage[arm.memberIndex].Valid())
                return false;
            storage[arm.memberIndex] = token;
            ++(discreteArm ? discrete : continuous);
        }
        return true;
    });
    return valid && discrete == row.variableControlInitialDiscreteMemberCount &&
        continuous == row.variableControlInitialContinuousMemberCount;
}

using InitialQueueEntryAdmission = harken::EngineActionPlayScratch::InitialQueueEntryAdmission;

harken::EnginePlayableServiceReference PlayableServiceReference(
    const harken::EnginePlayableServiceRow&) noexcept;
bool FreezeInitialQueuePrograms(harken::Engine&, harken::EnginePlayableServiceRow&) noexcept;

InitialQueueEntryAdmission* FindInitialQueueEntryAdmission(
    harken::EngineActionPlayScratch& scratch,
    const harken::EnginePlayableServiceReference& service) noexcept {
    for (const auto& owned : scratch.initialQueueEntryAdmissions) {
        if (owned != nullptr && harken::Engine::SameSelectionServiceReference(owned->service, service))
            return owned.get();
    }
    return nullptr;
}

bool MatchesPendingScheduleEntryParent(harken::Engine&,
    const harken::EngineActionPlayScratch&, const harken::EnginePlayableServiceRow&) noexcept;

harken::EngineActionPlayScratch* ResolveInitialNativeQueueForest(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch) noexcept {
    const auto token = scratch.initialNativeForestOwner.Valid()
        ? scratch.initialNativeForestOwner : scratch.queueSignalEntryOwner;
    auto* root = FindFrontierAttempt(engine, token);
    if (root == nullptr || !root->initialForestPublication || !root->continuationExecution ||
        root->initialForestCancellationSealed) return nullptr;
    if (root->initialQueueSignalAdmission != nullptr) return root;
    const auto* seed = engine.ResolvePlayableService(root->nativeEntrySeedService);
    if (!root->nativeEntryForestRoot || seed == nullptr || seed->nativeEntryDependency == nullptr ||
        !MatchesPendingScheduleEntryParent(engine, *root, *seed) ||
        !MatchesNativeEntryDependency(engine, *seed->nativeEntryDependency, *seed)) return nullptr;
    return root;
}

bool ReserveInitialQueueEntryAdmission(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch, harken::EnginePlayableServiceRow& service,
    std::uint64_t entryFrame) noexcept {
    if (!scratch.initialForestPublication) return true;
    auto* root = ResolveInitialNativeQueueForest(engine, scratch);
    if (root == nullptr || !service.InvocationValid() ||
        service.ticket == 0 || scratch.storage.generation == 0 ||
        scratch.storage.phase != harken::EngineFrontierAttemptPhase::Preparing) return false;
    const auto reference = PlayableServiceReference(service);
    auto* existing = FindInitialQueueEntryAdmission(scratch, reference);
    if (existing != nullptr)
        return existing->decision.Valid() && existing->entryFrame == entryFrame &&
            !existing->prepared.Valid() && !existing->committed.Valid();
    try {
        auto owned = std::make_unique<InitialQueueEntryAdmission>(engine.config.maxArmsPerGroup);
        owned->service = reference;
        owned->entryFrame = entryFrame;
        scratch.initialQueueEntryAdmissions.push_back(std::move(owned));
    } catch (const std::bad_alloc&) { return false; }
    auto& owned = *scratch.initialQueueEntryAdmissions.back();
    harken::DecisionReserveRequest request{};
    request.ticket.sequence = service.ticket;
    request.world = service.Invocation().worldGeneration;
    request.transport = engine.timelinePool.Epoch();
    request.expectedContinuationGeneration = scratch.storage.generation;
    request.sliceCount = 1;
    if (!engine.decisions.Reserve(request, &owned.decision)) return false;
    // The signal root already owns its coordinator. A descendant attempt owns
    // its own native entry; several Queue services may share that entry frame.
    if (&scratch != root || root->nativeEntryForestRoot) scratch.nativeEntryDomain = true;
    return true;
}

bool ResolveInitialQueueEntrySourceAdmission(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch, harken::EnginePlayableServiceRow& resource,
    harken::ParentAudioGroupRef* group, std::uint16_t* member, bool* routed) noexcept {
    if (group == nullptr || member == nullptr || routed == nullptr) return false;
    *routed = false;
    if (!scratch.initialForestPublication ||
        (!scratch.initialNativeForestOwner.Valid() && !scratch.queueSignalEntryOwner.Valid())) return true;
    auto* root = ResolveInitialNativeQueueForest(engine, scratch);
    if (root == nullptr || !resource.InvocationValid()) return false;
    auto* service = &resource;
    for (std::size_t depth = 0; depth < engine.playableServices.size(); ++depth) {
        // A nearer VC owns its original Source admission even when an outer
        // Queue remains in the real ancestry. Lifecycle membership is separate.
        if (service->variableControlInstance.Valid() || service->variableControlIndependentFrontier)
            return true;
        InitialQueueEntryAdmission* native = nullptr;
        if (!VisitInitialScheduleAttempts(engine, *root, [&](auto& attempt) noexcept {
            auto* found = FindInitialQueueEntryAdmission(attempt, PlayableServiceReference(*service));
            if (found == nullptr) return true;
            if (native != nullptr) return false;
            native = found;
            return true;
        })) return false;
        if (native != nullptr) {
            if (!native->decision.Valid() || native->prepared.Valid() || native->committed.Valid() ||
                native->memberCount >= native->members.size() || native->memberCount >= UINT16_MAX)
                return false;
            *group = {native->decision};
            *member = static_cast<std::uint16_t>(native->memberCount++);
            *routed = true;
            return true;
        }
        const auto boundary = root->initialQueueSignalAdmission != nullptr
            ? root->initialQueueSignalAdmission->service : root->nativeEntrySeedService;
        if (harken::Engine::SameSelectionServiceReference(PlayableServiceReference(*service), boundary)) return true;
        // A real nested Queue must have reserved its own admission before any
        // descendant Source is born; an outer signal is not a substitute.
        if (service->queueMode) return false;
        if (!service->parentService.Valid()) return true;
        auto* parent = engine.ResolvePlayableService(service->parentService);
        if (parent == nullptr || parent == service || parent->invocation != resource.invocation ||
            parent->invocationGeneration != resource.invocationGeneration) return false;
        service = parent;
    }
    return false;
}

bool PrepareInitialQueueEntryGroups(harken::Engine& engine,
    harken::EngineActionPlayScratch& root) noexcept {
    return VisitInitialScheduleAttempts(engine, root, [&](auto& owner) noexcept {
        for (const auto& pointer : owner.initialQueueEntryAdmissions) {
            if (pointer == nullptr) return false;
            auto& native = *pointer;
            auto* service = engine.ResolvePlayableService(native.service);
            if (service == nullptr || !service->queueMode || !service->queueInstance.Valid() ||
                !native.decision.Valid() || native.group.Exact() || native.prepared.Valid() ||
                native.committed.Valid() || native.memberCount > native.members.size()) return false;
            std::uint32_t count = 0;
            if (!VisitInitialScheduleAttempts(engine, root, [&](auto& attempt) noexcept {
                for (std::uint32_t index = 0; index < attempt.voiceStartCount; ++index) {
                    const auto token = attempt.voiceStarts[index].arm;
                    harken::TimelineArmObservation observed{};
                    if (!token.Valid() || !engine.timelineArms.Observe(token, &observed)) return false;
                    if (!SameCanonicalDecision(observed.parentGroup.decision, native.decision)) continue;
                    if (observed.memberIndex >= native.memberCount ||
                        native.members[observed.memberIndex].Valid()) return false;
                    native.members[observed.memberIndex] = token;
                    ++count;
                }
                return attempt.row != nullptr && FreezeInitialQueuePrograms(engine, *attempt.row);
            }) || count != native.memberCount || count > UINT16_MAX ||
                !engine.armGroups.Reserve(native.decision, native.members.data(),
                    static_cast<std::uint16_t>(count), &native.armGroup)) return false;
            harken::Plan03GroupSliceInput input{};
            input.executeFrame = native.entryFrame;
            input.decision = native.decision;
            input.members = native.members.data();
            input.memberCount = static_cast<std::uint16_t>(count);
            if (engine.timelinePool.PreparePlan03GroupSlice(input, engine.timelineArms, &native.prepared) !=
                    harken::Plan03GroupReserveStatus::Committed ||
                !engine.timelinePool.CommitPreparedPlan03GroupSlice(&native.prepared, &native.committed, true)) return false;
            auto& groups = engine.timelineGroupCaptureScratch;
            const auto groupCount = engine.timelinePool.CaptureLivePlan03Groups(groups.data(), groups.size());
            if (groupCount > groups.size()) return false;
            for (std::size_t index = 0; index < groupCount; ++index) {
                const auto& actual = groups[index];
                if (!engine.timelinePool.MatchesCommittedPlan03GroupSlice(native.committed, actual.identity)) continue;
                if (native.group.Exact() || actual.identity.backing != harken::Plan03GroupBacking::Page ||
                    !SameCanonicalDecision(actual.identity.decision, native.decision) ||
                    actual.identity.sliceIndex != input.sliceIndex || actual.memberCount != count ||
                    actual.sourceControlCount != 0 || (count != 0 && actual.members == nullptr)) return false;
                for (std::uint32_t member = 0; member < count; ++member)
                    if (!harken::Engine::SameOriginalSingleArm(actual.members[member], native.members[member])) return false;
                native.group = actual.identity;
            }
            if (!native.group.Exact()) return false;
        }
        return true;
    });
}

bool ReleaseInitialQueueEntryAdmissionOwners(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    for (const auto& pointer : scratch.initialQueueEntryAdmissions) {
        if (pointer == nullptr || !pointer->decisionCommitted || pointer->decisionCancelled || !pointer->initialBound ||
            pointer->prepared.Valid() || !pointer->committed.Valid() ||
            !engine.timelinePool.CanReleaseCommittedPlan03GroupSliceOwnership(pointer->committed)) return false;
    }
    for (const auto& pointer : scratch.initialQueueEntryAdmissions)
        if (!engine.timelinePool.ReleaseCommittedPlan03GroupSliceOwnership(&pointer->committed)) return false;
    scratch.initialQueueEntryAdmissions.clear();
    return true;
}

harken::UnpublishedGroupArmCancellationStatus CancelUnpublishedInitialGroupSources(
    harken::Engine& engine, harken::EngineActionPlayScratch& scratch,
    std::span<harken::CommittedPlan03GroupSlice*> originals,
    std::span<harken::UnpublishedGroupCancellationHold> groupStorage,
    std::span<harken::UnpublishedArmCancellationHold> armStorage,
    std::span<harken::EnginePreparedTimelineVoiceStart*> voices,
    std::span<harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext*> owners,
    std::span<const harken::TimelineArmTable::OriginalUnpublishedSourceDisposition*> sources) noexcept {
    using Status = harken::UnpublishedGroupArmCancellationStatus;
    if (originals.empty()) return Status::NotEligible;
    if (groupStorage.size() < originals.size() || voices.size() < armStorage.size() ||
        owners.size() < armStorage.size() || sources.size() < armStorage.size()) return Status::StorageTooSmall;
    if (!VisitInitialScheduleAttempts(engine, scratch, [&](auto& attempt) noexcept {
        ReleasePreparedTimelineVoiceProofs(attempt);
        return true;
    })) return Status::Busy;
    std::fill(voices.begin(), voices.end(), nullptr);
    std::fill(owners.begin(), owners.end(), nullptr);
    std::fill(sources.begin(), sources.end(), nullptr);
    harken::UnpublishedGroupArmCancellationProof proof;
    const auto status = engine.timelinePool.BeginUnpublishedGroupArmCancellation(
        originals, engine.timelineArms, groupStorage, armStorage, &proof);
    if (status != Status::Held) return status;
    const auto count = proof.OriginalArmCount();
    // Traverse only the original child-attempt ownership graph.
    for (std::size_t index = 0; index < count; ++index) {
        const auto arm = proof.OriginalArm(index);
        if (!VisitInitialScheduleAttempts(engine, scratch, [&](auto& attempt) noexcept {
            const auto find = [&](auto& starts, std::uint32_t size) noexcept {
                if (size > starts.size()) return false;
                for (std::uint32_t i = 0; i < size; ++i) {
                    auto& candidate = starts[i];
                    if (!harken::OriginalSourceSubmissionRegistry::SameToken(candidate.arm, arm)) continue;
                    if (voices[index] != nullptr || !candidate.armOwnershipHeld) return false;
                    voices[index] = &candidate;
                    for (const auto side : attempt.VoiceOwnerContextSides()) {
                        for (auto& owner : side) {
                            if (owner.token != &candidate) continue;
                            if (owners[index] != nullptr || owner.engine != &engine) return false;
                            owners[index] = &owner;
                        }
                    }
                }
                return true;
            };
            return find(attempt.voiceStarts, attempt.voiceStartCount) &&
                find(attempt.queueSuccessorVoiceStarts, attempt.queueSuccessorVoiceStartCount);
        }) || voices[index] == nullptr) return Status::Busy;
    }
    if (!VisitInitialScheduleAttempts(engine, scratch, [&](auto& attempt) noexcept {
        return CancelPreparedQueueCompletionBindings(engine, attempt);
    })) return Status::Busy;
    for (std::size_t index = count; index-- > 0;) {
        auto& voice = *voices[index];
        const bool disposed = owners[index] != nullptr
            ? CancelPreparedTimelineVoiceOwnerImpl(owners[index], &proof)
            : voice.prepared ? CancelPreparedTimelineVoiceStart(engine, &voice, &proof)
                             : RollbackCommittedTimelineVoiceStart(engine, &voice, &proof);
        if (!disposed) return Status::Busy;
        sources[index] = engine.originalSourceSubmissions.OriginalUnpublishedDisposition(voice.arm);
    }
    const auto finished = engine.timelinePool.FinishUnpublishedGroupArmCancellation(
        proof, {sources.data(), count});
    if (finished != Status::Consumed) return Status::Busy;
    // Native consumption is the sole permission to retire the original aliases.
    for (std::size_t index = 0; index < count; ++index) {
        auto& voice = *voices[index];
        assert(proof.ConsumedOriginalArm(voice.arm));
        voice.armOwnershipHeld = false;
        if (engine.voices.ReleaseObserved(voice.releaseObserver))
            (void)engine.ClearOriginalTimelineVoiceInstallIdentity(
                voice.renderHandle, voice.releaseObserver, voice.arm);
        voice = {};
        if (owners[index] != nullptr) owners[index]->committed = false;
    }
    return Status::Consumed;
}

harken::UnpublishedGroupArmCancellationStatus CancelUnpublishedActionGroupSources(
    harken::Engine& engine, harken::EngineActionPlayScratch& scratch,
    harken::EngineActionPlayScratch::PreparedActionResourceOwnerContext& resources) noexcept {
    using Status = harken::UnpublishedGroupArmCancellationStatus;
    if (resources.groupSlicesCommitted == 0) return Status::NotEligible;
    if (resources.groupSlicesCommitted > scratch.queueCommittedGroupSlices.size()) return Status::StorageTooSmall;
    std::array<harken::CommittedPlan03GroupSlice*, 2> originals{};
    std::array<harken::UnpublishedGroupCancellationHold, 2> groupStorage{};
    constexpr std::size_t kSourceCapacity = 2u * harken::kMaxKnownScheduleLeaves;
    std::array<harken::UnpublishedArmCancellationHold, kSourceCapacity> armStorage{};
    std::array<harken::EnginePreparedTimelineVoiceStart*, kSourceCapacity> voices{};
    std::array<harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext*, kSourceCapacity> owners{};
    std::array<const harken::TimelineArmTable::OriginalUnpublishedSourceDisposition*, kSourceCapacity> sources{};
    for (std::uint32_t index = 0; index < resources.groupSlicesCommitted; ++index)
        originals[index] = &scratch.queueCommittedGroupSlices[index];
    const auto result = CancelUnpublishedInitialGroupSources(engine, scratch,
        {originals.data(), resources.groupSlicesCommitted}, groupStorage, armStorage, voices, owners, sources);
    if (result == Status::Consumed) resources.groupSlicesCommitted = 0;
    return result;
}

bool CancelPreparedActionResourceOwnerImpl(void* opaque, bool preserveCanonicalResources) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedActionResourceOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr ||
        context->scratch == nullptr || context->row == nullptr) {
        return false;
    }
    auto& engine = *context->engine;
    auto& scratch = *context->scratch;
    auto& row = *context->row;
    bool resolved = true;
    if (scratch.queueTransactions.Valid()) {
        const bool cancelled = engine.timelinePool.CancelPreparedTransactionBatch(
            &scratch.queueTransactions);
        if (cancelled) context->transactionsCommitted = false;
        resolved = cancelled && resolved;
    } else {
        context->transactionsCommitted = false;
    }
    bool preparedSlicesResolved = true;
    for (std::uint32_t index = scratch.queueGroupSliceCount;
         index-- > context->groupSlicesCommitted;) {
        if (scratch.queueGroupSlices[index].Valid()) {
            preparedSlicesResolved =
                engine.timelinePool.CancelPreparedPlan03GroupSlice(
                    &scratch.queueGroupSlices[index]) &&
                preparedSlicesResolved;
        }
    }
    if (!preparedSlicesResolved) return false;
    const auto joint = CancelUnpublishedActionGroupSources(engine, scratch, *context);
    if (joint != harken::UnpublishedGroupArmCancellationStatus::NotEligible &&
        joint != harken::UnpublishedGroupArmCancellationStatus::Consumed) return false;
    while (context->groupSlicesCommitted != 0) {
        const std::uint32_t index = context->groupSlicesCommitted - 1u;
        if (!engine.timelinePool.RollbackCommittedPlan03GroupSlice(
                &scratch.queueCommittedGroupSlices[index])) {
            resolved = false;
            break;
        }
        --context->groupSlicesCommitted;
    }
    if (context->groupSlicesCommitted == 0 && preparedSlicesResolved) {
        scratch.queueGroupSliceCount = 0;
    }
    resolved = !context->transactionsCommitted &&
               scratch.queueGroupSliceCount == 0 &&
               preparedSlicesResolved && resolved;
    if (context->conditionalCommitted) {
        const bool initializing = context->preparedQueue != nullptr && context->preparedQueue->Valid();
        const bool retired = initializing
            ? engine.queueInstances.RollbackInitializingConditional(*context->preparedQueue,
                context->conditionalQueue, context->conditionalVersion, context->conditionalDecision)
            : engine.queueInstances.RetireConditionalForAbort(context->conditionalQueue,
                context->conditionalVersion, context->conditionalDecision);
        if (retired) {
            row.QueueFiling().queueConditional = {};
            context->conditionalCommitted = false;
        }
        resolved = retired && resolved;
    } else if (scratch.queueConditional.Valid()) {
        resolved = engine.queueInstances.CancelPreparedConditional(
                       &scratch.queueConditional) &&
                   resolved;
    }
    if (preserveCanonicalResources) {
        // Actual committed group ownership is retained by the parent.
    } else if (context->armGroupCommitted) {
        const bool cancelled =
            engine.armGroups.CancelBeforePublication(scratch.queueArmGroup);
        if (cancelled) {
            scratch.queueArmGroup = {};
            context->armGroupCommitted = false;
            if (scratch.queueFutureCanonicalCurrent != nullptr)
                scratch.queueFutureCanonicalCurrent->canonicalGroupExited = true;
        }
        resolved = cancelled && resolved;
    } else if (scratch.queueArmGroupPrepared) {
        const bool cancelled =
            engine.armGroups.CancelPrepared(scratch.queueArmGroup);
        if (cancelled) {
            scratch.queueArmGroupPrepared = false;
            scratch.queueArmGroup = {};
            if (scratch.queueFutureCanonicalCurrent != nullptr)
                scratch.queueFutureCanonicalCurrent->canonicalGroupExited = true;
        }
        resolved = cancelled && resolved;
    }
    if (context->queueInitialLaneArmGroupCommitted) {
        const bool cancelled = engine.armGroups.CancelBeforePublication(
            scratch.queueInitialLaneArmGroup);
        if (cancelled) {
            scratch.queueInitialLaneArmGroup = {};
            row.QueuePayload().queueInitialLaneArmGroup = {};
            context->queueInitialLaneArmGroupCommitted = false;
        }
        resolved = cancelled && resolved;
    } else if (scratch.queueInitialLaneArmGroupPrepared) {
        const bool cancelled = engine.armGroups.CancelPrepared(
            scratch.queueInitialLaneArmGroup);
        if (cancelled) {
            scratch.queueInitialLaneArmGroupPrepared = false;
            scratch.queueInitialLaneArmGroup = {};
            row.QueuePayload().queueInitialLaneArmGroup = {};
        }
        resolved = cancelled && resolved;
    }
    const std::uint64_t observed = engine.mixer.BlocksRendered();
    bool allArmsCancelled = true;
    for (std::uint32_t index = scratch.queueSourceControlArmCount;
         index-- > 0;) {
        const auto token = row.QueueFiling().queueTransitionGroupArms[index];
        const bool cancelled = index < context->sourceArmsCommitted
            ? DropTimelineArm(engine, token, observed)
            : engine.timelineArms.CancelPrepared(token);
        if (cancelled) row.QueueFiling().queueTransitionGroupArms[index] = {};
        allArmsCancelled = cancelled && allArmsCancelled;
        resolved = cancelled && resolved;
    }
    if (allArmsCancelled) {
        scratch.queueSourceControlArmCount = 0;
        if (row.HasFeatureArrays()) row.QueueFiling().queueSourceControlArmCount = 0;
        row.ClearQueueSourcePrograms();
        if (row.HasFeatureArrays()) row.QueuePayload().queueSourceArm = {};
        context->sourceArmsCommitted = 0;
    }
    if (preserveCanonicalResources) {
        // Transition and Bank follow the same actual committed Decision.
    } else if (context->transitionCommitted) {
        const bool cancelled = engine.transitionInstances.
            CancelBeforePublication(scratch.queueTransition);
        if (cancelled) {
            scratch.queueTransition = {};
            context->transitionCommitted = false;
            if (scratch.queueFutureCanonicalCurrent != nullptr)
                scratch.queueFutureCanonicalCurrent->canonicalTransitionExited = true;
        }
        resolved = cancelled && resolved;
    } else if (scratch.queueTransitionPrepared) {
        const bool cancelled = engine.transitionInstances.
            CancelPreparedAcquire(scratch.queueTransition);
        if (cancelled) {
            scratch.queueTransitionPrepared = false;
            scratch.queueTransition = {};
            if (scratch.queueFutureCanonicalCurrent != nullptr)
                scratch.queueFutureCanonicalCurrent->canonicalTransitionExited = true;
        }
        resolved = cancelled && resolved;
    }
    return resolved;
}

bool CancelPreparedActionResourceOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::PreparedActionResourceOwnerContext*>(opaque);
    if (context != nullptr && context->scratch != nullptr &&
        context->scratch->queueFutureCanonicalCurrent != nullptr)
        return ExitCanonicalQueueChildResources(*context->engine, *context->scratch);
    return CancelPreparedActionResourceOwnerImpl(opaque, false);
}

bool ValidatePreparedActionFinalOwnerFault(void* opaque) noexcept {
    return opaque != nullptr;
}

bool CommitPreparedActionFinalOwnerFault(void* opaque,
                                         std::uint64_t) noexcept {
    auto* engine = static_cast<harken::Engine*>(opaque);
    if (engine == nullptr) return false;
    if (engine->forceActionFinalOwnerCommitFailureForTest) {
        if (engine->actionFinalOwnerCommitFailureSkipForTest != 0) {
            --engine->actionFinalOwnerCommitFailureSkipForTest;
            return true;
        }
        engine->forceActionFinalOwnerCommitFailureForTest = false;
        return false;
    }
    return true;
}

bool CancelPreparedActionFinalOwnerFault(void*) noexcept { return true; }

bool ValidatePreparedDirectSelectionOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedDirectSelectionOwnerContext*>(opaque);
    return context != nullptr && context->table != nullptr &&
        context->delta && context->table->Delta(context->delta).live;
}

bool CommitPreparedDirectSelectionOwner(void* opaque, std::uint64_t) noexcept {
    return ValidatePreparedDirectSelectionOwner(opaque);
}

bool CancelPreparedDirectSelectionOwner(void* opaque) noexcept {
    auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedDirectSelectionOwnerContext*>(opaque);
    if (context == nullptr || context->table == nullptr || !context->delta) return true;
    if (context->table->CancelDelta(context->delta) != harken::SelectionMemoryStatusV1::Ok)
        return false;
    context->delta = {};
    return true;
}

bool MatchesPendingScheduleEntryRecord(harken::Engine& engine,
    const harken::EnginePlayableServiceRow& parent,
    const harken::EngineScheduleAggregateChild& record) noexcept {
    if (!parent.InvocationValid() || !record.pendingEntry ||
        record.content.kind != harken::PlayableKindV1::Container || record.service.Valid() ||
        record.lifecycleOwned || record.logicalComplete || record.resourcesReleased ||
        !record.naturalClipDeadline.Empty()) return false;
    const auto actual = engine.playableInstances.Classify(parent.ownerInstance);
    if (!actual.live || actual.scheduleEpoch != parent.ownerEpoch) return false;
    if (parent.scheduleAggregate != nullptr) {
        if (!parent.scheduleAggregate->committed ||
            (actual.kind != harken::PlayableKind::Track && actual.kind != harken::PlayableKind::Segment)) return false;
        for (const auto& owned : parent.scheduleAggregate->children)
            if (&owned == &record) return true;
        return false;
    }
    harken::ContainerPlaybackRow playback{};
    return actual.kind == harken::PlayableKind::Container &&
        parent.scheduleTerminalChild.get() == &record && !parent.actionPrepared &&
        parent.ordinaryLifecycleOwned && !parent.queueMode && !parent.variableControlInstance.Valid() &&
        engine.containerPlayback.Capture(parent.ownerInstance, &playback) &&
        playback.expectedScheduleEpoch == parent.ownerEpoch &&
        (playback.mode == static_cast<std::uint8_t>(harken::ContainerModeV1::Random) ||
         playback.mode == static_cast<std::uint8_t>(harken::ContainerModeV1::Sequence));
}

bool MatchesPendingScheduleEntryParent(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch,
    const harken::EnginePlayableServiceRow& parent) noexcept {
    return scratch.pendingScheduleChild != nullptr &&
        engine.ResolvePlayableService(scratch.continuationService) == &parent &&
        engine.playablePartitions.Owns(scratch.continuationPartition, parent.identity) &&
        scratch.continuationPartition.slot == parent.partition.slot &&
        scratch.continuationPartition.generation == parent.partition.generation &&
        MatchesPendingScheduleEntryRecord(engine, parent, *scratch.pendingScheduleChild);
}

bool ValidatePreparedDirectExposureOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedDirectExposureOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr || context->scratch == nullptr) return false;
    if (!context->scratch->continuationExecution) return true;
    const auto& scratch = *context->scratch;
    auto& engine = *context->engine;
    const auto& parent = scratch.continuationParentSnapshot;
    const auto* service = engine.ResolvePlayableService(scratch.continuationService);
    const bool pendingSchedule = scratch.pendingScheduleChild != nullptr;
    if (pendingSchedule && (service == nullptr ||
        !MatchesPendingScheduleEntryParent(engine, scratch, *service) ||
        service->phase == harken::EnginePlayableStartPhase::Cancelling ||
        service->pendingCancellationIntent != 0)) return false;
    const auto current = engine.playableInstances.Classify(
        pendingSchedule ? scratch.continuationService.owner : parent.instance);
    return current.live && current.scheduleEpoch ==
        (pendingSchedule ? scratch.continuationService.epoch : parent.expectedScheduleEpoch) &&
        service != nullptr && service->InvocationValid() &&
        engine.playablePartitions.Owns(scratch.continuationPartition, scratch.continuationService.token) &&
        engine.timelinePool.Epoch() == scratch.continuationTransportEpoch &&
        scratch.continuationOrder.executeFrame >= engine.timelinePool.PublishCutoffFrame() &&
        engine.mixer.BlocksRendered() <= scratch.continuationOrder.executeFrame / engine.config.blockFrames &&
        ValidatePreparedAuthorityOwner(&context->scratch->authorityOwnerContext);
}

bool CommitPreparedDirectExposureOwner(void* opaque, std::uint64_t) noexcept {
    if (!ValidatePreparedDirectExposureOwner(opaque)) return false;
    auto& context = *static_cast<harken::EngineActionPlayScratch::PreparedDirectExposureOwnerContext*>(opaque);
    return !context.scratch->frontierSignal.Valid() ||
        context.engine->queueInstances.CommitPreparedSignalAdvance(&context.scratch->frontierSignal);
}

bool CompletedPrivateVcArmRetirement(const harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch) noexcept {
    const auto& storage = scratch.storage;
    if (storage.initialVcUnboundRetirementConsumed) {
        if (storage.retiredInitialVcAttemptGeneration != storage.generation ||
            storage.retiredInitialVcArmCount != 2) return false;
        for (std::uint32_t i = 0; i < storage.retiredInitialVcArmCount; ++i) {
            harken::ArmState state{};
            if (engine.timelineArms.State(storage.retiredInitialVcArms[i], &state)) return false;
        }
        return true;
    }
    return storage.retiredInitialVcAttemptGeneration == storage.generation &&
        storage.retiredInitialVcArmCount != 0 && storage.initialVcRetirementDecisionsOpen &&
        storage.initialVcRetirementEntry == scratch.frontierDescriptor.entry &&
        storage.initialVcRetirementPrimary == scratch.frontierDescriptor.primary &&
        engine.decisions.IsOpen(scratch.frontierCoordinator);
}

bool PreparePrivateInitialVariableControlArmRetirement(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept;
bool FinishPrivateInitialVariableControlArmRetirement(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept;
bool RetirePrivateUnboundInitialVariableControlArms(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept;

bool ReleaseInitialFrontierBindings(harken::Engine& engine,
    const harken::FrontierEntryReceiptRef& entry, std::uint64_t completedAudioSequence,
    const harken::EngineActionPlayScratch* prepared,
    const harken::Plan03UnpublishedRetirementToken* witnessed) noexcept;

bool CancelInitialQueueEntryAdmissions(harken::Engine&, harken::EngineActionPlayScratch&) noexcept;
bool ReleaseInitialQueueEntryAdmissionOwners(harken::Engine&, harken::EngineActionPlayScratch&) noexcept;
bool ResolveInitialQueueEntrySourceAdmission(harken::Engine&, harken::EngineActionPlayScratch&,
    harken::EnginePlayableServiceRow&, harken::ParentAudioGroupRef*, std::uint16_t*, bool*) noexcept;

bool CancelInitialQueueSignalAdmission(harken::Engine&, harken::EngineActionPlayScratch&) noexcept;

bool CancelNativeEntryForestAdmissions(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    auto* root = scratch.initialNativeForestOwner.Valid()
        ? FindFrontierAttempt(engine, scratch.initialNativeForestOwner) : &scratch;
    if (root == nullptr) return false;
    const bool ordinarySchedule = !scratch.initialNativeForestOwner.Valid() &&
        !root->queueSignalEntryOwner.Valid() && !root->nativeEntryForestRoot &&
        !root->nativeEntrySeedService.Valid() && root->initialQueueSignalAdmission == nullptr;
    if (!root->initialForestPublication || ordinarySchedule)
        return CancelInitialQueueEntryAdmissions(engine, scratch);
    if (!root->initialForestCancellationSealed || !CancelInitialQueueSignalAdmission(engine, *root)) return false;
    return VisitPrivateInitialForest(engine, *root, [&](auto& attempt) noexcept {
        return attempt.initialForestCancellationSealed && CancelInitialQueueEntryAdmissions(engine, attempt);
    });
}

bool RollbackInitialNativeSideDecisions(harken::Engine&, harken::EngineActionPlayScratch&) noexcept;
bool ReleaseInitialNativeSideLifetimes(harken::Engine&, harken::EngineActionPlayScratch&) noexcept;

bool CancelInitialQueueEntryAdmissions(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    if (scratch.initialQueueEntryAdmissions.empty()) return true;
    const auto forestOwner = scratch.initialNativeForestOwner.Valid()
        ? scratch.initialNativeForestOwner : scratch.queueSignalEntryOwner;
    auto* root = FindFrontierAttempt(engine, forestOwner);
    if (root == nullptr || !root->initialForestPublication || !root->continuationExecution) return false;
    if (scratch.queueTransactions.Valid() &&
        !engine.timelinePool.CancelPreparedTransactionBatch(&scratch.queueTransactions)) return false;
    if (!RollbackInitialNativeSideDecisions(engine, scratch)) return false;
    if (engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator) != nullptr &&
        !ReleaseInitialFrontierBindings(engine, scratch.frontierDescriptor.entry, 0, &scratch, nullptr)) return false;
    if (!ReleaseInitialNativeSideLifetimes(engine, scratch)) return false;
    for (std::size_t index = scratch.initialQueueEntryAdmissions.size(); index-- > 0;) {
        auto& native = *scratch.initialQueueEntryAdmissions[index];
        if (native.group.Exact()) {
            harken::Plan03PageGroupView group{};
            if (!engine.timelinePool.ResolvePlan03GroupSliceProducer(native.group, &group)) return false;
            if (group.frontier != nullptr && group.frontier->Valid() &&
                !engine.timelinePool.DetachPlan03GroupFrontier(native.group, 0)) return false;
            native.initialBound = false;
        }
        if (native.prepared.Valid() &&
            !engine.timelinePool.CancelPreparedPlan03GroupSlice(&native.prepared)) return false;
        if (native.committed.Valid()) {
            std::array<harken::CommittedPlan03GroupSlice*, 1> originals{&native.committed};
            if (CancelUnpublishedInitialGroupSources(engine, *root, originals, native.cancellationGroups,
                    native.cancellationArms, native.voices, native.owners, native.sources) !=
                    harken::UnpublishedGroupArmCancellationStatus::Consumed) return false;
        }
        // The original held page was consumed. A partial later retry must not
        // resolve its retired identity or touch a reused page-group slot.
        native.group = {};
        native.initialBound = false;
        if (native.armGroup.Valid() && !engine.armGroups.CancelBeforePublication(native.armGroup)) return false;
        native.armGroup = {};
        if (native.decision.Valid()) {
            if (!native.decisionCancelled) {
                if (!engine.decisions.Cancel(native.decision)) return false;
                native.decisionCancelled = true;
            }
            if (!engine.decisions.ReclaimCancelled(native.decision)) return false;
            native.decision = {};
            native.decisionCancelled = false;
        }
    }
    scratch.initialQueueEntryAdmissions.clear();
    return true;
}

bool RollbackInitialNativeSideDecisions(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    if (scratch.initialFrontierSideCount > scratch.storage.initialFrontierSides.size()) return false;
    for (std::uint32_t index = 0; index < scratch.initialFrontierSideCount; ++index) {
        const auto& side = scratch.storage.initialFrontierSides[index];
        harken::DecisionCommittedSnapshot committed{};
        if (!engine.decisions.CaptureCommitted(side.decision, &committed)) continue;
        auto* service = engine.ResolvePlayableService(side.service);
        harken::Plan03PageGroupView group{};
        if (service == nullptr || !engine.timelinePool.ResolvePlan03GroupSliceProducer(side.group, &group) ||
            group.frontier == nullptr || !(group.frontier->entry == scratch.frontierDescriptor.entry) ||
            !engine.decisions.CanRollbackPreparedFrontierDecision(side.decision,
                scratch.frontierCoordinator, group.frontier)) return false;
        bool* originalCommitted = nullptr;
        auto* signal = scratch.initialQueueSignalAdmission.get();
        if (signal != nullptr && SameCanonicalDecision(signal->decision, side.decision))
            originalCommitted = &signal->decisionCommitted;
        for (const auto& pointer : scratch.initialQueueEntryAdmissions) {
            if (pointer == nullptr) return false;
            if (!SameCanonicalDecision(pointer->decision, side.decision)) continue;
            if (originalCommitted != nullptr) return false;
            originalCommitted = &pointer->decisionCommitted;
        }
        if (originalCommitted == nullptr) {
            if (SameCanonicalDecision(service->variableControlDiscreteDecision, side.decision))
                originalCommitted = &service->variableControlDiscreteDecisionCommitted;
            else if (SameCanonicalDecision(service->variableControlContinuousDecision, side.decision))
                originalCommitted = &service->variableControlContinuousDecisionCommitted;
            else return false;
        }
        if (!*originalCommitted || !engine.decisions.RollbackPreparedFrontierDecision(
                side.decision, scratch.frontierCoordinator, group.frontier)) return false;
        *originalCommitted = false;
    }
    return true;
}

bool ReleaseInitialNativeSideLifetimes(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    for (std::uint32_t index = 0; index < scratch.initialFrontierSideCount; ++index) {
        const auto& side = scratch.storage.initialFrontierSides[index];
        auto* service = engine.ResolvePlayableService(side.service);
        if (service == nullptr) return false;
        // The signal side belongs to the outer Queue service, whose own
        // lifetime may name an older entry. Return only this entry's loans.
        if (!(service->frontierLifetimeEntry == scratch.frontierDescriptor.entry)) continue;
        if (!service->frontierLifetimePin.Release()) return false;
        service->frontierLifetimeEntry = {};
    }
    return true;
}

bool CancelInitialQueueSignalAdmission(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    auto* owned = scratch.initialQueueSignalAdmission.get();
    if (owned == nullptr) return true;
    if (!RollbackInitialNativeSideDecisions(engine, scratch)) return false;
    if (scratch.queueTransactions.Valid() &&
        !engine.timelinePool.CancelPreparedTransactionBatch(&scratch.queueTransactions)) return false;
    if (owned->decisionCommitted) {
        harken::Plan03PageGroupView group{};
        if (!engine.timelinePool.ResolvePlan03GroupSliceProducer(owned->group, &group) ||
            group.frontier == nullptr || !engine.decisions.RollbackPreparedFrontierDecision(
                owned->decision, scratch.frontierCoordinator, group.frontier)) return false;
        owned->decisionCommitted = false;
    }
    if (!owned->signalBound && owned->group.Exact()) {
        harken::Plan03PageGroupView group{};
        if (!engine.timelinePool.ResolvePlan03GroupSliceProducer(owned->group, &group)) return false;
        if (group.frontier != nullptr && group.frontier->Valid() &&
            !engine.timelinePool.DetachPlan03GroupFrontier(owned->group, 0)) return false;
    }
    if (engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator) != nullptr &&
        !ReleaseInitialFrontierBindings(engine, scratch.frontierDescriptor.entry, 0, &scratch, nullptr))
        return false;
    if (!ReleaseInitialNativeSideLifetimes(engine, scratch)) return false;
    if (owned->prepared.Valid() &&
        !engine.timelinePool.CancelPreparedPlan03GroupSlice(&owned->prepared)) return false;
    if (owned->committed.Valid()) {
        std::array<harken::CommittedPlan03GroupSlice*, 1> originals{&owned->committed};
        if (CancelUnpublishedInitialGroupSources(engine, scratch, originals, owned->cancellationGroups,
                owned->cancellationArms, owned->voices, owned->owners, owned->sources) !=
                harken::UnpublishedGroupArmCancellationStatus::Consumed) return false;
    }
    owned->group = {};
    owned->signalBound = false;
    if (owned->armGroup.Valid() && !engine.armGroups.CancelBeforePublication(owned->armGroup)) return false;
    owned->armGroup = {};
    if (owned->decision.Valid()) {
        if (!owned->decisionCancelled) {
            if (!engine.decisions.Cancel(owned->decision)) return false;
            owned->decisionCancelled = true;
        }
        if (!engine.decisions.ReclaimCancelled(owned->decision)) return false;
        owned->decision = {};
        owned->decisionCancelled = false;
    }
    scratch.initialQueueSignalAdmission.reset();
    return true;
}

bool CancelPreparedDirectExposureOwnerImpl(
    void* opaque, bool preserveCommittedCoordinator) noexcept {
    if (opaque == nullptr) return false;
    auto& context = *static_cast<harken::EngineActionPlayScratch::
        PreparedDirectExposureOwnerContext*>(opaque);
    if (context.engine == nullptr || context.scratch == nullptr) return false;
    auto& scratch = *context.scratch;
    auto& engine = *context.engine;
    if (!SealNativeEntryPrivateOwner(engine, scratch) ||
        !CancelInitialQueueSignalAdmission(engine, scratch) ||
        !CancelNativeEntryForestAdmissions(engine, scratch)) return false;
    const auto* activation = engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator);
    const bool armsRetired = CompletedPrivateVcArmRetirement(engine, scratch);
    if (scratch.initialForestPublication && scratch.frontierDescriptor.entry.Valid()) {
        for (auto& owned : engine.initialFrontierArmPins) {
            if (!owned.pin.Valid() || !(owned.entry == scratch.frontierDescriptor.entry)) continue;
            if (!owned.pin.Release(0)) return false;
            owned.arm = {};
            owned.entry = {};
        }
    }
    if (activation != nullptr && !armsRetired && !engine.decisions.CanRollbackPreparedFrontierDecision(
            scratch.frontierCoordinator, scratch.frontierCoordinator)) {
        return false;
    }
    if (scratch.frontierArmPin.Valid() && !scratch.frontierArmPin.Release(0)) {
        return false;
    }
    if (scratch.frontierDescriptor.entry.Valid() &&
        engine.timelinePool.HasFrontierOwnerOperations(scratch.frontierDescriptor.entry.owner,
            scratch.frontierCoordinator) &&
        !engine.timelinePool.DetachPlan03GroupFrontier(scratch.frontierDescriptor.primary, 0)) {
        return false;
    }
    if (!scratch.queueSignalEntryOwner.Valid() && scratch.row != nullptr &&
        scratch.row->nativeEntryDependency != nullptr) {
        scratch.row->nativeEntryDependency->entryBound = false;
        if (!ReleaseNativeEntryDependency(*scratch.row, engine.mixer.BlocksRendered())) return false;
    }
    if (scratch.frontierSignal.Valid() &&
        !engine.queueInstances.CancelPreparedSignalAdvance(&scratch.frontierSignal)) {
        return false;
    }
    if (scratch.frontierCoordinator.Valid() &&
        !preserveCommittedCoordinator) {
        const auto* activation = engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator);
        if (activation != nullptr && !armsRetired && !engine.decisions.RollbackPreparedFrontierDecision(
                scratch.frontierCoordinator, scratch.frontierCoordinator)) {
            return false;
        }
        if (activation != nullptr &&
            !engine.variables.CancelPreparedFrontierEntryReadUse(activation->Descriptor().entry)) {
            return false;
        }
        if (activation != nullptr &&
            !engine.decisions.CancelPreparedFrontierActivation(scratch.frontierCoordinator)) {
            return false;
        }
    }
    if (scratch.directCommandsReserved) {
        engine.commands.CancelReservedBatch(&scratch.directCommandReservation);
        scratch.directCommandsReserved = false;
    }
    if (scratch.queueTransactions.Valid() &&
        !engine.timelinePool.CancelPreparedTransactionBatch(&scratch.queueTransactions)) {
        return false;
    }
    if (scratch.frontierPreparedPrimary.Valid() &&
        !engine.timelinePool.CancelPreparedPlan03GroupSlice(&scratch.frontierPreparedPrimary)) {
        return false;
    }
    if (scratch.frontierPrimary.Valid() &&
        !engine.timelinePool.RollbackCommittedPlan03GroupSlice(&scratch.frontierPrimary)) {
        return false;
    }
    if (scratch.frontierCoordinatorGroup.Valid()) {
        if (!engine.armGroups.CancelBeforePublication(scratch.frontierCoordinatorGroup)) {
            return false;
        }
        scratch.frontierCoordinatorGroup = {};
    }
    if (scratch.frontierCoordinator.Valid() &&
        !preserveCommittedCoordinator) {
        if (!scratch.frontierCoordinatorCancelled) {
            if (!engine.decisions.Cancel(scratch.frontierCoordinator)) {
                return false;
            }
            scratch.frontierCoordinatorCancelled = true;
        }
        if (!engine.decisions.ReclaimCancelled(scratch.frontierCoordinator)) {
            return false;
        }
        scratch.frontierCoordinator = {};
        scratch.frontierCoordinatorCancelled = false;
    }
    if (scratch.continuationParentLinked) {
        harken::PreparedPlayableInstance* childToken =
            scratch.instance.Handle() == scratch.continuationChildRoot ? &scratch.instance : nullptr;
        for (std::uint32_t index = 0; childToken == nullptr &&
                index < scratch.playableTreeExecutor.InstanceReservationCount(); ++index) {
            if (scratch.playableTreeExecutor.PreparedInstanceHandle(index) == scratch.continuationChildRoot) {
                childToken = scratch.playableTreeExecutor.PreparedInstanceToken(index);
                break;
            }
        }
        const bool pendingSchedule = scratch.pendingScheduleChild != nullptr;
        if (childToken == nullptr || !engine.playableInstances.WithdrawUnpublishedParentLink(
                *childToken, pendingSchedule ? scratch.continuationService.owner : scratch.continuationParentSnapshot.instance,
                pendingSchedule ? scratch.continuationService.epoch : scratch.continuationParentSnapshot.expectedScheduleEpoch))
            return false;
        if (!pendingSchedule && !engine.containerPlayback.Restore(scratch.continuationParentSnapshot)) return false;
        scratch.continuationParentLinked = false;
    }
    if (!CancelPreparedQueueCompletionBindings(engine, scratch)) {
        return false;
    }
    return true;
}

bool CancelPreparedDirectExposureOwner(void* opaque) noexcept {
    return CancelPreparedDirectExposureOwnerImpl(opaque, false);
}

bool MatchesPrivateInitialVcPageBatchProof(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch, harken::LogicCommitSequence sequence) noexcept {
    const auto& held = scratch.privateInitialVcPageCohort;
    const auto& scope = held.pageTransferScope;
    if (!held.pageBatchSelected || !held.pageTransferRequired || held.pageBatchConsumed ||
        held.backing != harken::EngineActionPlayScratch::PrivateInitialVcPageCohort::Backing::Page ||
        scratch.row == nullptr || sequence == 0 || scope.sequence != sequence ||
        scope.attemptGeneration != scratch.storage.generation ||
        held.attemptGeneration != scratch.storage.generation ||
        held.frame != scratch.row->startFrame || scope.world != scratch.row->Invocation().worldGeneration ||
        held.pageBatchWorld != scope.world || scope.cohortRoot != scratch.row->Invocation().actionFiring ||
        held.cohortRoot != scope.cohortRoot || held.pageBatchTransport != engine.timelinePool.Epoch()) return false;
    return held.pageBatchTransferProof.MatchesOriginalScope(scratch.queueTransactions, scope,
        held.pageBatchOriginalEvents, held.pageBatchPlannedBindings);
}

bool ValidatePrivateInitialVcPageBatch(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch) noexcept {
    const auto& held = scratch.privateInitialVcPageCohort;
    if (!held.pageBatchSelected) return !held.pageTransferRequired;
    return !held.pageBatchBindingsStarted && held.sequence != 0 &&
        MatchesPrivateInitialVcPageBatchProof(engine, scratch, held.sequence);
}

bool ValidatePrivateInitialVcPageTransfer(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch) noexcept {
    const auto& held = scratch.privateInitialVcPageCohort;
    if (!held.pageTransferRequired) return true;
    if (held.backing != harken::EngineActionPlayScratch::PrivateInitialVcPageCohort::Backing::Page ||
        scratch.row == nullptr || held.sequence == 0 || held.attemptGeneration != scratch.storage.generation ||
        held.frame != scratch.row->startFrame || held.pageTransferScope.cohortRoot != held.cohortRoot ||
        held.cohortRoot != scratch.row->Invocation().actionFiring ||
        held.pageTransferScope.sequence != held.sequence ||
        held.pageTransferScope.world != scratch.row->Invocation().worldGeneration ||
        held.pageTransferScope.attemptGeneration != scratch.storage.generation) return false;
    harken::Plan03GroupSliceInput primary{};
    primary.executeFrame = held.frame;
    primary.decision = held.coordinator;
    for (std::size_t position = 0; position < held.pageTransferProofs.size(); ++position) {
        const auto& original = position < 2 ? held.sides[position] : scratch.frontierPreparedPrimary;
        const auto& input = position < 2 ? held.descriptors[position] : primary;
        harken::Plan03GroupSliceIdentity prospective{};
        if (!original.CaptureProspectiveIdentity(&prospective) ||
            !(prospective == held.pageProspectiveIdentities[position]) ||
            prospective.transportEpoch != engine.timelinePool.Epoch() ||
            !held.pageTransferProofs[position].MatchesOriginalScope(original, held.pageTransferScope,
                input, engine.timelineArms)) return false;
    }
    return true;
}

bool CapturePrivateInitialVcPreparedOwner(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch,
    harken::FrontierOwnerIdentity* out) noexcept;

bool IsPlayableServiceDescendant(harken::Engine& engine,
    const harken::EnginePlayableServiceRow& candidate,
    const harken::EnginePlayableServiceRow& owner) noexcept;

bool MatchesPrivateImmediateEntryReceiver(harken::Engine& engine,
    const harken::EnginePlayableServiceRow& row, bool requireAssociation = true) noexcept {
    const auto& receiver = row.privateImmediateEntry;
    const auto capacity = receiver.results.size();
    return row.identity.slot < engine.playableServices.size() &&
        capacity != 0 && receiver.shape.cells == receiver.results.data() &&
        receiver.shape.capacity == capacity && receiver.shape.count <= capacity &&
        (!receiver.projectionReceived || (receiver.terminal.cells == receiver.shape.cells &&
            receiver.terminal.capacity == capacity && receiver.terminal.count == receiver.shape.count &&
            receiver.terminal.coordinator == receiver.shape.coordinator)) &&
        receiver.Valid() && row.InvocationValid() && receiver.service == row.identity &&
        receiver.partition.slot == row.partition.slot &&
        receiver.partition.generation == row.partition.generation &&
        receiver.invocationGeneration == row.invocationGeneration &&
        row.Invocation().actionFiring == receiver.root &&
        row.PendingImmediateCohortRoot() == receiver.root &&
        receiver.entry.owner.child == row.ownerInstance &&
        receiver.entry.owner.childEpoch == row.ownerEpoch &&
        receiver.entry.owner.invocation == row.rootInstance &&
        receiver.entry.owner.serviceSlot == row.identity.slot &&
        receiver.entry.owner.serviceGeneration == row.identity.generation &&
        engine.ResolvePlayableService(receiver.service, row.ownerInstance, row.ownerEpoch) == &row &&
        (!requireAssociation || engine.immediateActionLane.MatchesPrivateEntryAssociation(
            receiver.lane, receiver.root, receiver.ordinal, receiver.entry));
}

bool PrivateImmediateEntryStopPending(const harken::EnginePlayableServiceRow& row) noexcept {
    return row.privateImmediateEntry.Valid() && !row.privateImmediateEntry.commonPinsRetired &&
        row.pendingCancellationIntent == 1u;
}

bool MonitorSourceFinishedIndependently(harken::Engine& engine,
    harken::PlayableInstanceHandle instance) noexcept {
    const auto slot = engine.playableInstances.SourceRetirementSlot(instance);
    const auto* source = engine.sourceTerminals.At(slot);
    if (source == nullptr || !source->occupied || source->leaf != instance) return false;
    harken::SourceTerminalPayload payload{};
    if (!engine.sourceTerminals.Capture({slot, source->generation},
            engine.mixer.BlocksRendered(), &payload)) return false;
    return payload.kind == harken::SourceTerminalKind::Natural ||
        payload.kind == harken::SourceTerminalKind::ProducerFailure ||
        payload.kind == harken::SourceTerminalKind::IntegrityAbort;
}

const harken::MonitorControlCause* MonitorCauseForInstance(harken::Engine& engine,
    harken::PlayableInstanceHandle instance, const harken::MonitorControlCause& cause) noexcept {
    return MonitorSourceFinishedIndependently(engine, instance) ? nullptr : &cause;
}

void RecordPlayableControlTree(harken::Engine& engine,
    harken::PlayableInstanceHandle root, const harken::MonitorControlCause& cause) noexcept {
    engine.playableInstances.VisitPublishedSubtree(root, [&](auto instance) {
        if (!MonitorSourceFinishedIndependently(engine, instance))
            engine.playableInstances.RecordControlCause(instance, cause);
    });
}

void RecordServiceControlCause(harken::Engine& engine,
    harken::EnginePlayableServiceRow& row, const harken::MonitorControlCause& cause) noexcept {
    RecordPlayableControlTree(engine, row.rootInstance, cause);
    const auto savedTarget = engine.playableInstances.Classify(row.pendingControlTarget);
    if (savedTarget.live && savedTarget.scheduleEpoch == row.pendingControlTargetEpoch)
        RecordPlayableControlTree(engine, row.pendingControlTarget, cause);
    if (!row.parentService.Valid() && row.InvocationValid()) {
        const auto& invocation = row.Invocation();
        const auto outer = engine.playableInstances.Classify(invocation.variableControlOuterRootInstance);
        if (outer.live && outer.scheduleEpoch == invocation.variableControlOuterRootEpoch)
            RecordPlayableControlTree(engine, invocation.variableControlOuterRootInstance, cause);
    }
}

bool CaptureServiceControlCause(harken::Engine& engine,
    const harken::EnginePlayableServiceRow& row, harken::MonitorControlCause* out) noexcept {
    const auto* member = &row;
    for (std::size_t depth = 0; member != nullptr && depth < engine.playableServices.size(); ++depth) {
        if (member->pendingCancellationIntent != 0 || member->pendingRegisteredStopCapture) {
            *out = member->pendingControlCause;
            return true;
        }
        if (engine.playableInstances.CaptureControlCause(member->rootInstance, out)) return true;
        member = engine.ResolvePlayableService(member->parentService);
    }
    return false;
}

void RecordPreparedControlCause(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch, const harken::MonitorControlCause& cause) noexcept {
    if (scratch.playableTreeExecutor.PublishedOwnershipTransferred()) return;
    if (!scratch.cancellationCauseAccepted) {
        scratch.cancellationCause = cause;
        scratch.cancellationCauseAccepted = true;
    }
    const auto& executor = scratch.playableTreeExecutor;
    for (std::size_t index = 0; index < executor.PreparedInstanceCensusCount(); ++index) {
        const auto* token = executor.PreparedInstanceCensusToken(index);
        if (token == nullptr || (!engine.playableInstances.OwnsPrepared(*token) &&
            !engine.playableInstances.ValidateStamp(token->Handle(), token->ScheduleEpoch()))) continue;
        if (!MonitorSourceFinishedIndependently(engine, token->Handle()))
            engine.playableInstances.RecordControlCause(token->Handle(), scratch.cancellationCause);
    }
}

void MarkObservedPlayableVoiceTerminating(harken::Engine& engine, VnVoiceHandle render,
    const harken::MonitorControlCause& cause) noexcept {
    bool recordCause = true;
    for (std::uint32_t slot = 0; slot < engine.sourceTerminals.Capacity(); ++slot) {
        const auto* source = engine.sourceTerminals.At(slot);
        if (source->occupied && source->render == render) {
            recordCause = !MonitorSourceFinishedIndependently(engine, source->leaf);
            break;
        }
    }
    engine.ledger.MarkTerminating(render, cause, recordCause);
}

bool ServicePrivateImmediateEntryVoiceStops(harken::Engine& engine,
    harken::EnginePlayableServiceRow& row) noexcept {
    if (!PrivateImmediateEntryStopPending(row)) return true;
    if (!MatchesPrivateImmediateEntryReceiver(engine, row)) return false;
    const auto& receiver = row.privateImmediateEntry;
    const bool canCancelSources = receiver.projectionReceived ||
        engine.immediateActionLane.CanCancelPrivateEntrySources(
            receiver.lane, receiver.root, receiver.ordinal, receiver.entry);
    bool allIssued = true;
    engine.ledger.ForEachPlayableOwnedLive([&](VnVoiceHandle render,
        const harken::VoiceLedger::PlayableParentRef& parent) {
        const harken::EnginePlayableServiceRow* actual = nullptr;
        bool foundSource = false;
        std::uint32_t sourceSlot = UINT32_MAX;
        for (std::uint32_t slot = 0; slot < engine.sourceTerminals.Capacity(); ++slot) {
            const auto* source = engine.sourceTerminals.At(slot);
            if (!source->occupied || source->render != render) continue;
            foundSource = true;
            sourceSlot = slot;
            actual = engine.ResolveSourceResourceOwner(source->resourceOwner);
            break;
        }
        if (!foundSource) for (const auto& candidate : engine.playableServices) {
            if (candidate.phase != harken::EnginePlayableStartPhase::Free &&
                candidate.rootInstance == parent.internalToken &&
                IsPlayableServiceDescendant(engine, candidate, row)) {
                actual = &candidate;
                break;
            }
        }
        if (actual == nullptr || !IsPlayableServiceDescendant(engine, *actual, row)) return;
        const auto* voice = engine.voices.Resolve(render);
        if (voice == nullptr || engine.ledger.IsTerminating(render)) return;
        if (voice->timelineGated) {
            const auto* source = sourceSlot == UINT32_MAX ? nullptr : engine.sourceTerminals.At(sourceSlot);
            harken::EngineTimelineVoiceInstallIdentity installation{};
            if (!canCancelSources || source == nullptr ||
                !engine.CaptureTimelineVoiceInstallIdentity(render, &installation) ||
                installation.rootInstance != source->controller ||
                installation.releaseObserver.slot != source->release.slot ||
                installation.releaseObserver.targetSequence != source->release.targetSequence ||
                installation.startArm.renderSlot != static_cast<std::uint32_t>(render) ||
                installation.startArm.renderGeneration != static_cast<std::uint32_t>(render >> 32) ||
                !AbortTimelineArm(engine, installation.startArm)) {
                allIssued = false;
                return;
            }
        }
        harken::CommandRecord stop{};
        stop.opcode = harken::kOpcodeStop;
        stop.payload.stop.handle = render;
        // A withdrawn future Start has no audible tail, but still needs a real Stop.
        stop.payload.stop.fadeMs = voice->timelineGated ? 0 : row.pendingCancellationFadeMs;
        if (engine.commands.TryPush(stop)) MarkObservedPlayableVoiceTerminating(engine, render, row.pendingControlCause);
        else allIssued = false;
    });
    return allIssued;
}

void MarkPrivateImmediateEntryPinsRetired(harken::Engine& engine,
    harken::ImmediateLaneHandle lane) noexcept {
    for (auto& row : engine.playableServices) {
        auto& receiver = row.privateImmediateEntry;
        if (!receiver.Valid() || receiver.lane.slot != lane.slot ||
            receiver.lane.generation != lane.generation) continue;
        if (!MatchesPrivateImmediateEntryReceiver(engine, row, false)) {
            engine.runtimeRecreateRequired = true;
            continue;
        }
        receiver.commonPinsRetired = true;
    }
}

bool ReceivePrivateImmediateEntryTerminals(harken::Engine& engine,
    const harken::EngineImmediateEntryAttempt& attempt, std::uint64_t completed) noexcept {
    std::uint32_t received = 0, expected = 0;
    for (auto& row : engine.playableServices) {
        auto& receiver = row.privateImmediateEntry;
        if (!receiver.Valid() || receiver.lane.slot != attempt.lane.slot ||
            receiver.lane.generation != attempt.lane.generation) continue;
        if (!MatchesPrivateImmediateEntryReceiver(engine, row) || receiver.root != attempt.root ||
            receiver.commonPinsRetired || receiver.shape.count == 0) return false;
        if (!receiver.projectionReceived) {
            auto terminal = receiver.shape;
            if (!engine.immediateActionLane.CapturePrivateEntryTerminalProjection(receiver.lane,
                    receiver.root, receiver.ordinal, receiver.entry, completed, &terminal)) return false;
            receiver.terminal = terminal;
            receiver.projectionReceived = true;
        }
        if (expected == 0) expected = receiver.terminal.registeredEntryCount;
        if (expected == 0 || receiver.terminal.registeredEntryCount != expected ||
            receiver.ordinal >= expected) return false;
        for (const auto& other : engine.playableServices) {
            if (&other == &row) continue;
            const auto& prior = other.privateImmediateEntry;
            if (prior.Valid() && prior.lane.slot == receiver.lane.slot &&
                prior.lane.generation == receiver.lane.generation && prior.ordinal == receiver.ordinal)
                return false;
        }
        ++received;
    }
    if (received == 0 || received != expected) return false;
    // Every receipt has its original stable recipient before any lease is changed.
    for (auto& row : engine.playableServices) {
        auto& receiver = row.privateImmediateEntry;
        if (!receiver.Valid() || receiver.lane.slot != attempt.lane.slot ||
            receiver.lane.generation != attempt.lane.generation) continue;
        const harken::ImmediateLaneEntryOutcomeSnapshot* coordinator = nullptr;
        for (std::uint32_t index = 0; index < receiver.terminal.count; ++index)
            if (receiver.terminal.cells[index].bucketOrdinal == receiver.shape.coordinator)
                coordinator = &receiver.terminal.cells[index].outcome;
        if (coordinator == nullptr) return false;
        auto* activation = engine.decisions.ResolveFrontierActivation(receiver.entry.coordinator);
        if (activation == nullptr || !(activation->Descriptor().entry == receiver.entry)) return false;
        harken::FrontierActivationReceipt actual{};
        auto read = activation->Read(receiver.entry, completed, &actual);
        if (coordinator->outcome == harken::ImmediateLaneEntryOutcome::Applied) {
            if (read != harken::FrontierReceiptRead::Ready ||
                actual.outcome != harken::FrontierReceiptOutcome::Applied) return false;
        } else {
            if (read == harken::FrontierReceiptRead::InFlight) {
                (void)activation->Cancel(receiver.entry, harken::AudioSliceInvalidateReason::Cancel);
                read = activation->Read(receiver.entry, completed, &actual);
            }
            if (read != harken::FrontierReceiptRead::Ready ||
                actual.outcome != harken::FrontierReceiptOutcome::DefinitivelyNotApplied) return false;
        }
    }
    return true;
}

bool BuildPrivateInitialVcLaneEntryScope(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch,
    harken::ImmediateLanePrivateVariableControlEntryScope* out) noexcept {
    const auto& held = scratch.privateInitialVcPageCohort;
    harken::FrontierOwnerIdentity owner{};
    if (out == nullptr || !CapturePrivateInitialVcPreparedOwner(engine, scratch, &owner))
        return false;
    *out = {};
    out->entry = {held.coordinator, held.attemptGeneration, owner};
    out->coordinatorRequest = held.coordinatorRequest;
    out->provisionalFrame = held.frame;
    out->firstMember = held.laneFirstMemberOrdinal;
    out->memberCount = held.laneMemberCount;
    out->members = held.laneMemberManifests.data();
    out->groups[0] = held.descriptors[0];
    out->groups[1] = held.descriptors[1];
    out->groups[2].executeFrame = held.frame;
    out->groups[2].decision = held.coordinator;
    return true;
}

bool ValidatePrivateInitialVcLaneTransfer(harken::Engine& engine,
    const harken::EngineActionPlayScratch& scratch) noexcept {
    const auto& held = scratch.privateInitialVcPageCohort;
    if (!held.laneTransferRequired) return true;
    if (held.backing != harken::EngineActionPlayScratch::PrivateInitialVcPageCohort::Backing::ImmediateLane ||
        !held.laneMembersDeclared || held.laneFirstMemberOrdinal == UINT32_MAX ||
        held.laneMemberCount == 0 || held.laneMemberCount > held.laneMemberManifests.size() ||
        scratch.row == nullptr ||
        held.sequence == 0 || held.attemptGeneration != scratch.storage.generation ||
        held.frame != scratch.row->startFrame ||
        held.cohortRoot != scratch.row->Invocation().actionFiring) return false;
    const auto* attempt = FindImmediateEntryAttempt(engine, held.cohortRoot);
    if (attempt == nullptr || attempt->lane.slot != held.originalLane.slot ||
        attempt->lane.generation != held.originalLane.generation ||
        !engine.immediateActionLane.MatchesReservedMemberSpan(held.originalLane,
            held.cohortRoot, held.originalLaneDemand,
            held.laneFirstMemberOrdinal,
            held.laneMemberManifests.data(), held.laneMemberCount)) return false;
    for (std::size_t side = 0; side < held.laneSides.size(); ++side)
        if (!(held.laneSides[side] == held.laneOriginals[side].Identity()) ||
            !held.laneTransferProofs[side].MatchesOriginalScope(held.laneOriginals[side],
                held.cohortRoot, held.frame, held.descriptors[side], engine.timelineArms)) return false;
    harken::Plan03GroupSliceInput primary{};
    primary.executeFrame = held.frame;
    primary.decision = held.coordinator;
    harken::ImmediateLanePrivateVariableControlEntryScope entryScope{};
    return held.lanePrimary == held.laneOriginals[2].Identity() &&
        held.laneTransferProofs[2].MatchesOriginalScope(held.laneOriginals[2],
            held.cohortRoot, held.frame, primary, engine.timelineArms) &&
        BuildPrivateInitialVcLaneEntryScope(engine, scratch, &entryScope) &&
        engine.immediateActionLane.MatchesPrivateVariableControlEntry(held.originalLane,
            held.cohortRoot, held.originalLaneDemand, held.laneEntryOrdinal, entryScope,
            engine.timelinePool, engine.timelineArms, engine.decisions,
            held.laneOriginals, held.laneTransferProofs);
}

bool ValidatePreparedVariableControlExposureOwner(void* opaque) noexcept {
    const auto* context = static_cast<harken::EngineActionPlayScratch::
        PreparedVariableControlExposureOwnerContext*>(opaque);
    if (context == nullptr || context->engine == nullptr ||
        context->scratch == nullptr || context->row == nullptr) return false;
    harken::EngineActionPlayScratch::PreparedDirectExposureOwnerContext parent{
        context->engine, context->scratch};
    return ValidatePrivateInitialVcPageTransfer(*context->engine, *context->scratch) &&
        ValidatePrivateInitialVcPageBatch(*context->engine, *context->scratch) &&
        ValidatePrivateInitialVcLaneTransfer(*context->engine, *context->scratch) &&
        ValidatePreparedDirectExposureOwner(&parent);
}

bool CommitPreparedVariableControlExposureOwner(void* opaque, std::uint64_t) noexcept {
    return ValidatePreparedVariableControlExposureOwner(opaque);
}

bool ReleaseInitialFrontierBindings(harken::Engine& engine,
    const harken::FrontierEntryReceiptRef& entry, std::uint64_t completedAudioSequence,
    const harken::EngineActionPlayScratch* prepared = nullptr,
    const harken::Plan03UnpublishedRetirementToken* witnessed = nullptr) noexcept {
    if (!entry.Valid()) return true;
    for (const auto& scratch : engine.actionPlayScratch) {
        const auto& owner = scratch.storage.deferredContainerOwner;
        if (scratch.storage.phase != harken::EngineFrontierAttemptPhase::PublishedStopping ||
            !owner.active || owner.attemptGeneration != scratch.storage.generation ||
            !(owner.stoppingEntry == entry)) continue;
        if (witnessed == nullptr || !witnessed->Valid() ||
            !(*witnessed == owner.unpublishedRetirement)) return false;
    }
    auto& groups = engine.timelineGroupCaptureScratch;
    const auto count = engine.timelinePool.CaptureLivePlan03Groups(groups.data(), groups.size());
    if (count > groups.size()) return false;
    const auto* originalActivation = engine.decisions.ResolveFrontierActivation(entry.coordinator);
    if (originalActivation == nullptr || !(originalActivation->Descriptor().entry == entry))
        return false;
    // Applied initial admission must remain available until each delayed Start is read.
    // Check the complete cohort before returning any pins or detaching any binding.
    for (std::size_t index = 0; index < count; ++index) {
        const auto& group = groups[index];
        if (group.frontier == nullptr || group.lease == nullptr ||
            !(group.frontier->entry == entry) || group.frontier->role != harken::FrontierGroupRole::EntryMember ||
            (!group.frontier->variableSide.Valid() && !group.frontier->queueSignal.Valid() &&
             !(group.identity.backing == harken::Plan03GroupBacking::Page && group.frontier->queueInitial.Valid())) ||
            group.frontier->transition.Valid() ||
            group.lease->Capture().state != harken::AudioSliceState::SliceApplied) continue;
        if ((group.frontier->queueSignal.Valid() ||
             (group.identity.backing == harken::Plan03GroupBacking::Page && group.frontier->queueInitial.Valid())) && engine.timelinePool.FrontierMemberBindingDetached(
                group.identity, entry, completedAudioSequence)) continue;
        for (std::uint32_t member = group.sourceControlCount; member < group.memberCount; ++member) {
            const auto arm = group.members[member];
            if (arm.slot >= engine.initialFrontierArmPins.size()) return false;
            const auto& owned = engine.initialFrontierArmPins[arm.slot];
            if (!owned.pin.Valid()) continue;
            if (!(owned.entry == entry) || !harken::Engine::SameOriginalSingleArm(owned.arm, arm)) return false;
            auto* row = engine.timelineArms.RowAt(arm.slot);
            if (row == nullptr || row->reservation.test_and_set(std::memory_order_acquire)) return false;
            const auto state = row->state.load(std::memory_order_acquire);
            const auto read = row->frontierLastReadSequence.load(std::memory_order_acquire);
            const bool exact = row->identity.load(std::memory_order_acquire) ==
                    ((static_cast<std::uint64_t>(arm.generation) << 32) | arm.slot) &&
                row->renderSlot == arm.renderSlot && row->renderGeneration == arm.renderGeneration &&
                row->frontierAdmission == group.frontier && row->frontierAdmissionLease == group.lease;
            const bool waiting = row->startFrame > group.frontier->operation.order.executeFrame &&
                row->startedBlockSequence.load(std::memory_order_acquire) == 0 &&
                state != harken::ArmState::CancelRequested && state != harken::ArmState::Tombstoned;
            row->reservation.clear(std::memory_order_release);
            if (!exact || waiting || (read != 0 && completedAudioSequence <= read)) return false;
        }
    }
    const auto sameConditional = [](const auto& a, const auto& b) noexcept {
        return a.slot == b.slot && a.generation == b.generation && a.currentVersion == b.currentVersion &&
            a.pendingVersion == b.pendingVersion && a.current.slot == b.current.slot &&
            a.current.generation == b.current.generation && a.successor.slot == b.successor.slot &&
            a.successor.generation == b.successor.generation;
    };
    const auto conditionalCompletion = [&](const harken::Plan03PageGroupView& target) noexcept {
        if (target.frontier == nullptr || target.lease == nullptr || target.members == nullptr ||
            target.frontier->role != harken::FrontierGroupRole::Future ||
            !(target.frontier->entry == entry) ||
            target.identity.backing != harken::Plan03GroupBacking::ImmediateLane || target.identity.sliceIndex != 1u ||
            !target.frontier->queueConditional.Valid() || !target.frontier->transition.Valid() ||
            target.sourceControlCount != 1u || target.memberCount <= target.sourceControlCount) return false;
        harken::DecisionCommittedSnapshot decision{};
        if (!engine.decisions.CaptureCommitted(target.identity.decision, &decision) || decision.sliceCount != 2u ||
            decision.transitionGate.slot != target.frontier->transition.slot ||
            decision.transitionGate.generation != target.frontier->transition.generation) return false;
        std::uint32_t matches = 0;
        for (std::size_t candidate = 0; candidate < count; ++candidate) {
            const auto& source = groups[candidate];
            if (source.frontier == nullptr || source.lease == nullptr || source.members == nullptr ||
                source.frontier->role != harken::FrontierGroupRole::EntryMember ||
                !(source.frontier->entry == entry) || source.identity.backing != target.identity.backing ||
                source.identity.sliceIndex != 0u || !SameCanonicalDecision(source.identity.decision, target.identity.decision) ||
                !sameConditional(source.frontier->queueConditional, target.frontier->queueConditional) ||
                !(source.frontier->primary == target.frontier->primary) ||
                source.frontier->operation.owner != target.frontier->operation.owner ||
                source.frontier->transition.slot != target.frontier->transition.slot ||
                source.frontier->transition.generation != target.frontier->transition.generation ||
                source.frontier->operation.order.executeFrame != source.frontier->transition.audibleFrame ||
                source.frontier->operation.order.executeFrame >= target.frontier->operation.order.executeFrame ||
                source.memberCount != target.memberCount || source.sourceControlCount != target.sourceControlCount) continue;
            for (std::uint16_t member = 0; member < target.memberCount; ++member)
                if (!harken::Engine::SameOriginalSingleArm(source.members[member], target.members[member])) return false;
            ++matches;
        }
        return matches == 1u;
    };
    // The natural C1 owns both phases. Keep its Source loans until the
    // actual Target slice is final; retiring only the Prelude leaks C1.
    for (std::size_t index = 0; index < count; ++index) {
        const auto& group = groups[index];
        if (!conditionalCompletion(group)) continue;
        const auto state = group.lease->Capture().state;
        if (state != harken::AudioSliceState::SliceApplied && state != harken::AudioSliceState::SliceInvalidated)
            return false;
    }
    // Nongrouped Current Starts own an Engine pin bound to the empty primary
    // Coordinator. Return only those original loans before any backing detach.
    // EntryMember and Future loans retain their existing retirement paths.
    for (std::size_t slot = 0; slot < engine.initialFrontierArmPins.size(); ++slot) {
        auto& owned = engine.initialFrontierArmPins[slot];
        if (!owned.pin.Valid() || !(owned.entry == entry)) continue;
        const auto arm = owned.arm;
        if (!arm.Valid() || arm.slot != slot) return false;
        auto* row = engine.timelineArms.RowAt(arm.slot);
        if (row == nullptr || row->reservation.test_and_set(std::memory_order_acquire))
            return false;
        const bool originalRow = row->identity.load(std::memory_order_acquire) ==
                ((static_cast<std::uint64_t>(arm.generation) << 32) | arm.slot) &&
            row->renderSlot == arm.renderSlot &&
            row->renderGeneration == arm.renderGeneration;
        bool primaryLoan = false;
        bool primaryValid = false;
        bool waitingForStart = false;
        if (originalRow) {
            for (std::size_t index = 0; index < count; ++index) {
                const auto& group = groups[index];
                if (group.frontier == nullptr || group.lease == nullptr ||
                    !group.frontier->Valid() || !(group.frontier->entry == entry) ||
                    group.frontier->role != harken::FrontierGroupRole::Coordinator ||
                    row->frontierAdmission != group.frontier ||
                    row->frontierAdmissionLease != group.lease) continue;
                primaryLoan = true;
                primaryValid = group.identity == originalActivation->Descriptor().primary &&
                    group.identity == group.frontier->primary &&
                    group.identity == group.frontier->operation.group &&
                    group.frontier->operation.kind == harken::FrontierOperationKind::Entry &&
                    group.memberCount == 0u && group.sourceControlCount == 0u &&
                    !row->parentGroup.Valid() &&
                    row->memberIndex == UINT16_MAX;
                const auto state = row->state.load(std::memory_order_acquire);
                waitingForStart = group.lease->Capture().state == harken::AudioSliceState::SliceApplied &&
                    row->startFrame > group.frontier->operation.order.executeFrame &&
                    row->startedBlockSequence.load(std::memory_order_acquire) == 0 &&
                    state != harken::ArmState::CancelRequested && state != harken::ArmState::Tombstoned;
                break;
            }
        }
        row->reservation.clear(std::memory_order_release);
        if (!originalRow) return false;
        if (!primaryLoan) continue;
        if (waitingForStart) return false;
        // The held original pin prevents reuse. Native Release independently
        // rechecks the full identity, admission and strict-greater read fence.
        if (!primaryValid || !owned.pin.Release(completedAudioSequence)) return false;
        owned.arm = {};
        owned.entry = {};
    }
    // Detach the Target while its Prelude still proves the shared two-slice identity.
    for (std::uint32_t phase = 0; phase < 2u; ++phase) {
        for (std::size_t index = 0; index < count; ++index) {
            const auto& group = groups[index];
            if (group.frontier == nullptr || !(group.frontier->entry == entry) ||
                (phase == 0u ? !conditionalCompletion(group) :
                    group.frontier->role != harken::FrontierGroupRole::EntryMember)) continue;
            // Returned native members may already have retired and reused their arm slots.
            if ((group.frontier->queueSignal.Valid() ||
                 (group.identity.backing == harken::Plan03GroupBacking::Page && group.frontier->queueInitial.Valid())) && engine.timelinePool.FrontierMemberBindingDetached(
                    group.identity, entry, completedAudioSequence)) continue;
            for (std::uint32_t member = 0; member < group.memberCount; ++member) {
                const auto arm = group.members[member];
                if (arm.slot >= engine.initialFrontierArmPins.size()) return false;
                auto& owned = engine.initialFrontierArmPins[arm.slot];
                if (!owned.pin.Valid()) continue;
                if (!(owned.entry == entry) || owned.arm.generation != arm.generation ||
                    owned.arm.renderGeneration != arm.renderGeneration ||
                    !owned.pin.Release(completedAudioSequence)) return false;
                owned.arm = {};
                owned.entry = {};
            }
            if (group.frontier->queueSignal.Valid() ||
                (group.identity.backing == harken::Plan03GroupBacking::Page && group.frontier->queueInitial.Valid())) {
                const auto decision = group.identity.decision;
                const bool hasBinding = engine.timelinePool.HasFrontierOwnerOperations(
                    group.frontier->operation.owner, decision);
                harken::DecisionCommittedSnapshot committed{};
                const bool published = originalActivation->State() != harken::FrontierReceiptState::Prepared;
                if (published && (decision.slot >= engine.decisionRetirements.size() ||
                    !engine.decisions.CaptureCommitted(decision, &committed))) return false;
                if (published) {
                    const auto& prior = engine.decisionRetirements[decision.slot];
                    if (prior.decision.Valid() &&
                        (!SameCanonicalDecision(prior.decision, decision) ||
                         prior.group.slot != committed.armGroup.slot || prior.group.generation != committed.armGroup.generation ||
                         prior.rootInstance != entry.owner.invocation || prior.rootScheduleEpoch != entry.owner.invocationEpoch ||
                         (prior.phase != harken::EngineDecisionOwnershipPhase::ActiveArrival &&
                          prior.phase != harken::EngineDecisionOwnershipPhase::Retiring))) return false;
                    if (group.memberCount == 0) {
                        harken::FrontierActivationReceipt receipt{};
                        harken::ArmGroupSnapshot arms{};
                        if (group.sourceControlCount != 0 ||
                            originalActivation->Read(entry, completedAudioSequence, &receipt) !=
                                harken::FrontierReceiptRead::Ready ||
                            !engine.armGroups.Capture(committed.armGroup, &arms) ||
                            !SameCanonicalDecision(arms.parent, decision) || arms.memberCount != 0 ||
                            arms.ackedCount != 0 || arms.tombstonedCount != 0 || arms.maxTombstoneSequence != 0 ||
                            (arms.state != harken::ArmGroupState::Ready &&
                             arms.state != harken::ArmGroupState::Retiring)) return false;
                        // A completed entry without Sources has no member tombstone to wait for.
                        if (arms.state != harken::ArmGroupState::Retiring &&
                            !engine.armGroups.BeginRetire(committed.armGroup)) return false;
                    }
                }
                // Native detachment may erase an unread binding. Copy everything first.
                if (hasBinding) {
                    const bool detached = group.frontier->queueSignal.Valid()
                        ? engine.queueInstances.ReleaseFrontierSignal(*group.frontier, completedAudioSequence)
                        : engine.timelinePool.DetachPlan03GroupFrontier(group.identity, completedAudioSequence);
                    if (!detached) return false;
                }
                if (published) {
                    auto& retirement = engine.decisionRetirements[decision.slot];
                    if (!retirement.decision.Valid()) {
                        retirement.decision = decision;
                        retirement.group = committed.armGroup;
                        retirement.rootInstance = entry.owner.invocation;
                        retirement.rootScheduleEpoch = entry.owner.invocationEpoch;
                        retirement.phase = harken::EngineDecisionOwnershipPhase::ActiveArrival;
                    }
                    if (group.memberCount == 0)
                        retirement.phase = harken::EngineDecisionOwnershipPhase::Retiring;
                }
            } else if ((witnessed == nullptr || !(group.identity == witnessed->member)) &&
                engine.timelinePool.HasFrontierOwnerOperations(group.frontier->operation.owner, group.identity.decision) &&
                !engine.timelinePool.FrontierMemberBindingDetached(group.identity, entry, completedAudioSequence) &&
                !engine.timelinePool.DetachPlan03GroupFrontier(group.identity, completedAudioSequence)) return false;
        }
    }
    const auto* activation = engine.decisions.ResolveFrontierActivation(entry.coordinator);
    if (activation == nullptr || !(activation->Descriptor().entry == entry)) return false;
    if ((witnessed == nullptr || !(activation->Descriptor().primary == witnessed->primary)) &&
        engine.timelinePool.HasFrontierOwnerOperations(entry.owner, entry.coordinator) &&
        !engine.timelinePool.DetachPlan03GroupFrontier(activation->Descriptor().primary,
            completedAudioSequence)) return false;
    for (auto& record : engine.queueContinuationRecords) {
        if (!record.occupied || record.descriptor.entry != entry || !record.sourceTransitionBinding.Valid()) continue;
        if (!engine.transitionInstances.ReleaseFrontierBinding(record.sourceTransitionBinding)) return false;
        record.sourceTransitionBinding = {};
    }
    harken::DecisionCommittedSnapshot coordinator{};
    const bool committed = engine.decisions.CaptureCommitted(entry.coordinator, &coordinator);
    if (!committed && prepared == nullptr) return false;
    const auto decisionCount = committed ? coordinator.participantCount : prepared->initialFrontierSideCount;
    for (std::uint32_t index = 0; index < decisionCount; ++index) {
        harken::DecisionParticipantRef participant{};
        if (committed) {
            if (!engine.decisions.CaptureCommittedParticipant(entry.coordinator, index, &participant) ||
                participant.kind != harken::DecisionParticipantKind::Subdecision) return false;
        } else participant = prepared->storage.initialFrontierParticipants[index];
        const harken::DecisionToken decision{participant.slot, participant.generation};
        if (engine.decisions.HasFrontierDecisionBinding(decision) &&
            !engine.decisions.ReleaseFrontierDecisionBinding(decision)) return false;
    }
    return originalActivation->State() == harken::FrontierReceiptState::Prepared
        ? engine.variables.CancelPreparedFrontierEntryReadUse(entry)
        : engine.variables.FinishFrontierEntryReadUse(entry, completedAudioSequence);
}

bool ValidatePrivateInitialVcLaneGroup(harken::Engine& engine,
    std::uint64_t root, const harken::Plan03GroupSliceIdentity& identity,
    const harken::Plan03GroupSliceInput& expected, bool cancelling = false) noexcept {
    harken::Plan03PageGroupView actual{};
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 3> cohort{};
    const auto count = engine.timelinePool.CaptureImmediateLaneCohortGroups(
        root, cohort.data(), cohort.size());
    if (!identity.Exact() || identity.backing != harken::Plan03GroupBacking::ImmediateLane ||
        identity.transportEpoch != engine.timelinePool.Epoch() ||
        !SameCanonicalDecision(identity.decision, expected.decision) ||
        identity.sliceIndex != expected.sliceIndex || count > cohort.size() ||
        std::none_of(cohort.begin(), cohort.begin() + count,
            [&](const auto& group) noexcept { return group.identity == identity; }) ||
        !(engine.timelinePool.PrivatePlan03GroupBindable(identity) ||
            (cancelling && engine.timelinePool.PrivateImmediateLaneGroupRetirementReady(
                identity, engine.mixer.BlocksRendered()))) ||
        !engine.timelinePool.ResolvePlan03GroupSliceProducer(identity, &actual) ||
        !(actual.identity == identity) || actual.memberCount != expected.memberCount ||
        actual.sourceControlCount != expected.sourceControlCount ||
        (actual.frontier != nullptr && actual.frontier->Valid())) return false;
    for (std::uint16_t index = 0; index < expected.memberCount; ++index) {
        if (expected.members == nullptr || actual.members == nullptr) return false;
        const auto& arm = actual.members[index];
        const auto& member = expected.members[index];
        harken::TimelineArmObservation observed{};
        if (arm.slot != member.slot || arm.generation != member.generation ||
            arm.renderSlot != member.renderSlot || arm.renderGeneration != member.renderGeneration ||
            !engine.timelineArms.Observe(member, &observed) ||
            !SameCanonicalDecision(observed.parentGroup.decision, expected.decision) ||
            observed.memberIndex != index) return false;
    }
    return true;
}

bool CancelPrivateInitialVcPageCohort(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    auto& held = scratch.privateInitialVcPageCohort;
    held.ReleasePageTransferProofs();
    held.ReleaseLaneTransferProofs();
    // The private batch borrows Decision and Voice programs until actual cancellation.
    if (held.pageBatchSelected && !held.pageBatchConsumed && scratch.queueTransactions.Valid()) {
        if (!engine.timelinePool.CancelPreparedTransactionBatch(&scratch.queueTransactions)) return false;
        held.pageBatchCancelledAttemptGeneration = scratch.storage.generation;
    }
    const bool hasPreparedSide = std::any_of(held.sides.begin(), held.sides.end(),
        [](const auto& side) noexcept { return side.Valid(); });
    const bool hasLane = held.lanePrimary.Exact() || std::any_of(
        held.laneSides.begin(), held.laneSides.end(),
        [](const auto& side) noexcept { return side.Exact(); });
    if (held.sequence == 0 && !hasPreparedSide && !hasLane) return true;
    const auto fail = [&engine]() noexcept {
        engine.runtimeRecreateRequired = true;
        return false;
    };
    if (scratch.storage.phase == harken::EngineFrontierAttemptPhase::Published)
        return fail();
    if (held.attemptGeneration != scratch.storage.generation) return fail();
    if (held.backing == harken::EngineActionPlayScratch::PrivateInitialVcPageCohort::Backing::ImmediateLane) {
        if (held.cohortRoot == 0 || scratch.row == nullptr ||
            held.cohortRoot != scratch.row->Invocation().actionFiring) return fail();
        for (std::size_t side = held.laneSides.size(); side-- > 0;) {
            if (!held.laneSides[side].Exact()) continue;
            if (held.laneOriginals[side].Valid()) {
                if (!engine.timelinePool.CancelPrivateImmediateLaneGroup(
                        &held.laneOriginals[side], &held.laneSides[side])) return false;
            } else {
                if (held.laneTransferRequired ||
                    !ValidatePrivateInitialVcLaneGroup(engine, held.cohortRoot,
                        held.laneSides[side], held.descriptors[side], true)) return fail();
                if (!engine.CancelOriginalQueueLaneGroup(
                        held.cohortRoot, held.laneSides[side])) return false;
                held.laneSides[side] = {};
            }
        }
        if (held.lanePrimary.Exact()) {
            harken::Plan03GroupSliceInput primary{};
            primary.executeFrame = held.frame;
            primary.decision = held.coordinator;
            if (held.laneOriginals[2].Valid()) {
                if (!engine.timelinePool.CancelPrivateImmediateLaneGroup(
                        &held.laneOriginals[2], &held.lanePrimary)) return false;
            } else {
                if (held.laneTransferRequired ||
                    !ValidatePrivateInitialVcLaneGroup(engine, held.cohortRoot,
                        held.lanePrimary, primary, true)) return fail();
                if (!engine.CancelOriginalQueueLaneGroup(
                        held.cohortRoot, held.lanePrimary)) return false;
                held.lanePrimary = {};
            }
        }
    }
    for (std::size_t side = held.sides.size(); side-- > 0;) {
        if (held.sides[side].Valid() &&
            !engine.timelinePool.CancelPreparedPlan03GroupSlice(&held.sides[side]))
            return fail();
    }
    // Only the unbound coordinator can exit before the exposure owner.
    // Bound or committed frontiers keep their existing cancellation order.
    if (scratch.frontierCoordinator.Valid() &&
        engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator) == nullptr &&
        !scratch.frontierPrimary.Valid()) {
        harken::EngineActionPlayScratch::PreparedDirectExposureOwnerContext context{
            &engine, &scratch};
        if (!CancelPreparedDirectExposureOwner(&context)) return fail();
    }
    held.sequence = 0;
    return true;
}

void ReleaseTimelineVoiceBindings(harken::Engine& engine, VnVoiceHandle render, bool snapshotOnly);

bool WithdrawUnpublishedSourceLoansBeforeExposure(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    ReleasePreparedTimelineVoiceProofs(scratch);
    const auto retire = [&](harken::EnginePreparedTimelineVoiceStart& start) noexcept {
        const auto* source = engine.originalSourceSubmissions.Find(start.arm);
        if (!start.arm.Valid() || source == nullptr) return true;
        // Disposed is published only after the real consumer has dropped both loans.
        // An applied source can still own a physical voice; its ordinary Stop tail remains.
        if (source->State() == harken::OriginalSourceSubmissionRegistry::Phase::Disposed) {
            // Installation also disposes the command range. Only a real physical
            // release permits returning the new storage loans here.
            (void)engine.ReturnPendingVariableLeafSourceAfterPhysicalRelease(start.arm);
            return true;
        }
        const auto phase = source->State();
        if (phase == harken::OriginalSourceSubmissionRegistry::Phase::Published ||
            phase == harken::OriginalSourceSubmissionRegistry::Phase::ConsumerOwned ||
            phase == harken::OriginalSourceSubmissionRegistry::Phase::CleanupPending) {
            (void)engine.timelineArms.RequestCancel(start.arm);
            return false;
        }
        if (!engine.originalSourceSubmissions.CancelBoundPreparation(
                start.arm, engine.preparedVoiceCommandBatchProof)) return false;
        // The private initializer owns an Arm pin. Return it before Exposure
        // retires the Arm; the later Voice owner still releases its resources.
        if (start.initialVariableReadUse.Valid()) {
            if (!engine.variables.CancelPreparedTimelineReadUse(start.initialVariableReadUse)) return false;
            start.initialVariableReadUse = {};
        }
        if (engine.originalSourceSubmissions.OriginalVoiceStillCurrent(start.arm))
            ReleaseTimelineVoiceBindings(engine, start.renderHandle, false);
        if (!engine.originalSourceSubmissions.DisposeUnpublishedVoice(start.arm)) return false;
        // Transfer the actual completed physical disposition to the stable owner before
        // Exposure can retire the Arm and another issuance can reuse the registry row.
        start.voiceOwnershipHeld = false;
        if (!engine.ReturnPendingVariableLeafSourceAfterPhysicalRelease(start.arm)) return false;
        return engine.originalSourceSubmissions.WithdrawUnpublished(start.arm);
    };
    for (std::uint32_t i = 0; i < scratch.voiceStartCount; ++i)
        if (!retire(scratch.voiceStarts[i])) return false;
    for (std::uint32_t i = 0; i < scratch.queueSuccessorVoiceStartCount; ++i)
        if (!retire(scratch.queueSuccessorVoiceStarts[i])) return false;
    return true;
}

bool CancelInitialVariableControlArmGroups(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept;

bool CancelPreparedVariableControlExposureOwner(void* opaque) noexcept {
    if (opaque == nullptr) return false;
    auto& context = *static_cast<harken::EngineActionPlayScratch::
        PreparedVariableControlExposureOwnerContext*>(opaque);
    if (context.engine == nullptr || context.scratch == nullptr || context.row == nullptr) return false;
    auto& scratch = *context.scratch;
    ReleasePreparedTimelineVoiceProofs(scratch);
    auto& engine = *context.engine;
    auto& row = *context.row;
    if (!WithdrawUnpublishedSourceLoansBeforeExposure(engine, scratch)) return false;
    if (!CancelPrivateInitialVcPageCohort(engine, scratch)) return false;
    auto& retirement = scratch.storage;
    if (engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator) == nullptr &&
        scratch.privateInitialVcPageCohort.pageBatchSelected &&
        !scratch.privateInitialVcPageCohort.pageBatchConsumed &&
        scratch.variableControlInitialCommittedSliceCount != 0 &&
        !RetirePrivateUnboundInitialVariableControlArms(engine, scratch)) return false;
    const bool resumeRetirement = retirement.initialVcRetirementProof.Valid() &&
        retirement.initialVcRetirementDecisionsOpen;
    const bool completedRetirement = CompletedPrivateVcArmRetirement(engine, scratch);
    if ((resumeRetirement || (completedRetirement && !retirement.initialVcUnboundRetirementConsumed)) &&
        (retirement.initialVcRetirementEntry != scratch.frontierDescriptor.entry ||
         retirement.initialVcRetirementPrimary != scratch.frontierDescriptor.primary ||
         !engine.decisions.IsOpen(scratch.frontierCoordinator))) return false;
    // A reserved coordinator has no activation until PrepareFrontierActivation.
    // CanRollbackPreparedFrontierDecision rejects that empty state. Skip it and
    // release the reservation in CancelPreparedDirectExposureOwner instead.
    if (scratch.frontierCoordinator.Valid() &&
        engine.decisions.ResolveFrontierActivation(scratch.frontierCoordinator) !=
            nullptr) {
        if (!resumeRetirement && !completedRetirement &&
            !engine.decisions.CanRollbackPreparedFrontierDecision(
                scratch.frontierCoordinator, scratch.frontierCoordinator)) {
            return false;
        }
        for (std::uint32_t index = 0; !resumeRetirement && !completedRetirement &&
                index < scratch.initialFrontierSideCount; ++index) {
            const auto& side = scratch.storage.initialFrontierSides[index];
            harken::Plan03PageGroupView group{};
            harken::DecisionCommittedSnapshot committed{};
            if (!engine.decisions.CaptureCommitted(side.decision, &committed)) continue;
            auto* service = engine.ResolvePlayableService(side.service);
            if (service == nullptr ||
                !engine.timelinePool.ResolvePlan03GroupSliceProducer(side.group, &group) ||
                group.frontier == nullptr || !engine.decisions.CanRollbackPreparedFrontierDecision(
                side.decision, scratch.frontierCoordinator, group.frontier)) {
                return false;
            }
        }
        const bool beginRetirement = !retirement.initialVcRetirementProof.Valid() &&
            !completedRetirement && retirement.initialVcExactCommandAttemptGeneration ==
                scratch.storage.generation && retirement.initialVcExactCommandCount != 0 &&
            scratch.initialFrontierSideCount != 0 && !row.pendingImmediateEntry;
        if (beginRetirement &&
            !PreparePrivateInitialVariableControlArmRetirement(engine, scratch)) return false;
        for (std::uint32_t index = 0; !resumeRetirement && !completedRetirement &&
                index < scratch.initialFrontierSideCount; ++index) {
            const auto& side = scratch.storage.initialFrontierSides[index];
            harken::Plan03PageGroupView group{};
            harken::DecisionCommittedSnapshot committed{};
            if (!engine.decisions.CaptureCommitted(side.decision, &committed)) continue;
            if (!engine.timelinePool.ResolvePlan03GroupSliceProducer(side.group, &group) || group.frontier == nullptr ||
                !engine.decisions.RollbackPreparedFrontierDecision(side.decision,
                scratch.frontierCoordinator, group.frontier)) {
                return false;
            }
            auto* service = engine.ResolvePlayableService(side.service);
            if (service == nullptr) return false;
            if (service->variableControlDiscreteDecision.slot == side.decision.slot &&
                service->variableControlDiscreteDecision.generation == side.decision.generation)
                service->variableControlDiscreteDecisionCommitted = false;
            else service->variableControlContinuousDecisionCommitted = false;
        }
        if (retirement.initialVcRetirementProof.Valid()) {
            if (!retirement.initialVcRetirementDecisionsOpen) {
                if (!engine.decisions.RollbackPreparedFrontierDecision(
                        scratch.frontierCoordinator, scratch.frontierCoordinator)) return false;
                retirement.initialVcRetirementDecisionsOpen = true;
            }
            if (!FinishPrivateInitialVariableControlArmRetirement(engine, scratch)) return false;
        }
        if (!ReleaseInitialFrontierBindings(engine, scratch.frontierDescriptor.entry, 0, &scratch)) {
            return false;
        }
        for (std::uint32_t index = 0; index < scratch.initialFrontierSideCount; ++index) {
            auto* service = engine.ResolvePlayableService(scratch.storage.initialFrontierSides[index].service);
            if (service == nullptr) return false;
            if (!service->frontierLifetimeEntry.Valid()) continue;
            if (!(service->frontierLifetimeEntry == scratch.frontierDescriptor.entry) ||
                !service->frontierLifetimePin.Release()) {
                return false;
            }
            service->frontierLifetimeEntry = {};
        }
    }
    harken::EngineActionPlayScratch::PreparedDirectExposureOwnerContext exposure{&engine, &scratch};
    if (!CancelPreparedDirectExposureOwner(&exposure)) {
        return false;
    }
    while (scratch.variableControlInitialCommittedSliceCount != 0) {
        auto& slice = scratch.variableControlInitialCommittedSlices[
            scratch.variableControlInitialCommittedSliceCount - 1u];
        if (!engine.timelinePool.RollbackCommittedPlan03GroupSlice(&slice)) {
            return false;
        }
        --scratch.variableControlInitialCommittedSliceCount;
    }
    if (!CancelInitialVariableControlArmGroups(engine, scratch)) return false;
    return CancelPreparedQueueCompletionBindings(engine, scratch);
}

bool CancelInitialVariableControlArmGroups(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    const auto cancelGroups = [&](harken::EnginePlayableServiceRow& row,
        const auto& prepared,
        const harken::EngineActionPlayScratch::PreparedVariableControlOwnerContext& owner) noexcept {
        for (const auto side : {harken::VariableControlSide::Discrete,
                               harken::VariableControlSide::Continuous}) {
            auto* group = side == harken::VariableControlSide::Discrete
                ? &row.variableControlDiscreteArmGroup : &row.variableControlContinuousArmGroup;
            if (!group->Valid()) continue;
            harken::ArmGroupSnapshot snapshot{};
            if (!engine.armGroups.Capture(*group, &snapshot)) return false;
            // Real audio tombstones retain the group for ordinary fenced retirement.
            if (snapshot.ackedCount != 0 || snapshot.tombstonedCount != 0) continue;
            const auto decision = side == harken::VariableControlSide::Discrete
                ? row.variableControlDiscreteDecision : row.variableControlContinuousDecision;
            const auto count = side == harken::VariableControlSide::Discrete
                ? row.variableControlInitialDiscreteMemberCount : row.variableControlInitialContinuousMemberCount;
            auto& receipt = side == harken::VariableControlSide::Discrete
                ? row.VariableControlDiscreteGroupCancellation() : row.VariableControlContinuousGroupCancellation();
            harken::VariableControlInstanceSnapshot instance{};
            const bool liveInstance = engine.variableControlInstances.Capture(row.variableControlInstance, &instance);
            if (snapshot.parent.slot != decision.slot || snapshot.parent.generation != decision.generation ||
                snapshot.memberCount != count || snapshot.tombstonedCount != 0 || receipt.group.Valid()) return false;
            harken::EnginePlayableServiceRow::UnpublishedVariableGroupCancellation next{};
            if (liveInstance) {
                const auto& actualSide = side == harken::VariableControlSide::Discrete ? instance.discrete : instance.continuous;
                // CancelSide can terminate this exact Pending side before exposure
                // rollback. Its unpublished group still needs the same ownership checks.
                if (!row.InvocationValid() || engine.ResolvePlayableService(harken::EnginePlayableServiceReference{
                        row.identity, row.ownerInstance, row.ownerEpoch, row.invocationGeneration}) != &row ||
                    !engine.playablePartitions.Owns(row.partition, row.identity) ||
                    instance.rootInstance != row.ownerInstance || instance.world != row.Invocation().worldGeneration ||
                    actualSide.decision.slot != decision.slot || actualSide.decision.generation != decision.generation ||
                    (actualSide.state != harken::VariableControlSideState::Pending &&
                     actualSide.state != harken::VariableControlSideState::Terminal &&
                     !(owner.activated && owner.activationSide == side && owner.activationDecision != nullptr &&
                       SameCanonicalDecision(*owner.activationDecision, decision) && owner.activationBank != nullptr &&
                       actualSide.state == harken::VariableControlSideState::Committed &&
                       actualSide.lastApplied.slot == owner.activationBank->slot &&
                       actualSide.lastApplied.generation == owner.activationBank->generation)) ||
                    !engine.decisions.IsOpen(decision)) return false;
                next = {row.identity, row.partition, row.variableControlInstance, side, decision, *group,
                    instance.rootInstance, row.rootInstance, row.ownerInstance, row.ownerEpoch, row.invocationGeneration,
                    row.Invocation().worldGeneration, row.Invocation().actionFiring, count};
            } else {
                if (owner.committed) return false;
                if (prepared.Valid()) {
                    if (prepared.Token().slot != row.variableControlInstance.slot ||
                        prepared.Token().generation != row.variableControlInstance.generation) return false;
                } else {
                    // A cancelled VC does not release its independently owned groups.
                    // Prove the original unpublished decision and each actual arm instead.
                    const auto& original = side == harken::VariableControlSide::Discrete
                        ? scratch.variableControlDiscreteDecision : scratch.variableControlContinuousDecision;
                    if (&row != scratch.row ||
                        !owner.OriginalServiceAssociationMatches(&engine, &row) ||
                        owner.OriginalServiceInput().Pool() != &engine.playablePartitions ||
                        !engine.decisions.OwnsOpenPreparedReservation(original) ||
                        !SameCanonicalDecision(original.Token(), decision) ||
                        snapshot.maxTombstoneSequence != 0 ||
                        scratch.voiceStartCount > scratch.voiceStarts.size()) return false;
                    for (std::uint32_t memberIndex = 0; memberIndex < count; ++memberIndex) {
                        harken::ArmGroupMemberSnapshot member{};
                        harken::TimelineArmObservation arm{};
                        if (!engine.armGroups.CaptureMember(*group, static_cast<std::uint16_t>(memberIndex), &member) ||
                            member.acked || member.tombstoned ||
                            !engine.timelineArms.Observe(member.token, &arm) ||
                            arm.state != harken::ArmState::Prepared ||
                            !SameCanonicalDecision(arm.parentGroup.decision, decision) ||
                            arm.memberIndex != memberIndex || arm.startedBlockSequence != 0 ||
                            arm.tombstoneAudioSequence != 0 || arm.finalSourcePublished) return false;
                        std::uint32_t matches = 0;
                        for (std::uint32_t index = 0; index < scratch.voiceStartCount; ++index) {
                            const auto& voice = scratch.voiceStarts[index];
                            if (!harken::Engine::SameOriginalSingleArm(voice.arm, member.token)) continue;
                            if (!voice.prepared || !voice.armOwnershipHeld ||
                                !harken::Engine::SameOriginalSingleArm(voice.armPreparation.arm, member.token) ||
                                !SameCanonicalDecision(voice.armPreparation.parentGroup.decision, decision) ||
                                voice.armPreparation.memberIndex != memberIndex) return false;
                            ++matches;
                        }
                        if (matches != 1u) return false;
                    }
                }
            }
            if (!engine.armGroups.CancelBeforePublication(*group)) return false;
            receipt = next;
            *group = {};
        }
        return true;
    };
    if (scratch.row != nullptr && !cancelGroups(*scratch.row, scratch.variableControlInstance,
            scratch.variableControlOwnerContext)) return false;
    for (std::uint32_t index = 0; index < scratch.variableControlNestedVariableControlCount; ++index) {
        if (!scratch.variableControlNestedServices[index].Valid()) {
            if (scratch.variableControlNestedVariableControls[index].Valid() ||
                scratch.variableControlNestedDecisions[index].Valid() ||
                scratch.storage.nestedContinuousDecisions[index].Valid()) return false;
            continue;
        }
        auto* nested = engine.ResolvePlayableService(scratch.variableControlNestedServices[index]);
        if (nested == nullptr || !cancelGroups(*nested, scratch.variableControlNestedVariableControls[index],
                scratch.variableControlNestedOwnerContexts[index])) return false;
    }
    return true;
}

template <typename Context>
bool RegisterFrontierPreparedOwner(harken::EngineActionPlayScratch& scratch, Context* context,
    harken::PlayableTreeExecutor::OwnerValidateFn validate,
    harken::PlayableTreeExecutor::OwnerCommitFn commit,
    harken::PlayableTreeExecutor::OwnerCancelFn cancel) noexcept {
    using Scratch = harken::EngineActionPlayScratch;
    using Kind = harken::FrontierOwnerKind;
    using Commit = harken::FrontierOwnerCommitPhase;
    using Cancel = harken::FrontierOwnerCancelPhase;
    Kind kind{};
    Commit commitPhase{};
    Cancel cancelPhase{};
    if constexpr (std::is_same_v<Context, harken::EngineFrontierServiceOwnerContext>) {
        kind = Kind::Service; commitPhase = Commit::Mode; cancelPhase = Cancel::Mode;
    } else if constexpr (std::is_same_v<Context, harken::EngineFrontierQueueCurrentOwnerContext>) {
        kind = Kind::Occurrence; commitPhase = Commit::Completion; cancelPhase = Cancel::Completion;
    } else if constexpr (std::is_same_v<Context, harken::EngineFrontierQueueInitialDecisionContext>) {
        kind = Kind::Decision; commitPhase = Commit::Resource; cancelPhase = Cancel::InitialDecision;
    } else if constexpr (std::is_same_v<Context, harken::EngineFrontierQueueEntryDecisionOwnerContext>) {
        kind = Kind::Decision; commitPhase = Commit::Resource; cancelPhase = Cancel::Exposure;
    } else if constexpr (std::is_same_v<Context, harken::EngineFrontierQueueBindingOwnerContext>) {
        kind = Kind::Timeline; commitPhase = Commit::Resource; cancelPhase = Cancel::Exposure;
    } else if constexpr (std::is_same_v<Context, harken::EngineFrontierQueueOwnerContext>) {
        kind = Kind::Mode; commitPhase = Commit::Mode; cancelPhase = Cancel::Mode;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedSelectionOwnerContext>) {
        kind = Kind::Selection; commitPhase = Commit::Selection; cancelPhase = Cancel::Selection;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedPendingSelectionOwnerContext>) {
        kind = Kind::Selection; commitPhase = Commit::Selection; cancelPhase = Cancel::Selection;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedDirectSelectionOwnerContext>) {
        kind = Kind::Selection; commitPhase = Commit::Selection; cancelPhase = Cancel::Selection;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedDecisionOwnerContext>) {
        kind = Kind::Decision; commitPhase = Commit::Decision; cancelPhase = Cancel::Mode;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedOccurrenceOwnerContext>) {
        kind = Kind::Occurrence; commitPhase = Commit::Completion; cancelPhase = Cancel::Completion;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedCompositeOwnerContext>) {
        kind = Kind::Composite; commitPhase = Commit::Completion; cancelPhase = Cancel::Completion;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedTimelineVoiceOwnerContext>) {
        kind = Kind::Voice; commitPhase = Commit::Voice; cancelPhase = Cancel::Voice;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedActionResourceOwnerContext>) {
        kind = Kind::Timeline; commitPhase = Commit::Resource; cancelPhase = Cancel::Exposure;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedVariableControlExposureOwnerContext>) {
        kind = Kind::Group; commitPhase = Commit::Resource; cancelPhase = Cancel::FrontierBinding;
    } else if constexpr (std::is_same_v<Context, Scratch::PreparedDirectExposureOwnerContext>) {
        kind = Kind::Timeline; commitPhase = Commit::Resource; cancelPhase = Cancel::Exposure;
    } else if constexpr (std::is_same_v<Context, harken::EngineQueueFutureAttemptOwnerContext> ||
                         std::is_same_v<Context, harken::EngineScheduleChildAttemptOwnerContext>) {
        kind = Kind::Timeline; commitPhase = Commit::Resource; cancelPhase = Cancel::Exposure;
    } else {
        static_assert(std::is_same_v<Context, Scratch::PreparedQueueInstanceOwnerContext> ||
            std::is_same_v<Context, Scratch::PreparedVariableControlOwnerContext>);
        kind = Kind::Mode; commitPhase = Commit::Mode; cancelPhase = Cancel::Mode;
    }
    auto& storage = scratch.storage;
    auto& ledger = storage.ownerLedger;
    if (!scratch.frontierOwnerBatchRegistered) {
        if (!scratch.playableTreeExecutor.EnablePreparedOwnerRollbackRetention() ||
            !scratch.playableTreeExecutor.AdoptPreparedOwnerToken(&storage.ownerBatch,
                harken::EngineFrontierOwnerBatch::Validate,
                harken::EngineFrontierOwnerBatch::Commit,
                harken::EngineFrontierOwnerBatch::Cancel)) return false;
        scratch.frontierOwnerBatchRegistered = true;
        scratch.authorityOwnerContext.dependencies = &ledger;
    }
    const harken::FrontierOwnerRef identity = [&]() noexcept {
        if constexpr (std::is_same_v<Context, harken::EngineQueueFutureAttemptOwnerContext> ||
                      std::is_same_v<Context, harken::EngineScheduleChildAttemptOwnerContext>) {
            return harken::FrontierOwnerRef{kind, context->child.slot,
                                           context->child.generation};
        }
        return harken::FrontierOwnerRef{kind, ledger.NextContextSlot(kind),
                                       storage.generation};
    }();
    return ledger.Add(storage.generation, identity, context,
        commitPhase, cancelPhase, validate, commit, cancel);
}

bool IssueInitialSelectionBatch(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    auto& storage = scratch.storage;
    if (storage.initialSelection.preparation.mode == harken::EngineSelectionPreparationMode::Legacy)
        return storage.initialSelectionBatch.Empty() ||
            (storage.initialSelection.BoundFor(storage.generation) &&
             storage.initialSelectionBatch.MatchesOwner(&engine.selectionMemory, storage.initialSelection.identity));
    if (storage.initialSelection.preparation.mode != harken::EngineSelectionPreparationMode::PendingInitial)
        return false;
    if (!storage.initialSelectionBatch.Empty())
        return storage.initialSelectionBatch.MatchesOwner(&engine.selectionMemory, storage.initialSelection.identity);
    if (scratch.selectionPlayCount > scratch.selectionPlays.size()) return false;
    std::array<harken::PreparedSelectionPlayV1*, harken::kSelectionPathNodeCapacity> members{};
    for (std::uint32_t index = 0; index < scratch.selectionPlayCount; ++index) {
        if (!scratch.selectionPlays[index].Valid()) return false;
        members[index] = &scratch.selectionPlays[index];
    }
    return storage.initialSelection.IssueBatch(engine.selectionMemory, storage.initialSelectionBatch,
        storage.generation, members.data(), scratch.selectionPlayCount) == harken::SelectionMemoryStatusV1::Ok &&
        storage.initialSelectionBatch.MatchesMaterialized();
}

bool RegisterInitialSelectionOwners(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    if (!IssueInitialSelectionBatch(engine, scratch)) return false;
    if (scratch.storage.initialSelection.preparation.mode == harken::EngineSelectionPreparationMode::PendingInitial) {
        using Context = harken::EngineActionPlayScratch::PreparedPendingSelectionOwnerContext;
        auto& context = scratch.pendingSelectionOwnerContext;
        context = {&scratch.storage, scratch.storage.generation, &engine.selectionMemory};
        return RegisterFrontierPreparedOwner(scratch, &context, Context::Validate, Context::Commit, Context::Cancel);
    }
    for (std::uint32_t index = 0; index < scratch.selectionPlayCount; ++index) {
        auto& context = scratch.selectionOwnerContexts[index];
        context = {&engine.selectionMemory, &scratch.selectionPlays[index], false};
        if (!RegisterFrontierPreparedOwner(scratch, &context, ValidatePreparedSelectionOwner,
                CommitPreparedSelectionOwner, CancelPreparedSelectionOwner)) return false;
    }
    return true;
}

bool RegisterCurrentFrontierVoiceOwners(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) noexcept {
    while (scratch.frontierCurrentVoiceOwnerCount < scratch.voiceStartCount) {
        const auto index = scratch.frontierCurrentVoiceOwnerCount;
        auto& context = scratch.voiceStarts.Owners()[index];
        context = {&engine, &scratch.voiceStarts[index], false};
        if (!RegisterFrontierPreparedOwner(scratch, &context,
                ValidatePreparedTimelineVoiceOwner, CommitPreparedTimelineVoiceOwner,
                CancelPreparedTimelineVoiceOwner)) return false;
        ++scratch.frontierCurrentVoiceOwnerCount;
    }
    return true;
}

