// --- engine-session entries of the binding seam. The public verbs
// surface these one for one: the C entry
// points at the header tail unpack their descriptors and forward here, so
// semantics, validation order, and result codes live in this layer. ---

VnResult RegisterBinding(Engine& engine, BindingId id,
                         VnVariableId variableId, std::uint32_t scopeKind,
                         std::uint32_t targetId, const CurvePoint* points,
                         const CurveHandlePair* handles,
                         std::uint32_t pointCount,
                         std::uint32_t transitionMs,
                         std::uint64_t ownerCookie) {
    // Registration has no audible side effect: it touches the definition
    // pool only, never a voice, a bus, or the command queue. The owner
    // cookie stamps provenance (0 = caller; the pack apply paths pass
    // their handle so later unwinds can tell their entries from same-id
    // caller re-registrations).
    return engine.bindings.RegisterBinding(id, variableId, scopeKind,
                                           targetId, points, handles,
                                           pointCount, transitionMs,
                                           &engine.logicLogRing, ownerCookie);
}

VnResult UnregisterBindingImpl(Engine& engine, BindingId id,
                               VnPackHandle ignoredRecipeOwner) {
    if (engine.bindings.Find(id) == nullptr) {
        return VN_UNKNOWN_ID;
    }
    // Section 5.4: refused while ANY reference exists — attachments, live
    // voice instances, parked identity holders, or pending-start pinned
    // sets (parked and pending logical voices hold live instances,
    // sections 5.6/5.7). Detach first; no hidden cascade.
    if (engine.bindings.AnyAttachmentOf(id)) {
        return VN_IN_USE;
    }
    bool recipeReferenced = false;
    engine.logicPacks.ForEachRecord(
        [id, ignoredRecipeOwner,
         &recipeReferenced](const PackLogicRecord& record) {
            if (ignoredRecipeOwner != 0 &&
                record.handle == ignoredRecipeOwner) {
                return;
            }
            for (const PackLogicImage::VoiceRecipe& recipe :
                 record.voiceRecipes) {
                for (VnBindingId recipeBinding : recipe.bindings) {
                    if (recipeBinding == id) {
                        recipeReferenced = true;
                        return;
                    }
                }
            }
        });
    if (recipeReferenced) {
        return VN_IN_USE;
    }
    bool referenced = false;
    engine.params.ForEachInstanceOf(id, [&](VnVoiceHandle render) {
        if (engine.voices.IsAlive(render)) {
            referenced = true;
        }
    });
    // A voice-effect apply instance (effect-parameter scope) references the
    // definition just as a built-in instance does; unregister is refused while
    // one exists, or a recycled definition slot could be driven by a stale
    // instance (section 5.4 extended to the effect-parameter instance layer). A
    // parked voice's instances keep their slots as a held reservation, so they
    // are caught by this same scan (no separate parked-id list): a parked
    // instance is an unconditional reference (its render handle no longer
    // resolves), a live one while its render identity is alive.
    engine.bindings.ForEachVoiceEffectInstanceOf(
        id, [&](VnVoiceHandle render, bool parked) {
            if (parked || engine.voices.IsAlive(render)) {
                referenced = true;
            }
        });
    if (referenced) {
        return VN_IN_USE;
    }
    for (const ParkRecord& rec : engine.parkRecords) {
        if (!rec.active) {
            continue;
        }
        for (const ParamSystem::InstanceState& inst : rec.bindingInstances) {
            if (inst.definitionId == id) {
                return VN_IN_USE;
            }
        }
    }
    for (const PendingStartRecord& rec : engine.pendingStarts) {
        if (!rec.active) {
            continue;
        }
        for (std::uint32_t i = 0; i < rec.pinnedBindingCount; ++i) {
            if (rec.pinnedBindings[i].bindingId == id) {
                return VN_IN_USE;
            }
        }
    }
    const VnResult result = engine.bindings.UnregisterBinding(id);
    if (result == VN_OK) {
        // Only inert leftovers (dead voices awaiting slot reuse) can
        // remain; removing them keeps the recycled definition slot
        // unreadable through stale instances.
        engine.params.PurgeInstancesOf(id);
        engine.bindings.PurgeVoiceEffectInstancesOf(id);
    }
    return result;
}

VnResult UnregisterBinding(Engine& engine, BindingId id) {
    return UnregisterBindingImpl(engine, id, 0);
}

VnResult UnregisterPackBinding(Engine& engine, BindingId id,
                               VnPackHandle owner) {
    if (owner == 0 || engine.bindings.DefinitionOwnerOf(id) != owner) {
        return VN_IN_USE;
    }
    return UnregisterBindingImpl(engine, id, owner);
}

VnResult ReplaceBinding(Engine& engine, BindingId id, VnVariableId variableId,
                        std::uint32_t scopeKind, std::uint32_t targetId,
                        const CurvePoint* points,
                        const CurveHandlePair* handles,
                        std::uint32_t pointCount,
                        std::uint32_t transitionMs) {
    BindingTable::PreparedDefinitionToken prepared;
    const VnResult valid = engine.bindings.PrepareReplaceDefinition(
        id, variableId, scopeKind, targetId, points, handles, pointCount,
        transitionMs, &prepared);
    if (valid != VN_OK) {
        return valid;
    }
    const BindingTable::Definition* definition = engine.bindings.Find(id);
    if (definition != nullptr && definition->scopeKind == kTargetScopeVoice &&
        definition->targetId == kTargetVoicePitch &&
        ::BindingReplaceTouchesGuardedVoice(engine, id)) {
        engine.commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    engine.bindings.CommitPreparedDefinition(&prepared);
    return VN_OK;
}

bool VariableConsumerBlocked(const Engine& engine,
                             VnVariableId variableId) noexcept {
    return engine.variables.BlocksVariableConsumer(variableId);
}

VnResult AttachBinding(Engine& engine, BindingId id, std::uint32_t scopeKind,
                       VnObjectId objectId) {
    std::uint32_t busIndex = 0;
    if (scopeKind == kTargetScopeBus ||
        scopeKind == VN_TARGET_SCOPE_BUS_EFFECT_PARAM) {
        busIndex = engine.buses.FindIndex(objectId);
        if (busIndex == kInvalidBusIndex) {
            return VN_UNKNOWN_ID;
        }
    } else if (scopeKind == kTargetScopeVoice) {
        if (!engine.registry.Lookup(objectId).Valid()) {
            StreamManager::StreamFacts facts;
            bool knownHost = engine.streams.FindFile(objectId, &facts);
            const auto world = engine.variables.CurrentPlayableWorld();
            for (std::uint32_t i = 0; !knownHost && i < world.propertyCount; ++i)
                knownHost = world.properties[i].stableId == objectId;
            if (!knownHost) {
                return VN_UNKNOWN_ID;
            }
        }
    } else {
        // Unsupported scope refused, never guessed. VN_TARGET_SCOPE_VOICE_-
        // EFFECT_PARAM lands here too: a voice-effect binding attaches to a
        // LIVE voice via Vn_ApplyVoiceBinding, not to a playable id — no
        // playable-id attach path exists for it.
        return VN_INVALID_ARG;
    }
    // A bus-effect binding attaches only to a slot that already holds the
    // matching effect type and a bindable parameter: an empty slot, a
    // mismatched installed type, or a slot beyond the bus's fx slots is refused
    // VN_INVALID_ARG with zero side effects (no dormant bind-before-install on
    // the live path). The fold-time type recheck remains as defense in depth.
    if (scopeKind == VN_TARGET_SCOPE_BUS_EFFECT_PARAM) {
        const BindingTable::Definition* def = engine.bindings.Find(id);
        if (def == nullptr) {
            return VN_UNKNOWN_ID;
        }
        if (!engine.effectParamTargets.CanBind(
                EffectParamTargetStore::Scope::Bus, busIndex,
                UnpackEffectParamLocator(def->targetId))) {
            return VN_INVALID_ARG;
        }
    }
    // Section 10.4: every attach runs the publication-capacity check.
    // The pure precheck keeps the ordering side-effect-free: only an
    // otherwise-admissible attach consumes worst-case growth, so a pool
    // or validation refusal never needs a capacity undo.
    const VnResult pre = engine.bindings.CanAttach(id, scopeKind, objectId);
    const auto targetGeneration =
        scopeKind == kTargetScopeBus || scopeKind == VN_TARGET_SCOPE_BUS_EFFECT_PARAM
            ? engine.buses.GenerationAt(busIndex) : 0u;
    if (pre != VN_OK) {
        // Re-route through attach so a pool-full refusal logs the
        // pool-naming record exactly once.
        return engine.bindings.Attach(id, scopeKind, objectId, busIndex,
                                      &engine.logicLogRing, 0, targetGeneration);
    }
    const BindingTable::Definition* definition = engine.bindings.Find(id);
    if (definition != nullptr &&
        definition->sourceKind == BindingSourceKind::Variable &&
        VariableConsumerBlocked(engine, definition->variableId)) {
        engine.commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    // Effect-parameter bindings emit on their own command path (opcodes 14/22
    // via the update's fold+flush), not through the property publisher's
    // transaction, so they do not consume its section-10.4 worst-case budget.
    const bool usesPublisher = scopeKind != VN_TARGET_SCOPE_BUS_EFFECT_PARAM;
    if (usesPublisher &&
        !engine.propertyPublisher.TryGrowWorstCase(1, &engine.logicLogRing)) {
        return VN_INVALID_CONFIG;
    }
    const VnResult result = engine.bindings.Attach(
        id, scopeKind, objectId, busIndex, &engine.logicLogRing, 0, targetGeneration);
    if (result != VN_OK) {
        if (usesPublisher) {
            engine.propertyPublisher.ShrinkWorstCase(1); // defensive undo
        }
    } else if (scopeKind == kTargetScopeBus) {
        // The control graph grew: the next update's loop scan refreshes
        // the section-11.5 freeze marks against the new wiring.
    }
    return result;
}

VnResult DetachBinding(Engine& engine, BindingId id, std::uint32_t scopeKind,
                       VnObjectId objectId) {
    // A departing BUS contribution marks its target in the store (ramping
    // back to neutral over the definition's transitionMs at the next
    // publication); detaching also shrinks the control graph, so the next
    // update rescans the section-11.5 freeze marks.
    if (!engine.bindings.HasAttachment(id, scopeKind, objectId)) {
        return VN_UNKNOWN_ID;
    }
    const BindingTable::Definition* definition = engine.bindings.Find(id);
    if (scopeKind == kTargetScopeVoice && definition != nullptr &&
        definition->targetId == kTargetVoicePitch &&
        ::BindingDetachTouchesGuardedVoice(engine, id, objectId)) {
        engine.commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    const VnResult result =
        engine.bindings.Detach(id, scopeKind, objectId, &engine.busTargets);
    if (result != VN_OK) {
        return result;
    }
    if (scopeKind == kTargetScopeBus) {
    }
    // Symmetric with AttachBinding: effect-parameter attachments never grew the
    // publisher's worst-case budget, so their detach must not shrink it.
    if (scopeKind != VN_TARGET_SCOPE_BUS_EFFECT_PARAM) {
        engine.propertyPublisher.ShrinkWorstCase(1);
    }
    if (scopeKind == kTargetScopeVoice) {
        // Section 5.3: detach stops future instantiation AND neutralizes
        // the live instances born from this attachment (their
        // contribution ramps to neutral with the definition's
        // transitionMs; the slots free when their voices end). Parked
        // logical voices hold live instances, so their identity lists
        // shed the attachment too; pending-start pinned sets are
        // deliberately NOT altered (section 5.7 — an already-resolved
        // queued play keeps its resolved set).
        engine.params.NeutralizeInstancesOf(id, objectId);
        for (ParkRecord& rec : engine.parkRecords) {
            if (!rec.active) {
                continue;
            }
            for (std::size_t i = rec.bindingInstances.size(); i-- > 0;) {
                const ParamSystem::InstanceState& inst =
                    rec.bindingInstances[i];
                if (inst.definitionId == id && !inst.viaApply &&
                    inst.attachmentObjectId == objectId) {
                    rec.bindingInstances.erase(rec.bindingInstances.begin() +
                                               static_cast<std::ptrdiff_t>(i));
                }
            }
        }
    }
    return VN_OK;
}

bool PrepareVoiceBindings(Engine& engine,
    std::vector<ParamSystem::PreparedBindingToken>& preparations, std::size_t count) noexcept {
    try {
        if (count > preparations.capacity() && !engine.AllowNativeBackingAllocation()) return false;
        preparations.resize(count);
        for (auto& preparation : preparations)
            if (!preparation.IsPrepared() && !engine.params.PrepareBinding(&preparation)) return false;
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    } catch (const std::length_error&) {
        return false;
    }
}

VnResult ApplyVoiceBinding(Engine& engine, VnVoiceHandle publicHandle,
                           BindingId id) {
    const BindingTable::Definition* def = engine.bindings.Find(id);
    if (def == nullptr) {
        return VN_UNKNOWN_ID;
    }
    const VoiceLedger::Resolved resolved =
        engine.ledger.Classify(publicHandle);
    // Voice-effect-parameter scope: apply to the live voice via the effect-
    // parameter instance layer (BindingTable), leaving ParamSystem's built-in
    // target instance layer untouched. The definition's locator names the fx
    // slot / parameter; slot/type/index liveness against the installed effect
    // is enforced by the store at fold time.
    if (def->scopeKind == VN_TARGET_SCOPE_VOICE_EFFECT_PARAM) {
        if (resolved.kind == VoiceLedger::HandleKind::Parked) {
            ParkRecord& rec = engine.parkRecords[resolved.ledgerSlot];
            const EffectParamLocator locator =
                UnpackEffectParamLocator(def->targetId);
            bool compatibleEffect = false;
            for (const CapturedEffect& effect : rec.effects) {
                if (effect.slot == locator.slot &&
                    effect.type == locator.effectType &&
                    locator.paramIndex <
                        EffectParamCount(effect.type)) {
                    compatibleEffect = true;
                    break;
                }
            }
            if (!compatibleEffect) {
                return VN_INVALID_ARG;
            }
            const VnResult pre =
                engine.bindings.CanApplyVoiceEffectInstance(
                    id, publicHandle, rec.parkedRenderHandle);
            if (pre == VN_OK &&
                def->sourceKind == BindingSourceKind::Variable &&
                VariableConsumerBlocked(engine, def->variableId)) {
                engine.commands.NoteBackpressure();
                return VN_BACKPRESSURE;
            }
            const VnResult applied =
                engine.bindings.ApplyVoiceEffectInstance(
                    id, publicHandle, rec.parkedRenderHandle,
                    &engine.logicLogRing, rec.stateEmitter);
            if (applied == VN_OK) {
                if (!engine.bindings.PrepareVoiceEffectInstancePark(rec.parkedRenderHandle)) {
                    (void)engine.bindings.ClearVoiceEffectInstance(rec.parkedRenderHandle, id);
                    return kResultNoBinding;
                }
                engine.bindings.ParkVoiceEffectInstances(
                    rec.parkedRenderHandle);
            }
            return applied;
        }
        if (resolved.kind != VoiceLedger::HandleKind::Live) {
            return VN_STALE_HANDLE;
        }
        const VnResult voiceLive =
            engine.voices.CheckLive(resolved.renderHandle);
        if (voiceLive != VN_OK) {
            return voiceLive;
        }
        // The effect must already be installed at the locator's slot with the
        // matching type and a bindable parameter: an empty slot, a mismatched
        // type, or a slot beyond fxSlotsPerVoice is refused VN_INVALID_ARG with
        // zero side effects (no dormant bind-before-install on the live path).
        if (!engine.effectParamTargets.CanBind(
                EffectParamTargetStore::Scope::Voice,
                resolved.renderHandle,
                UnpackEffectParamLocator(def->targetId))) {
            return VN_INVALID_ARG;
        }
        const VnResult pre = engine.bindings.CanApplyVoiceEffectInstance(
            id, publicHandle, resolved.renderHandle);
        if (pre == VN_OK &&
            def->sourceKind == BindingSourceKind::Variable &&
            VariableConsumerBlocked(engine, def->variableId)) {
            engine.commands.NoteBackpressure();
            return VN_BACKPRESSURE;
        }
        return engine.bindings.ApplyVoiceEffectInstance(
            id, publicHandle, resolved.renderHandle,
            &engine.logicLogRing, engine.params.EmitterHandleOf(resolved.renderHandle));
    }
    if (def->scopeKind != kTargetScopeVoice) {
        return VN_INVALID_ARG;
    }
    if (resolved.kind == VoiceLedger::HandleKind::Parked) {
        ParkRecord& rec = engine.parkRecords[resolved.ledgerSlot];
        for (const ParamSystem::InstanceState& instance :
             rec.bindingInstances) {
            if (instance.definitionId == id && instance.viaApply) {
                return VN_IN_USE;
            }
        }
        if (rec.bindingInstances.size() >=
                engine.config.voiceBindingInstanceSlots ||
            rec.bindingInstances.size() ==
                rec.bindingInstances.capacity()) {
            ++engine.bindingInstanceRefusedCount;
            LogRecord record{};
            record.level = VN_LOG_WARN;
            record.code = kLogCodeBindingPoolExhausted;
            record.arg0 = kBindingPoolVoiceInstances;
            record.arg1 = engine.config.voiceBindingInstanceSlots;
            engine.logicLogRing.Push(record);
            return kResultNoBinding;
        }
        bool targetAlreadyOwned = false;
        for (const ParamSystem::BindingState& binding : rec.bindings) {
            if (binding.targetId == def->targetId) {
                targetAlreadyOwned = true;
                break;
            }
        }
        if (!targetAlreadyOwned) {
            for (const ParamSystem::InstanceState& instance :
                 rec.bindingInstances) {
                const BindingTable::Definition* existing =
                    engine.bindings.Find(instance.definitionId);
                if (existing != nullptr &&
                    existing->scopeKind == kTargetScopeVoice &&
                    existing->targetId == def->targetId) {
                    targetAlreadyOwned = true;
                    break;
                }
            }
        }
        if (def->sourceKind == BindingSourceKind::Variable &&
            VariableConsumerBlocked(engine, def->variableId)) {
            engine.commands.NoteBackpressure();
            return VN_BACKPRESSURE;
        }
        if (def->targetId == kTargetVoicePitch &&
            ::GuardCompletionMutation(engine, publicHandle) != VN_OK) {
            return VN_BACKPRESSURE;
        }
        if (!targetAlreadyOwned &&
            !engine.propertyPublisher.TryGrowWorstCase(
                1, &engine.logicLogRing)) {
            return VN_INVALID_CONFIG;
        }
        ParamSystem::InstanceState instance;
        instance.definitionId = id;
        instance.attachmentObjectId = {};
        instance.viaApply = true;
        rec.bindingInstances.push_back(instance);
        if (!targetAlreadyOwned) {
            ++rec.instanceReservedTargets;
        }
        return VN_OK;
    }
    if (resolved.kind != VoiceLedger::HandleKind::Live) {
        return VN_STALE_HANDLE;
    }
    const VnResult live = engine.voices.CheckLive(resolved.renderHandle);
    if (live != VN_OK) {
        return live;
    }
    const BindingDefinitionView view = engine.bindings.ViewOf(*def);
    const ParamSystem::InstanceBindResult pre =
        engine.params.CanBindVoiceInstance(view, resolved.renderHandle,
                                           /*attachmentObjectId=*/{},
                                           /*viaApply=*/true);
    if (pre != ParamSystem::InstanceBindResult::Ok) {
        switch (engine.params.BindVoiceInstance(
            view, resolved.renderHandle, /*attachmentObjectId=*/{},
            /*viaApply=*/true)) {
        case ParamSystem::InstanceBindResult::Duplicate:
            return VN_IN_USE;
        case ParamSystem::InstanceBindResult::CapacityRefused:
            return VN_INVALID_CONFIG;
        case ParamSystem::InstanceBindResult::SlotCeiling:
        case ParamSystem::InstanceBindResult::TableFull:
        default: {
            ++engine.bindingInstanceRefusedCount;
            LogRecord record{};
            record.level = VN_LOG_WARN;
            record.code = kLogCodeBindingPoolExhausted;
            record.arg0 = kBindingPoolVoiceInstances;
            record.arg1 = engine.config.voiceBindingInstanceSlots;
            engine.logicLogRing.Push(record);
            return kResultNoBinding;
        }
        }
    }
    if (pre == ParamSystem::InstanceBindResult::Ok &&
        def->sourceKind == BindingSourceKind::Variable &&
        VariableConsumerBlocked(engine, def->variableId)) {
        engine.commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    ParamSystem::PreparedBindingToken preparation;
    if (!engine.params.PrepareBinding(&preparation)) return VN_BACKPRESSURE;
    if (def->targetId == kTargetVoicePitch &&
        ::GuardCompletionMutation(engine, publicHandle) != VN_OK) {
        return VN_BACKPRESSURE;
    }
    switch (engine.params.BindVoiceInstance(view,
                                            resolved.renderHandle,
                                            /*attachmentObjectId=*/{},
                                            /*viaApply=*/true, &preparation)) {
    case ParamSystem::InstanceBindResult::Ok:
        return VN_OK;
    case ParamSystem::InstanceBindResult::Duplicate:
        return VN_IN_USE;
    case ParamSystem::InstanceBindResult::CapacityRefused:
        // The section-10.4 growth refusal already logged both numbers.
        return VN_INVALID_CONFIG;
    case ParamSystem::InstanceBindResult::SlotCeiling:
    case ParamSystem::InstanceBindResult::TableFull:
    default: {
        ++engine.bindingInstanceRefusedCount;
        LogRecord record{};
        record.level = VN_LOG_WARN;
        record.code = kLogCodeBindingPoolExhausted;
        record.arg0 = kBindingPoolVoiceInstances;
        record.arg1 = engine.config.voiceBindingInstanceSlots;
        engine.logicLogRing.Push(record);
        return kResultNoBinding;
    }
    }
}

VnResult ClearVoiceBinding(Engine& engine, VnVoiceHandle publicHandle,
                           BindingId id) {
    const VoiceLedger::Resolved resolved =
        engine.ledger.Classify(publicHandle);
    const BindingTable::Definition* def = engine.bindings.Find(id);
    if (resolved.kind == VoiceLedger::HandleKind::Parked) {
        ParkRecord& rec = engine.parkRecords[resolved.ledgerSlot];
        if (def != nullptr &&
            def->scopeKind == VN_TARGET_SCOPE_VOICE_EFFECT_PARAM) {
            return engine.bindings.ClearVoiceEffectInstance(
                       rec.parkedRenderHandle, id)
                       ? VN_OK
                       : VN_UNKNOWN_ID;
        }
        for (std::size_t i = 0; i < rec.bindingInstances.size(); ++i) {
            const ParamSystem::InstanceState& instance =
                rec.bindingInstances[i];
            if (instance.definitionId != id || !instance.viaApply) {
                continue;
            }
            const std::uint32_t targetId =
                def != nullptr ? def->targetId : UINT32_MAX;
            if (targetId == kTargetVoicePitch &&
                ::GuardCompletionMutation(engine, publicHandle) != VN_OK) {
                return VN_BACKPRESSURE;
            }
            rec.bindingInstances.erase(rec.bindingInstances.begin() +
                                       static_cast<std::ptrdiff_t>(i));
            if (targetId != UINT32_MAX) {
                bool targetStillOwned = false;
                for (const ParamSystem::BindingState& binding :
                     rec.bindings) {
                    if (binding.targetId == targetId) {
                        targetStillOwned = true;
                        break;
                    }
                }
                if (!targetStillOwned) {
                    for (const ParamSystem::InstanceState& remaining :
                         rec.bindingInstances) {
                        const BindingTable::Definition* existing =
                            engine.bindings.Find(
                                remaining.definitionId);
                        if (existing != nullptr &&
                            existing->scopeKind ==
                                kTargetScopeVoice &&
                            existing->targetId == targetId) {
                            targetStillOwned = true;
                            break;
                        }
                    }
                }
                if (!targetStillOwned &&
                    rec.instanceReservedTargets > 0) {
                    engine.propertyPublisher.ShrinkWorstCase(1);
                    --rec.instanceReservedTargets;
                }
            }
            return VN_OK;
        }
        return VN_UNKNOWN_ID;
    }
    if (resolved.kind != VoiceLedger::HandleKind::Live) {
        return VN_STALE_HANDLE;
    }
    const VnResult live = engine.voices.CheckLive(resolved.renderHandle);
    if (live != VN_OK) {
        return live;
    }
    // A voice-effect-parameter binding's instance lives in the effect-parameter
    // layer; its removal returns the parameter to its base at the next fold.
    if (def != nullptr &&
        def->scopeKind == VN_TARGET_SCOPE_VOICE_EFFECT_PARAM) {
        return engine.bindings.ClearVoiceEffectInstance(resolved.renderHandle, id)
                   ? VN_OK
                   : VN_UNKNOWN_ID;
    }
    if (def != nullptr && def->scopeKind == kTargetScopeVoice &&
        def->targetId == kTargetVoicePitch) {
        bool hasExactInstance = false;
        engine.params.ForEachInstance(
            [&](const ParamSystem::InstanceCaptureRow& row) {
                if (row.handle == resolved.renderHandle &&
                    row.definitionId == id && row.viaApply &&
                    !row.neutralized) {
                    hasExactInstance = true;
                }
            });
        if (!hasExactInstance) {
            return VN_UNKNOWN_ID;
        }
        if (::GuardCompletionMutation(engine, publicHandle) != VN_OK) {
            return VN_BACKPRESSURE;
        }
    }
    return engine.params.NeutralizeVoiceInstance(resolved.renderHandle, id)
               ? VN_OK
               : VN_UNKNOWN_ID;
}

// --- attribution capture (section 12): the two caller-buffer verbs. Both
// read logic-thread state only, never allocate, and share the buffer /
// truncation contract documented at the public header. ---

namespace {

// Shared buffer validation: requiredCount is mandatory (truncation
// reports through it); a sized buffer must exist and declare a known row
// vintage. Row shapes have a single vintage so far, so the check is an
// exact sizeof match — later vintages widen this the VnConfig way.
template <typename Row>
VnResult ValidateCaptureBuffer(const Row* out, std::uint32_t capacity,
                               const std::uint32_t* requiredCount) {
    if (requiredCount == nullptr) {
        return VN_INVALID_ARG;
    }
    if (capacity > 0 && (out == nullptr || out->structSize != sizeof(Row))) {
        return VN_INVALID_ARG;
    }
    return VN_OK;
}

// Books one capture truncation: counted, and flagged through the
// logic-side ring with the named code. requiredCount already reported
// the full need, so the call itself stays VN_OK.
void NoteCaptureTruncated(harken::Engine& engine, std::uint64_t surface,
                          std::uint64_t required) {
    ++engine.captureTruncationCount;
    harken::LogRecord record{};
    record.level = VN_LOG_WARN;
    record.code = harken::kLogCodeCaptureTruncated;
    record.arg0 = surface;
    record.arg1 = required;
    engine.logicLogRing.Push(record);
}

// The value an untouched combine slot reports in a target row: the fold's
// no-op — 0 for the additive domains, the reduction's starting base for
// the min/max domains (a printed 0 would read as a hard filter clamp).
float UntouchedSlotValue(std::uint32_t scopeKind, std::uint32_t targetId,
                         float base) {
    const harken::TargetMeta* meta =
        harken::FindTargetMeta(scopeKind, targetId);
    if (meta == nullptr) {
        return 0.0f;
    }
    switch (meta->domain) {
    case harken::CombineDomain::AddDb:
    case harken::CombineDomain::AddCents:
    case harken::CombineDomain::Add:
    case harken::CombineDomain::AddLogHz:
    case harken::CombineDomain::AddLogQ:
        return 0.0f;
    case harken::CombineDomain::MinHz:
    case harken::CombineDomain::MaxHz:
    case harken::CombineDomain::Max:
        return base;
    }
    return 0.0f;
}

} // namespace

VnResult CapturePropertyTargets(Engine& engine, VnPropertyTargetInfo* out,
                                std::uint32_t capacity,
                                std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    std::uint32_t required = 0;
    const auto emit = [&](const VnPropertyTargetInfo& row) {
        if (required < capacity) {
            out[required] = row;
        }
        ++required;
    };
    // Bus rows first, dense (creation) index order x target id order. A
    // bus target is active when a combine slot is set, a publication
    // demand mark is pending, an attachment feeds it, or its committed
    // value sits off the neutral base (the quiescent -18 dB case the
    // capture exists to explain). Pack-authored mix lives in its own
    // slot and is not reported as apiDirectValue.
    const std::uint32_t busCount = engine.buses.BusCount();
    for (std::uint32_t bus = 0; bus < busCount; ++bus) {
        for (std::uint32_t t = 0; t < kBusTargetCount; ++t) {
            std::uint32_t feeders = 0;
            engine.bindings.ForEachBusAttachment(
                [&](const BindingTable::Attachment& a,
                    const BindingTable::Definition& def) {
                    if (a.busIndex == bus && def.targetId == t) {
                        ++feeders;
                    }
                });
            const TargetMeta* meta = FindTargetMeta(kTargetScopeBus, t);
            const float base = meta != nullptr ? meta->neutral : 0.0f;
            const bool authoredActive = engine.busTargets.SlotActive(
                bus, t, BusTargetStore::kSlotAuthoredIndex);
            const bool apiActive = engine.busTargets.SlotActive(
                bus, t, BusTargetStore::kSlotApiDirectIndex);
            const bool varActive = engine.busTargets.SlotActive(
                bus, t, BusTargetStore::kSlotVariableIndex);
            const bool pending =
                engine.busTargets.PendingPublication(bus, t) ||
                engine.variables.HasPendingWriteForBusTarget(engine.bindings,
                                                             bus, t);
            if (!authoredActive && !apiActive && !varActive && !pending &&
                feeders == 0 &&
                engine.busTargets.LastCommitted(bus, t) == base) {
                continue;
            }
            VnPropertyTargetInfo row{};
            row.structSize = sizeof(VnPropertyTargetInfo);
            row.scopeKind = VN_TARGET_SCOPE_BUS;
            row.objectId = engine.buses.IdAt(bus);
            row.targetId = t;
            row.pendingPublication = pending ? 1u : 0u;
            row.base = base;
            row.apiDirectValue =
                apiActive ? engine.busTargets.SlotValue(
                                bus, t, BusTargetStore::kSlotApiDirectIndex)
                          : UntouchedSlotValue(kTargetScopeBus, t, base);
            row.variableValue =
                varActive ? engine.busTargets.SlotValue(
                                bus, t, BusTargetStore::kSlotVariableIndex)
                          : UntouchedSlotValue(kTargetScopeBus, t, base);
            row.finalValue = engine.busTargets.Reduce(bus, t);
            row.activeBindingCount = feeders;
            row.lastPublishedRampMs =
                engine.busTargets.LastPublishedRampMs(bus, t);
            emit(row);
        }
    }
    // Live-voice rows, slot order x target id order. The walker's active
    // predicate is the parameter system's; engine-level voice liveness
    // filters here (an ended render slot awaiting reuse is not a live
    // target), and the row reports the caller's PUBLIC handle.
    engine.params.ForEachActiveTarget(
        [&](const ParamSystem::TargetCaptureRow& r) {
            if (!engine.voices.IsAlive(r.handle)) {
                return;
            }
            VnPropertyTargetInfo row{};
            row.structSize = sizeof(VnPropertyTargetInfo);
            row.scopeKind = VN_TARGET_SCOPE_VOICE;
            row.instanceHandle = engine.ledger.ToPublic(r.handle);
            row.targetId = r.targetId;
            const bool pending =
                r.pendingPublication ||
                engine.variables.HasPendingWriteForVoiceTarget(
                    engine.params, r.handle, r.targetId);
            row.pendingPublication = pending ? 1u : 0u;
            row.base = r.base;
            row.apiDirectValue =
                r.apiActive ? r.apiValue
                            : UntouchedSlotValue(kTargetScopeVoice,
                                                 r.targetId, r.base);
            row.variableValue =
                r.variableActive
                    ? r.variableValue
                    : UntouchedSlotValue(kTargetScopeVoice, r.targetId,
                                         r.base);
            row.finalValue = r.resolved;
            row.activeBindingCount = r.feederCount;
            row.lastPublishedRampMs = r.lastPublishedRampMs;
            emit(row);
        });
    *requiredCount = required;
    if (capacity > 0 && required > capacity) {
        NoteCaptureTruncated(engine, kCaptureSurfaceTargets, required);
    }
    return VN_OK;
}

VnResult CapturePropertyBindings(Engine& engine, VnPropertyBindingInfo* out,
                                 std::uint32_t capacity,
                                 std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    std::uint32_t required = 0;
    const auto emit = [&](const VnPropertyBindingInfo& row) {
        if (required < capacity) {
            out[required] = row;
        }
        ++required;
    };
    // 1. Attachment pool entries, pool index order, both scopes. A BUS
    // attachment's contribution is its last realized fold (what the
    // target rows' Variable slot sums); a VOICE attachment is an armed
    // template for future plays and contributes nothing itself.
    engine.bindings.ForEachAttachment(
        [&](const BindingTable::Attachment& a,
            const BindingTable::Definition& def) {
            VnPropertyBindingInfo row{};
            row.structSize = sizeof(VnPropertyBindingInfo);
            row.bindingId = a.bindingId;
            row.variableId = def.variableId;
            row.scopeKind = def.scopeKind;
            row.targetId = def.targetId;
            row.objectId = a.objectId;
            row.definitionRevision = def.revision;
            row.transitionMs = def.transitionMs;
            float input = 0.0f;
            if (engine.params.ScopedVariableValue(nullptr, 0,
                                                  def.variableId, &input)) {
                row.currentInput = input;
            }
            std::uint32_t flags = 0;
            if (a.scopeKind == kTargetScopeBus) {
                if (a.meterFrozen) {
                    flags |= VN_PROPERTY_BINDING_NEUTRALIZING;
                } else if (a.lastHadValue) {
                    flags |= VN_PROPERTY_BINDING_ACTIVE;
                    row.currentContribution = a.lastContribution;
                }
            } else {
                flags |= VN_PROPERTY_BINDING_ACTIVE;
            }
            row.stateFlags = flags;
            emit(row);
        });
    // 2. Live definition-backed instances, table order. Contribution and
    // the ACTIVE flag reflect the last realized evaluation; the input is
    // the Variable's value right now at the voice's emitter scope.
    engine.params.ForEachInstance(
        [&](const ParamSystem::InstanceCaptureRow& r) {
            if (!engine.voices.IsAlive(r.handle)) {
                return; // inert leftover awaiting slot reuse
            }
            VnPropertyBindingInfo row{};
            row.structSize = sizeof(VnPropertyBindingInfo);
            row.bindingId = r.definitionId;
            row.variableId = r.variableId;
            row.scopeKind = VN_TARGET_SCOPE_VOICE;
            row.targetId = r.targetId;
            row.instanceHandle = engine.ledger.ToPublic(r.handle);
            row.definitionRevision = r.lastRevision;
            row.transitionMs = r.transitionMs;
            float input = 0.0f;
            if (engine.params.ScopedVariableValue(&engine.emitters,
                                                  r.emitterHandle,
                                                  r.variableId, &input)) {
                row.currentInput = input;
            }
            // Lifecycle flags are exhaustive for instances: every live
            // entry is either evaluating (ACTIVE — an unset Variable
            // just contributes 0) or on its way out (NEUTRALIZING).
            const std::uint32_t flags =
                r.neutralized ? VN_PROPERTY_BINDING_NEUTRALIZING
                              : VN_PROPERTY_BINDING_ACTIVE;
            // The last realized contribution, unconditionally: inside
            // the clear/detach window it is still the in-force value the
            // target rows' Variable slot folds (the exit evaluation is
            // what zeroes it), and it reads 0 while the Variable has
            // never resolved — so binding rows sum to the target rows in
            // every phase, the section-12 attribution invariant.
            row.currentContribution = r.lastContribution;
            row.stateFlags = flags;
            emit(row);
        });
    // 3. Instance identities held by parked voices (section 5.6) and
    // pinned by pending-start voices (section 5.7): PENDING rows, not
    // currently evaluating. Revision and transition are the definition's
    // current (held identities evaluate the current revision at
    // return/onset), and the contribution is what the current input
    // would apply then — mirroring the parked re-evaluation.
    const auto emitHeldIdentity = [&](BindingId bindingId,
                                      VnVoiceHandle publicHandle,
                                      VnEmitterHandle emitterHandle) {
        const BindingTable::Definition* def = engine.bindings.Find(bindingId);
        if (def == nullptr) {
            return; // defensive: a held identity pins its definition
        }
        VnPropertyBindingInfo row{};
        row.structSize = sizeof(VnPropertyBindingInfo);
        row.bindingId = bindingId;
        row.variableId = def->variableId;
        row.scopeKind = def->scopeKind;
        row.targetId = def->targetId;
        row.instanceHandle = publicHandle;
        row.definitionRevision = def->revision;
        row.transitionMs = def->transitionMs;
        float input = 0.0f;
        if (engine.params.ScopedVariableValue(&engine.emitters,
                                              emitterHandle,
                                              def->variableId, &input)) {
            row.currentInput = input;
            row.currentContribution = def->Evaluate(input);
        }
        row.stateFlags = VN_PROPERTY_BINDING_PENDING;
        emit(row);
    };
    for (const ParkRecord& rec : engine.parkRecords) {
        const auto slot = engine.parkRecords.IndexOf(rec);
        if (!rec.active) {
            continue;
        }
        const VnVoiceHandle publicHandle = engine.ledger.PublicHandleForSlot(
            static_cast<std::uint32_t>(slot));
        for (const ParamSystem::InstanceState& inst : rec.bindingInstances) {
            emitHeldIdentity(inst.definitionId, publicHandle,
                             rec.stateEmitter);
        }
    }
    for (const PendingStartRecord& rec : engine.pendingStarts) {
        if (!rec.active) {
            continue;
        }
        for (std::uint32_t i = 0; i < rec.pinnedBindingCount; ++i) {
            emitHeldIdentity(rec.pinnedBindings[i].bindingId,
                             rec.publicHandle, rec.emitterHandle);
        }
    }
    *requiredCount = required;
    if (capacity > 0 && required > capacity) {
        NoteCaptureTruncated(engine, kCaptureSurfaceBindings, required);
    }
    return VN_OK;
}

static_assert(static_cast<std::uint32_t>(EffectParamUnit::Db) ==
                  VN_EFFECT_PARAMETER_UNIT_DB &&
              static_cast<std::uint32_t>(EffectParamUnit::Linear) ==
                  VN_EFFECT_PARAMETER_UNIT_LINEAR &&
              static_cast<std::uint32_t>(EffectParamUnit::Hz) ==
                  VN_EFFECT_PARAMETER_UNIT_HZ &&
              static_cast<std::uint32_t>(EffectParamUnit::Q) ==
                  VN_EFFECT_PARAMETER_UNIT_Q &&
              static_cast<std::uint32_t>(EffectParamUnit::Ms) ==
                  VN_EFFECT_PARAMETER_UNIT_MS,
              "public effect parameter units must mirror the registry");
static_assert(static_cast<std::uint32_t>(EffectParamCombine::AddDb) ==
                  VN_EFFECT_PARAMETER_COMBINE_ADD_DB &&
              static_cast<std::uint32_t>(EffectParamCombine::Multiply) ==
                  VN_EFFECT_PARAMETER_COMBINE_MULTIPLY &&
              static_cast<std::uint32_t>(EffectParamCombine::AddLogHz) ==
                  VN_EFFECT_PARAMETER_COMBINE_ADD_LOG_HZ &&
              static_cast<std::uint32_t>(EffectParamCombine::AddLogQ) ==
                  VN_EFFECT_PARAMETER_COMBINE_ADD_LOG_Q &&
              static_cast<std::uint32_t>(EffectParamCombine::None) ==
                  VN_EFFECT_PARAMETER_COMBINE_NONE &&
              static_cast<std::uint32_t>(EffectParamCombine::AddLogTime) ==
                  VN_EFFECT_PARAMETER_COMBINE_ADD_LOG_TIME,
              "public effect parameter combines must mirror the registry");
static_assert(kTargetVoiceVolume == VN_TARGET_VOICE_VOLUME &&
                  kTargetVoicePitch == VN_TARGET_VOICE_PITCH &&
                  kTargetVoiceLowpassCutoff ==
                      VN_TARGET_VOICE_LOWPASS_CUTOFF &&
                  kTargetVoiceHighpassCutoff ==
                      VN_TARGET_VOICE_HIGHPASS_CUTOFF &&
                  kTargetVoicePan == VN_TARGET_VOICE_PAN &&
                  kTargetVoiceWidth == VN_TARGET_VOICE_WIDTH &&
                  kTargetVoiceLowShelfGainDb ==
                      VN_TARGET_VOICE_LOW_SHELF_GAIN_DB &&
                  kTargetVoiceLowpassQ == VN_TARGET_VOICE_LOWPASS_Q &&
                  kTargetVoiceHighpassQ == VN_TARGET_VOICE_HIGHPASS_Q &&
                  kTargetVoiceLowShelfFreqHz ==
                      VN_TARGET_VOICE_LOW_SHELF_FREQUENCY_HZ &&
                  kTargetVoiceLowShelfQ == VN_TARGET_VOICE_LOW_SHELF_Q &&
                  kTargetVoiceHighShelfGainDb ==
                      VN_TARGET_VOICE_HIGH_SHELF_GAIN_DB &&
                  kTargetVoiceHighShelfFreqHz ==
                      VN_TARGET_VOICE_HIGH_SHELF_FREQUENCY_HZ &&
                  kTargetVoiceHighShelfQ == VN_TARGET_VOICE_HIGH_SHELF_Q,
              "public voice target ids must mirror the runtime table");

VnResult CaptureEffectCapabilities(Engine& engine, VnEffectCapability* out,
                                   std::uint32_t capacity,
                                   std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    const std::uint32_t required = kEffectRegistryRowCount;
    *requiredCount = required;
    const std::uint32_t written =
        std::min(capacity, required);
    for (std::uint32_t i = 0; i < written; ++i) {
        const EffectRegistryRow& source = kEffectRegistry[i];
        VnEffectCapability row{};
        row.structSize = sizeof(VnEffectCapability);
        row.effectType = source.effectType;
        row.descriptorSize = source.descriptorSize;
        row.descriptorVintage = source.descriptorVintage;
        row.parameterCount = source.paramCount;
        row.hostScopeMask = source.hostScopeMask;
        out[i] = row;
    }
    if (capacity > 0 && required > capacity) {
        NoteCaptureTruncated(engine, kCaptureSurfaceEffectCapabilities,
                             required);
    }
    return VN_OK;
}

VnResult CaptureEffectParameterCapabilities(
    Engine& engine, VnEffectParameterCapability* out,
    std::uint32_t capacity, std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    std::uint32_t required = 0;
    for (std::uint32_t effectIndex = 0;
         effectIndex < kEffectRegistryRowCount; ++effectIndex) {
        required += kEffectRegistry[effectIndex].paramCount;
    }
    *requiredCount = required;
    std::uint32_t emitted = 0;
    for (std::uint32_t effectIndex = 0;
         effectIndex < kEffectRegistryRowCount && emitted < capacity;
         ++effectIndex) {
        const EffectRegistryRow& effect = kEffectRegistry[effectIndex];
        for (std::uint32_t paramIndex = 0;
             paramIndex < effect.paramCount && emitted < capacity;
             ++paramIndex) {
            const EffectParamMeta& source = effect.params[paramIndex];
            VnEffectParameterCapability row{};
            row.structSize = sizeof(VnEffectParameterCapability);
            row.effectType = effect.effectType;
            row.parameterIndex = paramIndex;
            row.unit = static_cast<std::uint32_t>(source.unit);
            row.combine = static_cast<std::uint32_t>(source.combine);
            row.flags =
                source.combine != EffectParamCombine::None
                    ? VN_EFFECT_PARAMETER_BINDABLE
                    : 0u;
            if (source.supportsTransition) {
                row.flags |= VN_EFFECT_PARAMETER_SUPPORTS_TRANSITION;
            }
            row.neutral = source.neutral;
            row.clampMin =
                source.clampMin == kEffectParamClampStrictlyPositive
                    ? std::numeric_limits<float>::denorm_min()
                    : source.clampMin;
            row.clampMax =
                source.clampMax == kEffectParamClampNyquist
                    ? std::nextafter(
                          0.5f *
                              static_cast<float>(
                                  engine.config.mixRate.SampleRate()),
                          0.0f)
                    : source.clampMax ==
                              kEffectParamClampStrictlyBelowOne
                          ? std::nextafter(1.0f, 0.0f)
                          : source.clampMax;
            out[emitted++] = row;
        }
    }
    if (capacity > 0 && required > capacity) {
        NoteCaptureTruncated(
            engine, kCaptureSurfaceEffectParameterCapabilities, required);
    }
    return VN_OK;
}

VnResult CaptureEffectDynamicCapabilities(
    Engine& engine, VnEffectDynamicCapability* out,
    std::uint32_t capacity, std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    *requiredCount = kEffectRegistryRowCount;
    const std::uint32_t written =
        (std::min)(capacity, kEffectRegistryRowCount);
    for (std::uint32_t i = 0; i < written; ++i) {
        const EffectRegistryRow& source = kEffectRegistry[i];
        VnEffectDynamicCapability row{};
        row.structSize = sizeof row;
        row.effectType = source.effectType;
        row.acceptedSignalFormsMask = source.dynamicSignalFormsMask;
        row.allowedSourceKindsMask = source.dynamicSourceKindsMask;
        row.allowedBusTapsMask = source.dynamicBusTapsMask;
        row.allowedVoiceTapsMask = source.dynamicVoiceTapsMask;
        row.hostScopeMask = source.hostScopeMask;
        row.maxRawRoutesPerInstance = source.dynamicMaxRawRoutes;
        if (source.dynamicMaxRawRoutes != 0) {
            row.configuredGlobalRouteCapacity =
                engine.config.dynamicRouteCapacity;
            row.configuredBusTapCapacity =
                engine.config.dynamicBusTapCapacity;
            row.configuredVoiceTapCapacity =
                engine.config.dynamicVoiceTapCapacity;
        }
        row.rawBusLatencyBlocks = source.dynamicRawBusLatencyBlocks;
        row.rawVoiceLatencyBlocks = source.dynamicRawVoiceLatencyBlocks;
        row.flags = source.dynamicFlags;
        row.descriptorVintage = source.descriptorVintage;
        row.rawRouteLevelMinDb = source.dynamicRawRouteLevelMinDb;
        row.rawRouteLevelMaxDb = source.dynamicRawRouteLevelMaxDb;
        row.rawRouteLevelDefaultDb =
            source.dynamicRawRouteLevelDefaultDb;
        row.rawRouteCombine = source.dynamicRawRouteCombine;
        row.rawChannelReduction = source.dynamicRawChannelReduction;
        out[i] = row;
    }
    if (capacity > 0 && *requiredCount > capacity) {
        NoteCaptureTruncated(
            engine, kCaptureSurfaceEffectDynamicCapabilities,
            *requiredCount);
    }
    return VN_OK;
}

VnResult CaptureEffectDynamicParameterCapabilities(
    Engine& engine, VnEffectDynamicParameterCapability* out,
    std::uint32_t capacity, std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    std::uint32_t required = 0;
    for (std::uint32_t effect = 0;
         effect < kEffectRegistryRowCount; ++effect) {
        for (std::uint32_t parameter = 0;
             parameter < kEffectRegistry[effect].paramCount; ++parameter) {
            if (kEffectRegistry[effect]
                    .params[parameter].dynamicControlSafe) {
                ++required;
            }
        }
    }
    *requiredCount = required;
    std::uint32_t emitted = 0;
    const std::uint32_t smoothingFrames =
        CompressorTransitionFrames(engine.config.mixRate.SampleRate());
    for (std::uint32_t effect = 0;
         effect < kEffectRegistryRowCount && emitted < capacity; ++effect) {
        const EffectRegistryRow& effectRow = kEffectRegistry[effect];
        for (std::uint32_t parameter = 0;
             parameter < effectRow.paramCount && emitted < capacity;
             ++parameter) {
            if (!effectRow.params[parameter].dynamicControlSafe) {
                continue;
            }
            VnEffectDynamicParameterCapability row{};
            row.structSize = sizeof row;
            row.effectType = effectRow.effectType;
            row.parameterIndex = parameter;
            row.acceptedSignalFormsMask = VN_DYNAMIC_SIGNAL_CONTROL;
            row.sourceKindsMask = VN_DYNAMIC_SOURCE_VARIABLE;
            row.updateCadence = VN_DYNAMIC_CADENCE_UPDATE;
            row.smoothingOwner = VN_DYNAMIC_SMOOTHING_EFFECT_INTERNAL;
            row.smoothingFrames = smoothingFrames;
            row.flags = VN_DYNAMIC_PARAM_CONTROL_SAFE;
            out[emitted++] = row;
        }
    }
    if (capacity > 0 && required > capacity) {
        NoteCaptureTruncated(
            engine, kCaptureSurfaceEffectDynamicParameterCapabilities,
            required);
    }
    return VN_OK;
}

float RuntimePeakDb(float linear) {
    if (!std::isfinite(linear) || linear <= 0.0f) {
        return -160.0f;
    }
    const float db = 20.0f * std::log10(linear);
    return db < -160.0f ? -160.0f : db;
}

VnResult CaptureCompressorRuntimeInfo(
    Engine& engine, VnCompressorRuntimeInfo* out,
    std::uint32_t capacity, std::uint32_t* requiredCount) {
    const VnResult valid =
        ValidateCaptureBuffer(out, capacity, requiredCount);
    if (valid != VN_OK) {
        return valid;
    }
    std::uint32_t required = 0;
    const auto emit = [&](const EffectInstanceRef& ref,
                          std::uint32_t hostScope,
                          std::uint32_t hostDenseIndex,
                          VnObjectId objectId, std::uint64_t internalIdentity,
                          std::uint64_t publicIdentity,
                          std::uint32_t effectSlot) {
        VnCompressorRuntimeInfo info{};
        info.structSize = sizeof info;
        info.objectId = objectId;
        info.instanceHandle = publicIdentity;
        info.hostScope = hostScope;
        info.effectSlot = effectSlot;
        info.stateFlags = VN_COMPRESSOR_RUNTIME_STALE;
        info.mainInputPeakDb = -160.0f;
        info.detectorPeakDb = -160.0f;
        info.outputPeakDb = -160.0f;

        CompressorRuntimePayload payload{};
        const bool coherent =
            engine.effectBank.CaptureCompressorRuntime(ref, &payload);
        const bool identityMatches =
            payload.poolGeneration == ref.generation &&
            payload.hostScope == hostScope &&
            payload.hostDenseIndex == hostDenseIndex &&
            payload.hostIdentity == internalIdentity &&
            payload.hostObjectId == objectId &&
            payload.effectSlot == effectSlot;
        if (identityMatches) {
            info.blockEpoch = payload.blockEpoch;
            info.detectorNonFiniteCount =
                payload.detectorNonFiniteCount;
            info.detectorSaturationCount =
                payload.detectorSaturationCount;
            info.stateFlags = payload.stateFlags;
            if (!coherent) {
                info.stateFlags |= VN_COMPRESSOR_RUNTIME_STALE;
            }
            info.transitionFramesRemaining =
                payload.transitionFramesRemaining;
            info.staleRouteCount = payload.staleRouteCount;
            info.mainInputPeakDb =
                RuntimePeakDb(payload.mainInputPeakLinear);
            info.detectorPeakDb =
                RuntimePeakDb(payload.detectorPeakLinear);
            info.outputPeakDb =
                RuntimePeakDb(payload.outputPeakLinear);
            info.maxGainReductionDb =
                payload.maxGainReductionDb;
            info.endGainReductionDb =
                payload.endGainReductionDb;
        }
        if (required < capacity) {
            out[required] = info;
        }
        ++required;
    };

    for (std::uint32_t renderSlot = 0;
         renderSlot < engine.voiceEffectInstanceRefs.size();
         ++renderSlot) {
        VnVoiceHandle renderHandle = 0;
        VnVoiceHandle publicHandle = 0;
        bool live = false;
        engine.ledger.ForEachLive(
            [&](VnVoiceHandle render, std::uint32_t, std::uint64_t,
                std::uint32_t) {
                if (static_cast<std::uint32_t>(render) == renderSlot) {
                    renderHandle = render;
                    publicHandle = engine.ledger.ToPublic(render);
                    live = true;
                }
            });
        if (!live) {
            continue;
        }
        for (std::uint32_t effectSlot = 0;
             effectSlot < engine.config.fxSlotsPerVoice; ++effectSlot) {
            const EffectInstanceRef& ref =
                engine.voiceEffectInstanceRefs[renderSlot][effectSlot];
            if (ref.type == VN_EFFECT_COMPRESSOR) {
                emit(ref, VN_EFFECT_HOST_SCOPE_VOICE, renderSlot,
                     {}, renderHandle, publicHandle, effectSlot);
            }
        }
    }
    const std::uint32_t busCount = engine.buses.BusCount();
    for (std::uint32_t bus = 0; bus < busCount; ++bus) {
        if (!engine.buses.AliveAt(bus)) {
            continue;
        }
        for (std::uint32_t effectSlot = 0;
             effectSlot < engine.config.fxSlotsPerBus; ++effectSlot) {
            const EffectInstanceRef& ref =
                engine.busEffectInstanceRefs[bus][effectSlot];
            if (ref.type == VN_EFFECT_COMPRESSOR) {
                const VnBusId busId = engine.buses.IdAt(bus);
                emit(ref, VN_EFFECT_HOST_SCOPE_BUS, bus, busId, 0, 0,
                     effectSlot);
            }
        }
    }
    *requiredCount = required;
    if (capacity > 0 && required > capacity) {
        NoteCaptureTruncated(
            engine, kCaptureSurfaceCompressorRuntime, required);
    }
    return VN_OK;
}

