// Single engine instance. The API is externally synchronized, so plain
// pointer state is sufficient — no atomics, no locks.
Engine* g_engine = nullptr;

bool CanonicalSetMutationBlocked() noexcept {
    return g_engine != nullptr &&
        (g_engine->canonicalPackSetBusy || g_engine->pendingVariableGroupReplacementActive);
}

namespace {
struct EnginePageOwner {
    StablePageReservation pages;
    Engine* instance = nullptr;

    ~EnginePageOwner() {
        if (instance != nullptr) std::destroy_at(instance);
    }
};

// Public detachment leaves this owner alive until the existing teardown epilogue.
EnginePageOwner* g_engineOwner = nullptr;

// Survives Term/Init so checked tokens cannot revive after reloading the same Packs.
std::uint64_t g_lastPackGeneration = 0;
#if !defined(HARKEN_RT_QUALIFICATION)
thread_local std::uint32_t g_testPlayableCapacity = 0;
thread_local std::uint32_t g_testModeCapacity = 0;
#endif
// In-callback termination state. Depth counts the user-callback frames the
// update pump has open on this (externally synchronized) thread. A Vn_Term
// issued at depth > 0 detaches g_engine immediately but leaves the object
// alive and this flag set; the outer Vn_Update runs the teardown once the
// callback frame has returned.
int g_callbackDepth = 0;
bool g_termPending = false;
bool g_callbackExceptionPending = false;
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
struct TestTimelineCapacityState {
    std::uint64_t generation = 0;
    TimelineCapacityOverrideForTest values{};
};
thread_local TestTimelineCapacityState g_testTimelineCapacity{};
std::atomic<std::uint64_t> g_testTimelineCapacityOwner{0};
std::atomic<std::uint64_t> g_testTimelineCapacityNextGeneration{1};
#endif

// Marks one user-callback invocation, so API re-entry (Vn_Term, Vn_Update)
// can tell it is running inside a callback frame.
struct CallbackScope {
    explicit CallbackScope(Engine& engine) : m_engine(engine) {
        engine.CompleteVariableOperation();
        ++g_callbackDepth;
        ++m_engine.callbackDispatchDepth;
    }
    ~CallbackScope() {
        --m_engine.callbackDispatchDepth;
        --g_callbackDepth;
    }

private:
    Engine& m_engine;
};

VnResult StartRealDevice(Engine& engine,
                         const DeviceQueryResult* endpointObservation,
                         std::uint64_t* admissionGeneration) {
    ClearRealDeviceInitStage();
    if (admissionGeneration == nullptr) {
        return VN_DEVICE_ERROR;
    }
    *admissionGeneration = 0;
    if (!engine.voices.EnsureRenderWorkersReady()) {
        return VN_DEVICE_ERROR;
    }
    VnResult result = engine.device.Prepare(
        engine.mixer, engine.config, endpointObservation);
    if (result != VN_OK) {
        return VN_DEVICE_ERROR;
    }

    // The platform callback may begin here to establish its scheduling domain,
    // but DeviceBackend keeps render admission closed. Racing callbacks write
    // silence without consuming staging or advancing the mixer.
    std::uint64_t preparedGeneration = 0;
    result = engine.device.StartPrepared(&preparedGeneration);
    if (result != VN_OK ||
        !engine.device.CallbackRealtimeDomainReady()) {
        engine.device.RevokeRenderAdmission();
        engine.voices.DisableRenderWorkers();
        (void)engine.device.StopCallback();
        (void)engine.voices.UnbindRealtimeWorkerDomain();
        engine.device.ReleasePrepared();
        return VN_DEVICE_ERROR;
    }

    if (engine.config.renderWorkerCount != 0) {
        const RealtimeWorkerDomain domain = engine.device.WorkerDomain();
        if (!engine.voices.BindRealtimeWorkerDomain(domain) ||
            !engine.voices.EnableRealtimeRenderWorkers()) {
            engine.device.RevokeRenderAdmission();
            engine.voices.DisableRenderWorkers();
            (void)engine.device.StopCallback();
            (void)engine.voices.UnbindRealtimeWorkerDomain();
            engine.device.ReleasePrepared();
            return VN_DEVICE_ERROR;
        }
    }
    // The caller owns the lifecycle linearization point. No callback can
    // render until it commits this exact open generation after updating the
    // public engine state.
    *admissionGeneration = preparedGeneration;
    ClearRealDeviceInitStage();
    return VN_OK;
}

VnResult StopRealDevice(Engine& engine) {
    // Revoke the public render transaction first. A callback already admitted
    // may finish, while any later callback writes silence. Disable then closes
    // worker batch admission; StopCallback synchronously joins callback exit
    // before workers leave and the context is released.
    engine.device.RevokeRenderAdmission();
    engine.voices.DisableRenderWorkers();
    const VnResult stopResult = engine.device.StopCallback();
    const bool unbound = engine.voices.UnbindRealtimeWorkerDomain();
    engine.device.ReleasePrepared();
    return stopResult == VN_OK && unbound ? VN_OK : VN_DEVICE_ERROR;
}

// Single teardown epilogue, shared by the direct Vn_Term path and the
// deferred in-callback path. The device callback stops first so no audio
// thread runs inside the mixer — or appends trace journal blocks — while
// the session trace finalizes (the implicit Vn_TraceStop) and the engine
// is destroyed.
void TeardownEngine(Engine* engine) {
    engine->InvalidateProjectGenerationReservations();
    harken::remote::Shutdown(true);
    if (!engine->config.nullDevice) {
        (void)StopRealDevice(*engine);
    } else {
        engine->voices.DisableRenderWorkers();
    }
    engine->streamSeekHandoffs.CancelAllAfterAudioJoin();
    engine->actionSeeks.CancelAllAfterAudioJoin(VN_NOT_INITIALIZED);
    harken::monitor::OnEngineTeardown(engine);
    engine->voices.DiscardAllStreamParkMailboxes();
    if (engine->trace != nullptr) engine->trace->RecordSessionTerminate();
    engine->variables.ReleaseOrdinaryReservations(*engine);
    engine->variables.TerminateSession();
    engine->CompleteVariableOperation();
    if (engine->trace != nullptr) {
        engine->trace->Stop();
        engine->trace.reset();
    }
    g_lastPackGeneration = std::max(g_lastPackGeneration,
        engine->packComposition.CompositeGeneration());
    assert(g_engineOwner != nullptr && g_engineOwner->instance == engine);
    delete g_engineOwner;
    g_engineOwner = nullptr;
    g_engine = nullptr;
    g_termPending = false;
    memguard::Uninstall();
}
} // namespace

MonitorRequestContext BeginMonitorRequest(
    MonitorRequestOrigin origin, std::uint32_t operation) noexcept {
    return g_engine != nullptr ? g_engine->monitorRequests.Begin(origin, operation)
                               : MonitorRequestContext{{}, origin, operation};
}

Engine* ActiveEngine() {
    return g_engine;
}

void CaptureMonitorAcceptedRequest(monitor::RequestObservation& observation,
    std::uint32_t subject, std::uint64_t handle) noexcept {
    if (!observation.Active() || g_engine == nullptr) return;
    auto& engine = *g_engine;
    observation.Subject(subject, handle);
    MonitorEmitterOrigin origin{};
    if (subject == VN_MONITOR_SUBJECT_ACTION) {
        ActionFiringSnapshot snapshot{};
        if (!engine.actionFirings.Capture(handle, &snapshot)) return;
        observation.Content(snapshot.owner.projectId, snapshot.actionId, VN_MONITOR_CONTENT_ACTION,
            snapshot.worldGeneration, snapshot.programSemanticFingerprint);
        observation.Relations(snapshot.root, handle, snapshot.acceptedLogicSequence);
        origin = snapshot.emitterOrigin;
    } else if (subject == VN_MONITOR_SUBJECT_PLAYABLE) {
        MonitorContentIdentity content{};
        const auto view = engine.playableInstances.Classify(handle);
        if (!view.live || !engine.playableInstances.CaptureContentIdentity(handle, &content)) return;
        observation.Content(content.projectId, content.stableId, static_cast<unsigned>(view.kind),
            content.worldGeneration, content.programSemanticFingerprint, content.contentRevision);
        observation.Relations(handle, 0, 0);
        engine.playableInstances.CaptureEmitterOrigin(handle, &origin);
    } else if (subject == VN_MONITOR_SUBJECT_LOGICAL_VOICE) {
        const auto resolved = engine.ledger.Classify(handle);
        VoiceLedger::MonitorIdentity identity{};
        if (resolved.kind == VoiceLedger::HandleKind::Stale ||
            !engine.ledger.CaptureMonitorIdentity(resolved.ledgerSlot, &identity)) return;
        origin = identity.emitterOrigin;
    } else return;
    const auto context = engine.emitters.Context(origin.emitter);
    observation.Emitters(origin, engine.monitorEmitters.CaptureBinding(origin,
        context.stateEmitter, context.spatialEmitter));
}


#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
ScopedTimelineCapacityOverrideForTest::ScopedTimelineCapacityOverrideForTest(
    std::uint32_t events, std::uint32_t groups,
    std::uint32_t frameBatches, std::uint32_t originalConditionalRows) noexcept {
    if (g_engine != nullptr || g_termPending ||
        g_testTimelineCapacity.generation != 0) return;
    const auto generation = g_testTimelineCapacityNextGeneration.fetch_add(
        1, std::memory_order_relaxed);
    if (generation == 0) return;
    std::uint64_t empty = 0;
    if (!g_testTimelineCapacityOwner.compare_exchange_strong(empty, generation,
            std::memory_order_acq_rel, std::memory_order_acquire)) return;
    g_testTimelineCapacity = {generation, {events, groups, frameBatches, originalConditionalRows}};
    generation_ = generation;
}

ScopedTimelineCapacityOverrideForTest::~ScopedTimelineCapacityOverrideForTest()
    noexcept {
    if (generation_ == 0) return;
    if (g_testTimelineCapacity.generation != generation_ ||
        g_testTimelineCapacityOwner.load(std::memory_order_acquire) !=
            generation_) {
        assert(false && "Timeline capacity test scope must end on its owner thread");
        return;
    }
    g_testTimelineCapacity = {};
    g_testTimelineCapacityOwner.store(0, std::memory_order_release);
}

TimelineCapacityOverrideReadForTest ReadTimelineCapacityOverrideForTest(
    TimelineCapacityOverrideForTest* out) noexcept {
    const auto active =
        g_testTimelineCapacityOwner.load(std::memory_order_acquire);
    if (active == 0) return TimelineCapacityOverrideReadForTest::None;
    if (g_testTimelineCapacity.generation != active)
        return TimelineCapacityOverrideReadForTest::OtherThread;
    if (out != nullptr) *out = g_testTimelineCapacity.values;
    return TimelineCapacityOverrideReadForTest::CurrentThread;
}
#endif

#if !defined(HARKEN_RT_QUALIFICATION)
void SetPlayableCapacitiesForTests(std::uint32_t playable, std::uint32_t modes) noexcept {
    g_testPlayableCapacity = playable;
    g_testModeCapacity = modes;
}

VnResult AcquireMasterClaimForTests(std::uint8_t kind, std::uint64_t fingerprint) {
    Engine* engine = g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    return harken::AcquireMasterClaimKind(*engine, kind, fingerprint);
}

void ReleaseMasterClaimForTests(std::uint8_t kind) noexcept {
    Engine* engine = g_engine;
    if (engine == nullptr) {
        return;
    }
    harken::ReleaseMasterClaimKind(*engine, kind);
}
#endif

