harken::EngineActionPlayScratch* FindImmediateActionPlay(
    const ImmediateActionPlan& plan, std::uint32_t index) noexcept {
    if (plan.engine == nullptr || index >= plan.preparedPlayCount ||
        index >= plan.engine->actionPlayAttemptTokens.size()) return nullptr;
    const auto token = plan.engine->actionPlayAttemptTokens[index];
    if (!token.Valid() || !plan.engine->actionPlayScratch.IsConstructed(token.slot)) return nullptr;
    auto& scratch = plan.engine->actionPlayScratch[token.slot];
    const auto& storage = scratch.storage;
    return storage.generation == token.generation &&
        storage.phase != harken::EngineFrontierAttemptPhase::Free &&
        storage.phase != harken::EngineFrontierAttemptPhase::Quarantined ? &scratch : nullptr;
}

bool ReserveImmediateActionPlays(void* opaque,
                                 std::uint32_t count) noexcept;
bool WithdrawUnpublishedActionFrontierSources(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch, std::size_t depth) noexcept {
    if (depth >= engine.actionPlayScratch.size() ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureAttempts.size() ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureOwners.size()) return false;
    for (std::uint32_t index = 0; index < scratch.queueFutureAttemptCount; ++index) {
        const auto token = scratch.storage.queueFutureAttempts[index];
        if (!token.Valid()) continue;
        const auto& owner = scratch.storage.queueFutureOwners[index];
        auto* child = FindFrontierAttempt(engine, token);
        if (owner.engine != &engine || FindFrontierAttempt(engine, owner.parent) != &scratch ||
            owner.child.slot != token.slot || owner.child.generation != token.generation ||
            child == nullptr || child == &scratch ||
            (scratch.row != nullptr && child->row != nullptr &&
                (scratch.row->invocation != child->row->invocation ||
                 scratch.row->invocationGeneration != child->row->invocationGeneration)) ||
            !WithdrawUnpublishedActionFrontierSources(engine, *child, depth + 1u)) return false;
    }
    return WithdrawUnpublishedSourceLoansBeforeExposure(engine, scratch);
}

bool WithdrawUnpublishedImmediateActionSources(ImmediateActionPlan& plan) noexcept {
    if (plan.engine == nullptr) return false;
    for (std::uint32_t index = 0; index < plan.preparedPlayCount; ++index) {
        auto* scratch = FindImmediateActionPlay(plan, index);
        if (scratch != nullptr && !WithdrawUnpublishedActionFrontierSources(*plan.engine, *scratch, 0))
            return false;
    }
    return true;
}

