                member.group = lane.event.frontier.group;
                member.arm = lane.event.armToken;
                member.kind = harken::ImmediateLaneMemberKind::SingleEvent;
                member.future = true;
                member.relativeFrame = lane.relativeFrame;
                member.timeDomain = lane.timeDomain;
                member.fixedFrame = lane.fixedFrame;
                member.programGeneration = lane.event.program.programGeneration;
                member.target = payload.target;
                member.ownerInstance = lane.event.ownerInstanceHandle;
                member.ownerEpoch = lane.event.ownerInstanceScheduleEpoch;
