                if (holder == nullptr ||
                    staged.frozen == nullptr ||
                    staged.payload == nullptr || program.frozen == nullptr ||
                    staged.newExecuteFrame < startFrame) {
                    filingFailed = true;
                    break;
                }
                std::size_t matchingGroup = queueGroupCount;
                std::uint64_t latestFrame = 0;
                for (std::size_t group = 0; group < queueGroupCount; ++group) {
                    const auto& candidate = engine.
                        initialQueueTimingGroupsScratch[group];
                    const auto expectedDecision =
                        holder->queueFirstContinuationLane
                            ? engine.InitialQueueFilingFuture(*holder).queueDecision
                            : holder->initialQueueEntryDecision;
                    if (candidate.decision.slot !=
                            expectedDecision.slot ||
                        candidate.decision.generation !=
                            expectedDecision.generation ||
                        candidate.executeFrame > staged.newExecuteFrame)
                        continue;
                    for (std::uint16_t arm = 0;
                         arm < candidate.memberCount; ++arm) {
                        const auto member = candidate.members[arm];
                        if (member.slot == staged.frozen->armToken.slot &&
                            member.generation ==
                                staged.frozen->armToken.generation &&
                            (matchingGroup == queueGroupCount ||
                             candidate.executeFrame >= latestFrame)) {
                            matchingGroup = group;
                            latestFrame = candidate.executeFrame;
                        }
                    }
                }
                if (matchingGroup == queueGroupCount) {
                    filingFailed = true;
                    break;
                }
                const auto& group = engine.initialQueueTimingGroupsScratch[
                    matchingGroup];
                const auto identity = groupIdentity(
                    group.decision, group.sliceIndex);
                if (!identity.Exact()) {
                    filingFailed = true;
                    break;
                }
