EngineFrontierAttemptToken Engine::NativeBackingTokenFor(const EngineActionPlayScratch& scratch) const noexcept {
    for (std::uint32_t slot = 0; slot < actionPlayScratch.size(); ++slot)
        if (actionPlayScratch.IsConstructed(slot) && &actionPlayScratch[slot] == &scratch)
            return {slot, scratch.storage.generation};
    return {};
}

bool Engine::PrepareOriginalQueueCheckpointReturn(const OriginalQueueFactoryLifetimeHolder& factory,
    QueueCheckpointTable::BackingPreparation** destination) noexcept {
    if (destination == nullptr) return false;
    *destination = nullptr;
    const auto token = factory.checkpointBorrower_;
    if (!token.Valid()) return true;
    auto* child = FindFrontierAttempt(*this, token);
    if (child == nullptr || !child->queueRolesBorrowed || !child->queueCheckpointBacking.Valid() ||
        !factory.checkpointBacking_.Valid()) return false;
    auto* group = NativeBackingGroupFor(*child);
    std::uint32_t ordinal = UINT32_MAX;
    auto* owner = group == nullptr ? nullptr : NativeBackingOwnerFor(*group, &ordinal);
    if (owner == nullptr || ordinal >= owner->queueRoleReservations.size()) return false;
    const auto& slot = owner->queueRoleReservations[ordinal];
    if (slot.state != QueueRoleReservationSlot::State::Borrowed || !slot.directory.Empty() ||
        slot.borrower.slot != token.slot || slot.borrower.generation != token.generation ||
        child->frontierQueueCount > child->storage.frontierQueues.size()) return false;
    std::uint32_t matches = 0;
    for (std::uint32_t index = 0; index < child->frontierQueueCount; ++index)
        matches += &child->storage.frontierQueues[index].prepared == factory.preparation_;
    if (matches != 1) return false;
    *destination = &child->queueCheckpointBacking;
    return true;
}

bool Engine::FinishOriginalQueueCheckpointReturn(OriginalQueueFactoryLifetimeHolder& factory,
    QueueCheckpointTable::BackingPreparation* destination) noexcept {
    if (destination != nullptr) {
        if (!factory.checkpointBacking_.ReturnTo(destination)) {
            runtimeRecreateRequired = true;
            return false;
        }
    } else factory.checkpointBacking_.Release();
    factory.checkpointBorrower_ = {};
    return true;
}

EngineActionPlayScratch* Engine::NativeBackingParentFor(const EngineActionPlayScratch& future) noexcept {
    const auto token = NativeBackingTokenFor(future);
    if (!token.Valid() || FindFrontierAttempt(*this, token) != &future || !future.queueFutureExecution ||
        !future.directExecution || !future.continuationExecution) return nullptr;
    auto* parent = FindFrontierAttempt(*this, future.queueFutureParent);
    if (parent == nullptr || parent->queueFutureAttemptCount > parent->storage.queueFutureAttempts.size() ||
        parent->queueFutureAttemptCount > parent->storage.queueFutureOwners.size() ||
        parent->frontierQueueCount > parent->storage.frontierQueues.size()) return nullptr;
    std::uint32_t links = 0;
    for (std::uint32_t index = 0; index < parent->queueFutureAttemptCount; ++index) {
        const auto candidate = parent->storage.queueFutureAttempts[index];
        if (candidate.slot != token.slot || candidate.generation != token.generation) continue;
        const auto& owner = parent->storage.queueFutureOwners[index];
        if (owner.engine != this || owner.parent.slot != future.queueFutureParent.slot ||
            owner.parent.generation != future.queueFutureParent.generation ||
            owner.child.slot != token.slot || owner.child.generation != token.generation) return nullptr;
        ++links;
    }
    if (links != 1) return nullptr;
    const auto* row = ResolvePlayableService(future.continuationService);
    if (row == nullptr || row != future.row ||
        !playablePartitions.Owns(future.continuationPartition, future.continuationService.token) ||
        row->partition.slot != future.continuationPartition.slot ||
        row->partition.generation != future.continuationPartition.generation) return nullptr;
    std::uint32_t queues = 0;
    if (parent->row == row && future.queueFuturePreparedQueue == &parent->queueInstance &&
        parent->initialForestPublication && parent->queueInstance.Valid() &&
        FindInitialQueueEntryAdmission(*parent, PlayableServiceReference(*row)) != nullptr &&
        parent->queueInstance.Token().slot == row->queueInstance.slot &&
        parent->queueInstance.Token().generation == row->queueInstance.generation)
        ++queues;
    for (std::uint32_t index = 0; index < parent->frontierQueueCount; ++index) {
        const auto& queue = parent->storage.frontierQueues[index];
        if (&queue.prepared != future.queueFuturePreparedQueue) continue;
        if (queue.engine != this || !SameSelectionServiceReference(queue.service, future.continuationService))
            return nullptr;
        ++queues;
    }
    return queues == 1 ? parent : nullptr;
}

Engine::OriginalPendingVariableGroupHolder* Engine::NativeBackingGroupFor(
    const EngineActionPlayScratch& child) noexcept {
    const auto reference = child.pendingVariableReplacementService;
    const auto producerToken = child.pendingVariableReplacementProducer;
    if (!reference.Valid() || !acceptedPendingVariableGroups.IsConstructed(reference.token.slot) ||
        !producerToken.Valid() || !actionPlayScratch.IsConstructed(producerToken.slot)) return nullptr;
    auto& group = acceptedPendingVariableGroups[reference.token.slot];
    const auto& producer = actionPlayScratch[producerToken.slot];
    const auto& retention = producer.storage.originalPendingVariableProducer;
    const auto& issued = group.reprepare_;
    const auto* attempt = issued.attempt;
    const auto childToken = NativeBackingTokenFor(child);
    if (group.engine != this || !group.accepted || !group.cut.Valid() || !group.producer.Valid() ||
        group.producer.original_ != &retention || group.producer.marker_ != retention.marker_ ||
        retention.marker_ == 0 || !SameSelectionServiceReference(retention.reference_, group.reference) ||
        retention.engine_ != this || retention.storage_ != &producer.storage ||
        producer.storage.generation != producerToken.generation ||
        retention.storageGeneration_ != producerToken.generation ||
        !SameSelectionServiceReference(reference, group.reference) ||
        !MatchesOriginalPlayableServiceLifetime(group.service) ||
        !SameSelectionServiceReference(group.service.FactoryReference(), group.reference) ||
        child.pendingVariableReplacementCut != group.cut ||
        issued.engine != this || issued.storage != &producer.storage ||
        issued.storageGeneration != producerToken.generation || issued.producerMarker != retention.marker_ ||
        issued.cut != group.cut || attempt == nullptr || !OwnsImmediateEntryAttemptStorage(*attempt) ||
        issued.attemptGeneration != attempt->generation ||
        !attempt->active || FindImmediateEntryAttempt(*this, attempt->root) != attempt ||
        child.pendingVariableReplacementEntryGeneration != attempt->generation ||
        issued.replacementChildren.slot != childToken.slot || issued.replacementChildren.generation != childToken.generation ||
        (child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildren &&
         child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenSourcesCommitting &&
         child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenSourcesPrivateCommitted &&
         child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenCancelPending))
        return nullptr;
    return &group;
}

Engine::OriginalPendingVariableGroupHolder* Engine::NativeBackingOwnerFor(
    OriginalPendingVariableGroupHolder& group, std::uint32_t* ordinal) noexcept {
    if (ordinal == nullptr || group.engine != this) return nullptr;
    if (group.reprepare_.cohortHead == nullptr) {
        *ordinal = 0;
        return &group;
    }
    auto* head = group.reprepare_.cohortHead;
    bool owned = false;
    for (auto& candidate : acceptedPendingVariableGroups) if (&candidate == head) { owned = true; break; }
    if (!owned) for (auto& candidate : preparedPendingVariableGroups) if (&candidate == head) { owned = true; break; }
    if (!owned || head->engine != this || head->reprepare_.cohortHead != head ||
        group.reprepare_.cohortCount == 0 || group.reprepare_.cohortOrdinal >= group.reprepare_.cohortCount ||
        head->reprepare_.cohortCount != group.reprepare_.cohortCount ||
        head->reprepare_.attempt != group.reprepare_.attempt ||
        head->reprepare_.attemptGeneration != group.reprepare_.attemptGeneration ||
        !head->accepted || !head->cut.Valid() || !head->producer.Valid() ||
        !MatchesOriginalPlayableServiceLifetime(head->service) ||
        !SameSelectionServiceReference(head->service.FactoryReference(), head->reference) ||
        head->reprepare_.cut != head->cut) return nullptr;
    const auto* original = head->producer.original_;
    if (original == nullptr || original->engine_ != this || original->storage_ != head->reprepare_.storage ||
        original->storageGeneration_ != head->reprepare_.storageGeneration || original->marker_ == 0 ||
        head->producer.marker_ != original->marker_ || head->reprepare_.producerMarker != original->marker_ ||
        !SameSelectionServiceReference(original->reference_, head->reference)) return nullptr;
    *ordinal = group.reprepare_.cohortOrdinal;
    return head;
}

bool Engine::PrepareNativeVoiceSide(EngineActionPlayScratch& scratch,
    bool successor, std::uint32_t shape) noexcept {
    auto& side = successor ? scratch.queueSuccessorVoiceStarts : scratch.voiceStarts;
    auto& borrowed = successor ? scratch.successorNativeBorrowed : scratch.currentNativeBorrowed;
    if (shape > kMaxKnownScheduleLeaves) return false;
    if (!side.Empty() || borrowed) return side.Shape() == shape && shape <= side.size();
    const auto token = NativeBackingTokenFor(scratch);
    if (!token.Valid()) return false;
    if (!successor && !scratch.pendingVariableReplacementService.Valid()) {
        OriginalPendingOrdinarySelectionHolder* holder = nullptr;
        for (auto& candidate : pendingOrdinarySelections) {
            if (candidate.replacement.slot != token.slot || candidate.replacement.generation != token.generation) continue;
            if (holder != nullptr) return false;
            holder = &candidate;
        }
        if (holder != nullptr) {
            if (shape != 1 || holder->engine != this || holder->storage == nullptr ||
                holder->storage->generation != holder->generation || !holder->producer.Valid() ||
                !MatchesOriginalPlayableServiceLifetime(holder->service) ||
                !SameSelectionServiceReference(scratch.continuationService, holder->reference) ||
                holder->nativeReplacement.size() != 1 || holder->nativeReplacement.Shape() != 0) return false;
            side = std::move(holder->nativeReplacement);
            const bool activated = side.Activate(shape);
            assert(activated);
            borrowed = true;
            return activated;
        }
    }
    auto* parent = successor && scratch.queueFutureParent.Valid()
        ? NativeBackingParentFor(scratch) : &scratch;
    if (parent != nullptr && parent->pendingVariableReplacementService.Valid()) {
        if (successor && shape == 0) return true;
        auto* group = NativeBackingGroupFor(*parent);
        std::uint32_t ordinal = UINT32_MAX;
        auto* owner = group == nullptr ? nullptr : NativeBackingOwnerFor(*group, &ordinal);
        const auto* originalRow = group == nullptr ? nullptr : ResolvePlayableService(group->reference);
        if (owner == nullptr || owner->nativeReplacementSlots.empty() || originalRow == nullptr ||
            ResolveVariableControlProgram(*this, *originalRow) == nullptr) return false;
        NativeReplacementSlot* selected = nullptr;
        for (auto& slot : owner->nativeReplacementSlots) {
            if ((successor ? slot.producerOrdinal != UINT32_MAX : slot.producerOrdinal != ordinal) ||
                slot.borrower.Valid() || slot.capacity < shape || slot.side.size() != slot.capacity ||
                slot.side.Shape() != 0 || slot.side.Captures().size() != slot.capacity) continue;
            if (selected == nullptr || slot.capacity < selected->capacity) selected = &slot;
        }
        if (selected == nullptr) return false;
        side = std::move(selected->side);
        const bool activated = side.Activate(shape);
        assert(activated);
        selected->borrower = token;
        borrowed = true;
        return activated;
    }
    // Replacement children must use their pre-retirement episode even after partial cleanup.
    if (scratch.pendingVariableReplacementService.Valid() ||
        (successor && scratch.queueFutureParent.Valid() && parent == nullptr)) return false;
    if (shape == 1 && !ordinarySingleVoiceBacking.Empty()) {
        assert(ordinarySingleVoiceBacking.size() == 1 && ordinarySingleVoiceBacking.Shape() == 0);
        side = std::move(ordinarySingleVoiceBacking);
        const bool activated = side.Activate(shape);
        assert(activated);
        return activated;
    }
    if (shape > 1) ordinarySingleVoiceBacking = {};
    return side.Construct(shape, shape, [&]() noexcept { return AllowNativeBackingAllocation(); });
}

void Engine::RecycleOrdinaryVoiceBackingAfterSafeReset(EngineActionPlayScratch& scratch) noexcept {
    const auto recycle = [&](auto& side, bool borrowed) noexcept {
        assert(!borrowed);
        if (borrowed || !ordinarySingleVoiceBacking.Empty() || side.size() != 1) return;
        side.ResetOrdinaryAfterSafeReset();
        ordinarySingleVoiceBacking = std::move(side);
    };
    recycle(scratch.voiceStarts, scratch.currentNativeBorrowed);
    recycle(scratch.queueSuccessorVoiceStarts, scratch.successorNativeBorrowed);
}

bool Engine::AdoptPendingVariableQueueRoles(EngineActionPlayScratch& scratch) noexcept {
    auto* group = NativeBackingGroupFor(scratch);
    std::uint32_t ordinal = UINT32_MAX;
    auto* owner = group == nullptr ? nullptr : NativeBackingOwnerFor(*group, &ordinal);
    const auto token = NativeBackingTokenFor(scratch);
    if (owner == nullptr || ordinal >= owner->queueRoleReservations.size() || !token.Valid()) return false;
    auto& slot = owner->queueRoleReservations[ordinal];
    if (scratch.queueRolesBorrowed) {
        return slot.state == QueueRoleReservationSlot::State::Borrowed && slot.directory.Empty() &&
            slot.ReplacementStorageEmpty() &&
            scratch.queueCheckpointBacking.Valid() &&
            slot.borrower.slot == token.slot && slot.borrower.generation == token.generation &&
            scratch.storage.frontierQueues.size() == slot.capacity && scratch.frontierQueueCount <= slot.capacity &&
            scratch.pendingVariableReplacementControls.size() == slot.controlCapacity &&
            scratch.pendingVariableReplacementGroups.size() == slot.GroupCapacity() &&
            scratch.pendingVariableReplacementQueueLanes.size() == slot.LaneCapacity();
    }
    if (slot.state != QueueRoleReservationSlot::State::Available || slot.borrower.Valid() ||
        slot.directory.size() != slot.capacity || slot.capacity > scratch.storage.queueRoleCapacity ||
        !slot.ReplacementStorageComplete() || !scratch.pendingVariableReplacementControls.empty() ||
        !scratch.pendingVariableReplacementGroups.empty() || !scratch.pendingVariableReplacementQueueLanes.empty() ||
        scratch.queueCheckpointBacking.Valid() ||
        !scratch.storage.frontierQueues.Empty() || scratch.frontierQueueCount != 0) return false;
    scratch.storage.frontierQueues = std::move(slot.directory);
    scratch.pendingVariableReplacementControls = std::move(slot.controls);
    scratch.pendingVariableReplacementGroups = std::move(slot.groups);
    scratch.pendingVariableReplacementQueueLanes = std::move(slot.lanes);
    scratch.queueCheckpointBacking = std::move(slot.checkpoints);
    slot.borrower = token;
    slot.state = QueueRoleReservationSlot::State::Borrowed;
    scratch.queueRolesBorrowed = true;
    return true;
}

bool Engine::PrepareNativeBackingReturn(const EngineActionPlayScratch& scratch,
    NativeBackingReturnPlan* plan) noexcept {
    if (plan == nullptr) return false;
    *plan = {};
    if (!scratch.currentNativeBorrowed && !scratch.successorNativeBorrowed && !scratch.queueRolesBorrowed) return true;
    if (scratch.storage.ownerLedger.TransferredFor(scratch.storage.generation)) return false;
    const auto token = NativeBackingTokenFor(scratch);
    if (!token.Valid()) return false;
    const auto find = [&](bool successor, auto** destination, auto** borrower, auto** capacity) noexcept {
        const auto& side = successor ? scratch.queueSuccessorVoiceStarts : scratch.voiceStarts;
        if (!(successor ? scratch.successorNativeBorrowed : scratch.currentNativeBorrowed)) return true;
        if (!side.CaptureReadersReturned()) return false;
        if (!successor && !scratch.pendingVariableReplacementService.Valid()) {
            for (auto& holder : pendingOrdinarySelections) {
                if (holder.replacement.slot != token.slot || holder.replacement.generation != token.generation) continue;
                if (*destination != nullptr || holder.engine != this || holder.storage == nullptr ||
                    holder.storage->generation != holder.generation || !holder.producer.Valid() ||
                    !MatchesOriginalPlayableServiceLifetime(holder.service) ||
                    !SameSelectionServiceReference(scratch.continuationService, holder.reference) ||
                    !holder.nativeReplacement.Empty() || side.size() != 1) return false;
                *destination = &holder.nativeReplacement;
                *borrower = &holder.replacement;
            }
            return *destination != nullptr;
        }
        auto* parent = successor ? NativeBackingParentFor(scratch) : &scratch;
        auto* group = parent == nullptr ? nullptr : NativeBackingGroupFor(*parent);
        std::uint32_t ordinal = UINT32_MAX;
        auto* owner = group == nullptr ? nullptr : NativeBackingOwnerFor(*group, &ordinal);
        if (owner == nullptr) return false;
        if (successor && (!scratch.queueFutureExecution || !scratch.continuationService.Valid() ||
                !scratch.continuationPartition.Valid())) return false;
        for (auto& slot : owner->nativeReplacementSlots) {
            if (slot.borrower.slot != token.slot || slot.borrower.generation != token.generation) continue;
            if (*destination != nullptr ||
                (successor ? slot.producerOrdinal != UINT32_MAX : slot.producerOrdinal != ordinal) ||
                slot.capacity != side.size() || side.Shape() > slot.capacity || !slot.side.Empty()) return false;
            *destination = &slot.side;
            *borrower = &slot.borrower;
            *capacity = &slot.capacity;
        }
        return *destination != nullptr;
    };
    if (!find(false, &plan->current, &plan->currentBorrower, &plan->currentCapacity) ||
        !find(true, &plan->successor, &plan->successorBorrower, &plan->successorCapacity)) return false;
    if (scratch.queueRolesBorrowed) {
        auto* group = NativeBackingGroupFor(scratch);
        std::uint32_t ordinal = UINT32_MAX;
        auto* owner = group == nullptr ? nullptr : NativeBackingOwnerFor(*group, &ordinal);
        if (owner == nullptr || ordinal >= owner->queueRoleReservations.size()) return false;
        auto& slot = owner->queueRoleReservations[ordinal];
        if (slot.state != QueueRoleReservationSlot::State::Borrowed || !slot.directory.Empty() ||
            !slot.ReplacementStorageEmpty() ||
            !scratch.queueCheckpointBacking.Valid() ||
            slot.borrower.slot != token.slot || slot.borrower.generation != token.generation ||
            scratch.storage.frontierQueues.size() != slot.capacity ||
            slot.capacity > scratch.storage.queueRoleCapacity || scratch.frontierQueueCount > slot.capacity ||
            scratch.pendingVariableReplacementControls.size() != slot.controlCapacity ||
            scratch.pendingVariableReplacementGroups.size() != slot.GroupCapacity() ||
            scratch.pendingVariableReplacementQueueLanes.size() != slot.LaneCapacity()) return false;
        plan->queue = &slot;
    }
    return true;
}

void Engine::CommitNativeBackingReturn(EngineActionPlayScratch& scratch,
    const NativeBackingReturnPlan& plan) noexcept {
    const auto finish = [](auto& side, bool& borrowed, auto* destination, auto* borrower) noexcept {
        if (destination == nullptr) { assert(!borrowed); return; }
        assert(borrowed && borrower != nullptr && borrower->Valid() && destination->Empty());
        side.ClearAfterSafeReset();
        *destination = std::move(side);
        *borrower = {};
        borrowed = false;
    };
    finish(scratch.voiceStarts, scratch.currentNativeBorrowed, plan.current, plan.currentBorrower);
    finish(scratch.queueSuccessorVoiceStarts, scratch.successorNativeBorrowed, plan.successor, plan.successorBorrower);
    if (plan.queue != nullptr) {
        assert(scratch.queueRolesBorrowed && plan.queue->state == QueueRoleReservationSlot::State::Borrowed &&
            plan.queue->directory.Empty());
        scratch.storage.frontierQueues.ClearAfterSafeReset();
        plan.queue->directory = std::move(scratch.storage.frontierQueues);
        for (auto& control : scratch.pendingVariableReplacementControls) control = {};
        std::fill(scratch.pendingVariableReplacementGroups.begin(), scratch.pendingVariableReplacementGroups.end(),
            Plan03GroupSliceIdentity{});
        std::fill(scratch.pendingVariableReplacementQueueLanes.begin(), scratch.pendingVariableReplacementQueueLanes.end(),
            EngineActionPlayScratch::PendingVariableReplacementQueueLane{});
        plan.queue->controls = std::move(scratch.pendingVariableReplacementControls);
        plan.queue->groups = std::move(scratch.pendingVariableReplacementGroups);
        plan.queue->lanes = std::move(scratch.pendingVariableReplacementQueueLanes);
        plan.queue->checkpoints = std::move(scratch.queueCheckpointBacking);
        plan.queue->borrower = {};
        plan.queue->state = QueueRoleReservationSlot::State::Available;
        scratch.queueRolesBorrowed = false;
    } else assert(!scratch.queueRolesBorrowed);
}

void Engine::CommitNativeBackingTransferEnd(EngineActionPlayScratch& scratch,
    const NativeBackingReturnPlan& plan) noexcept {
    assert(scratch.storage.ownerLedger.TransferredFor(scratch.storage.generation));
    if (plan.currentBorrower != nullptr) *plan.currentBorrower = {};
    if (plan.successorBorrower != nullptr) *plan.successorBorrower = {};
    if (plan.currentCapacity != nullptr) *plan.currentCapacity = 0;
    if (plan.successorCapacity != nullptr) *plan.successorCapacity = 0;
    scratch.currentNativeBorrowed = false;
    scratch.successorNativeBorrowed = false;
    if (plan.queue != nullptr) {
        assert(scratch.queueRolesBorrowed && plan.queue->state == QueueRoleReservationSlot::State::Borrowed &&
            plan.queue->directory.Empty());
        const auto token = NativeBackingTokenFor(scratch);
        for (auto& factory : originalQueueFactoryLifetimeHolders)
            if (factory.checkpointBorrower_.slot == token.slot &&
                factory.checkpointBorrower_.generation == token.generation)
                factory.checkpointBorrower_ = {};
        scratch.queueCheckpointBacking.Release();
        plan.queue->borrower = {};
        plan.queue->state = QueueRoleReservationSlot::State::Consumed;
        scratch.queueRolesBorrowed = false;
    }
}

Engine::OriginalPendingVariableGroupHolder* Engine::PreparedPendingVariableNativeBackingGroup(
    EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt) noexcept {
    if (!OwnsImmediateEntryAttemptStorage(attempt) || !attempt.active || attempt.generation == 0 ||
        attempt.root == 0 || !attempt.lane.Valid() ||
        attempt.gate.Observe(attempt.generation) != ImmediateEntryAttemptState::Preparing ||
        !producer.prepared || producer.variableControlCommitted || !producer.variableControl ||
        producer.storage.phase != EngineFrontierAttemptPhase::Preparing || producer.row == nullptr ||
        !NativeBackingTokenFor(producer).Valid()) return nullptr;
    auto& row = *producer.row;
    auto* group = PreparedPendingVariableGroupFor(producer.storage);
    const auto& cohort = producer.privateInitialVcPageCohort;
    if (group == nullptr || group->engine != this || group->accepted || !group->cut.Valid() ||
        !group->producer.Valid() || !group->service.Valid() || !group->root.Valid() ||
        !row.actionPrepared || !row.pendingImmediateEntry || !row.InvocationValid() ||
        row.Invocation().actionFiring != attempt.root || !cohort.laneAcceptedOriginals ||
        cohort.cohortRoot != attempt.root || cohort.attemptGeneration != producer.storage.generation ||
        cohort.originalLane.slot != attempt.lane.slot || cohort.originalLane.generation != attempt.lane.generation ||
        row.pendingImmediateTimeDomain != ImmediateLaneTimeDomain::RelativeToAnchor ||
        !MatchesOriginalPlayableServiceStorage(row)) return nullptr;
    const auto& original = producer.storage.originalPendingVariableProducer;
    const EnginePlayableServiceReference reference{row.identity, row.ownerInstance,
        row.ownerEpoch, row.invocationGeneration};
    if (group->producer.original_ != &original || group->producer.marker_ != original.marker_ ||
        original.engine_ != this || original.storage_ != &producer.storage ||
        original.storageGeneration_ != producer.storage.generation || original.service_ != &row ||
        original.invocation_ != row.invocation || !SameSelectionServiceReference(original.reference_, reference) ||
        !SameSelectionServiceReference(group->reference, reference) ||
        !SameSelectionServiceReference(group->service.FactoryReference(), reference) ||
        !MatchesOriginalPlayableServiceLifetime(group->service)) return nullptr;
    const auto root = row.Invocation().variableControlOuterRootInstance != 0
        ? row.Invocation().variableControlOuterRootInstance : row.rootInstance;
    const auto* links = producer.playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
    if (links == nullptr || !playableInstances.IsOriginalLifetimePinFor(group->root, root) ||
        !playableInstances.IsOriginalLifetimeCurrent(group->root) ||
        !playableInstances.MatchesPreparedOriginalAncestry(*links, row.ownerInstance, root)) return nullptr;
    return group;
}

bool Engine::PregrantPendingVariableCohortNativeBacking(const EngineImmediateEntryAttempt& attempt,
    std::span<const EngineFrontierAttemptToken> producers) noexcept {
    if (producers.empty() || producers.data() != actionPlayAttemptTokens.data() ||
        producers.size() > actionPlayAttemptTokens.size()) return false;
    auto* producer = FindFrontierAttempt(*this, producers.front());
    auto* head = producer == nullptr ? nullptr : PreparedPendingVariableNativeBackingGroup(*producer, attempt);
    if (head == nullptr || !head->nativeReplacementSlots.empty() ||
        !head->queueRoleReservations.empty() || head->nativeRuntimeBacking) return false;
    std::vector<NativeReplacementSlot> candidate;
    std::vector<QueueRoleReservationSlot> queueCandidate;
    std::unique_ptr<NativeRuntimeBacking> runtimeCandidate;
    if (!BuildPendingVariableNativeBacking(attempt, nullptr, &candidate, &queueCandidate,
            &runtimeCandidate, nullptr, producers)) return false;
    head->nativeReplacementSlots = std::move(candidate);
    head->queueRoleReservations = std::move(queueCandidate);
    head->nativeRuntimeBacking = std::move(runtimeCandidate);
    return true;
}

bool Engine::BuildPendingVariableNativeBacking(const EngineImmediateEntryAttempt& attempt,
    EngineActionPlayScratch* single, std::vector<NativeReplacementSlot>* slots,
    std::vector<QueueRoleReservationSlot>* queueSlots,
    std::unique_ptr<NativeRuntimeBacking>* runtimeBacking, bool* waiting,
    std::span<const EngineFrontierAttemptToken> preparedProducers) noexcept {
    namespace backing = native_backing;
    if (waiting != nullptr) *waiting = false;
    if (slots == nullptr || !slots->empty() || queueSlots == nullptr || !queueSlots->empty() ||
        runtimeBacking == nullptr || *runtimeBacking != nullptr ||
        !OwnsImmediateEntryAttemptStorage(attempt) ||
        !attempt.active || attempt.generation == 0 || attempt.root == 0) return false;
    const bool preparing = !preparedProducers.empty();
    if (preparing && (single != nullptr || preparedProducers.data() != actionPlayAttemptTokens.data() ||
        preparedProducers.size() > actionPlayAttemptTokens.size() || preparedProducers.size() > UINT32_MAX)) return false;
    const auto producerCount = preparing ? static_cast<std::uint32_t>(preparedProducers.size())
        : single == nullptr ? attempt.privateVcProducerCount : 1u;
    if (producerCount == 0 || producerCount > actionPlayScratch.size() ||
        (!preparing && (single == nullptr ? !MatchesPrivateImmediateVcProducerChain(*this, attempt, true)
            : attempt.privateVcProducerCount != 0 || !actionPlayScratch.IsConstructed(attempt.producerSlot) ||
              &actionPlayScratch[attempt.producerSlot] != single ||
              single->storage.generation != attempt.producerGeneration))) return false;
    const auto firstToken = [&]() noexcept {
        return preparing ? preparedProducers.front()
            : single == nullptr ? attempt.privateVcProducerHead : NativeBackingTokenFor(*single);
    };
    const auto nextToken = [&](const EngineActionPlayScratch& producer, std::uint32_t ordinal) noexcept {
        return preparing ? ordinal + 1u < producerCount ? preparedProducers[ordinal + 1u] : EngineFrontierAttemptToken{}
            : single == nullptr ? producer.privateInitialVcPageCohort.rootProducerNext : EngineFrontierAttemptToken{};
    };
    const auto resolveGroup = [&](EngineActionPlayScratch* producer) noexcept {
        return producer == nullptr ? nullptr : preparing
            ? PreparedPendingVariableNativeBackingGroup(*producer, attempt)
            : OriginalPendingVariableGroupForProducer(*producer, attempt);
    };
    const auto shortage = [&]() noexcept { if (waiting != nullptr) *waiting = true; return false; };
    try {
        if (!AllowNativeBackingAllocation()) return shortage();
        std::vector<backing::Profile> profiles(producerCount);
        std::vector<backing::MemoEntry> memo;
        backing::Profile futures{};
        std::uint64_t nativeVoices = 0;
        std::uint64_t nativeSelections = 0;
        SelectionMemoryTableV1::BackingShape selectionShape{};
        std::uint64_t nativeRelations = 0;
        std::uint64_t nativeCompletions = 0;
        std::uint64_t nativeGroups = 0;
        std::uint64_t nativeLaneMembers = 0;
        std::uint64_t nativeBindingRows = 0;
        std::uint64_t queueControls = 0;
        EffectPoolBank::BackingDemand effectInstances{};
        auto token = firstToken();
        for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal) {
            auto* producer = FindFrontierAttempt(*this, token);
            auto* group = resolveGroup(producer);
            if (group == nullptr || producer->row == nullptr || group->RepreparePending() ||
                group->leafRetirement != OriginalPendingVariableGroupHolder::LeafRetirement::None ||
                !group->nativeReplacementSlots.empty() || !group->queueRoleReservations.empty()) return false;
            auto& row = *producer->row;
            const auto* program = ResolveVariableControlProgram(*this, row);
            if (program == nullptr || program->mode != ContainerModeV1::VariableControl ||
                row.root.kind != PlayableKindV1::Container || !row.InvocationValid()) return false;
            const auto& selection = producer->storage.initialSelection;
            const bool boundSelection = selection.BoundFor(producer->storage.generation);
            if (boundSelection && (!selection.prefixSealed || selection.prefixCount > selection.prefix.size())) return false;
            backing::Limits limits{};
            const auto futureCapacity = std::min({static_cast<std::size_t>(producer->storage.queueRoleCapacity),
                producer->storage.queueFutureAttempts.size(), producer->storage.queueFutureOwners.size(),
                static_cast<std::size_t>(config.maxPlayableInstances)});
            if (futureCapacity > UINT32_MAX || row.selectionCount > row.selectedChildOrdinals.size()) return false;
            limits.immediateFutureSides = static_cast<std::uint32_t>(futureCapacity);
            limits.queueRoleCapacity = producer->storage.queueRoleCapacity;
            limits.propertyPrefixCount = row.VariableControlPropertyRoot().stableId != VnObjectId{} ? row.selectionCount : 0;
            limits.seedPrefixCount = boundSelection ? selection.prefixCount : 0;
            const bool pack = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0;
            PlayableWorldViewV1 world{};
            backing::AuthorityStamp stamp{};
            if (pack) {
                const auto& invocation = row.Invocation();
                if (invocation.packLease.compositeGeneration != invocation.worldGeneration ||
                    invocation.packPlaybackView.CompositeGeneration() != invocation.worldGeneration ||
                    packComposition.ValidateLease(invocation.packLease) != VN_OK) return false;
                stamp = {invocation.worldGeneration, invocation.packPlaybackView.WorldSemanticFingerprint()};
                limits.currentScheduleDepth = kSelectionPathNodeCapacity;
                limits.directFutureScheduleDepth = WorldCapacitySummaryV1{}.maxTrackSegmentScheduleDepth;
            } else {
                world = row.variableControlWorldUsesCurrentAuthority ? variables.CurrentPlayableWorld() : row.VariableControlWorld();
                if (world.generation != row.Invocation().worldGeneration) return false;
                stamp = {world.generation, world.identity.runtimeSemanticFingerprint};
                limits.currentScheduleDepth = limits.directFutureScheduleDepth = world.maxTrackSegmentScheduleDepth;
            }
            backing::Result result;
            for (;;) {
                backing::MemoWorkspace workspace(memo.data(), memo.size());
                if (pack) {
                    backing::PackContent content(row.Invocation().packPlaybackView);
                    result = backing::Counter(content, limits, workspace).Count(row.root, stamp);
                } else {
                    backing::WorldContent content(world, config.voiceBindingInstanceSlots);
                    result = backing::Counter(content, limits, workspace).Count(row.root, stamp);
                }
                if (result.status != backing::Status::WorkspaceExhausted) break;
                if (memo.size() > memo.max_size() / 2u) return false;
                const auto nextSize = memo.empty() ? 64u : memo.size() * 2u;
                if (!AllowNativeBackingAllocation()) return shortage();
                memo.resize(nextSize);
            }
            if (!result || ResolveVariableControlProgram(*this, row) != program) return false;
            if (!pack) {
                const auto after = row.variableControlWorldUsesCurrentAuthority ? variables.CurrentPlayableWorld() : row.VariableControlWorld();
                if (after.generation != stamp.generation || after.identity.runtimeSemanticFingerprint != stamp.semanticFingerprint)
                    return false;
            } else if (packComposition.ValidateLease(row.Invocation().packLease) != VN_OK ||
                row.Invocation().packPlaybackView.CompositeGeneration() != stamp.generation ||
                row.Invocation().packPlaybackView.WorldSemanticFingerprint() != stamp.semanticFingerprint) return false;
            profiles[ordinal] = result.profile;
            if (result.profile.controlSides < 2u || result.profile.containerRows == 0) return false;
            if (!PrepareVariableControlOwners(row,
                    std::min(kMaxKnownScheduleLeaves + 64u, result.profile.controlSides / 2u - 1u),
                    std::min(kMaxKnownScheduleLeaves + 64u, result.profile.containerRows - 1u))) return shortage();
            futures.voice.Include(result.profile.voice);
            futures.queue.Include(result.profile.queue);
            const auto voiceRows = backing::ReservedRows(result.profile);
            const auto bindingsPerVoice = std::min({result.profile.voice.bindings,
                config.voiceBindingInstanceSlots, kMaxVoiceBindingInstanceSlots});
            const auto bindingRows = voiceRows * bindingsPerVoice;
            if (nativeBindingRows > UINT64_MAX - bindingRows) return false;
            nativeBindingRows += bindingRows;
            for (std::uint32_t type = 0; type < effectInstances.size(); ++type) {
                const auto count = voiceRows * result.profile.voice.effectInstances[type];
                if (effectInstances[type] > UINT64_MAX - count) return false;
                effectInstances[type] += count;
            }
            const auto futureRows = voiceRows - result.profile.current;
            // Initial Queue groups can repeat current leaves; both transition slices retain future members.
            const auto laneMembers = result.profile.current * (1ull + result.profile.Q) +
                2ull * (futureRows + result.profile.Q);
            if (nativeLaneMembers > UINT64_MAX - laneMembers) return false;
            nativeLaneMembers += laneMembers;
            nativeVoices += voiceRows;
            nativeSelections = std::min<std::uint64_t>(
                std::max(selectionMemory.RowCapacity(), selectionMemory.DeltaCapacity()),
                nativeSelections + 2ull * result.profile.selectionCount);
            selectionShape.Include(result.profile.selection);
            nativeRelations += result.profile.referenceRows;
            nativeCompletions += result.profile.Q + result.profile.H[2];
            queueControls += result.profile.Q;
            nativeGroups += std::max(2u, result.profile.controlSides) + 1u + 4ull * result.profile.Q;
            for (std::uint32_t threshold = 1; threshold <= backing::kLeafCapacity; ++threshold) {
                if (result.profile.H[threshold] > UINT32_MAX - futures.H[threshold]) return false;
                futures.H[threshold] += result.profile.H[threshold];
                const auto root = threshold <= result.profile.rootContinuousMembers ? 1u : 0u;
                if (result.profile.controllerWeights[threshold] < root) return false;
                const auto nested = result.profile.controllerWeights[threshold] - root;
                if (nested > UINT32_MAX - futures.controllerWeights[threshold]) return false;
                futures.controllerWeights[threshold] += nested;
                const auto childRoot = threshold <= result.profile.rootContinuousChildren ? 1u : 0u;
                if (result.profile.controllerChildWeights[threshold] < childRoot) return false;
                const auto childNested = result.profile.controllerChildWeights[threshold] - childRoot;
                if (childNested > UINT32_MAX - futures.controllerChildWeights[threshold]) return false;
                futures.controllerChildWeights[threshold] += childNested;
                const auto initialRoot = threshold <= result.profile.rootInitialMembers ? 1u : 0u;
                if (result.profile.controllerInitialArms[threshold] < initialRoot) return false;
                const auto initialNested = result.profile.controllerInitialArms[threshold] - initialRoot;
                if (initialNested > UINT32_MAX - futures.controllerInitialArms[threshold]) return false;
                futures.controllerInitialArms[threshold] += initialNested;
            }
            if (preparing)
                for (std::uint32_t prior = 0; prior < ordinal; ++prior)
                    if (preparedProducers[prior].slot == token.slot) return false;
            token = nextToken(*producer, ordinal);
        }
        if (token.Valid()) return false;
        const auto slotCount = static_cast<std::uint64_t>(producerCount) + futures.H[1];
        std::vector<NativeReplacementSlot> candidate;
        if (slotCount > candidate.max_size()) return false;
        if (!AllowNativeBackingAllocation()) return shortage();
        candidate.reserve(static_cast<std::size_t>(slotCount));
        const auto append = [&](std::uint32_t capacity, std::uint32_t ordinal) noexcept {
            auto& slot = candidate.emplace_back();
            slot.capacity = capacity;
            slot.producerOrdinal = ordinal;
            const auto allow = [&]() noexcept { return AllowNativeBackingAllocation(); };
            if (!slot.side.Construct(capacity, 0, allow) || !slot.side.ConstructCaptures(allow)) return false;
            const auto& columns = ordinal == UINT32_MAX ? futures.voice : profiles[ordinal].voice;
            for (auto& captured : slot.side.Captures()) {
                if (!allow() || CapturedTimelineVoiceInstallBuilder::Reserve(
                        std::min({columns.bindings, config.voiceBindingInstanceSlots, kMaxVoiceBindingInstanceSlots}),
                        columns.path, std::min({columns.sends, config.voiceSendSlots, kTimelineMaxVoiceSends}),
                        std::min({columns.effects, config.fxSlotsPerVoice, kTimelineMaxVoiceEffects}), &captured.voice) !=
                            PlayableStartStatus::Accepted) return false;
            }
            return true;
        };
        for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal)
            if (!append(profiles[ordinal].current, ordinal)) return shortage();
        if (!backing::EmitDescendingFutureCapacities(futures,
                [&](std::uint32_t capacity) noexcept { return append(capacity, UINT32_MAX); })) return shortage();
        std::vector<QueueRoleReservationSlot> queueCandidate;
        if (!AllowNativeBackingAllocation()) return shortage();
        queueCandidate.reserve(producerCount);
        for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal) {
            auto& slot = queueCandidate.emplace_back();
            slot.capacity = profiles[ordinal].Q;
            slot.controlCapacity = std::max(2u, profiles[ordinal].controlSides);
            if (slot.controlCapacity < 2u ||
                slot.controlCapacity > EngineActionPlayScratch::kPendingVariableReplacementControlCapacity) return false;
            if (!slot.directory.Construct(slot.capacity, [&]() noexcept { return AllowNativeBackingAllocation(); }))
                return shortage();
            if (!AllowNativeBackingAllocation()) return shortage();
            slot.controls.resize(slot.controlCapacity);
            if (!AllowNativeBackingAllocation()) return shortage();
            slot.groups.resize(slot.GroupCapacity());
            if (slot.LaneCapacity() != 0) {
                if (!AllowNativeBackingAllocation()) return shortage();
                slot.lanes.resize(slot.LaneCapacity());
            }
        }
        if (nativeVoices > UINT32_MAX || nativeCompletions > UINT32_MAX || nativeGroups > UINT32_MAX ||
            queueControls > UINT32_MAX - nativeVoices) return false;
        if (!AllowNativeBackingAllocation()) return shortage();
        auto nativeCandidate = std::make_unique<NativeRuntimeBacking>();
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->rootMemberWeights.resize(producerCount);
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->rootInitialArms.resize(producerCount);
        token = firstToken();
        for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal) {
            const auto* producer = FindFrontierAttempt(*this, token);
            if (producer == nullptr || producer->row == nullptr) return false;
            auto& root = nativeCandidate->rootMemberWeights[ordinal];
            root.service = producer->row->identity;
            const auto capacity = std::min(profiles[ordinal].rootContinuousMembers, config.maxVariableControlLiveRows);
            // Roots survive retry cancellation, so each keeps its full allowance separate from new nested services.
            if (producer->row->VariablePayload().variableControlMemberWeights.size() >= capacity)
                root.weights.storage = producer->row->VariablePayload().variableControlMemberWeights.storage;
            else {
                if (!AllowNativeBackingAllocation()) return shortage();
                root.weights.storage = std::make_shared<EngineVariableMemberWeights::Values>(capacity);
            }
            const auto childCapacity = profiles[ordinal].rootContinuousChildren;
            if (producer->row->VariablePayload().variableControlMemberWeights.Children().size() >= childCapacity)
                root.weights.childStorage = producer->row->VariablePayload().variableControlMemberWeights.childStorage;
            else {
                if (!AllowNativeBackingAllocation()) return shortage();
                root.weights.childStorage = std::make_shared<EngineVariableMemberWeights::ChildValues>(childCapacity);
            }
            auto& initial = nativeCandidate->rootInitialArms[ordinal];
            initial.service = producer->row->identity;
            const auto initialCapacity = profiles[ordinal].rootInitialMembers;
            if (producer->row->variableControlInitialArms.size() >= initialCapacity)
                initial.arms = producer->row->variableControlInitialArms;
            else {
                if (!AllowNativeBackingAllocation()) return shortage();
                initial.arms.storage = std::make_shared<EngineVariableInitialArms::Values>(initialCapacity);
            }
            token = nextToken(*producer, ordinal);
        }
        if (token.Valid()) return false;
        const auto weightColumns = std::max(futures.controllerWeights[1], futures.controllerChildWeights[1]);
        if (weightColumns != 0) {
            if (!AllowNativeBackingAllocation()) return shortage();
            nativeCandidate->memberWeights.resize(weightColumns);
            const auto prepareColumn = [&](const auto& counts, auto column, std::uint32_t limit) noexcept {
                std::uint32_t index = 0;
                return backing::EmitDescendingCapacities(counts, [&](std::uint32_t capacity) noexcept {
                    if (!AllowNativeBackingAllocation()) return false;
                    try {
                        auto& storage = nativeCandidate->memberWeights[index++].*column;
                        using Values = typename std::remove_reference_t<decltype(storage)>::element_type;
                        storage = std::make_shared<Values>(std::min(capacity, limit));
                    } catch (...) { return false; }
                    return true;
                });
            };
            if (!prepareColumn(futures.controllerWeights, &EngineVariableMemberWeights::storage,
                    config.maxVariableControlLiveRows) ||
                !prepareColumn(futures.controllerChildWeights, &EngineVariableMemberWeights::childStorage,
                    backing::kLeafCapacity)) return shortage();
        }
        if (futures.controllerInitialArms[1] != 0) {
            if (!AllowNativeBackingAllocation()) return shortage();
            nativeCandidate->initialArms.reserve(futures.controllerInitialArms[1]);
            if (!backing::EmitDescendingCapacities(futures.controllerInitialArms, [&](std::uint32_t capacity) noexcept {
                    if (!AllowNativeBackingAllocation()) return false;
                    try {
                        auto& arms = nativeCandidate->initialArms.emplace_back();
                        arms.storage = std::make_shared<EngineVariableInitialArms::Values>(capacity);
                    } catch (...) { return false; }
                    return true;
                })) return shortage();
        }
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->reprepareProducers.resize(producerCount);
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->selections.resize(producerCount);
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->publicationProducers.resize(producerCount);
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->publicationChildren.resize(producerCount);
        if (!AllowNativeBackingAllocation()) return shortage();
        nativeCandidate->publicationOwners.resize(producerCount);
        if (queueControls != 0 && !queueScheduleStorage.Prepare(
                {futures.queue.programs, futures.queue.events}, &nativeCandidate->queueSchedules,
                [&]() noexcept { return AllowNativeBackingAllocation(); })) return shortage();
        // Queue futures acquire a slot even when their selected schedule has no leaves.
        if (!PrepareActionPlayBacking(producerCount, static_cast<std::uint32_t>(queueControls),
                &nativeCandidate->actionPlays) ||
            !PrepareQueueProgramBankBacking(queueControls == 0 ? 0u : queueProgramBanks.size(),
                &nativeCandidate->queueBanks) ||
            !PrepareMemberProgramBacking(static_cast<std::uint32_t>(nativeVoices),
                &nativeCandidate->memberPrograms) ||
            !PreparePlayableMemberBacking(static_cast<std::uint32_t>(nativeVoices),
                &nativeCandidate->members) ||
            !PrepareMemberRelationBacking(static_cast<std::uint32_t>(std::min<std::uint64_t>(
                nativeRelations, memberRelations.Capacity())), &nativeCandidate->relations) ||
            !queueInstances.PrepareBacking(static_cast<std::uint32_t>(queueControls),
                static_cast<std::uint32_t>(queueControls), &nativeCandidate->queues) ||
            !queueCheckpoints.PrepareBacking(static_cast<std::uint32_t>(queueControls), &nativeCandidate->checkpoints) ||
            !decisions.PrepareBacking(static_cast<std::uint32_t>(nativeGroups), &nativeCandidate->decisions) ||
            !compositeCompletionOwners.PrepareBacking(static_cast<std::uint32_t>(nativeCompletions), &nativeCandidate->completions) ||
            !voices.PrepareSlotBacking(static_cast<std::uint32_t>(nativeVoices), &nativeCandidate->voices) ||
            !ledger.PrepareBacking(static_cast<std::uint32_t>(std::min<std::uint64_t>(
                nativeVoices, ledger.Capacity())), &nativeCandidate->ledger) ||
            !ledger.PrepareMonitorSelectionBacking(static_cast<std::uint32_t>(std::min<std::uint64_t>(
                nativeVoices, ledger.MonitorSelectionCapacity())), &nativeCandidate->monitor) ||
            !selectionMemory.PrepareBacking({
                static_cast<std::uint32_t>(std::min<std::uint64_t>(nativeSelections, selectionMemory.RowCapacity())),
                static_cast<std::uint32_t>(std::min<std::uint64_t>(nativeSelections, selectionMemory.DeltaCapacity())),
                std::min(producerCount, selectionMemory.BatchCapacity()), selectionShape},
                &nativeCandidate->selectionHistory) ||
            !timelineArms.PrepareBacking(static_cast<std::uint32_t>(nativeVoices + queueControls),
                &nativeCandidate->arms) ||
            !variables.PrepareReadCutBacking(static_cast<std::uint32_t>(std::min<std::uint64_t>(
                nativeVoices + queueControls + producerCount, variables.ReadCutCapacity())),
                &nativeCandidate->readCuts) ||
            !armGroups.PrepareBacking(static_cast<std::uint32_t>(nativeGroups),
                static_cast<std::uint32_t>(nativeVoices + queueControls), &nativeCandidate->groups) ||
            !timelinePool.PrepareImmediateLaneBacking(static_cast<std::uint32_t>(nativeGroups),
                nativeLaneMembers, &nativeCandidate->laneGroups) ||
            !immediateActionLane.PreparePrivateEntryBacking(static_cast<std::uint32_t>(nativeGroups),
                &nativeCandidate->laneEntries) ||
            !immediateActionLane.PrepareAttemptBacking(&nativeCandidate->laneAttempts) ||
            !PreparePlayableServiceBacking(static_cast<std::uint32_t>(std::min<std::uint64_t>(
                nativeGroups, playableServices.Capacity())), &nativeCandidate->services) ||
            !PreparePendingVariableQueueOriginBacking(static_cast<std::uint32_t>(nativeGroups),
                &nativeCandidate->queueOrigins) ||
            !effectBank.PrepareBacking(effectInstances, &nativeCandidate->effects) ||
            !params.PrepareBindingBacking(static_cast<std::uint32_t>(std::min<std::uint64_t>(
                nativeBindingRows, params.PreparationCapacity())), &nativeCandidate->bindings)) return shortage();
        for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal)
            if (!nativeCandidate->checkpoints.Split(profiles[ordinal].Q, 0, &queueCandidate[ordinal].checkpoints))
                return false;
        if (!preparing && single == nullptr && !MatchesPrivateImmediateVcProducerChain(*this, attempt, true)) return false;
        token = firstToken();
        for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal) {
            auto* producer = FindFrontierAttempt(*this, token);
            auto* group = resolveGroup(producer);
            if (group == nullptr || producer->row == nullptr || group->RepreparePending() ||
                group->leafRetirement != OriginalPendingVariableGroupHolder::LeafRetirement::None ||
                !group->nativeReplacementSlots.empty() || !group->queueRoleReservations.empty() ||
                ResolveVariableControlProgram(*this, *producer->row) == nullptr) return false;
            const auto& row = *producer->row;
            if (!row.InvocationValid()) return false;
            if (!row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0) {
                if (packComposition.ValidateLease(row.Invocation().packLease) != VN_OK ||
                    row.Invocation().packPlaybackView.CompositeGeneration() != row.Invocation().worldGeneration) return false;
            } else {
                const auto world = row.variableControlWorldUsesCurrentAuthority
                    ? variables.CurrentPlayableWorld() : row.VariableControlWorld();
                if (world.generation != row.Invocation().worldGeneration) return false;
            }
            token = nextToken(*producer, ordinal);
        }
        if (token.Valid()) return false;
        *slots = std::move(candidate);
        *queueSlots = std::move(queueCandidate);
        *runtimeBacking = std::move(nativeCandidate);
        return true;
    } catch (const std::bad_alloc&) {
        return shortage();
    } catch (const std::length_error&) {
        return false;
    }
}

bool Engine::MatchesPendingVariableNativeBacking(OriginalPendingVariableGroupHolder& owner,
    std::uint32_t producerCount) noexcept {
    if (producerCount == 0 || producerCount > owner.nativeReplacementSlots.size() ||
        owner.queueRoleReservations.size() != producerCount || !owner.nativeRuntimeBacking ||
        !owner.nativeRuntimeBacking->groups.Valid() || !owner.nativeRuntimeBacking->actionPlays.Valid() ||
        !owner.nativeRuntimeBacking->memberPrograms.Valid() ||
        !owner.nativeRuntimeBacking->members.Valid() ||
        !owner.nativeRuntimeBacking->relations.Valid() ||
        !owner.nativeRuntimeBacking->queueBanks.Valid() ||
        !owner.nativeRuntimeBacking->queues.instances.Valid() ||
        !owner.nativeRuntimeBacking->queues.conditionals.Valid() || !owner.nativeRuntimeBacking->checkpoints.Valid() ||
        !owner.nativeRuntimeBacking->arms.Valid() || !owner.nativeRuntimeBacking->ledger.Valid() ||
        !owner.nativeRuntimeBacking->bindings.Valid() ||
        !owner.nativeRuntimeBacking->laneAttempts.Valid()) return false;
    for (const auto& slot : owner.queueRoleReservations)
        if (slot.capacity != 0 && !owner.nativeRuntimeBacking->queueSchedules.Valid()) return false;
    for (std::size_t index = 0; index < owner.nativeReplacementSlots.size(); ++index) {
        const auto& slot = owner.nativeReplacementSlots[index];
        if (slot.producerOrdinal != (index < producerCount ? index : UINT32_MAX) ||
            slot.capacity > kMaxKnownScheduleLeaves) return false;
        if (!slot.borrower.Valid()) {
            if (slot.side.size() != slot.capacity || slot.side.Shape() != 0 ||
                slot.side.Captures().size() != slot.capacity) return false;
            for (const auto& capture : slot.side.Captures()) if (!capture.voice.HasStorage()) return false;
            continue;
        }
        auto* child = FindFrontierAttempt(*this, slot.borrower);
        const bool successor = slot.producerOrdinal == UINT32_MAX;
        if (child == nullptr || !slot.side.Empty()) return false;
        const auto& side = successor ? child->queueSuccessorVoiceStarts : child->voiceStarts;
        if (!(successor ? child->successorNativeBorrowed : child->currentNativeBorrowed) ||
            side.size() != slot.capacity || side.Shape() > slot.capacity ||
            side.Captures().size() != slot.capacity) return false;
        for (const auto& capture : side.Captures()) if (!capture.voice.HasStorage()) return false;
        auto* parent = successor ? NativeBackingParentFor(*child) : child;
        auto* group = parent == nullptr ? nullptr : NativeBackingGroupFor(*parent);
        std::uint32_t ordinal = UINT32_MAX;
        if (group == nullptr || NativeBackingOwnerFor(*group, &ordinal) != &owner ||
            (!successor && ordinal != slot.producerOrdinal)) return false;
    }
    for (std::uint32_t ordinal = 0; ordinal < producerCount; ++ordinal) {
        const auto& slot = owner.queueRoleReservations[ordinal];
        if (slot.state == QueueRoleReservationSlot::State::Available) {
            if (slot.borrower.Valid() || slot.directory.size() != slot.capacity ||
                !slot.ReplacementStorageComplete()) return false;
        } else if (slot.state == QueueRoleReservationSlot::State::Consumed) {
            if (slot.borrower.Valid() || !slot.directory.Empty() || !slot.ReplacementStorageEmpty()) return false;
        } else if (slot.state == QueueRoleReservationSlot::State::Borrowed) {
            auto* child = FindFrontierAttempt(*this, slot.borrower);
            if (child == nullptr || !child->queueRolesBorrowed || !slot.directory.Empty() || !slot.ReplacementStorageEmpty() ||
                !child->queueCheckpointBacking.Valid() ||
                child->storage.frontierQueues.size() != slot.capacity || child->frontierQueueCount > slot.capacity ||
                child->pendingVariableReplacementControls.size() != slot.controlCapacity ||
                child->pendingVariableReplacementGroups.size() != slot.GroupCapacity() ||
                child->pendingVariableReplacementQueueLanes.size() != slot.LaneCapacity())
                return false;
            auto* group = NativeBackingGroupFor(*child);
            std::uint32_t actual = UINT32_MAX;
            if (group == nullptr || NativeBackingOwnerFor(*group, &actual) != &owner || actual != ordinal) return false;
        } else return false;
    }
    return true;
}

bool Engine::EnsurePendingVariableNativeBacking(EngineActionPlayScratch& producer,
    const EngineImmediateEntryAttempt& attempt, bool* waiting) noexcept {
    if (waiting != nullptr) *waiting = false;
    auto* group = OriginalPendingVariableGroupForProducer(producer, attempt);
    if (group == nullptr || !group->reprepare_.reserveForReplacement) return false;
    std::uint32_t ordinal = UINT32_MAX;
    auto* owner = NativeBackingOwnerFor(*group, &ordinal);
    const auto count = attempt.privateVcProducerCount == 0 ? 1u : attempt.privateVcProducerCount;
    if (owner == nullptr || ordinal >= count) return false;
    if (owner->nativeReplacementSlots.empty() != owner->queueRoleReservations.empty()) return false;
    if (owner->nativeReplacementSlots.empty()) {
        if (attempt.privateVcProducerCount != 0 || group->RepreparePending() ||
            group->leafRetirement != OriginalPendingVariableGroupHolder::LeafRetirement::None) return false;
        std::vector<NativeReplacementSlot> candidate;
        std::vector<QueueRoleReservationSlot> queueCandidate;
        std::unique_ptr<NativeRuntimeBacking> runtimeCandidate;
        if (!BuildPendingVariableNativeBacking(attempt, &producer, &candidate, &queueCandidate,
                &runtimeCandidate, waiting)) return false;
        owner->nativeReplacementSlots = std::move(candidate);
        owner->queueRoleReservations = std::move(queueCandidate);
        owner->nativeRuntimeBacking = std::move(runtimeCandidate);
    }
    return MatchesPendingVariableNativeBacking(*owner, count);
}

bool Engine::ReserveRegisteredPendingVariableNativeBacking(EngineImmediateEntryAttempt& attempt,
    bool* waiting) noexcept {
    if (waiting != nullptr) *waiting = false;
    if (!MatchesPrivateImmediateVcProducerChain(*this, attempt, true)) return false;
    auto* producer = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    auto* head = producer == nullptr ? nullptr : OriginalPendingVariableGroupForProducer(*producer, attempt);
    if (head == nullptr) return false;
    if (head->nativeReplacementSlots.empty() != head->queueRoleReservations.empty()) return false;
    if (head->nativeReplacementSlots.empty()) {
        std::vector<NativeReplacementSlot> candidate;
        std::vector<QueueRoleReservationSlot> queueCandidate;
        std::unique_ptr<NativeRuntimeBacking> runtimeCandidate;
        if (!BuildPendingVariableNativeBacking(attempt, nullptr, &candidate, &queueCandidate,
                &runtimeCandidate, waiting)) return false;
        head->nativeReplacementSlots = std::move(candidate);
        head->queueRoleReservations = std::move(queueCandidate);
        head->nativeRuntimeBacking = std::move(runtimeCandidate);
    }
    return MatchesPendingVariableNativeBacking(*head, attempt.privateVcProducerCount);
}

bool Engine::CancelPendingOrdinarySelectionCandidate(OriginalPendingOrdinarySelectionHolder& holder) noexcept {
    if (!holder.replacement.Valid()) return true;
    auto* child = FindFrontierAttempt(*this, holder.replacement);
    if (child == nullptr || !child->directExecution || !child->continuationExecution ||
        child->continuationService.token != holder.reference.token ||
        child->continuationService.owner != holder.reference.owner ||
        child->continuationService.epoch != holder.reference.epoch ||
        child->continuationService.invocationGeneration != holder.reference.invocationGeneration ||
        !CancelDirectFrontierAttempt(*this, *child)) return false;
    holder.replacement = {};
    return true;
}

static bool PreparePendingOrdinaryVoiceBacking(Engine& engine,
    const EnginePlayableServiceRow& row, const PlayableWorldViewV1* world,
    CapturedTimelineVoiceInstall* out) noexcept {
    namespace backing = native_backing;
    if (out == nullptr) return false;
    if (out->HasStorage()) return true;
    const bool pack = world == nullptr;
    backing::Limits limits{};
    limits.currentScheduleDepth = limits.directFutureScheduleDepth = pack
        ? WorldCapacitySummaryV1{}.maxTrackSegmentScheduleDepth : world->maxTrackSegmentScheduleDepth;
    limits.immediateFutureSides = engine.config.maxPlayableInstances;
    limits.queueRoleCapacity = engine.config.maxPlayableInstances;
    const backing::AuthorityStamp stamp{row.Invocation().worldGeneration, pack
        ? row.Invocation().packPlaybackView.WorldSemanticFingerprint() : world->identity.runtimeSemanticFingerprint};
    std::vector<backing::MemoEntry> memo;
    try {
        for (;;) {
            backing::MemoWorkspace workspace(memo.data(), memo.size());
            const auto result = pack
                ? backing::Counter(backing::PackContent(row.Invocation().packPlaybackView), limits, workspace).Count(row.root, stamp)
                : backing::Counter(backing::WorldContent(*world, engine.config.voiceBindingInstanceSlots), limits, workspace)
                    .Count(row.root, stamp);
            if (result.status == backing::Status::WorkspaceExhausted) {
                if (memo.size() > memo.max_size() / 2u || !engine.AllowNativeBackingAllocation()) return false;
                memo.resize(memo.empty() ? 64u : memo.size() * 2u);
                continue;
            }
            if (!result || !engine.AllowNativeBackingAllocation()) return false;
            const auto& columns = result.profile.voice;
            return CapturedTimelineVoiceInstallBuilder::Reserve(
                std::min({columns.bindings, engine.config.voiceBindingInstanceSlots, kMaxVoiceBindingInstanceSlots}),
                columns.path, std::min({columns.sends, engine.config.voiceSendSlots, kTimelineMaxVoiceSends}),
                std::min({columns.effects, engine.config.fxSlotsPerVoice, kTimelineMaxVoiceEffects}), out) ==
                    PlayableStartStatus::Accepted;
        }
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool PreparePendingOrdinaryMemberDirectories(Engine& engine, EnginePlayableServiceRow& row,
    const Engine::OriginalPendingOrdinarySelectionHolder& holder, std::uint32_t childCount) noexcept {
    if (!engine.PreparePlayableMemberDirectory(row)) return false;
    if (childCount == 0) return true;
    auto retiring = holder.retiredServices;
    auto retiringCount = holder.retiredServiceCount;
    if (retiringCount == 0 && !holder.sourceRetired) {
        auto next = row.frontierChildService;
        while (next.Valid()) {
            auto* service = engine.ResolvePlayableService(next);
            if (service == nullptr || retiringCount == retiring.size()) return false;
            retiring[retiringCount++] = next;
            next = service->frontierChildService;
        }
    }
    // Prepare the slots that the existing first-free policy can reuse after retirement.
    // Retiring children count toward capacity; they do not need duplicate service slots.
    for (auto& service : engine.playableServices) {
        if (&service == &row || service.quarantined) continue;
        const bool reusable = Engine::PlayableServiceReusable(service) ||
            (service.identity.generation != UINT64_MAX &&
             std::any_of(retiring.begin(), retiring.begin() + retiringCount,
                [&](const EnginePlayableServiceReference& reference) noexcept {
                    return engine.ResolvePlayableService(reference) == &service;
                }));
        if (!reusable) continue;
        if (!engine.PreparePlayableMemberDirectory(service)) return false;
        if (--childCount == 0) return true;
    }
    const auto previous = engine.playableServices.size();
    if (childCount > engine.playableServices.Capacity() - previous ||
        !engine.playableServices.ConstructThrough(previous + childCount,
            [&](std::uint32_t required) noexcept {
                return engine.PreparePlayableServiceDependencies(required);
            })) return false;
    if (!engine.InitializePlayableServiceRows(previous)) return false;
    for (auto slot = previous; slot < previous + childCount; ++slot)
        if (!engine.PreparePlayableMemberDirectory(engine.playableServices[slot])) return false;
    return true;
}

Engine::PendingOrdinarySelectionResult Engine::ServicePendingOrdinarySelections(
    EngineImmediateEntryAttempt& attempt, std::uint64_t anchor) noexcept {
    using Result = PendingOrdinarySelectionResult;
    if (!MatchesPendingSelectionCensus(attempt) || anchor == UINT64_MAX) return Result::Refused;
    const auto reject = [&](VnResult status) noexcept {
        for (auto& member : playableServices) {
            if (member.PendingImmediateCohortRoot() != attempt.root ||
                member.phase != EnginePlayableStartPhase::PendingImmediateEntry) continue;
            if (member.arm.Valid()) (void)AbortTimelineArm(*this, member.arm);
            member.pendingImmediateEntry = false;
            member.phase = EnginePlayableStartPhase::Cancelling;
            member.controlLifecycle = PlayableControlLifecycle::FailingSourceActive;
            member.controlReason = PlayableControlReason::StartRefused;
            member.Invocation().actionTerminalResult = status;
            member.Invocation().actionTerminalReason = ActionTerminalReason::RuntimeError;
        }
        return Result::Rejected;
    };
    const auto temporary = [](VnResult status) noexcept {
        return status == VN_BACKPRESSURE || status == VN_NO_VOICE || status == VN_NO_STREAM ||
            status == VN_NO_EFFECT;
    };
    for (std::uint32_t index = 0; index < attempt.selectionProducerCount; ++index) {
        const auto& cell = attempt.selectionProducers[index];
        if (cell.returned || cell.variableControl) continue;
        auto* producer = FindFrontierAttempt(*this, cell.token);
        auto* batch = ResolvePendingSelectionCensusProducer(cell);
        if (producer == nullptr || producer->row == nullptr || batch == nullptr || !batch->Accepted())
            return Result::Refused;
        if (producer->storage.initialSelection.preparation.mode == EngineSelectionPreparationMode::Legacy)
            continue;
        auto& row = *producer->row;
        auto* holder = PendingOrdinarySelectionFor(producer->storage);
        if (holder == nullptr || !holder->accepted || !MatchesPendingOrdinarySelection(*holder, producer->storage, row) ||
            producer->storage.phase != EngineFrontierAttemptPhase::PrivateCommitted || row.queueMode ||
            row.selectionCount == 0 || row.selectionCount > row.selectedChildOrdinals.size() ||
            row.containerInstanceCount != row.selectionCount ||
            !row.pendingImmediateEntry || row.phase != EnginePlayableStartPhase::PendingImmediateEntry)
            return Result::Refused;
        auto* oldResource = ResolvePlayableService(holder->resourceReference);
        if (holder->sourceRetired) {
            if (!holder->retirement.StorageReturned() ||
                !originalSourceSubmissions.PendingInstalledSourceRetirementSettled(holder->retirement, holder->arm) ||
                holder->source.Valid() || holder->body.Valid() || !row.ordinaryFinalSourceTransferred ||
                row.arm.Valid() || row.renderHandle != 0 || row.releaseObserver.Valid() ||
                playableInstances.Classify(row.activeLeafInstance).live) return Result::Refused;
        } else if (oldResource == nullptr || !holder->resource.Valid() ||
            !SameSelectionServiceReference(holder->resource.FactoryReference(), holder->resourceReference) ||
            oldResource->invocation != row.invocation || oldResource->invocationGeneration != row.invocationGeneration ||
            !SameOriginalSingleArm(holder->arm, oldResource->arm) ||
            (row.frontierChildService.Valid() && ResolvePlainInitialForwardedResource(*this, row, true) != oldResource))
            return Result::Refused;
        if (!CancelPendingOrdinarySelectionCandidate(*holder)) return Result::Waiting;
        if (!holder->retirement.Valid() && !holder->sourceRetired) {
            TimelineArmObservation installed{};
            if (!timelineArms.Observe(holder->arm, &installed)) return Result::Refused;
            if (installed.state == ArmState::PendingApply) return Result::Waiting;
            if (installed.state != ArmState::Armed ||
                !originalSourceSubmissions.IsOriginalInstalledSourceCurrent(holder->source, oldResource->renderHandle))
                return Result::Refused;
        }
        if (batch->CertifyMaterialized(batch->MaterializedFrame(), row.selectedChildOrdinals.data(), row.selectionCount) &&
            batch->MaterializedFrame() == anchor) continue;
        if (!batch->CancelReplacement() || batch->BeginReplacement() != SelectionMemoryStatusV1::Ok)
            return Result::Waiting;
        const bool pack = row.containerLoopAuthorityKind == PlayableExecutionAuthorityKind::Pack;
        const auto* world = pack ? nullptr : ContainerLoopWorld(*this, row);
        if ((!pack && world == nullptr) || (pack && packComposition.ValidateLease(row.Invocation().packLease) != VN_OK))
            return Result::Refused;
        const auto authority = pack ? PlayableExecutionAuthority::Pack(row.Invocation().packPlaybackView)
            : PlayableExecutionAuthority::Current(*world);
        const auto& identity = producer->storage.initialSelection.identity;
        std::array<std::uint32_t, kSelectionPathNodeCapacity> ordinals{};
        std::array<SelectionPathNodeV1, kSelectionPathNodeCapacity> path{};
        std::uint32_t selectionCount = 0;
        auto current = row.root;
        PlayableRefV1 firstChild{};
        while (current.kind == PlayableKindV1::Container) {
            if (selectionCount == path.size()) return Result::Refused;
            ContainerTraversalRequest request{identity.world, identity.worldSemanticFingerprint, identity.rootStableId,
                row.Invocation().invocationEmitter, identity.callerSeed, identity.acceptedPostOrdinal, selectionCount,
                selectionCount == 0 ? nullptr : path.data(), selectionCount == 0 ? 0 : ordinals[selectionCount - 1u],
                identity.ticket, identity.eventBegin + selectionCount, anchor, 0,
                ContainerTraversalOwnership::PreparedToken, nullptr, nullptr,
                {EngineSelectionPreparationMode::PendingReplacement, batch}, nullptr};
            const auto traverse = [&](const auto& view) noexcept {
                return PrepareSharedContainerSelectionStep(*this, authority, view,
                    ClassifySharedContainerTraversalStep(*this, authority, view, current), request);
            };
            const auto selected = pack ? traverse(row.Invocation().packPlaybackView) : traverse(*world);
            if (selected.status != ContainerTraversalStatus::Ok || selected.child == nullptr || selected.program == nullptr ||
                (selected.program->mode != ContainerModeV1::Random && selected.program->mode != ContainerModeV1::Sequence))
                return Result::Refused;
            ordinals[selectionCount] = selected.selectedChildOrdinal;
            path[selectionCount++] = selected.pathNode;
            current = selected.canonicalChild;
            if (selectionCount == 1) firstChild = current;
        }
        if (current.kind != PlayableKindV1::Sound || selectionCount == 0 ||
            batch->SealReplacement(anchor, ordinals.data(), selectionCount) != SelectionMemoryStatusV1::Ok)
            return Result::Refused;
        if (selectionCount == row.selectionCount &&
            std::equal(ordinals.begin(), ordinals.begin() + selectionCount, row.selectedChildOrdinals.begin()) &&
            !holder->retirement.Valid()) {
            if (batch->InstallReplacement() != SelectionMemoryStatusV1::Ok) return Result::Waiting;
            producer->storage.initialSelection.executeFrame = anchor;
            continue;
        }
        const auto cut = pack
            ? playablePropertyCutScratch.Resolve(row.Invocation().packPlaybackView, row.root, ordinals.data(), selectionCount)
            : playablePropertyCutScratch.Resolve(*world, row.root, ordinals.data(), selectionCount);
        if (cut != ResolvedPlayablePropertyCutStatusV1::Ok) return Result::Refused;
        const auto actualLeaf = playablePropertyCutScratch.View().leaf;
        TimelineVoiceInstallDesc voice{};
        const auto built = BuildTimelineVoiceInstallFromCut(*this, playablePropertyCutScratch.View(), &voice,
            pack ? &row.Invocation().packLease : nullptr);
        if (built != PlayableStartStatus::Accepted) {
            switch (built) {
            case PlayableStartStatus::Capacity: return reject(VN_INVALID_CONFIG);
            case PlayableStartStatus::InvalidInput: return reject(VN_INVALID_ARG);
            case PlayableStartStatus::MediaMismatch: return reject(VN_BAD_CURRENT_WORLD);
            case PlayableStartStatus::CapabilityUnavailable: return reject(VN_CAPABILITY_UNAVAILABLE);
            default: return Result::Refused;
            }
        }
        for (std::uint32_t effect = 0; effect < voice.effectCount; ++effect) {
            std::uint32_t demand = 1;
            for (std::uint32_t prior = 0; prior < effect; ++prior)
                demand += voice.effects[prior].type == voice.effects[effect].type;
            if (demand > effectBank.CapacityOf(voice.effects[effect].type)) return reject(VN_INVALID_CONFIG);
        }
        const auto preflight = PreflightTimelineVoiceStart(*this, voice);
        if (preflight != VN_OK && !temporary(preflight)) return reject(preflight);
        if (!PreparePendingOrdinaryMemberDirectories(*this, row, *holder, selectionCount - 1u))
            return Result::Waiting;
        if (holder->nativeReplacement.Empty()) {
            if (holder->sourceRetired || holder->retirement.Valid()) return Result::Refused;
            if (!holder->nativeReplacement.Construct(1, 0,
                    [&]() noexcept { return AllowNativeBackingAllocation(); })) return Result::Waiting;
        }
        if (!holder->nativeVoiceBacking.Valid()) {
            if (holder->sourceRetired || holder->retirement.Valid()) return Result::Refused;
            if (!voices.PrepareSlotBacking(1, &holder->nativeVoiceBacking)) return Result::Waiting;
        }
        if (!holder->nativePlayBacking.Valid()) {
            if (holder->sourceRetired || holder->retirement.Valid()) return Result::Refused;
            if (!PrepareActionPlayBacking(1, 0, &holder->nativePlayBacking)) return Result::Waiting;
        }
        if (!holder->nativeMemberBacking.Valid() || !holder->nativeRelationBacking.Valid() ||
            !holder->nativeProgramBacking.Valid() ||
            !holder->nativeScheduleBacking.Valid()) {
            if (holder->sourceRetired || holder->retirement.Valid()) return Result::Refused;
            if ((!holder->nativeMemberBacking.Valid() && !PreparePlayableMemberBacking(1, &holder->nativeMemberBacking)) ||
                (!holder->nativeRelationBacking.Valid() && !PrepareMemberRelationBacking(1, &holder->nativeRelationBacking)) ||
                (!holder->nativeProgramBacking.Valid() && !PrepareQueueProgramBankBacking(1, &holder->nativeProgramBacking)) ||
                (!holder->nativeScheduleBacking.Valid() && !queueScheduleStorage.Prepare({1, 1},
                    &holder->nativeScheduleBacking, [&]() noexcept { return AllowNativeBackingAllocation(); })))
                return Result::Waiting;
        }
        if (!holder->replacementVoice.HasStorage()) {
            if (holder->sourceRetired || holder->retirement.Valid()) return Result::Refused;
            if (!PreparePendingOrdinaryVoiceBacking(*this, row, world, &holder->replacementVoice))
                return Result::Waiting;
        }
        if (CaptureTimelineVoiceInstall(voice, &holder->replacementVoice, true) != PlayableStartStatus::Accepted)
            return Result::Refused;
        const auto preparedVoiceBacking = holder->nativeVoiceBacking.Use();
        const auto preparedLedgerBacking = holder->nativeLedgerBacking.Use();
        const auto preparedMonitorBacking = holder->nativeMonitorBacking.Use();
        const auto preparedPlayBacking = holder->nativePlayBacking.Use();
        const auto preparedMemberBacking = holder->nativeMemberBacking.Use();
        const auto preparedRelationBacking = holder->nativeRelationBacking.Use();
        const auto preparedProgramBacking = holder->nativeProgramBacking.Use();
        const auto preparedScheduleBacking = holder->nativeScheduleBacking.Use();
        if (!holder->sourceRetired) {
            if (!holder->retirement.Valid()) {
                if (!originalSourceSubmissions.IsOriginalInstalledSourceCurrent(holder->source, oldResource->renderHandle))
                    return Result::Waiting;
                ContainerPlaybackRow oldParent{};
                if (!containerPlayback.Capture(row.rootInstance, &oldParent) || oldParent.activeChild == 0 ||
                    oldParent.expectedScheduleEpoch != row.ownerEpoch) return Result::Refused;
                const auto oldChild = playableInstances.Classify(oldParent.activeChild);
                if (!oldChild.live || oldChild.parent != row.rootInstance ||
                    oldChild.scheduleEpoch != oldParent.activeChildEpoch) return Result::Refused;
                holder->retiredChild = oldParent.activeChild;
                holder->retiredChildEpoch = oldChild.scheduleEpoch;
                auto next = row.frontierChildService;
                auto* parent = &row;
                holder->retiredServiceCount = 0;
                while (next.Valid()) {
                    auto* service = ResolvePlayableService(next);
                    if (service == nullptr || service->invocation != row.invocation ||
                        service->invocationGeneration != row.invocationGeneration ||
                        ResolvePlayableService(service->parentService) != parent ||
                        holder->retiredServiceCount == holder->retiredServices.size()) return Result::Refused;
                    holder->retiredServices[holder->retiredServiceCount++] = next;
                    parent = service;
                    next = service->frontierChildService;
                }
                if (parent != oldResource) return Result::Refused;
                const auto retired = originalSourceSubmissions.RequestPendingInstalledSourceRetirementWithReceipt(
                    holder->source, holder->body, &holder->retirement);
                if (retired == OriginalSourceSubmissionRegistry::InstalledSourceRetirementRequest::Deferred)
                    return Result::Waiting;
                if (retired != OriginalSourceSubmissionRegistry::InstalledSourceRetirementRequest::Requested)
                    return Result::Refused;
            }
            if (!originalSourceSubmissions.PendingInstalledSourceRetirementSettled(holder->retirement, holder->arm))
                return Result::Waiting;
            if (!originalSourceSubmissions.ReturnPendingInstalledSourceRetirementStorage(holder->retirement, holder->arm))
                return Result::Waiting;
            holder->body.Release();
            holder->source.Release();
            if (!ReturnOriginalSingleSourcePreparationAfterPhysicalRelease(holder->arm) ||
                !DropTimelineArm(*this, holder->arm, mixer.BlocksRendered())) return Result::Waiting;
            const auto oldChild = holder->retiredChild;
            const auto state = playableInstances.Classify(oldChild);
            if (!state.live || state.parent != row.rootInstance || state.scheduleEpoch != holder->retiredChildEpoch)
                return Result::Refused;
            if (state.lifecycle < PlayableLifecycle::LogicalComplete &&
                (!playableInstances.SetTerminalOutcome(oldChild, {PlayableTerminalKind::ReplacementReset, VN_OK, 0}) ||
                 !playableInstances.AdvanceLifecycle(oldChild, PlayableLifecycle::LogicalComplete))) return Result::Waiting;
            const auto outcome = PlayableTreeExecutor::ServiceChildOutcome(
                playableInstances, containerPlayback, row.rootInstance, oldChild, state.scheduleEpoch, 0);
            if (outcome != ContainerPlaybackTable::ChildOutcomeStatus::Accepted &&
                outcome != ContainerPlaybackTable::ChildOutcomeStatus::Duplicate) return Result::Refused;
            (void)ClearTimelineVoiceInstallIdentity(oldResource->renderHandle);
            oldResource->ordinaryFinalSourceTransferred = true;
            oldResource->arm = {};
            oldResource->renderHandle = 0;
            oldResource->releaseObserver = {};
            oldResource->schedule.armToken = {};
            oldResource->activeLeafInstance = 0;
            // The original receipt and retired leaf discharge this source's final resource duty.
            row.ordinaryFinalSourceTransferred = true;
            row.arm = {};
            row.renderHandle = 0;
            row.releaseObserver = {};
            row.schedule.armToken = {};
            row.activeLeafInstance = 0;
            row.frontierChildService = {};
            // Detached outgoing services keep native retirement ownership, never entry eligibility.
            for (std::uint32_t index = 0; index < holder->retiredServiceCount; ++index) {
                auto* service = ResolvePlayableService(holder->retiredServices[index]);
                if (service == nullptr || service->invocation != row.invocation ||
                    service->invocationGeneration != row.invocationGeneration) return Result::Refused;
                service->ordinaryFinalSourceTransferred = true;
                service->pendingImmediateEntry = false;
                service->phase = EnginePlayableStartPhase::Cancelling;
                service->controlLifecycle = PlayableControlLifecycle::Cancelling;
            }
            holder->resource.Return();
            holder->sourceRetired = true;
        }
        // Retired services may outlive their storage fence, but require their old owner to end first.
        if (!PlayableTreeExecutor::RetirePlayableTreeBottomUp(playableInstances, containerPlayback,
                holder->retiredChild, PlayableTerminalKind::ReplacementReset)) return Result::Waiting;
        holder->retiredChild = 0;
        holder->retiredChildEpoch = 0;
        while (holder->retiredServiceCount != 0) {
            const auto index = holder->retiredServiceCount - 1u;
            const auto reference = holder->retiredServices[index];
            auto retired = reference;
            auto* service = ResolvePlayableService(reference);
            if (service != nullptr) {
                service->ordinaryFinalSourceTransferred = true;
                service->frontierChildService = {};
            }
            if (!RetireNestedVariableControlService(*this, retired) || ResolvePlayableService(reference) != nullptr)
                return Result::Waiting;
            holder->retiredServices[index] = {};
            --holder->retiredServiceCount;
        }
        auto* child = AcquireFrontierAttempt(*this, &holder->replacement);
        if (child == nullptr) return Result::Waiting;
        child->directExecution = true;
        child->continuationExecution = true;
        child->continuationService = holder->reference;
        child->continuationPartition = row.partition;
        child->continuationTransportEpoch = timelinePool.Epoch();
        const auto& currentEvent = row.event;
        child->continuationOrder = {anchor, row.ticket, row.Invocation().actionExecutionOrdinal,
            currentEvent.eventIndex, currentEvent.transactionOrdinal, currentEvent.subeventPhase, 0};
        child->authorityOwnerContext.engine = this;
        child->authorityOwnerContext.worldGeneration = row.Invocation().worldGeneration;
        child->authorityOwnerContext.pack = pack;
        child->authorityOwnerContext.packLease = row.Invocation().packLease;
        child->authorityOwnerContext.service = &row;
        if (!containerPlayback.Capture(row.rootInstance, &child->continuationParentSnapshot))
            return Result::Waiting;
        child->directExposureOwnerContext = {this, child};
        if (!RegisterFrontierPreparedOwner(*child, &child->directExposureOwnerContext,
                ValidatePreparedDirectExposureOwner, CommitPreparedDirectExposureOwner,
                CancelPreparedDirectExposureOwner)) return Result::Waiting;
        auto& tree = child->playableTreeExecutor;
        std::array<PlayableInstanceHandle, kSelectionPathNodeCapacity> containers{};
        containers[0] = row.rootInstance;
        EnginePlayableServiceRow* resource = &row;
        EnginePlayableServiceReference firstService{};
        if (selectionCount > 1) {
            if (firstChild.kind != PlayableKindV1::Container ||
                !tree.PrepareInstance(playableInstances, PlayableKind::Container, row.rootInstance)) return Result::Waiting;
            const auto nestedRoot = tree.PreparedInstanceHandle(0);
            const auto nestedEpoch = tree.PreparedInstanceEpoch(0);
            const auto loopLimit = [&](VnObjectId stableId) noexcept {
                return pack ? ReadPlayableLoopCount(row.Invocation().packPlaybackView, stableId)
                    : ReadPlayableLoopCount(*world, stableId);
            };
            const bool expanded = pack
                ? PrepareSharedPlayableFrontier(*this, tree, authority, row.Invocation().packPlaybackView,
                    firstChild, ordinals.data() + 1u, selectionCount - 1u, nestedRoot, nestedEpoch, loopLimit)
                : PrepareSharedPlayableFrontier(*this, tree, authority, *world, firstChild,
                    ordinals.data() + 1u, selectionCount - 1u, nestedRoot, nestedEpoch, loopLimit);
            if (!expanded) return Result::Waiting;
            for (std::uint32_t index = 1; index < selectionCount; ++index)
                containers[index] = tree.PreparedInstanceHandle(index - 1u);
            PreparedFrontierPath preparedPath{};
            preparedPath.path = path;
            preparedPath.ordinals = ordinals;
            preparedPath.containers = containers;
            preparedPath.selectionCount = 1;
            preparedPath.adoptedSelectionCount = selectionCount;
            const bool prepared = pack
                ? PrepareFrontierContainerPath(*this, *child, row, authority, row.Invocation().packPlaybackView,
                    firstChild, row.rootInstance, row.ownerEpoch, identity.worldSemanticFingerprint,
                    identity.callerSeed, identity.ticket, anchor, 0, preparedPath)
                : PrepareFrontierContainerPath(*this, *child, row, authority, *world,
                    firstChild, row.rootInstance, row.ownerEpoch, identity.worldSemanticFingerprint,
                    identity.callerSeed, identity.ticket, anchor, 0, preparedPath);
            if (!prepared || preparedPath.terminal.kind != PlayableKindV1::Sound ||
                preparedPath.selectionCount != selectionCount || !preparedPath.rootService.Valid()) return Result::Waiting;
            resource = ResolvePlayableService(preparedPath.resourceService);
            firstService = preparedPath.rootService;
            if (resource == nullptr) return Result::Waiting;
        } else if (!tree.PrepareInstance(playableInstances, PlayableKind::Sound, row.rootInstance)) return Result::Waiting;
        const auto newLeaf = tree.PreparedInstanceHandle(selectionCount - 1u);
        ObservePreparedContent(*this, tree, newLeaf, pack
            ? MonitorContentFor(row.Invocation().packPlaybackView, actualLeaf)
            : MonitorContentFor(*world, actualLeaf));
        const auto newLeafEpoch = tree.PreparedInstanceEpoch(selectionCount - 1u);
        if (resource != &row) resource->activeLeafInstance = newLeaf;
        OriginalPlayableServiceLifetimePin resourcePin;
        if (resource->identity.slot >= originalPlayableServiceLifetimeHolders.size() ||
            !originalPlayableServiceLifetimeHolders[resource->identity.slot].Borrow(&resourcePin)) return Result::Waiting;
        if (!PrepareNativeVoiceSide(*child, false, 1)) return Result::Waiting;
        auto& start = child->voiceStarts[0];
        auto& variablesCut = producer->storage.initialVariableCut;
        if (!variables.PreparePendingOrdinarySelectionReadCut(*this, *producer, attempt, anchor))
            return Result::Waiting;
        child->frontierProgramBank = ReserveQueueProgramBank(*this, {1, 1});
        auto* replacementMember = child->frontierProgramBank == nullptr ? nullptr
            : AcquireQueueProgramMember(*child->frontierProgramBank, 0);
        if (replacementMember == nullptr) return Result::Waiting;
        const auto installed = InstallTimelineVoiceStart(*this, holder->replacementVoice.Input(), newLeaf, anchor, row.rootInstance,
            row.rootInstance, nullptr, nullptr, {}, UINT16_MAX, nullptr, &start, nullptr,
            resource, nullptr,
            true, true, false, false, &variablesCut,
            {anchor, row.ticket, row.Invocation().actionExecutionOrdinal}, true, 0);
        child->voiceStartCount = start.prepared ? 1u : 0u;
        child->voiceStarts.Owners()[0] = {this, &start, false};
        if (installed.status != VN_OK) return temporary(installed.status) ? Result::Waiting : reject(installed.status);
        CaptureQueueProgramMember(*this, *replacementMember, holder->replacementVoice.Share(), actualLeaf, installed, anchor, {});
        SetPlayableMemberCompletion(*replacementMember, {newLeaf, newLeafEpoch, installed.sourceTerminal});
        auto payload = row.payload;
        payload.target = voice.target;
        auto runtime = row.runtimeProgram;
        runtime.generation = newLeaf;
        runtime.payloads = &payload;
        auto event = currentEvent;
        event.armToken = start.arm;
        auto schedule = row.schedule;
        schedule.armToken = start.arm;
        schedule.ownerInstance = newLeaf;
        schedule.ownerInstanceScheduleEpoch = newLeafEpoch;
        schedule.entryAnchorFrame = anchor;
        schedule.runtimeProgram = {newLeaf, &runtime};
        schedule.events = &event;
        if (FreezeQueueProgram(*this, *child->frontierProgramBank, schedule) == nullptr ||
            !PreparePlayableMemberBinding(*resource, 0, child->frontierProgramBank->members[0])) return Result::Waiting;
        if (!RegisterCurrentFrontierVoiceOwners(*this, *child)) return Result::Waiting;
        child->frontierOwnerLedgerComplete = true;
        auto* actualSource = OriginalSinglePreparationForArm(start.arm);
        OriginalSourceLifetimePin source;
        VoicePool::OriginalSourceBodyLifetimePin body;
        if (actualSource == nullptr || !BorrowOriginalSingleSourcePreparation(*actualSource, &source, &body) ||
            !commands.ReserveBatch(start.commandCount, &child->directCommandReservation)) return Result::Waiting;
        child->directCommandsReserved = true;
        if (!PrepareVoiceCommandBatch(*this, &child->directCommandReservation, {start.commands.data(), start.commandCount}) ||
            !ProvePreparedFrontierVoiceCommits(*this, *child) ||
            (tree.ContainerReservationCount() != 0 && !tree.ProveContainerCommits()) || !tree.ProveInstanceCommits() ||
            !tree.ProveParentLinks(playableInstances) || !IssueOriginalPlayableTreeLifetimes(tree) ||
            batch->CanInstallReplacement() != SelectionMemoryStatusV1::Ok || !tree.Validate()) return Result::Waiting;
        if (!tree.Commit(identity.ticket)) {
            runtimeRecreateRequired = true;
            return Result::Refused;
        }
        for (std::uint32_t index = 0; index < selectionCount; ++index) {
            if (!PlayableTreeExecutor::ServiceActiveChild(playableInstances, containerPlayback, containers[index],
                    tree.PreparedInstanceHandle(index))) {
                runtimeRecreateRequired = true;
                return Result::Refused;
            }
        }
        if (batch->InstallReplacement() != SelectionMemoryStatusV1::Ok) {
            runtimeRecreateRequired = true;
            return Result::Refused;
        }
        row.capturedVoice = std::move(holder->replacementVoice);
        row.usesCapturedVoice = true;
        row.leaf = actualLeaf;
        row.activeLeafInstance = newLeaf;
        row.arm = start.arm;
        row.renderHandle = start.renderHandle;
        row.releaseObserver = start.releaseObserver;
        row.monitorSelection = start.monitorSelection;
        row.startFrame = anchor;
        row.ordinaryFinalSourceTransferred = false;
        row.payload = payload;
        row.event = event;
        row.runtimeProgram = *schedule.runtimeProgram.program;
        row.schedule = schedule;
        auto& replacementBank = *child->frontierProgramBank;
        row.QueuePayload().queueCurrentProgramBank = &replacementBank;
        row.QueuePayload().queueCurrentPrograms = {0, 1};
        row.selectionCount = row.containerInstanceCount = selectionCount;
        row.containerInstances = containers;
        row.selectedChildOrdinals = ordinals;
        row.selectionPath = path;
        producer->storage.initialSelection.executeFrame = anchor;
        producer->storage.initialSelection.materializedOrdinals = ordinals;
        if (resource != &row) {
            TransferFrontierLeafResource(*this, row, *resource);
            row.frontierChildService = firstService;
        }
        if (!BindSinglePlayableProgram(*this, *resource, replacementBank, 0)) {
            runtimeRecreateRequired = true;
            return Result::Refused;
        }
        child->frontierProgramBank = nullptr;
        replacementBank.published = true;
        if (resource != &row) {
            if (!ForwardPlainInitialQueuePending(*this, row, *resource)) {
                runtimeRecreateRequired = true;
                return Result::Refused;
            }
        }
        holder->source = std::move(source);
        holder->body = std::move(body);
        holder->arm = start.arm;
        holder->release = start.releaseObserver;
        holder->resource = std::move(resourcePin);
        holder->resourceReference = PlayableServiceReference(*resource);
        holder->retirement.Release();
        holder->sourceRetired = false;
        if (!variables.CommitTimelineReadUse(start.initialVariableReadUse)) {
            runtimeRecreateRequired = true;
            return Result::Refused;
        }
        start.initialVariableReadUse = {};
        PublishVoiceCommandBatch(*this, &child->directCommandReservation, {start.commands.data(), start.commandCount});
        child->directCommandsReserved = false;
        for (std::uint32_t index = 0; index < child->frontierServiceCount; ++index) {
            auto* service = ResolvePlayableService(child->storage.frontierServices[index].service);
            if (service == nullptr || !playablePartitions.Publish(service->partition, service->identity)) {
                runtimeRecreateRequired = true;
                return Result::Refused;
            }
            service->actionPrepared = false;
        }
        NativeBackingReturnPlan nativeTransfer;
        if (!PrepareNativeBackingReturn(*child, &nativeTransfer)) return Result::Refused;
        if (!tree.ReleasePublishedOwnership() || !child->storage.ownerLedger.Transfer(child->storage.generation)) {
            runtimeRecreateRequired = true;
            return Result::Refused;
        }
        producer->voiceStarts[0] = std::move(start);
        CommitNativeBackingTransferEnd(*child, nativeTransfer);
        child->storage.phase = EngineFrontierAttemptPhase::Free;
        holder->replacement = {};
        return Result::Waiting;
    }
    return Result::Ready;
}

bool Engine::MatchesPendingVariableQueueRecordChains(const EngineImmediateEntryAttempt& attempt) const noexcept {
    if (!attempt.active || attempt.root == 0 || attempt.generation == 0) return false;
    const auto matches = [&](const auto& records, std::uint32_t head, std::uint32_t count,
        bool continuation) noexcept {
        if (count > records.size()) return false;
        auto slot = head;
        for (std::uint32_t index = 0; index < count; ++index) {
            if (slot >= records.size()) return false;
            const auto& record = records[slot];
            if (!record.occupied || record.generation == 0 || record.root != attempt.root ||
                record.attemptGeneration != attempt.generation || !record.service.Valid() ||
                record.service.slot >= playableServices.size()) return false;
            const auto& service = playableServices[record.service.slot];
            if (service.identity != record.service || !service.InvocationValid() ||
                service.Invocation().actionFiring != attempt.root || service.ownerInstance != record.ownerInstance ||
                service.ownerEpoch != record.ownerEpoch || !service.queueInstance.Valid() ||
                service.queueInstance.slot != record.queue.slot || service.queueInstance.generation != record.queue.generation ||
                service.queueFirstContinuationLane != continuation ||
                !SameCanonicalDecision(service.initialQueueEntryDecision, record.initialDecision) ||
                !SameCanonicalDecision(continuation ? service.QueueFiling().queueDecision : service.initialQueueEntryDecision,
                    record.memberDecision)) return false;
            for (const auto& other : records)
                if (&other != &record && other.occupied && other.root == attempt.root &&
                    other.attemptGeneration == attempt.generation && other.service == record.service) return false;
            if (attempt.queueContinuationService == record.service) return false;
            slot = record.next;
        }
        if (slot != UINT32_MAX) return false;
        std::uint32_t occupied = 0;
        for (const auto& record : records)
            occupied += record.occupied && record.root == attempt.root && record.attemptGeneration == attempt.generation;
        return occupied == count;
    };
    if (!matches(queueContinuationRecords, attempt.queueContinuationHead, attempt.queueContinuationCount, true) ||
        !matches(queueFutureRecords, attempt.queueFutureHead, attempt.queueFutureCount, false)) return false;
    for (const auto& continuation : queueContinuationRecords) {
        if (!continuation.occupied || continuation.root != attempt.root ||
            continuation.attemptGeneration != attempt.generation) continue;
        for (const auto& future : queueFutureRecords)
            if (future.occupied && future.root == attempt.root && future.attemptGeneration == attempt.generation &&
                future.service == continuation.service) return false;
    }
    return true;
}

bool Engine::MatchesPendingVariableRetiredInitialSide(const OriginalPendingVariableGroupHolder& group,
    const EnginePlayableServiceRow& service,
    const VariableControlInstanceTable::OriginalInitialSideReceipt& receipt,
    VariableControlSide side) noexcept {
    if (group.engine != this || !group.accepted ||
        group.leafRetirement != OriginalPendingVariableGroupHolder::LeafRetirement::Settled ||
        group.nestedInitialSideCount > group.nestedInitialSides.size()) return false;
    const auto* root = ResolvePlayableService(group.reference);
    if (root == nullptr || !root->InvocationValid() || service.invocation != root->invocation) return false;
    const bool discrete = side == VariableControlSide::Discrete;
    const auto decision = discrete ? service.variableControlDiscreteDecision : service.variableControlContinuousDecision;
    const auto bank = discrete ? service.variableControlDiscreteBank : service.variableControlContinuousBank;
    const auto armGroup = discrete ? service.variableControlDiscreteArmGroup : service.variableControlContinuousArmGroup;
    const auto members = discrete ? service.variableControlInitialDiscreteMemberCount : service.variableControlInitialContinuousMemberCount;
    const DecisionReserveRequest* input = nullptr;
    if (root == &service && &receipt == &group.initialSides[discrete ? 0u : 1u])
        input = &group.initialDecisionInputs[discrete ? 0u : 1u];
    for (std::uint32_t index = 0; index < group.nestedInitialSideCount; ++index) {
        const auto& saved = group.nestedInitialSides[index];
        if (ResolvePlayableService(saved.service) != &service || saved.side != side || &receipt != &saved.original) continue;
        if (input != nullptr || saved.instance.slot != service.variableControlInstance.slot ||
            saved.instance.generation != service.variableControlInstance.generation ||
            !SameCanonicalDecision(saved.decision, decision) || saved.bank.slot != bank.slot || saved.bank.generation != bank.generation ||
            saved.armGroup.slot != armGroup.slot || saved.armGroup.generation != armGroup.generation ||
            saved.memberCount != members || saved.group !=
                (discrete ? service.InitialLaneDiscreteGroup() : service.InitialLaneContinuousGroup())) return false;
        input = &saved.input;
    }
    if (input == nullptr || !variableControlInstances.MatchesOriginalInitialSideReceipt(receipt,
            service.variableControlInstance, side, decision, bank)) return false;
    const auto* baseline = ResolveOriginalSingleDecisionBaseline(this, decisions, decision);
    auto current = *input;
    current.ticket.sequence = root->ticket;
    return baseline != nullptr && decisions.MatchesOriginalDecisionFactory(*baseline, *input) &&
        decisions.MatchesOpenReservation(decision, current);
}

bool Engine::MatchesPendingVariableRetiredNativeScope(const OriginalPendingVariableGroupHolder& group,
    const Plan03GroupSliceIdentity& identity, std::uint64_t root, std::uint64_t anchor,
    const Plan03GroupSliceInput& input) noexcept {
    if (group.engine != this || !group.accepted || !group.cut.Valid() || !group.producer.Valid()) return false;
    const auto* service = ResolvePlayableService(group.reference);
    const auto* original = group.producer.original_;
    const EngineActionPlayScratch* producer = nullptr;
    for (const auto& candidate : actionPlayScratch)
        if (&candidate.storage.originalPendingVariableProducer == original) producer = &candidate;
    if (producer == nullptr || original->engine_ != this || original->storage_ != &producer->storage ||
        original->marker_ != group.producer.marker_ || original->storageGeneration_ != producer->storage.generation ||
        producer->storage.phase != EngineFrontierAttemptPhase::PrivateCommitted || !producer->variableControlCommitted ||
        producer->row != service || service == nullptr || !MatchesOriginalPlayableServiceStorage(*service) ||
        !service->InvocationValid() || original->service_ != service || original->invocation_ != service->invocation ||
        !SameSelectionServiceReference(original->reference_, group.reference) ||
        !MatchesOriginalPlayableServiceLifetime(group.service) ||
        !SameSelectionServiceReference(group.service.FactoryReference(), group.reference) ||
        !playableInstances.IsOriginalLifetimePinFor(group.root,
            service->Invocation().variableControlOuterRootInstance != 0
                ? service->Invocation().variableControlOuterRootInstance : service->rootInstance) ||
        !playableInstances.IsOriginalLifetimeCurrent(group.root) || service->Invocation().actionFiring != root ||
        !PendingVariableGroupSourcesSettled(group) || identity.committedRow >= originalQueueGroupHolders.size() ||
        input.sourceControlCount > input.memberCount || (input.memberCount != 0 && input.members == nullptr) ||
        !timelinePool.IsOriginalQueueFutureGroupRegistrationFor(
            originalQueueGroupHolders[identity.committedRow], identity, root)) return false;
    for (std::uint16_t member = input.sourceControlCount; member < input.memberCount; ++member) {
        std::uint32_t matches = 0;
        for (std::uint32_t leaf = 0; leaf < group.leafCount; ++leaf)
            matches += OriginalSourceSubmissionRegistry::SameToken(group.leafArms[leaf], input.members[member]) &&
                originalSourceSubmissions.PendingInstalledSourceRetirementSettled(
                    group.leafRetirementReceipts[leaf], group.leafArms[leaf]);
        for (const auto& future : pendingVariableFutureSources) {
            if (future.group != &group || !OriginalSourceSubmissionRegistry::SameToken(future.arm, input.members[member])) continue;
            SourceTerminalToken terminal{};
            matches += CapturePendingVariableRetiredFutureTerminal(future, &terminal);
        }
        if (matches != 1) return false;
    }
    return timelinePool.MatchesOriginalQueueFutureGroupScopeImpl(
        originalQueueGroupHolders[identity.committedRow], root, anchor, input, timelineArms, true);
}

bool Engine::MatchesPendingVariableQueueNativeOrigins(const OriginalPendingVariableGroupHolder& group) const noexcept {
    if (group.engine != this || group.queueNativeOriginCount > pendingVariableQueueNativeOrigins.size()) return false;
    const auto stride = timelinePool.MaxArmsPerGroup();
    std::uint32_t count = 0;
    for (std::size_t slot = 0; slot < pendingVariableQueueNativeOrigins.size(); ++slot) {
        const auto& original = pendingVariableQueueNativeOrigins[slot];
        if (original.group != &group) continue;
        if (++count > group.queueNativeOriginCount || original.ordinal >= group.queueNativeOriginCount ||
            !original.service.Valid() || !original.partition.Valid() || !original.queue.Valid() ||
            !original.identity.Exact() || original.attemptGeneration == 0 || original.scope.cohortRoot == 0 ||
            original.scope.input.memberCount > stride ||
            original.scope.input.sourceControlCount > original.scope.input.memberCount ||
            original.memberOffset > group.queueNativeMembers.size() ||
            original.scope.input.memberCount > group.queueNativeMembers.size() - original.memberOffset ||
            original.scope.input.members != (original.scope.input.memberCount == 0 ? nullptr :
                group.queueNativeMembers.data() + original.memberOffset) ||
            original.identity.decision.slot != original.scope.input.decision.slot ||
            original.identity.decision.generation != original.scope.input.decision.generation ||
            original.identity.sliceIndex != original.scope.input.sliceIndex) return false;
        for (const auto& other : pendingVariableQueueNativeOrigins) {
            if (&other == &original || other.group != &group) continue;
            if (other.ordinal == original.ordinal || other.identity == original.identity) return false;
            if (original.scope.input.memberCount != 0 && other.scope.input.memberCount != 0 &&
                (original.memberOffset >= other.memberOffset
                    ? original.memberOffset - other.memberOffset < other.scope.input.memberCount
                    : other.memberOffset - original.memberOffset < original.scope.input.memberCount)) return false;
        }
    }
    return count == group.queueNativeOriginCount;
}

void Engine::ObservePendingVariableQueueNativeDisposal(void* context, Plan03GroupSliceIdentity identity,
    std::uint64_t root, std::uint64_t domain) noexcept {
    auto& engine = *static_cast<Engine*>(context);
    for (auto& original : engine.pendingVariableQueueNativeOrigins) {
        if (original.Empty() || !(original.identity == identity) || original.scope.cohortRoot != root ||
            original.scope.selectedFutureDomain != domain) continue;
        original.disposed = true;
    }
}

bool Engine::CapturePendingVariableQueueNativeOrigins(EngineActionPlayScratch& scratch,
    const PlayableInstanceTable::PreparedParentLinksProof& links) noexcept {
    using Origin = OriginalPendingVariableQueueNativeOrigin;
    auto* group = PreparedPendingVariableGroupFor(scratch.storage);
    if (group == nullptr || group->engine != this || group->queueNativeOriginCount != 0 || scratch.row == nullptr)
        return false;
    if (scratch.frontierQueueCount == 0 && scratch.queueFutureAttemptCount == 0) return true;
    if (scratch.frontierQueueCount > scratch.storage.frontierQueues.size() ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureAttempts.size()) return false;
    const auto* attempt = FindImmediateEntryAttempt(*this, scratch.row->Invocation().actionFiring);
    if (attempt == nullptr || !MatchesPendingVariableQueueRecordChains(*attempt)) return false;
    auto& census = initialQueueLaneGroupsScratch;
    const auto count = timelinePool.CaptureLiveImmediateLaneCohortGroups(attempt->root, census.data(), census.size());
    if (count > census.size()) return false;
    const auto ownsService = [&](const EnginePlayableServiceRow& service) noexcept {
        // Wrappers delegate their audible current and issue no native timing groups.
        if (!service.queueTimingPending) return false;
        std::uint32_t currents = 0, futures = 0;
        for (std::uint32_t index = 0; index < scratch.frontierQueueCount; ++index) {
            const auto& queue = scratch.storage.frontierQueues[index];
            if (queue.engine == this && ResolvePlayableService(queue.service) == &service) ++currents;
        }
        for (std::uint32_t index = 0; index < scratch.queueFutureAttemptCount; ++index) {
            const auto* future = FindFrontierAttempt(*this, scratch.storage.queueFutureAttempts[index]);
            if (future != nullptr && future->row == &service &&
                ResolvePlayableService(future->continuationService) == &service) ++futures;
        }
        return currents == 1 && futures <= 1;
    };
    const auto nativeIssuer = [&](EnginePlayableServiceToken token) noexcept {
        if (!token.Valid() || token.slot >= playableServices.size()) return false;
        const auto& service = playableServices[token.slot];
        return service.identity == token && service.queueTimingPending &&
            !IsInitialQueueTimingOnlyCurrent(service);
    };
    // A recorded native issuer cannot disappear merely by clearing its timing flag.
    for (const auto& record : queueContinuationRecords)
        if (record.occupied && record.root == attempt->root && record.attemptGeneration == attempt->generation &&
            !nativeIssuer(record.service)) return false;
    for (const auto& record : queueFutureRecords)
        if (record.occupied && record.root == attempt->root && record.attemptGeneration == attempt->generation &&
            !nativeIssuer(record.service)) return false;
    if (attempt->queueContinuationService.Valid() && !nativeIssuer(attempt->queueContinuationService)) return false;
    const auto capture = [&](const Plan03GroupSliceIdentity& identity, Origin& captured) noexcept {
        std::uint32_t matches = 0;
        for (const auto& service : playableServices) {
            if (!service.identity.Valid() || !service.InvocationValid() || !service.queueInstance.Valid() ||
                service.PendingImmediateCohortRoot() != attempt->root ||
                !ownsService(service) || IsInitialQueueTimingOnlyCurrent(service)) continue;
            Origin candidate{};
            candidate.service = {service.identity, service.ownerInstance, service.ownerEpoch, service.invocationGeneration};
            candidate.partition = service.partition;
            candidate.queue = service.queueInstance;
            candidate.identity = identity;
            candidate.attemptGeneration = attempt->generation;
            bool primary = false;
            auto continuation = attempt->queueContinuationHead;
            for (std::uint32_t index = 0; index < attempt->queueContinuationCount; ++index) {
                const auto& record = queueContinuationRecords[continuation];
                if (record.service == service.identity) {
                    candidate.recordKind = Origin::RecordKind::Continuation;
                    candidate.recordSlot = continuation;
                    candidate.recordGeneration = record.generation;
                    candidate.recordNext = record.next;
                    primary = identity == record.primaryGroup;
                }
                continuation = record.next;
            }
            auto future = attempt->queueFutureHead;
            for (std::uint32_t index = 0; index < attempt->queueFutureCount; ++index) {
                const auto& record = queueFutureRecords[future];
                if (record.service == service.identity) {
                    if (candidate.recordKind != Origin::RecordKind::None) return false;
                    candidate.recordKind = Origin::RecordKind::Future;
                    candidate.recordSlot = future;
                    candidate.recordGeneration = record.generation;
                    candidate.recordNext = record.next;
                    primary = identity == record.primaryGroup;
                }
                future = record.next;
            }
            if (attempt->queueContinuationService == service.identity) {
                if (candidate.recordKind != Origin::RecordKind::None ||
                    attempt->queueContinuationQueue.slot != service.queueInstance.slot ||
                    attempt->queueContinuationQueue.generation != service.queueInstance.generation ||
                    !SameCanonicalDecision(attempt->queueContinuationMemberDecision, service.QueueFiling().queueDecision)) return false;
                candidate.recordKind = Origin::RecordKind::Singleton;
                primary = identity == attempt->QueueCoordinators().queueContinuationPrimaryGroup;
            }
            const bool current = service.queueFirstContinuationLane &&
                SameCanonicalDecision(identity.decision, service.initialQueueEntryDecision);
            const bool successor = SameCanonicalDecision(identity.decision,
                service.queueFirstContinuationLane ? service.QueueFiling().queueDecision : service.initialQueueEntryDecision);
            if (!primary && !current && !successor) continue;
            if (candidate.recordKind == Origin::RecordKind::None ||
                ++matches != 1 || !playablePartitions.Owns(service.partition, service.identity) ||
                !playableInstances.MatchesPreparedOriginalAncestry(links, service.ownerInstance,
                    group->root.OriginalHandle()) || identity.committedRow >= originalQueueGroupHolders.size()) return false;
            auto& baseline = originalQueueGroupHolders[identity.committedRow];
            Plan03PageGroupView native{};
            if (!timelinePool.IsOriginalQueueFutureGroupRegistrationFor(baseline, identity, attempt->root) ||
                !baseline.CaptureOriginalScope(timelinePool, timelineArms, &candidate.scope) ||
                candidate.scope.cohortRoot != attempt->root || candidate.scope.selectedFutureDomain != 0 ||
                !timelinePool.ResolvePlan03GroupSliceProducer(identity, &native) || native.identity != identity ||
                native.memberCount != candidate.scope.input.memberCount ||
                native.sourceControlCount != candidate.scope.input.sourceControlCount ||
                (native.memberCount != 0 && native.members == nullptr)) return false;
            candidate.role = primary ? Origin::Role::Primary : current ? Origin::Role::Current : Origin::Role::Successor;
            const auto expectedCount = primary ? 0u : current ? service.QueuePayload().queueInitialCurrentDelayedCount : service.QueueFiling().queueTransitionGroupArmCount;
            const auto expectedControls = primary || current ? 0u : service.QueueFiling().queueSourceControlArmCount;
            const auto* expected = current ? service.QueuePayload().queueInitialCurrentDelayedArms.data() : service.QueueFiling().queueTransitionGroupArms.data();
            const auto frameIndex = primary ? (service.queueFirstContinuationLane ? 1u : 0u)
                : current ? 0u : identity.sliceIndex + (service.queueFirstContinuationLane ? 1u : 0u);
            if (service.QueuePayload().queueUnplacedGroupCount == 0 ||
                service.QueuePayload().queueUnplacedGroupCount > service.QueuePayload().queueUnplacedGroupFrames.size() ||
                expectedCount > (current ? service.QueuePayload().queueInitialCurrentDelayedArms.size() : service.QueueFiling().queueTransitionGroupArms.size()) ||
                frameIndex >= service.QueuePayload().queueUnplacedGroupCount ||
                candidate.scope.input.executeFrame != service.QueuePayload().queueUnplacedGroupFrames[frameIndex] ||
                native.memberCount != expectedCount || native.sourceControlCount != expectedControls ||
                (primary || current ? identity.sliceIndex != 0 :
                    identity.sliceIndex >= service.QueuePayload().queueUnplacedGroupCount - (service.queueFirstContinuationLane ? 1u : 0u))) return false;
            for (std::uint32_t member = 0; member < native.memberCount; ++member) {
                if (!SameOriginalSingleArm(native.members[member], candidate.scope.input.members[member])) return false;
                if (member < expectedControls && !SameOriginalSingleArm(native.members[member], expected[member])) return false;
                std::uint32_t members = 0;
                for (std::uint32_t index = 0; index < expectedCount; ++index)
                    members += SameOriginalSingleArm(native.members[member], expected[index]);
                if (members != 1) return false;
                for (std::uint32_t prior = 0; prior < member; ++prior)
                    if (SameOriginalSingleArm(native.members[member], native.members[prior])) return false;
            }
            if (!baseline.MatchesOriginalScope(candidate.scope.cohortRoot,
                    candidate.scope.provisionalAnchorFrame, candidate.scope.input, timelineArms)) return false;
            captured = candidate;
        }
        return matches <= 1;
    };
    std::uint32_t origins = 0, primaryOrigins = 0;
    std::size_t memberCount = 0;
    for (std::size_t index = 0; index < count; ++index) {
        Origin captured{};
        if (!capture(census[index].identity, captured)) return false;
        if (!captured.service.Valid()) continue;
        for (const auto& old : pendingVariableQueueNativeOrigins)
            if (!old.Empty() && old.identity == captured.identity) return false;
        if (++origins > pendingVariableQueueNativeOrigins.Capacity()) return false;
        primaryOrigins += captured.role == Origin::Role::Primary;
        if (captured.scope.input.memberCount > timelinePool.MaxArmsPerGroup() ||
            captured.scope.input.memberCount > group->queueNativeMembers.max_size() - memberCount) return false;
        memberCount += captured.scope.input.memberCount;
    }
    // Every owned Queue must have its primary and every issued native slice.
    for (const auto& service : playableServices) {
        if (!service.identity.Valid() || !service.InvocationValid() || !service.queueInstance.Valid() ||
            service.PendingImmediateCohortRoot() != attempt->root || !ownsService(service)) continue;
        if (IsInitialQueueTimingOnlyCurrent(service)) continue;
        std::uint32_t nativeCount = 0;
        for (std::size_t index = 0; index < count; ++index) {
            Origin captured{};
            if (!capture(census[index].identity, captured)) return false;
            nativeCount += captured.service.token == service.identity;
        }
        if (nativeCount != service.QueuePayload().queueUnplacedGroupCount + 1u) return false;
    }
    auto occupied = pendingVariableQueueNativeOrigins.ConstructedCount();
    while (occupied != 0 && pendingVariableQueueNativeOrigins[occupied - 1u].Empty()) --occupied;
    const auto required = static_cast<std::uint32_t>(std::min<std::uint64_t>(
        pendingVariableQueueNativeOrigins.Capacity(), static_cast<std::uint64_t>(occupied) + origins));
    if (!pendingVariableQueueNativeOrigins.ConstructThrough(required)) return false;
    if (static_cast<std::size_t>(std::count_if(pendingVariableQueueNativeOrigins.begin(), pendingVariableQueueNativeOrigins.end(),
            [](const auto& original) { return original.Empty(); })) < origins) return false;
    try {
        if (memberCount != 0) {
            if (!AllowNativeBackingAllocation()) return false;
            group->queueNativeMembers.resize(memberCount);
        }
        if (primaryOrigins != 0) {
            if (!AllowNativeBackingAllocation()) return false;
            group->boundAbort.queues.resize(primaryOrigins);
            if (!AllowNativeBackingAllocation()) return false;
            group->reprepare_.queues.resize(primaryOrigins);
        }
        if (origins != 0) {
            if (!AllowNativeBackingAllocation()) return false;
            group->reprepare_.nativeGroups.resize(std::size_t{3} + group->nestedInitialSideCount + origins);
        }
    } catch (const std::bad_alloc&) {
        return false;
    } catch (const std::length_error&) {
        return false;
    }
    std::size_t memberOffset = 0;
    for (std::size_t index = 0; index < count; ++index) {
        Origin captured{};
        const bool authenticated = capture(census[index].identity, captured);
        assert(authenticated);
        (void)authenticated;
        if (!captured.service.Valid()) continue;
        const auto found = std::find_if(pendingVariableQueueNativeOrigins.begin(), pendingVariableQueueNativeOrigins.end(),
            [](const auto& original) { return original.Empty(); });
        assert(found != pendingVariableQueueNativeOrigins.end());
        auto* members = captured.scope.input.memberCount == 0 ? nullptr : group->queueNativeMembers.data() + memberOffset;
        if (captured.scope.input.memberCount != 0)
            std::copy_n(captured.scope.input.members, captured.scope.input.memberCount, members);
        captured.scope.input.members = members;
        captured.memberOffset = memberOffset;
        memberOffset += captured.scope.input.memberCount;
        captured.group = group;
        captured.ordinal = group->queueNativeOriginCount++;
        *found = captured;
    }
    return true;
}

bool Engine::CanTransferPendingVariableQueueNativeOrigins(EngineActionPlayScratch& scratch,
    const EngineImmediateEntryAttempt& attempt) noexcept {
    auto* group = OriginalPendingVariableGroupForPublication(scratch, attempt);
    if (group == nullptr || !MatchesPendingVariableQueueNativeOrigins(*group)) return false;
    if (group->queueNativeOriginCount == 0) return true;
    if (!MatchesPendingVariableQueueRecordChains(attempt)) return false;
    for (auto& original : pendingVariableQueueNativeOrigins) {
        if (original.group != group) continue;
        // Exact disposal survives native slot reuse and ends this old responsibility.
        if (original.disposed) continue;
        const auto* service = ResolvePlayableService(original.service);
        if (original.scope.cohortRoot != attempt.root || original.attemptGeneration != attempt.generation ||
            service == nullptr || service->partition.slot != original.partition.slot ||
            service->partition.generation != original.partition.generation ||
            service->queueInstance.slot != original.queue.slot || service->queueInstance.generation != original.queue.generation ||
            original.identity.committedRow >= originalQueueGroupHolders.size() ||
            !timelinePool.IsOriginalQueueFutureGroupRegistrationFor(originalQueueGroupHolders[original.identity.committedRow],
                original.identity, attempt.root) ||
            !originalQueueGroupHolders[original.identity.committedRow].MatchesOriginalScope(original.scope.cohortRoot,
                original.scope.provisionalAnchorFrame, original.scope.input, timelineArms)) return false;
        if (original.recordKind == OriginalPendingVariableQueueNativeOrigin::RecordKind::Continuation) {
            if (original.recordSlot >= queueContinuationRecords.size()) return false;
            const auto& record = queueContinuationRecords[original.recordSlot];
            if (record.generation != original.recordGeneration || record.next != original.recordNext ||
                record.service != original.service.token || !record.prerequisiteMember.Exact() ||
                !record.conditionalMember.Exact() ||
                record.targetMember.Exact() != (service->QueuePayload().queueUnplacedGroupCount == 3u) ||
                (original.role == OriginalPendingVariableQueueNativeOrigin::Role::Primary
                    ? !(original.identity == record.primaryGroup)
                    : original.role == OriginalPendingVariableQueueNativeOrigin::Role::Current
                        ? !(original.identity == record.prerequisiteMember)
                        : original.identity != record.conditionalMember && original.identity != record.targetMember) ||
                !timelinePool.IsPlan03GroupReaderFor(record.prerequisiteMemberPin, record.prerequisiteMember)) return false;
        } else if (original.recordKind == OriginalPendingVariableQueueNativeOrigin::RecordKind::Future) {
            if (original.recordSlot >= queueFutureRecords.size()) return false;
            const auto& record = queueFutureRecords[original.recordSlot];
            if (record.generation != original.recordGeneration || record.next != original.recordNext ||
                record.service != original.service.token || !record.prerequisiteMember.Exact() ||
                !record.sourceMember.Exact() || !record.targetMember.Exact() ||
                (original.role == OriginalPendingVariableQueueNativeOrigin::Role::Primary
                    ? !(original.identity == record.primaryGroup)
                    : !(original.identity == record.sourceMember) && !(original.identity == record.targetMember)) ||
                !timelinePool.IsPlan03GroupReaderFor(record.prerequisiteMemberPin, record.prerequisiteMember) ||
                !record.parentPin.Valid() || record.parentPin.Owner() != &decisions ||
                !SameCanonicalDecision(record.parentPin.Token(), scratch.frontierDescriptor.entry.coordinator) ||
                !(record.parentEntry == scratch.frontierDescriptor.entry) ||
                scratch.initialFrontierSideCount > scratch.storage.initialFrontierSides.size()) return false;
            const auto queueOwner = playableInstances.Classify(service->ownerInstance);
            std::uint32_t prerequisites = 0;
            EnginePlayableServiceReference parentReference{};
            for (std::uint32_t index = 0; index < scratch.initialFrontierSideCount; ++index) {
                const auto& side = scratch.storage.initialFrontierSides[index];
                if (!(side.group == record.prerequisiteMember)) continue;
                const auto* parent = ResolvePlayableService(side.service);
                Plan03PageGroupView native{};
                if (++prerequisites != 1 || !queueOwner.live || parent == nullptr ||
                    parent->ownerInstance != queueOwner.parent || !parent->InvocationValid() ||
                    &parent->Invocation() != &scratch.row->Invocation() ||
                    !SameCanonicalDecision(side.decision, side.group.decision) ||
                    !timelinePool.ResolvePlan03GroupSliceProducer(side.group, &native) ||
                    native.frontier == nullptr || native.lease == nullptr ||
                    !(native.frontier->entry == record.parentEntry) ||
                    !(native.frontier->operation.group == side.group)) return false;
                const bool discrete = SameCanonicalDecision(side.decision, parent->variableControlDiscreteDecision);
                if (!(side.group == (discrete ? parent->InitialLaneDiscreteGroup() : parent->InitialLaneContinuousGroup()))) return false;
                const auto bank = discrete ? parent->variableControlDiscreteBank : parent->variableControlContinuousBank;
                const auto kind = discrete ? VariableControlSide::Discrete : VariableControlSide::Continuous;
                const VariableControlInstanceTable::OriginalInitialSideReceipt* receipt = nullptr;
                if (parent == scratch.row) receipt = &group->initialSides[discrete ? 0u : 1u];
                else for (std::uint32_t nested = 0; nested < group->nestedInitialSideCount; ++nested) {
                    const auto& held = group->nestedInitialSides[nested];
                    if (SameSelectionServiceReference(held.service, side.service) && held.side == kind && held.group == side.group)
                        receipt = &held.original;
                }
                if (receipt == nullptr || !variableControlInstances.MatchesOriginalInitialSideReceipt(
                        *receipt, parent->variableControlInstance, kind, side.decision, bank) ||
                    !variableControlInstances.MatchesPrivateInitialFrontierSide(*receipt,
                        *native.frontier, timelinePool, decisions)) return false;
                parentReference = side.service;
            }
            if (prerequisites != 1 || (original.prerequisite.Valid() &&
                    (!(original.prerequisite == record.prerequisiteMember) ||
                     !SameSelectionServiceReference(original.prerequisiteService, parentReference) ||
                     !(original.prerequisiteEntry == record.parentEntry)))) return false;
            original.prerequisite = record.prerequisiteMember;
            original.prerequisiteService = parentReference;
            original.prerequisiteEntry = record.parentEntry;
        } else if (original.recordKind == OriginalPendingVariableQueueNativeOrigin::RecordKind::Singleton &&
            attempt.queueContinuationService != original.service.token) return false;
    }
    return true;
}

void Engine::TransferPendingVariableQueueNativeOrigins(OriginalPendingVariableGroupHolder& group) noexcept {
    assert(MatchesPendingVariableQueueNativeOrigins(group));
    for (auto& original : pendingVariableQueueNativeOrigins)
        if (original.group == &group) original = {};
    group.queueNativeOriginCount = 0;
    std::vector<TimelineArmToken>().swap(group.queueNativeMembers);
}

bool Engine::ReturnDisposedPendingVariableQueueNativeOrigins(OriginalPendingVariableGroupHolder& group) noexcept {
    if (!MatchesPendingVariableQueueNativeOrigins(group)) return false;
    for (const auto& original : pendingVariableQueueNativeOrigins)
        if (original.group == &group && !original.disposed) return false;
    for (auto& original : pendingVariableQueueNativeOrigins)
        if (original.group == &group) original = {};
    group.queueNativeOriginCount = 0;
    std::vector<TimelineArmToken>().swap(group.queueNativeMembers);
    return true;
}

bool Engine::BindPendingVariableGroupQueueFutureSources(EngineActionPlayScratch& scratch,
    const PlayableInstanceTable::PreparedParentLinksProof& links) noexcept {
    auto* group = PreparedPendingVariableGroupFor(scratch.storage);
    if (group == nullptr || group->engine != this || group->accepted || !group->cut.Valid() ||
        !group->producer.Valid() || scratch.row == nullptr || group->futureSourceCount != 0 ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureAttempts.size() ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureOwners.size()) return false;
    std::size_t count = 0;
    const auto parentSlot = actionPlayScratch.IndexOf(scratch);
    // Authenticate all original prepared voices before attaching any association.
    for (std::uint32_t futureIndex = 0; futureIndex < scratch.queueFutureAttemptCount; ++futureIndex) {
        const auto token = scratch.storage.queueFutureAttempts[futureIndex];
        const auto& owner = scratch.storage.queueFutureOwners[futureIndex];
        const auto* future = FindFrontierAttempt(*this, token);
        if (future == nullptr || future->row == nullptr || !future->queueFutureExecution || !future->prepared ||
            !future->frontierOwnerLedgerComplete || future->storage.phase != EngineFrontierAttemptPhase::Preparing ||
            owner.engine != this || owner.committed || owner.parent.slot != parentSlot ||
            owner.parent.generation != scratch.storage.generation || owner.child.slot != token.slot ||
            owner.child.generation != token.generation || future->queueFutureParent.slot != parentSlot ||
            future->queueFutureParent.generation != scratch.storage.generation ||
            ResolvePlayableService(future->continuationService) != future->row ||
            future->continuationPartition.slot != future->row->partition.slot ||
            future->continuationPartition.generation != future->row->partition.generation ||
            future->row->invocation != scratch.row->invocation ||
            future->row->invocationGeneration != scratch.row->invocationGeneration ||
            !playableInstances.MatchesPreparedOriginalAncestry(links, future->row->ownerInstance,
                group->root.OriginalHandle()) ||
            future->queueSuccessorVoiceStartCount > future->queueSuccessorVoiceStarts.size() ||
            future->queueSuccessorVoiceStartCount > future->queueSuccessorVoiceStarts.Owners().size()) return false;
        if (future->row->QueueFiling().queueSameProgramKey) {
            if (future->queueSuccessorVoiceStartCount != 0) return false;
            continue;
        }
        if (owner.originalParentLinks != &links || !future->row->queueTimingPending ||
            future->queueFuturePreparedQueue == nullptr || !future->queueFuturePreparedQueue->Valid() ||
            future->queueFuturePreparedQueue->Token().slot != future->row->queueInstance.slot ||
            future->queueFuturePreparedQueue->Token().generation != future->row->queueInstance.generation ||
            !future->playableTreeExecutor.InstanceCommitProofsHeld() ||
            future->queueFutureMemberCount != future->queueSuccessorVoiceStartCount ||
            future->queueFutureMemberCount > future->queueFutureMemberSlots.size() ||
            future->queueFutureMemberBase > playableStorage.memberCount ||
            future->queueFutureMemberCount > playableStorage.memberCount - future->queueFutureMemberBase)
            return false;
        const auto& tree = future->playableTreeExecutor;
        const auto& row = *future->row;
        const auto controlCount = row.QueueFiling().queueSourceControlArmCount;
        const auto nativeCount = row.QueueFiling().queueTransitionGroupArmCount;
        if (!future->queueArmGroupPrepared || nativeCount > row.QueueFiling().queueTransitionGroupArms.size() ||
            nativeCount > UINT16_MAX || controlCount > nativeCount ||
            nativeCount - controlCount != future->queueSuccessorVoiceStartCount ||
            controlCount != future->queueSourceControlArmCount || controlCount != future->queueSourceCommandCount ||
            controlCount > future->queueSourceCommands.size() || controlCount > row.QueueRuntimeViews().queueSourceSchedules.size() ||
            controlCount > row.QueueRuntimeViews().queueSourceRuntimePrograms.size() ||
            future->queueArmGroup.slot != future->row->QueueFiling().queueArmGroup.slot ||
            future->queueArmGroup.generation != future->row->QueueFiling().queueArmGroup.generation) return false;
        const auto nativeParent = future->row->queueFirstContinuationLane
            ? future->queueFutureCurrentDecision : future->row->initialQueueEntryDecision;
        if (!armGroups.MatchesPreparedMembers(future->queueArmGroup, nativeParent,
                row.QueueFiling().queueTransitionGroupArms.data(), static_cast<std::uint16_t>(nativeCount))) return false;
        const auto* bank = future->queueFutureProgramBank;
        if (controlCount != 0 && (bank == nullptr || bank != row.QueueFiling().queueSuccessorProgramBank ||
                !bank->occupied || bank->published || bank->programCount != nativeCount ||
                bank->programCount > bank->schedules.size() || bank->eventCount > bank->events.size()))
            return false;
        for (std::uint32_t index = 0; index < controlCount; ++index) {
            const auto arm = row.QueueFiling().queueTransitionGroupArms[index];
            const auto& command = future->queueSourceCommands[index];
            const auto& schedule = row.QueueRuntimeViews().queueSourceSchedules[index];
            const auto programIndex = future->queueSuccessorVoiceStartCount + index;
            const auto& frozen = bank->schedules[programIndex];
            const auto& program = bank->runtimes[programIndex];
            std::uint32_t eventBase = 0;
            for (std::uint32_t prior = 0; prior < programIndex; ++prior) {
                if (bank->schedules[prior].eventCount > bank->eventCount - eventBase) return false;
                eventBase += bank->schedules[prior].eventCount;
            }
            const auto handle = (static_cast<VnVoiceHandle>(arm.renderGeneration) << 32) | arm.renderSlot;
            if (command.opcode != kOpcodePlay || command.payload.play.handle != handle ||
                command.payload.play.sourceIdentity != handle ||
                command.payload.play.batch.batchVersion != kPlayLedBatchVersion ||
                command.payload.play.batch.batchKind != PlayLedBatchKind::TimelineControlArm ||
                command.payload.play.batch.batchCommandCount != 1 ||
                command.payload.play.batch.armToken != (static_cast<std::uint64_t>(arm.generation) << 32 | arm.slot) ||
                !SameOriginalSingleArm(schedule.armToken, arm) || schedule.ownerInstance != row.rootInstance ||
                schedule.ownerInstanceScheduleEpoch != row.ownerEpoch || schedule.transactionId != row.ticket ||
                program.generation != row.rootInstance || program.payloadCount == 0 || program.payloads == nullptr ||
                schedule.runtimeProgram.program != &program || schedule.runtimeProgram.programGeneration != row.rootInstance ||
                !SameOriginalSingleArm(frozen.armToken, arm) || frozen.ownerInstance != row.rootInstance ||
                frozen.ownerInstanceScheduleEpoch != row.ownerEpoch || frozen.transactionId != row.ticket ||
                frozen.entryAnchorFrame != schedule.entryAnchorFrame || frozen.eventCount != schedule.eventCount ||
                frozen.eventCount != program.payloadCount || frozen.eventCount > bank->eventCount - eventBase ||
                frozen.runtimeProgram.program != &program || frozen.runtimeProgram.programGeneration != row.rootInstance ||
                frozen.events != bank->events.data() + eventBase || program.payloads != bank->payloads.data() + eventBase)
                return false;
            const auto& preparation = future->queueSourceArmPreparations[index];
            if (!SameOriginalSingleArm(preparation.arm, arm) ||
                preparation.programGeneration != row.rootInstance ||
                !(preparation.target == program.payloads[0].target) ||
                !SameCanonicalDecision(preparation.parentGroup.decision, nativeParent) ||
                preparation.memberIndex != index || !preparation.pendingImmediateStart ||
                preparation.startFrame != 0 || preparation.armDeadline != 0) return false;
            TimelineArmTable::PreparedCommitProof proof;
            if (!timelineArms.ProvePreparedCommit(preparation, &proof)) return false;
        }
        for (std::uint32_t index = 0; index < future->queueSuccessorVoiceStartCount; ++index) {
            const auto& start = future->queueSuccessorVoiceStarts[index];
            const auto& commit = future->queueSuccessorVoiceStarts.Owners()[index];
            if (!start.prepared || commit.engine != this || commit.token != &start || commit.committed ||
                !commit.preparedCommitProofsRequired || !start.armPreparation.pendingImmediateStart ||
                !start.armPreparation.parentGroup.Valid() || start.arm.slot >= pendingVariableLeafSources.size() ||
                start.commandCount == 0 || start.commandCount > start.commands.size()) return false;
            const auto& staged = pendingVariableLeafSources[start.arm.slot];
            if (staged.group != nullptr || staged.cut.Valid() ||
                staged.domain != OriginalPendingVariableLeafSource::Domain::Unbound ||
                !OriginalSourceSubmissionRegistry::SameToken(staged.arm, start.arm) ||
                staged.programGeneration != start.armPreparation.programGeneration ||
                staged.parent != start.ledgerPreparation.parent.internalToken ||
                staged.preparedStartFrame < scratch.row->startFrame ||
                staged.physicalRelease.slot != start.releaseObserver.slot ||
                staged.physicalRelease.targetSequence != start.releaseObserver.targetSequence ||
                !playableInstances.MatchesPreparedOriginalAncestry(links, staged.parent, group->root.OriginalHandle()) ||
                !originalSourceSubmissions.MatchesPreparedInitialGroupSourcePair(staged.source, staged.body,
                    commit.armCommitProof, commit.voiceCommitProof, start.voicePreparation,
                    preparedVoiceCommandBatchProof, start.arm, staged.sourceIdentity)) return false;
            const PreparedPlayableInstance* original = nullptr;
            for (std::size_t node = 0; node < tree.PreparedInstanceCensusCount(); ++node) {
                const auto* candidate = tree.PreparedInstanceCensusToken(node);
                if (candidate == nullptr || !candidate->Valid()) return false;
                if (candidate->Handle() == staged.programGeneration) {
                    if (original != nullptr) return false;
                    original = candidate;
                }
            }
            auto* baseline = ResolveOriginalPlayableBaseline(this, playableInstances, staged.programGeneration);
            if (original == nullptr || baseline == nullptr || baseline->OriginalParent() != original->Parent() ||
                baseline->OriginalScheduleEpoch() != original->ScheduleEpoch()) return false;
            const auto& member = ReadPlayableMemberReference(future->queueFutureMemberBase + index);
            const auto slot = future->queueFutureMemberSlots[index];
            auto* expectedResource = future->frontierResourceService.Valid()
                ? ResolvePlayableService(future->frontierResourceService) : future->row;
            EnginePlayableServiceRow* resource = nullptr;
            std::size_t physicalSlot = 0;
            if (expectedResource == nullptr || !ResolvePlayableMember(member, &resource, &physicalSlot) ||
                resource != expectedResource || resource->invocation != row.invocation ||
                resource->invocationGeneration != row.invocationGeneration || physicalSlot != slot ||
                member.leaf != staged.programGeneration || member.leafEpoch != original->ScheduleEpoch() ||
                slot >= playableStorage.memberCount || !OriginalSourceSubmissionRegistry::SameToken(
                    ReadPlayableMember(slot).arm, start.arm) || ReadPlayableMember(slot).render != start.renderHandle)
                return false;
            const auto root = future->variableControlNestedQueueSuccessor.Handle();
            auto cursor = original->Handle();
            bool resourceReached = resource == &row, queueReached = false;
            for (std::size_t depth = 0; depth < tree.PreparedInstanceCensusCount(); ++depth) {
                const PreparedPlayableInstance* ancestor = nullptr;
                for (std::size_t node = 0; node < tree.PreparedInstanceCensusCount(); ++node) {
                    const auto* candidate = tree.PreparedInstanceCensusToken(node);
                    if (candidate != nullptr && candidate->Handle() == cursor) ancestor = candidate;
                }
                if (ancestor == nullptr || !ancestor->Valid()) return false;
                if (ancestor->Handle() == resource->ownerInstance) {
                    if (ancestor->ScheduleEpoch() != resource->ownerEpoch) return false;
                    resourceReached = true;
                }
                if (ancestor->Handle() == root) {
                    queueReached = ancestor->Parent() == row.ownerInstance;
                    break;
                }
                cursor = ancestor->Parent();
            }
            if (!resourceReached || !queueReached) return false;
            if (!SameOriginalSingleArm(row.QueueFiling().queueTransitionGroupArms[controlCount + index], start.arm) ||
                !SameCanonicalDecision(nativeParent, start.armPreparation.parentGroup.decision) ||
                start.armPreparation.memberIndex != controlCount + index) return false;
            if (start.initialVariableReadUse.Valid() && !variables.MatchesPreparedTimelineReadUse(
                    start.initialVariableReadUse, group->cut, start.renderHandle, commit.armCommitProof,
                    originalSourceSubmissions, staged.preparedStartFrame - scratch.row->startFrame)) return false;
            for (std::uint32_t priorFuture = 0; priorFuture <= futureIndex; ++priorFuture) {
                const auto* previous = FindFrontierAttempt(*this, scratch.storage.queueFutureAttempts[priorFuture]);
                if (previous == nullptr) return false;
                const auto limit = priorFuture == futureIndex ? index : previous->queueSuccessorVoiceStartCount;
                for (std::uint32_t prior = 0; prior < limit; ++prior) {
                    const auto& voice = previous->queueSuccessorVoiceStarts[prior];
                    if (voice.arm.slot == start.arm.slot || voice.renderHandle == start.renderHandle ||
                        (SameCanonicalDecision(voice.armPreparation.parentGroup.decision,
                            start.armPreparation.parentGroup.decision) &&
                         voice.armPreparation.memberIndex == start.armPreparation.memberIndex)) return false;
                }
            }
            if (++count > pendingVariableFutureSources.size()) return false;
        }
    }
    if (static_cast<std::size_t>(std::count_if(pendingVariableFutureSources.begin(), pendingVariableFutureSources.end(),
            [](const auto& original) { return original.Empty(); })) < count) return false;
    if (scratch.row->Invocation().variableControlOuterRootInstance == 0 &&
        !CapturePendingVariableGroupFutureNodes(scratch, links, *group)) return false;
    if (!CapturePendingVariableQueueNativeOrigins(scratch, links)) return false;
    for (std::uint32_t futureIndex = 0; futureIndex < scratch.queueFutureAttemptCount; ++futureIndex) {
        const auto& future = *FindFrontierAttempt(*this, scratch.storage.queueFutureAttempts[futureIndex]);
        for (std::uint32_t index = 0; index < future.queueSuccessorVoiceStartCount; ++index) {
            const auto& start = future.queueSuccessorVoiceStarts[index];
            auto& staged = pendingVariableLeafSources[start.arm.slot];
            auto found = std::find_if(pendingVariableFutureSources.begin(), pendingVariableFutureSources.end(),
                [](const auto& original) { return original.Empty(); });
            assert(found != pendingVariableFutureSources.end());
            auto& captured = *found;
            captured.group = group;
            captured.service = future.continuationService;
            captured.partition = future.continuationPartition;
            captured.queue = future.queueFuturePreparedQueue->Token();
            captured.arm = start.arm;
            captured.parentGroup = start.armPreparation.parentGroup;
            captured.memberIndex = start.armPreparation.memberIndex;
            captured.ordinal = group->futureSourceCount++;
            captured.sourceIdentity = staged.sourceIdentity;
            captured.programGeneration = staged.programGeneration;
            captured.parent = staged.parent;
            captured.epoch = ReadPlayableMemberReference(future.queueFutureMemberBase + index).leafEpoch;
            captured.preparedStartFrame = staged.preparedStartFrame;
            captured.release = staged.physicalRelease;
            captured.retained = true;
            staged.group = group;
            staged.cut = group->cut;
            staged.leafIndex = static_cast<std::uint32_t>(found - pendingVariableFutureSources.begin());
            staged.domain = OriginalPendingVariableLeafSource::Domain::QueueFuture;
        }
    }
    return true;
}

bool Engine::SealPendingVariableGroupInitialSideNativeGroup(EngineActionPlayScratch& scratch,
    EnginePlayableServiceRow& service, bool discrete, const Plan03GroupSliceIdentity& identity,
    const Plan03GroupSliceInput& input) noexcept {
    auto* group = PreparedPendingVariableGroupFor(scratch.storage);
    if (group == nullptr || group->Empty()) return true;
    if (group->engine != this || scratch.row == nullptr || group->accepted ||
        &service.Invocation() != &scratch.row->Invocation()) return false;
    OriginalPendingVariableGroupHolder::NestedInitialSide* original = nullptr;
    for (std::uint32_t side = 0; side < group->nestedInitialSideCount; ++side) {
        auto& candidate = group->nestedInitialSides[side];
        if (ResolvePlayableService(candidate.service) != &service ||
            candidate.side != (discrete ? VariableControlSide::Discrete : VariableControlSide::Continuous)) continue;
        if (original != nullptr) return false;
        original = &candidate;
    }
    Plan03PageGroupView native{};
    ArmGroupSnapshot arms{};
    const auto actualArms = discrete ? service.variableControlDiscreteArmGroup : service.variableControlContinuousArmGroup;
    if (original == nullptr || !SameCanonicalDecision(original->decision, input.decision) ||
        original->memberCount != input.memberCount || original->armGroup.slot != actualArms.slot ||
        original->armGroup.generation != actualArms.generation ||
        !variableControlInstances.MatchesOriginalInitialSideReceipt(original->original,
            original->instance, original->side, input.decision, original->bank) ||
        (original->group.Valid() && !(original->group == identity)) ||
        !identity.Exact() || identity.committedRow >= originalQueueGroupHolders.size() ||
        !SameCanonicalDecision(identity.decision, input.decision) || identity.sliceIndex != input.sliceIndex ||
        !timelinePool.IsOriginalQueueFutureGroupRegistrationFor(
            originalQueueGroupHolders[identity.committedRow], identity, scratch.row->Invocation().actionFiring) ||
        !timelinePool.ResolvePlan03GroupSliceProducer(identity, &native) ||
        native.memberCount != input.memberCount || native.sourceControlCount != 0 || native.frontier != nullptr ||
        !armGroups.Capture(actualArms, &arms) || arms.memberCount != input.memberCount ||
        !SameCanonicalDecision(arms.parent, input.decision)) return false;
    for (std::uint16_t member = 0; member < input.memberCount; ++member) {
        ArmGroupMemberSnapshot actual{};
        if (native.members == nullptr || input.members == nullptr ||
            !armGroups.CaptureMember(actualArms, member, &actual) ||
            !SameOriginalSingleArm(native.members[member], input.members[member]) ||
            !SameOriginalSingleArm(actual.token, input.members[member])) return false;
    }
    original->group = identity;
    return true;
}

bool Engine::CapturePendingVariableGroupTopology(EngineActionPlayScratch& scratch,
    const PlayableInstanceTable::PreparedParentLinksProof& links,
    OriginalPendingVariableGroupHolder& group) noexcept {
    const auto& row = *scratch.row;
    if (row.Invocation().variableControlOuterRootInstance != 0) return true;
    for (std::uint32_t index = 0; index < scratch.variableControlChildCount; ++index) {
        const auto kind = scratch.variableControlChildKinds[index];
        if (kind != PlayableKind::Sound && kind != PlayableKind::Track && kind != PlayableKind::Segment &&
            kind != PlayableKind::Container) return true;
    }
    constexpr auto nodeCapacity = 2u * kMaxKnownScheduleLeaves;
    if (row.variableControlChildCount > kMaxKnownScheduleLeaves ||
        scratch.voiceStartCount > kMaxKnownScheduleLeaves ||
        scratch.variableControlChildCount > nodeCapacity ||
        scratch.variableControlLeafChildCount > nodeCapacity - scratch.variableControlChildCount) return false;
    OriginalPendingVariableGroupHolder::InitialTopology topology;
    try {
        const auto allocateColumn = [&](auto& column, std::size_t count) {
            if (count == 0) return true;
            if (!AllowNativeBackingAllocation()) return false;
            column.resize(count);
            return true;
        };
        if (!allocateColumn(topology.nodes, scratch.variableControlChildCount + scratch.variableControlLeafChildCount) ||
            !allocateColumn(topology.topNodes, row.variableControlChildCount) ||
            !allocateColumn(topology.leafNodes, scratch.voiceStartCount) ||
            !allocateColumn(topology.leafTops, scratch.voiceStartCount)) return false;
    } catch (const std::bad_alloc&) {
        return false;
    } catch (const std::length_error&) {
        return false;
    }
    if (row.ownerInstance != scratch.instance.Handle() || row.ownerEpoch != scratch.instance.ScheduleEpoch() ||
        row.variableControlChildCount > scratch.variableControlChildCount ||
        row.variableControlNestedChildCount != scratch.variableControlChildCount ||
        row.variableControlChildCount > topology.topNodes.size() ||
        scratch.voiceStartCount > topology.leafNodes.size() ||
        scratch.variableControlChildCount + scratch.variableControlLeafChildCount > topology.nodes.size()) return false;
    std::array<PlayableInstanceTable::PreparedNodeCensusEntry, 2u * kMaxKnownScheduleLeaves + 1u> census{};
    census[0] = {&scratch.instance, PlayableKind::Container};
    std::uint32_t censusCount = 1;
    const auto append = [&](const PreparedPlayableInstance& original, PlayableKind kind) noexcept {
        if (!original.Valid() || censusCount == census.size()) return false;
        for (std::uint32_t index = 0; index < topology.nodeCount; ++index)
            if (topology.nodes[index].handle == original.Handle()) return false;
        auto& node = topology.nodes[topology.nodeCount++];
        node.handle = original.Handle();
        node.parent = original.Parent();
        node.epoch = original.ScheduleEpoch();
        node.kind = kind;
        census[censusCount++] = {&original, kind};
        return true;
    };
    for (std::uint32_t index = 0; index < scratch.variableControlChildCount; ++index)
        if (!append(scratch.variableControlChildren[index], scratch.variableControlChildKinds[index])) return false;
    topology.structuralCount = topology.nodeCount;
    for (std::uint32_t index = 0; index < scratch.variableControlLeafChildCount; ++index)
        if (!append(scratch.variableControlLeafChildren[index], PlayableKind::Sound)) return false;
    if (!playableInstances.MatchesPreparedOriginalNodeCensus(links, {census.data(), censusCount})) return false;
    topology.topCount = row.variableControlChildCount;
    topology.leafCount = scratch.voiceStartCount;
    for (std::uint32_t index = 0; index < topology.topCount; ++index) {
        const auto& node = topology.nodes[index];
        if (node.parent != row.ownerInstance || node.handle != row.variableControlChildInstances[index] ||
            node.epoch != row.variableControlChildEpochs[index] || node.kind != row.variableControlChildKinds[index]) return false;
        topology.topNodes[index] = index;
    }
    for (std::uint32_t index = 0; index < topology.leafCount; ++index) {
        std::uint32_t found = UINT32_MAX, top = UINT32_MAX;
        for (std::uint32_t node = 0; node < topology.nodeCount; ++node)
            if (topology.nodes[node].handle == row.variableControlLeafInstances[index]) found = node;
        if (found == UINT32_MAX || topology.nodes[found].kind != PlayableKind::Sound ||
            topology.nodes[found].epoch != row.variableControlLeafEpochs[index] ||
            scratch.voiceStarts[index].armPreparation.programGeneration != topology.nodes[found].handle) return false;
        for (std::uint32_t prior = 0; prior < index; ++prior)
            if (topology.leafNodes[prior] == found) return false;
        for (std::uint32_t root = 0; root < topology.topCount; ++root) {
            if (!playableInstances.MatchesPreparedOriginalAncestry(links,
                    topology.nodes[found].handle, topology.nodes[topology.topNodes[root]].handle)) continue;
            if (top != UINT32_MAX) return false;
            top = root;
        }
        if (top == UINT32_MAX) return false;
        topology.leafNodes[index] = found;
        topology.leafTops[index] = top;
    }
    for (std::uint32_t index = 0; index < topology.nodeCount; ++index) {
        const auto& node = topology.nodes[index];
        if (!playableInstances.MatchesPreparedOriginalAncestry(links, node.handle, row.ownerInstance)) return false;
        std::uint32_t descendants = 0;
        for (std::uint32_t leaf = 0; leaf < topology.leafCount; ++leaf)
            descendants += playableInstances.MatchesPreparedOriginalAncestry(links,
                topology.nodes[topology.leafNodes[leaf]].handle, node.handle);
        if (node.kind == PlayableKind::Sound && descendants != 1) return false;
    }
    for (std::uint32_t index = 0; index < topology.nodeCount; ++index) {
        auto& node = topology.nodes[index];
        auto* original = ResolveOriginalPlayableBaseline(this, playableInstances, node.handle);
        if (original == nullptr || !original->Borrow(&node.loan) ||
            node.loan.OriginalParent() != node.parent || node.loan.OriginalScheduleEpoch() != node.epoch) return false;
    }
    topology.sealed = scratch.queueFutureAttemptCount == 0;
    group.topology_ = std::move(topology);
    return true;
}

bool Engine::CapturePendingVariableGroupFutureNodes(EngineActionPlayScratch& scratch,
    const PlayableInstanceTable::PreparedParentLinksProof& links,
    OriginalPendingVariableGroupHolder& group) noexcept {
    if (group.engine != this || scratch.row == nullptr || group.futureNodeCount != 0 ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureAttempts.size() ||
        scratch.queueFutureAttemptCount > scratch.storage.queueFutureOwners.size()) return false;
    std::size_t total = 0;
    const auto parentSlot = actionPlayScratch.IndexOf(scratch);
    // Future trees have their own commit census, while the arranging Queue belongs to links.
    for (std::uint32_t index = 0; index < scratch.queueFutureAttemptCount; ++index) {
        const auto token = scratch.storage.queueFutureAttempts[index];
        const auto& owner = scratch.storage.queueFutureOwners[index];
        const auto* future = FindFrontierAttempt(*this, token);
        if (future == nullptr || future->row == nullptr || !future->queueFutureExecution || !future->prepared ||
            !future->frontierOwnerLedgerComplete || future->storage.phase != EngineFrontierAttemptPhase::Preparing ||
            owner.engine != this || owner.committed || owner.parent.slot != parentSlot ||
            owner.parent.generation != scratch.storage.generation || owner.child.slot != token.slot ||
            owner.child.generation != token.generation || future->queueFutureParent.slot != parentSlot ||
            future->queueFutureParent.generation != scratch.storage.generation ||
            ResolvePlayableService(future->continuationService) != future->row ||
            future->continuationPartition.slot != future->row->partition.slot ||
            future->continuationPartition.generation != future->row->partition.generation ||
            future->row->invocation != scratch.row->invocation ||
            future->row->invocationGeneration != scratch.row->invocationGeneration ||
            !playableInstances.MatchesPreparedOriginalAncestry(links, future->row->ownerInstance,
                scratch.row->ownerInstance)) return false;
        const auto queueNode = std::find_if(group.topology_.nodes.begin(),
            group.topology_.nodes.begin() + group.topology_.nodeCount, [&](const auto& node) {
                return node.handle == future->row->ownerInstance && node.epoch == future->row->ownerEpoch &&
                    node.kind == PlayableKind::Container;
            });
        if (queueNode == group.topology_.nodes.begin() + group.topology_.nodeCount) return false;
        if (future->row->QueueFiling().queueSameProgramKey) {
            if (future->variableControlNestedQueueSuccessor.Handle() != 0 ||
                future->queueSuccessorVoiceStartCount != 0) return false;
            continue;
        }
        const auto& tree = future->playableTreeExecutor;
        const auto count = tree.PreparedInstanceCensusCount();
        if (owner.originalParentLinks != &links || !tree.InstanceCommitProofsHeld() || !tree.Validate() ||
            count == 0 || count > pendingVariableFutureNodes.size() - total ||
            future->queueSuccessorVoiceStartCount > future->queueSuccessorVoiceStarts.size() ||
            future->queueFuturePreparedQueue == nullptr || !future->queueFuturePreparedQueue->Valid() ||
            future->queueFuturePreparedQueue->Token().slot != future->row->queueInstance.slot ||
            future->queueFuturePreparedQueue->Token().generation != future->row->queueInstance.generation ||
            !future->variableControlNestedQueueSuccessor.Valid() ||
            future->variableControlNestedQueueSuccessor.Parent() != future->row->ownerInstance) return false;
        const auto root = future->variableControlNestedQueueSuccessor.Handle();
        std::uint32_t rootCount = 0, sounds = 0;
        for (std::size_t node = 0; node < count; ++node) {
            const auto* original = tree.PreparedInstanceCensusToken(node);
            auto* baseline = original == nullptr ? nullptr :
                ResolveOriginalPlayableBaseline(this, playableInstances, original->Handle());
            PlayableKind kind{};
            if (baseline == nullptr || !playableInstances.CaptureOriginalPreparedNodeKind(*original, *baseline, &kind) ||
                std::any_of(group.topology_.nodes.begin(), group.topology_.nodes.begin() + group.topology_.nodeCount,
                    [&](const auto& current) { return current.handle == original->Handle(); })) return false;
            rootCount += original->Handle() == root;
            sounds += kind == PlayableKind::Sound;
            for (std::uint32_t priorFuture = 0; priorFuture <= index; ++priorFuture) {
                const auto* prior = FindFrontierAttempt(*this, scratch.storage.queueFutureAttempts[priorFuture]);
                if (prior == nullptr) return false;
                const auto limit = priorFuture == index ? node : prior->playableTreeExecutor.PreparedInstanceCensusCount();
                for (std::size_t previous = 0; previous < limit; ++previous) {
                    const auto* other = prior->playableTreeExecutor.PreparedInstanceCensusToken(previous);
                    if (other == nullptr || other->Handle() == original->Handle()) return false;
                }
            }
            auto cursor = original->Handle();
            bool reached = false;
            for (std::size_t depth = 0; depth < count; ++depth) {
                const PreparedPlayableInstance* actual = nullptr;
                for (std::size_t candidate = 0; candidate < count; ++candidate) {
                    const auto* entry = tree.PreparedInstanceCensusToken(candidate);
                    if (entry != nullptr && entry->Handle() == cursor) actual = entry;
                }
                if (actual == nullptr) return false;
                if (actual->Handle() == root) {
                    reached = actual->Parent() == future->row->ownerInstance;
                    break;
                }
                cursor = actual->Parent();
            }
            if (!reached) return false;
            if (kind == PlayableKind::Sound) {
                std::uint32_t voices = 0;
                for (std::uint32_t voice = 0; voice < future->queueSuccessorVoiceStartCount; ++voice)
                    voices += future->queueSuccessorVoiceStarts[voice].armPreparation.programGeneration == original->Handle();
                if (voices != 1) return false;
                for (std::size_t child = 0; child < count; ++child) {
                    const auto* candidate = tree.PreparedInstanceCensusToken(child);
                    if (candidate == nullptr || candidate->Parent() == original->Handle()) return false;
                }
            }
        }
        if (rootCount != 1 || sounds != future->queueSuccessorVoiceStartCount) return false;
        total += count;
    }
    if (static_cast<std::size_t>(std::count_if(pendingVariableFutureNodes.begin(), pendingVariableFutureNodes.end(),
            [](const auto& node) { return node.Empty(); })) < total) return false;
    // All capacity, factory identities and closed parent paths have passed before saving records.
    for (std::uint32_t index = 0; index < scratch.queueFutureAttemptCount; ++index) {
        const auto token = scratch.storage.queueFutureAttempts[index];
        const auto& future = *FindFrontierAttempt(*this, token);
        if (future.row->QueueFiling().queueSameProgramKey) continue;
        const auto& tree = future.playableTreeExecutor;
        for (std::size_t node = 0; node < tree.PreparedInstanceCensusCount(); ++node) {
            const auto& original = *tree.PreparedInstanceCensusToken(node);
            const auto* baseline = ResolveOriginalPlayableBaseline(this, playableInstances, original.Handle());
            PlayableKind kind{};
            const bool captured = playableInstances.CaptureOriginalPreparedNodeKind(original, *baseline, &kind);
            assert(captured);
            (void)captured;
            auto found = std::find_if(pendingVariableFutureNodes.begin(), pendingVariableFutureNodes.end(),
                [](const auto& entry) { return entry.Empty(); });
            assert(found != pendingVariableFutureNodes.end());
            *found = {&group, future.continuationService, future.continuationPartition,
                future.queueFuturePreparedQueue->Token(), token, original.Handle(), original.Parent(),
                future.variableControlNestedQueueSuccessor.Handle(), original.ScheduleEpoch(), kind,
                group.futureNodeCount++, false};
        }
    }
    group.topology_.sealed = true;
    return true;
}

bool Engine::MatchesPendingVariableGroupFutureNodes(const OriginalPendingVariableGroupHolder& group,
    bool retiredSources) const noexcept {
    if (group.engine != this || group.futureNodeCount > pendingVariableFutureNodes.size()) return false;
    std::uint32_t count = 0;
    for (const auto& node : pendingVariableFutureNodes) {
        if (node.group != &group) continue;
        if (++count > group.futureNodeCount || node.ordinal >= group.futureNodeCount ||
            !node.service.Valid() || !node.partition.Valid() || !node.queue.Valid() || !node.preparation.Valid() ||
            node.handle == 0 || node.parent == 0 || node.futureRoot == 0 || node.epoch == 0) return false;
        for (const auto& other : pendingVariableFutureNodes)
            if (&other != &node && other.group == &group &&
                (other.ordinal == node.ordinal || other.handle == node.handle)) return false;
        auto cursor = node.handle;
        bool reached = false;
        for (std::uint32_t depth = 0; depth < group.futureNodeCount; ++depth) {
            const OriginalPendingVariableFutureNode* actual = nullptr;
            for (const auto& candidate : pendingVariableFutureNodes)
                if (candidate.group == &group && candidate.handle == cursor &&
                    candidate.preparation.slot == node.preparation.slot &&
                    candidate.preparation.generation == node.preparation.generation &&
                    SameSelectionServiceReference(candidate.service, node.service) && candidate.futureRoot == node.futureRoot)
                    actual = &candidate;
            if (actual == nullptr) return false;
            if (actual->handle == node.futureRoot) {
                reached = actual->parent == node.service.owner;
                break;
            }
            cursor = actual->parent;
        }
        if (!reached) return false;
        if (node.disposed) {
            if (!retiredSources) return false;
            continue;
        }
        const auto* service = const_cast<Engine*>(this)->ResolvePlayableService(node.service);
        if (service == nullptr || service->partition.slot != node.partition.slot ||
            service->partition.generation != node.partition.generation ||
            service->queueInstance.slot != node.queue.slot || service->queueInstance.generation != node.queue.generation)
            return false;
        const auto* baseline = ResolveOriginalPlayableBaseline(const_cast<Engine*>(this),
            const_cast<PlayableInstanceTable&>(playableInstances), node.handle);
        if (baseline == nullptr || !playableInstances.IsOriginalLifetimeCurrent(*baseline) ||
            baseline->OriginalParent() != node.parent || baseline->OriginalScheduleEpoch() != node.epoch) return false;
        const auto actual = playableInstances.Classify(node.handle);
        if (!actual.live) continue;
        if (actual.parent != node.parent || actual.scheduleEpoch != node.epoch || actual.kind != node.kind) return false;
        std::uint32_t children = 0;
        for (auto child = actual.firstChild; child != 0; child = playableInstances.NextSibling(child)) {
            if (++children > group.futureNodeCount || std::count_if(pendingVariableFutureNodes.begin(),
                    pendingVariableFutureNodes.end(), [&](const auto& candidate) {
                        return candidate.group == &group && candidate.parent == node.handle && candidate.handle == child;
                    }) != 1) return false;
        }
        const auto expected = std::count_if(pendingVariableFutureNodes.begin(), pendingVariableFutureNodes.end(),
            [&](const auto& candidate) { return candidate.group == &group && candidate.parent == node.handle &&
                playableInstances.Classify(candidate.handle).live; });
        if (children != expected || (node.kind == PlayableKind::Sound && children != 0)) return false;
    }
    return count == group.futureNodeCount;
}

bool Engine::MatchesPendingVariableGroupTopology(const OriginalPendingVariableGroupHolder& group,
    const EnginePlayableServiceRow& row, bool retiredSources) noexcept {
    const auto& topology = group.topology_;
    if (group.engine != this || !topology.sealed || topology.topCount != row.variableControlChildCount ||
        topology.leafCount != group.leafCount || topology.leafCount != row.scheduleLeafCount ||
        topology.structuralCount != row.variableControlNestedChildCount ||
        !MatchesPendingVariableGroupFutureNodes(group, retiredSources)) return false;
    if (retiredSources && group.leafRetirement != OriginalPendingVariableGroupHolder::LeafRetirement::Settled) return false;
    for (std::uint32_t index = 0; index < topology.structuralCount; ++index) {
        const auto& node = topology.nodes[index];
        if (node.handle != row.variableControlChildInstances[index] || node.epoch != row.variableControlChildEpochs[index] ||
            node.kind != row.variableControlChildKinds[index]) return false;
    }
    for (std::uint32_t leaf = 0; leaf < topology.leafCount; ++leaf) {
        const auto& node = topology.nodes[topology.leafNodes[leaf]];
        if (node.handle != row.variableControlLeafInstances[leaf] || node.epoch != row.variableControlLeafEpochs[leaf]) return false;
        if (retiredSources && !originalSourceSubmissions.PendingInstalledSourceRetirementSettled(
                group.leafRetirementReceipts[leaf], group.leafArms[leaf])) return false;
    }
    for (std::uint32_t top = 0; top < topology.topCount; ++top) {
        const auto& node = topology.nodes[topology.topNodes[top]];
        if (node.handle != row.variableControlChildInstances[top] || node.epoch != row.variableControlChildEpochs[top] ||
            node.kind != row.variableControlChildKinds[top]) return false;
    }
    for (std::uint32_t index = 0; index < topology.nodeCount; ++index) {
        const auto& node = topology.nodes[index];
        const auto actual = playableInstances.Classify(node.handle);
        if (!actual.live) {
            if (!retiredSources || !node.nativeDisposition) return false;
            continue;
        }
        if (actual.parent != node.parent || actual.scheduleEpoch != node.epoch || actual.kind != node.kind ||
            (!node.nativeDisposition && (!playableInstances.IsOriginalLifetimePinFor(node.loan, node.handle) ||
                !playableInstances.IsOriginalLifetimeCurrent(node.loan)))) return false;
        std::uint32_t children = 0;
        for (auto child = actual.firstChild; child != 0; child = playableInstances.NextSibling(child)) {
            if (++children > topology.nodeCount + group.futureNodeCount || std::count_if(topology.nodes.begin(),
                    topology.nodes.begin() + topology.nodeCount, [&](const auto& sealed) {
                        return sealed.handle == child && sealed.parent == node.handle;
                    }) + std::count_if(pendingVariableFutureNodes.begin(), pendingVariableFutureNodes.end(),
                        [&](const auto& sealed) { return sealed.group == &group && sealed.handle == child &&
                            sealed.parent == node.handle; }) != 1) return false;
        }
        const auto expected = std::count_if(topology.nodes.begin(), topology.nodes.begin() + topology.nodeCount,
            [&](const auto& sealed) { return sealed.parent == node.handle && playableInstances.Classify(sealed.handle).live; }) +
            std::count_if(pendingVariableFutureNodes.begin(), pendingVariableFutureNodes.end(), [&](const auto& sealed) {
                return sealed.group == &group && sealed.parent == node.handle && playableInstances.Classify(sealed.handle).live;
            });
        if (children != expected || (node.kind == PlayableKind::Sound && children != 0)) return false;
    }
    const auto root = playableInstances.Classify(row.ownerInstance);
    if (!root.live || root.scheduleEpoch != row.ownerEpoch) return false;
    std::uint32_t children = 0;
    for (auto child = root.firstChild; child != 0; child = playableInstances.NextSibling(child)) {
        if (++children > topology.topCount || std::count_if(topology.topNodes.begin(),
                topology.topNodes.begin() + topology.topCount, [&](auto index) {
                    return topology.nodes[index].handle == child;
                }) != 1) return false;
    }
    return children == std::count_if(topology.topNodes.begin(), topology.topNodes.begin() + topology.topCount,
        [&](auto index) { return playableInstances.Classify(topology.nodes[index].handle).live; });
}

bool Engine::CapturePendingVariableGroupRetiredMemberStorage(OriginalPendingVariableGroupHolder& group,
    EnginePlayableServiceRow& row) noexcept {
    if (group.engine != this || group.reprepare_.engine != nullptr || group.leafCount != row.scheduleLeafCount ||
        group.leafCount > group.reprepare_.members.size() || !MatchesPendingVariableGroupTopology(group, row,
            group.leafRetirement == OriginalPendingVariableGroupHolder::LeafRetirement::Settled) ||
        row.variableControlChildCount > kMaxKnownScheduleLeaves ||
        row.variableControlChildCount > group.reprepare_.children.size()) return false;
    group.reprepare_.membersCaptured = false;
    std::array<OriginalPendingVariableGroupHolder::InitialReprepare::MemberStorage,
        kMaxKnownScheduleLeaves> members{};
    for (std::uint32_t index = 0; index < group.leafCount; ++index) {
        auto& member = members[index];
        EnginePlayableServiceRow* owner = nullptr;
        std::size_t resolvedSlot = 0;
        if (!ResolveImmediateInitialMemberSlots(*this, row, index, &member.logicalSlot, &member.physicalSlot) ||
            !CapturePlayableMemberReference(row, member.logicalSlot, &member.reference) ||
            !ResolvePlayableMember(member.reference, &owner, &resolvedSlot) ||
            !IsPlayableServiceDescendant(*this, *owner, row) ||
            resolvedSlot != member.physicalSlot || member.reference.leaf != row.variableControlLeafInstances[index] ||
            member.reference.leafEpoch != row.variableControlLeafEpochs[index] ||
            member.reference.memberOffset >= playableStorage.currentEventStride ||
            member.reference.memberOffset >= playableStorage.initialProgramStride) return false;
        const auto slot = member.physicalSlot;
        member.arm = ReadPlayableMember(slot).arm;
        member.render = ReadPlayableMember(slot).render;
        member.release = ReadPlayableMember(slot).release;
        member.source = ReadPlayableMember(slot).completion.source;
        const auto* record = ResolveMemberProgram(member.reference);
        if (record == nullptr) return false;
        member.program = owner->memberPrograms[member.reference.memberOffset];
        const auto& schedule = record->schedule;
        if (!SameOriginalSingleArm(member.arm, group.leafArms[index]) || member.render == 0 ||
            !member.release.Valid() || schedule.ownerInstance != member.reference.leaf ||
            schedule.ownerInstanceScheduleEpoch != member.reference.leafEpoch ||
            schedule.runtimeProgram.program != &record->runtime)
            return false;
        if (group.leafRetirement == OriginalPendingVariableGroupHolder::LeafRetirement::None) {
            const auto* source = sourceTerminals.Resolve(member.source);
            if (source == nullptr || source->leaf != member.reference.leaf ||
                source->acceptedEpoch != member.reference.leafEpoch || source->render != member.render ||
                source->release.slot != member.release.slot ||
                source->release.targetSequence != member.release.targetSequence || source->controller != owner->rootInstance ||
                ResolveSourceResourceOwner(source->resourceOwner) != owner ||
                ReadPlayableMember(slot).completion.resourcesRetired) return false;
        }
        for (std::uint32_t prior = 0; prior < index; ++prior)
            if (members[prior].logicalSlot == member.logicalSlot || members[prior].physicalSlot == slot) return false;
    }
    std::copy_n(members.begin(), group.leafCount, group.reprepare_.members.begin());
    group.reprepare_.childCount = row.variableControlChildCount;
    std::copy_n(row.variableControlChildInstances.begin(), row.variableControlChildCount,
        group.reprepare_.children.begin());
    std::copy_n(row.variableControlChildEpochs.begin(), row.variableControlChildCount,
        group.reprepare_.childEpochs.begin());
    group.reprepare_.membersCaptured = true;
    return true;
}

bool Engine::MatchesPendingVariableGroupRetiredMemberStorage(const OriginalPendingVariableGroupHolder& group,
    EnginePlayableServiceRow& row, std::uint32_t index) noexcept {
    const auto& issued = group.reprepare_;
    if (!issued.membersCaptured || index >= group.leafCount || !group.topology_.sealed ||
        issued.engine != this || issued.cut != group.cut || !variables.CanReleaseReadCut(group.cut)) return false;
    const auto& original = issued.members[index];
    EnginePlayableServiceRow* owner = nullptr;
    std::size_t slot = 0;
    if (!original.source.Valid() || original.logicalSlot >= playableStorage.memberCount ||
        original.reference.memberOffset >= playableStorage.currentEventStride ||
        original.reference.memberOffset >= playableStorage.initialProgramStride ||
        !ResolvePlayableMember(original.reference, &owner, &slot) ||
        !IsPlayableServiceDescendant(*this, *owner, row) || slot != original.physicalSlot)
        return false;
    const auto& reference = ReadPlayableMemberReference(original.logicalSlot);
    const auto& member = ReadPlayableMember(slot).completion;
    const auto offset = original.reference.memberOffset;
    const auto* record = ResolveMemberProgram(original.reference);
    if (record == nullptr || owner->memberPrograms[offset] != original.program) return false;
    const auto& runtime = record->runtime;
    const auto& schedule = record->schedule;
    return reference.service.token == original.reference.service.token &&
        reference.service.owner == original.reference.service.owner && reference.service.epoch == original.reference.service.epoch &&
        reference.service.invocationGeneration == original.reference.service.invocationGeneration &&
        reference.partitionGeneration == original.reference.partitionGeneration && reference.memberOffset == offset &&
        reference.leaf == original.reference.leaf && reference.leafEpoch == original.reference.leafEpoch &&
        reference.authoredChildOrdinal == original.reference.authoredChildOrdinal &&
        group.topology_.leafTops[index] < issued.childCount &&
        issued.children[group.topology_.leafTops[index]] ==
            group.topology_.nodes[group.topology_.topNodes[group.topology_.leafTops[index]]].handle &&
        issued.childEpochs[group.topology_.leafTops[index]] ==
            group.topology_.nodes[group.topology_.topNodes[group.topology_.leafTops[index]]].epoch &&
        group.topology_.nodes[group.topology_.leafNodes[index]].handle == original.reference.leaf &&
        group.topology_.nodes[group.topology_.leafNodes[index]].epoch == original.reference.leafEpoch &&
        SameOriginalSingleArm(ReadPlayableMember(slot).arm, original.arm) &&
        SameOriginalSingleArm(original.arm, group.leafArms[index]) &&
        ReadPlayableMember(slot).render == original.render &&
        ReadPlayableMember(slot).release.slot == original.release.slot &&
        ReadPlayableMember(slot).release.targetSequence == original.release.targetSequence &&
        schedule.ownerInstance == original.reference.leaf && schedule.ownerInstanceScheduleEpoch == original.reference.leafEpoch &&
        schedule.runtimeProgram.program == &runtime && schedule.runtimeProgram.programGeneration == runtime.generation &&
        runtime.generation == original.reference.leaf && runtime.payloadCount == 1 &&
        runtime.payloads == record->payloads.data() &&
        schedule.events == record->events.data() && schedule.eventCount == 1 &&
        SameOriginalSingleArm(schedule.armToken, original.arm) &&
        !member.source.Valid() && member.resourcesRetired && member.completedSource.kind != SourceTerminalKind::None &&
        member.completedSource.kind != SourceTerminalKind::ProducerFailure &&
        member.completedSource.kind != SourceTerminalKind::IntegrityAbort &&
        member.sourceRender == original.render && SameOriginalSingleArm(member.sourceStartArm, original.arm) &&
        member.sourceStartedBlockSequence == 0 && member.sourceReleaseSequence != 0 &&
        mixer.BlocksRendered() > member.sourceReleaseSequence && sourceTerminals.Resolve(original.source) == nullptr &&
        voices.ReleaseObserved(original.release);
}

static bool PendingVariableReplacementEmptyCensus(const EngineActionPlayScratch& child) noexcept {
    return child.voiceStartCount == 0 && child.frontierCurrentVoiceOwnerCount == 0 &&
        child.variableControlChildCount == 0 && child.variableControlLeafChildCount == 0 &&
        child.pendingVariableReplacementTopCount == 0 && child.pendingVariableReplacementLeafCount == 0 &&
        child.pendingVariableReplacementCommandCount == 0 && child.instance.Handle() == 0 &&
        child.playableTreeExecutor.InstanceReservationCount() == 0 &&
        child.playableTreeExecutor.ContainerReservationCount() == 0 &&
        child.playableTreeExecutor.OwnerTokenCount() == 0 && !child.playableTreeExecutor.ParentLinkProofHeld() &&
        child.storage.ownerLedger.Empty();
}

bool Engine::CapturePendingVariableReplacementTopology(EngineActionPlayScratch& child,
    std::span<const PendingVariableGroupChild> leaves) noexcept {
    auto& topology = child.pendingVariableReplacementTopology;
    if (topology.sealed || topology.nodeCount != 0 || child.row == nullptr ||
        child.variableControlChildCount < child.pendingVariableReplacementTopCount ||
        child.variableControlChildCount > kMaxKnownScheduleLeaves || leaves.size() != child.voiceStartCount ||
        leaves.size() > topology.leafNodes.size()) return false;
    if (child.variableControlChildCount == 0) {
        if (!PendingVariableReplacementEmptyCensus(child)) return false;
        topology.sealed = true;
        return true;
    }
    const auto* links = child.playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
    if (links == nullptr) return false;
    std::array<PlayableInstanceTable::PreparedNodeCensusEntry, 2u * kMaxKnownScheduleLeaves> census{};
    const auto append = [&](const PreparedPlayableInstance& original, PlayableKind kind) noexcept {
        if (!original.Valid() || topology.nodeCount == topology.nodes.size()) return false;
        for (std::uint32_t index = 0; index < topology.nodeCount; ++index)
            if (topology.nodes[index].handle == original.Handle()) return false;
        auto& node = topology.nodes[topology.nodeCount];
        node.handle = original.Handle();
        node.parent = original.Parent();
        node.epoch = original.ScheduleEpoch();
        node.kind = kind;
        census[topology.nodeCount++] = {&original, kind};
        return true;
    };
    for (std::uint32_t top = 0; top < child.variableControlChildCount; ++top) {
        if (!append(child.variableControlChildren[top], child.variableControlChildKinds[top]) ||
            (top < child.pendingVariableReplacementTopCount &&
             topology.nodes[top].parent != child.row->ownerInstance)) return false;
    }
    for (std::uint32_t leaf = 0; leaf < child.variableControlLeafChildCount; ++leaf)
        if (!append(child.variableControlLeafChildren[leaf], PlayableKind::Sound)) return false;
    if (!playableInstances.MatchesPreparedOriginalNodeCensus(*links, {census.data(), topology.nodeCount}) ||
        !IssueOriginalPlayableLifetimes(*links)) return false;
    for (std::uint32_t index = 0; index < leaves.size(); ++index) {
        const auto top = leaves[index].topIndex == UINT32_MAX ? index : leaves[index].topIndex;
        if (top >= child.pendingVariableReplacementTopCount) return false;
        std::uint32_t found = UINT32_MAX;
        for (std::uint32_t node = 0; node < topology.nodeCount; ++node)
            if (topology.nodes[node].handle == child.variableControlLeafHandles[index]) found = node;
        if (found == UINT32_MAX || topology.nodes[found].kind != PlayableKind::Sound ||
            topology.nodes[found].epoch != child.variableControlLeafEpochs[index] ||
            !playableInstances.MatchesPreparedOriginalAncestry(*links,
                topology.nodes[found].handle, topology.nodes[top].handle)) return false;
        for (std::uint32_t prior = 0; prior < index; ++prior)
            if (topology.leafNodes[prior] == found) return false;
        topology.leafNodes[index] = found;
        topology.leafTops[index] = top;
    }
    for (std::uint32_t node = 0; node < topology.nodeCount; ++node) {
        auto& original = topology.nodes[node];
        if (!playableInstances.MatchesPreparedOriginalAncestry(*links, original.handle, child.row->ownerInstance))
            return false;
        if (original.kind == PlayableKind::Sound && std::count(topology.leafNodes.begin(),
                topology.leafNodes.begin() + leaves.size(), node) != 1) return false;
        auto* baseline = ResolveOriginalPlayableBaseline(this, playableInstances, original.handle);
        if (baseline == nullptr || !baseline->Borrow(&original.original) ||
            original.original.OriginalParent() != original.parent ||
            original.original.OriginalScheduleEpoch() != original.epoch) return false;
    }
    topology.sealed = true;
    return true;
}

bool Engine::MatchesPendingVariableReplacementLeafOrigin(const EngineActionPlayScratch& child,
    std::uint32_t index) noexcept {
    const auto& topology = child.pendingVariableReplacementTopology;
    if (!topology.sealed || index >= child.voiceStartCount || index >= topology.leafNodes.size() ||
        topology.leafNodes[index] >= topology.nodeCount || topology.leafTops[index] >= child.variableControlChildCount)
        return false;
    const auto& leaf = topology.nodes[topology.leafNodes[index]];
    const auto& top = topology.nodes[topology.leafTops[index]];
    bool belongsToTop = leaf.handle == top.handle;
    auto parent = leaf.parent;
    for (std::uint32_t depth = 0; !belongsToTop && parent != 0 && depth < topology.nodeCount; ++depth) {
        belongsToTop = parent == top.handle;
        if (belongsToTop) break;
        const auto found = std::find_if(topology.nodes.begin(), topology.nodes.begin() + topology.nodeCount,
            [parent](const auto& node) { return node.handle == parent; });
        if (found == topology.nodes.begin() + topology.nodeCount) break;
        parent = found->parent;
    }
    return leaf.kind == PlayableKind::Sound && leaf.handle == child.variableControlLeafHandles[index] &&
        leaf.epoch == child.variableControlLeafEpochs[index] &&
        belongsToTop && (leaf.handle != top.handle || top.kind == PlayableKind::Sound) &&
        playableInstances.IsOriginalLifetimePinFor(leaf.original, leaf.handle) &&
        playableInstances.IsOriginalLifetimeCurrent(leaf.original) &&
        leaf.original.OriginalParent() == leaf.parent && leaf.original.OriginalScheduleEpoch() == leaf.epoch &&
        playableInstances.IsOriginalLifetimePinFor(top.original, top.handle) &&
        playableInstances.IsOriginalLifetimeCurrent(top.original);
}

bool Engine::CapturePendingVariableReplacementFutureTopology(EngineActionPlayScratch& child) noexcept {
    const auto& current = child.pendingVariableReplacementTopology;
    const auto* links = child.playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
    if (!current.sealed || child.row == nullptr || child.queueFutureAttemptCount > child.storage.queueFutureAttempts.size() ||
        child.queueFutureAttemptCount > child.storage.queueFutureOwners.size() ||
        (child.queueFutureAttemptCount != 0 && links == nullptr)) return false;
    for (std::uint32_t index = 0; index < child.queueFutureAttemptCount; ++index) {
        const auto token = child.storage.queueFutureAttempts[index];
        const auto& owner = child.storage.queueFutureOwners[index];
        auto* future = FindFrontierAttempt(*this, token);
        if (future == nullptr || future->row == nullptr || !future->queueFutureExecution || !future->prepared ||
            !future->frontierOwnerLedgerComplete || future->storage.phase != EngineFrontierAttemptPhase::Preparing ||
            owner.engine != this || owner.committed || owner.rootLinkDeferred ||
            FindFrontierAttempt(*this, owner.parent) != &child || owner.parent.generation != child.storage.generation ||
            owner.child.slot != token.slot || owner.child.generation != token.generation ||
            future->queueFutureParent.slot != owner.parent.slot || future->queueFutureParent.generation != owner.parent.generation ||
            ResolvePlayableService(future->continuationService) != future->row ||
            future->continuationPartition.slot != future->row->partition.slot ||
            future->continuationPartition.generation != future->row->partition.generation ||
            future->row->invocation != child.row->invocation ||
            future->row->invocationGeneration != child.row->invocationGeneration) return false;
        auto& topology = future->pendingVariableReplacementTopology;
        if (topology.sealed || topology.nodeCount != 0 ||
            std::count_if(current.nodes.begin(), current.nodes.begin() + current.nodeCount, [&](const auto& node) {
                return node.handle == future->row->ownerInstance && node.epoch == future->row->ownerEpoch &&
                    node.kind == PlayableKind::Container;
            }) != 1) return false;
        topology.futureParent = owner.parent;
        topology.futurePreparation = token;
        topology.futureService = future->continuationService;
        topology.futurePartition = future->continuationPartition;
        topology.futureQueue = future->row->queueInstance;
        topology.futureRoot = future->variableControlNestedQueueSuccessor.Handle();
        if (future->row->QueueFiling().queueSameProgramKey) {
            if (topology.futureRoot != 0 || future->queueSuccessorVoiceStartCount != 0) return false;
            topology.sealed = true;
            continue;
        }
        const auto& tree = future->playableTreeExecutor;
        const auto count = tree.PreparedInstanceCensusCount();
        if (count == 0 || count > topology.nodes.size() || !tree.InstanceCommitProofsHeld() || !tree.Validate() ||
            owner.originalParentLinks != links || !future->variableControlNestedQueueSuccessor.Valid() ||
            future->variableControlNestedQueueSuccessor.Parent() != future->row->ownerInstance ||
            future->queueSuccessorVoiceStartCount > future->queueSuccessorVoiceStarts.size()) return false;
        std::uint32_t roots = 0, sounds = 0;
        for (std::size_t node = 0; node < count; ++node) {
            const auto* original = tree.PreparedInstanceCensusToken(node);
            auto* baseline = original == nullptr ? nullptr :
                ResolveOriginalPlayableBaseline(this, playableInstances, original->Handle());
            PlayableKind kind{};
            if (baseline == nullptr || !playableInstances.CaptureOriginalPreparedNodeKind(*original, *baseline, &kind) ||
                std::any_of(current.nodes.begin(), current.nodes.begin() + current.nodeCount,
                    [&](const auto& other) { return other.handle == original->Handle(); })) return false;
            for (std::uint32_t priorFuture = 0; priorFuture <= index; ++priorFuture) {
                const auto* prior = FindFrontierAttempt(*this, child.storage.queueFutureAttempts[priorFuture]);
                if (prior == nullptr) return false;
                const auto& priorTopology = prior->pendingVariableReplacementTopology;
                if (std::any_of(priorTopology.nodes.begin(), priorTopology.nodes.begin() + priorTopology.nodeCount,
                        [&](const auto& other) { return other.handle == original->Handle(); })) return false;
            }
            auto cursor = original->Handle();
            bool reached = false;
            for (std::size_t depth = 0; depth < count; ++depth) {
                const PreparedPlayableInstance* entry = nullptr;
                for (std::size_t candidate = 0; candidate < count; ++candidate) {
                    const auto* actual = tree.PreparedInstanceCensusToken(candidate);
                    if (actual != nullptr && actual->Handle() == cursor) entry = actual;
                }
                if (entry == nullptr) return false;
                if (entry->Handle() == topology.futureRoot) {
                    reached = entry->Parent() == future->row->ownerInstance;
                    break;
                }
                cursor = entry->Parent();
            }
            if (!reached) return false;
            roots += original->Handle() == topology.futureRoot;
            if (kind == PlayableKind::Sound) {
                ++sounds;
                std::uint32_t voices = 0;
                for (std::uint32_t voice = 0; voice < future->queueSuccessorVoiceStartCount; ++voice)
                    voices += future->queueSuccessorVoiceStarts[voice].armPreparation.programGeneration == original->Handle();
                if (voices != 1) return false;
                for (std::size_t descendant = 0; descendant < count; ++descendant) {
                    const auto* actual = tree.PreparedInstanceCensusToken(descendant);
                    if (actual == nullptr || actual->Parent() == original->Handle()) return false;
                }
            }
            auto& saved = topology.nodes[topology.nodeCount++];
            saved.handle = original->Handle();
            saved.parent = original->Parent();
            saved.epoch = original->ScheduleEpoch();
            saved.kind = kind;
            if (!baseline->Borrow(&saved.original) || saved.original.OriginalParent() != saved.parent ||
                saved.original.OriginalScheduleEpoch() != saved.epoch) return false;
        }
        if (roots != 1 || sounds != future->queueSuccessorVoiceStartCount) return false;
        topology.sealed = true;
    }
    return true;
}

bool Engine::MatchesPendingVariableReplacementFutureTopology(const EngineActionPlayScratch& child,
    bool committed) noexcept {
    if (child.row == nullptr || child.queueFutureAttemptCount > child.storage.queueFutureAttempts.size() ||
        child.queueFutureAttemptCount > child.storage.queueFutureOwners.size()) return false;
    for (std::uint32_t index = 0; index < child.queueFutureAttemptCount; ++index) {
        const auto token = child.storage.queueFutureAttempts[index];
        const auto& owner = child.storage.queueFutureOwners[index];
        const auto* future = FindFrontierAttempt(*this, token);
        if (future == nullptr || future->row == nullptr || !future->queueFutureExecution ||
            owner.engine != this || owner.committed != committed || owner.rootLinkDeferred ||
            FindFrontierAttempt(*this, owner.parent) != &child || owner.parent.generation != child.storage.generation ||
            owner.child.slot != token.slot || owner.child.generation != token.generation ||
            future->queueFutureParent.slot != owner.parent.slot || future->queueFutureParent.generation != owner.parent.generation ||
            ResolvePlayableService(future->continuationService) != future->row ||
            future->row->invocation != child.row->invocation ||
            future->row->invocationGeneration != child.row->invocationGeneration) return false;
        const auto& saved = future->pendingVariableReplacementTopology;
        const auto& tree = future->playableTreeExecutor;
        if (!saved.sealed || saved.nodeCount > saved.nodes.size() ||
            saved.futureParent.slot != owner.parent.slot || saved.futureParent.generation != owner.parent.generation ||
            saved.futurePreparation.slot != token.slot || saved.futurePreparation.generation != token.generation ||
            !SameSelectionServiceReference(saved.futureService, future->continuationService) ||
            saved.futurePartition.slot != future->continuationPartition.slot ||
            saved.futurePartition.generation != future->continuationPartition.generation ||
            saved.futurePartition.slot != future->row->partition.slot || saved.futurePartition.generation != future->row->partition.generation ||
            saved.futureQueue.slot != future->row->queueInstance.slot || saved.futureQueue.generation != future->row->queueInstance.generation ||
            saved.futureRoot != future->variableControlNestedQueueSuccessor.Handle()) return false;
        if (future->row->QueueFiling().queueSameProgramKey) {
            if (saved.nodeCount != 0 || saved.futureRoot != 0 || future->queueSuccessorVoiceStartCount != 0) return false;
            continue;
        }
        const auto* links = child.playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
        if (saved.nodeCount == 0 || tree.PreparedInstanceCensusCount() != saved.nodeCount ||
            (committed ? !tree.Committed() || future->storage.phase != EngineFrontierAttemptPhase::PrivateCommitted ||
                owner.originalParentLinks != nullptr : !tree.InstanceCommitProofsHeld() || !tree.Validate() ||
                future->storage.phase != EngineFrontierAttemptPhase::Preparing || links == nullptr || owner.originalParentLinks != links))
            return false;
        for (std::uint32_t node = 0; node < saved.nodeCount; ++node) {
            const auto& record = saved.nodes[node];
            const auto* original = tree.PreparedInstanceCensusToken(node);
            if (original == nullptr || original->Handle() != record.handle || original->Parent() != record.parent ||
                original->ScheduleEpoch() != record.epoch || !playableInstances.IsOriginalLifetimePinFor(record.original, record.handle) ||
                !playableInstances.IsOriginalLifetimeCurrent(record.original) || record.original.OriginalParent() != record.parent ||
                record.original.OriginalScheduleEpoch() != record.epoch) return false;
        }
    }
    return true;
}

bool Engine::MatchesPendingVariableReplacementTopology(const EngineActionPlayScratch& child,
    bool committed) noexcept {
    const auto& topology = child.pendingVariableReplacementTopology;
    if (!topology.sealed || child.row == nullptr ||
        child.variableControlChildCount < child.pendingVariableReplacementTopCount ||
        child.variableControlChildCount > kMaxKnownScheduleLeaves ||
        child.variableControlLeafChildCount > child.variableControlLeafChildren.size() ||
        topology.nodeCount != child.variableControlChildCount + child.variableControlLeafChildCount ||
        topology.nodeCount > topology.nodes.size() || !MatchesPendingVariableReplacementFutureTopology(child, committed)) return false;
    if (topology.nodeCount == 0) return PendingVariableReplacementEmptyCensus(child);
    const auto visitNodes = [&](auto&& visitor) noexcept {
        for (std::uint32_t index = 0; index < topology.nodeCount; ++index)
            if (!visitor(topology.nodes[index])) return false;
        for (std::uint32_t index = 0; index < child.queueFutureAttemptCount; ++index) {
            const auto& saved = FindFrontierAttempt(*this, child.storage.queueFutureAttempts[index])->pendingVariableReplacementTopology;
            for (std::uint32_t node = 0; node < saved.nodeCount; ++node)
                if (!visitor(saved.nodes[node])) return false;
        }
        return true;
    };
    std::uint32_t allCount = 0;
    visitNodes([&](const auto&) noexcept { ++allCount; return true; });
    const auto matchesCommittedNode = [&](const auto& node) noexcept {
        const auto actual = playableInstances.Classify(node.handle);
        if (!actual.live || actual.kind != node.kind || actual.parent != node.parent || actual.scheduleEpoch != node.epoch)
            return false;
        std::uint32_t children = 0, expected = 0;
        visitNodes([&](const auto& candidate) noexcept { expected += candidate.parent == node.handle; return true; });
        for (auto descendant = actual.firstChild; descendant != 0; descendant = playableInstances.NextSibling(descendant)) {
            std::uint32_t matches = 0;
            visitNodes([&](const auto& candidate) noexcept {
                matches += candidate.handle == descendant && candidate.parent == node.handle;
                return true;
            });
            if (++children > allCount || matches != 1) return false;
        }
        return children == expected && (node.kind != PlayableKind::Sound || children == 0);
    };
    std::array<PlayableInstanceTable::PreparedNodeCensusEntry, 2u * kMaxKnownScheduleLeaves> census{};
    for (std::uint32_t index = 0; index < topology.nodeCount; ++index) {
        const auto& node = topology.nodes[index];
        if (!playableInstances.IsOriginalLifetimePinFor(node.original, node.handle) ||
            !playableInstances.IsOriginalLifetimeCurrent(node.original) ||
            node.original.OriginalParent() != node.parent || node.original.OriginalScheduleEpoch() != node.epoch)
            return false;
        if (index < child.variableControlChildCount) {
            if ((index < child.pendingVariableReplacementTopCount && node.parent != child.row->ownerInstance) ||
                node.kind != child.variableControlChildKinds[index] ||
                node.handle != child.variableControlChildren[index].Handle() ||
                node.epoch != child.variableControlChildren[index].ScheduleEpoch()) return false;
            census[index] = {&child.variableControlChildren[index], node.kind};
        } else census[index] = {&child.variableControlLeafChildren[index - child.variableControlChildCount], PlayableKind::Sound};
        if (committed && !matchesCommittedNode(node)) return false;
    }
    for (std::uint32_t index = 0; index < child.voiceStartCount; ++index)
        if (!MatchesPendingVariableReplacementLeafOrigin(child, index)) return false;
    if (!committed) {
        const auto* links = child.playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
        return links != nullptr && playableInstances.MatchesPreparedOriginalNodeCensus(*links,
            {census.data(), topology.nodeCount});
    }
    if (!visitNodes(matchesCommittedNode)) return false;
    const auto root = playableInstances.Classify(child.row->ownerInstance);
    if (!root.live || root.scheduleEpoch != child.row->ownerEpoch) return false;
    std::uint32_t roots = 0;
    for (auto top = root.firstChild; top != 0; top = playableInstances.NextSibling(top))
        if (++roots > child.pendingVariableReplacementTopCount || std::count_if(topology.nodes.begin(),
                topology.nodes.begin() + child.pendingVariableReplacementTopCount,
                [&](const auto& original) { return original.handle == top; }) != 1) return false;
    return roots == child.pendingVariableReplacementTopCount;
}

EngineActionPlayScratch* Engine::PreparePendingVariableGroupFactory(EngineActionPlayScratch& producer,
    const EngineImmediateEntryAttempt& attempt, std::uint64_t anchor, bool replaceSelection) noexcept {
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (group == nullptr || !group->ReprepareReady() || anchor == UINT64_MAX) return nullptr;
    if (group->reprepare_.replacementChildren.Valid()) {
        auto* child = FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
        return child != nullptr && !child->prepared && child->row == producer.row &&
            child->storage.phase == EngineFrontierAttemptPhase::PendingVariableChildren &&
            child->pendingVariableReplacementAnchorFrame == anchor &&
            child->pendingVariableReplacementCut == group->cut &&
            MatchesPendingVariableReplacementProducer(*child, producer, attempt) &&
            AdoptPendingVariableQueueRoles(*child) ? child : nullptr;
    }
    EngineFrontierAttemptToken token;
    auto* child = AcquireFrontierAttempt(*this, &token);
    if (child == nullptr) return nullptr;
    group->reprepare_.replacementChildren = token;
    child->storage.phase = EngineFrontierAttemptPhase::PendingVariableChildren;
    child->row = producer.row;
    child->pendingVariableReplacementService = group->reference;
    child->pendingVariableReplacementProducer = {
        actionPlayScratch.IndexOf(producer), producer.storage.generation};
    child->pendingVariableReplacementEntryGeneration = attempt.generation;
    child->pendingVariableReplacementCut = group->cut;
    child->pendingVariableReplacementAnchorFrame = anchor;
    if (!AdoptPendingVariableQueueRoles(*child)) {
        (void)CancelPendingVariableGroupChildren(*group);
        return nullptr;
    }
    child->packLeaseBorrowed = !producer.row->variableControlWorldUsesCurrentAuthority &&
        producer.row->Invocation().packLease.leaseToken != 0;
    child->packLease = producer.row->Invocation().packLease;
    child->packPlaybackView = producer.row->Invocation().packPlaybackView;
    auto& context = child->storage.initialSelection;
    context = producer.storage.initialSelection;
    context.attemptGeneration = child->storage.generation;
    context.executeFrame = anchor;
    context.materializedOrdinals = {};
    if (replaceSelection && !group->initialSelectionBatch.Empty()) {
        if (!producer.storage.initialSelection.BoundFor(producer.storage.generation) ||
            !group->initialSelectionBatch.MatchesOwner(&selectionMemory, context.identity) ||
            group->initialSelectionBatch.BeginReplacement() != SelectionMemoryStatusV1::Ok) {
            (void)CancelPendingVariableGroupChildren(*group);
            return nullptr;
        }
        context.preparation = {EngineSelectionPreparationMode::PendingReplacement, &group->initialSelectionBatch};
    } else context.preparation = {};
    return child;
}

bool Engine::PreparePendingVariableGroupChildren(EngineActionPlayScratch& producer,
    const EngineImmediateEntryAttempt& attempt, std::uint64_t anchor,
    std::span<const PendingVariableGroupChild> leaves) noexcept {
    std::array<PendingVariableGroupTop, kMaxKnownScheduleLeaves> tops{};
    if (leaves.size() > tops.size()) return false;
    for (std::uint32_t index = 0; index < leaves.size(); ++index) {
        tops[index].root = leaves[index].leaf;
        tops[index].authoredChildOrdinal = leaves[index].authoredChildOrdinal;
        tops[index].side = leaves[index].side;
        tops[index].weight = leaves[index].weight;
    }
    return PreparePendingVariableGroupChildren(producer, attempt, anchor, leaves, {tops.data(), leaves.size()});
}

bool Engine::PreparePendingVariableGroupChildren(EngineActionPlayScratch& producer,
    const EngineImmediateEntryAttempt& attempt, std::uint64_t anchor,
    std::span<const PendingVariableGroupChild> leaves, std::span<const PendingVariableGroupTop> tops) noexcept {
    const auto* scope = activePendingVariableGroupReplacement_;
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (!pendingVariableGroupReplacementActive || scope == nullptr || group == nullptr ||
        scope->group_ != group || scope->producer_ != &producer || scope->attempt_ != &attempt ||
        scope->producerGeneration_ != producer.storage.generation || scope->attemptGeneration_ != attempt.generation ||
        scope->cut_ != group->cut || !group->ReprepareReady() ||
        leaves.size() > kMaxKnownScheduleLeaves || tops.size() > kMaxKnownScheduleLeaves ||
        preparedVoiceCommandBatchProof.Valid()) return false;
    for (std::uint32_t side = 0; side < scope->sides_.size(); ++side) {
        if (!scope->sides_[side]) continue;
        if (!(*scope->held_)[side].Valid() || !scope->next_[side].Valid() ||
            !(*scope->proofs_)[side].Valid() ||
            !SameCanonicalDecision((*scope->proofs_)[side].Token(), scope->next_[side]) ||
            (*scope->proofs_)[side].Sequence() != producer.row->ticket) return false;
    }
    std::array<std::uint16_t, 2> members{};
    for (const auto& leaf : leaves) {
        if (leaf.side != VariableControlSide::Discrete && leaf.side != VariableControlSide::Continuous) return false;
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        const auto& proof = (*scope->proofs_)[side];
        if (!scope->sides_[side] || !(*scope->held_)[side].Valid() || !scope->next_[side].Valid() ||
            !proof.Valid() || !SameCanonicalDecision(proof.Token(), scope->next_[side]) ||
            proof.Sequence() != producer.row->ticket || leaf.authoredOffset > INT64_MAX ||
            leaf.authoredOffset > UINT64_MAX - anchor || members[side] == UINT16_MAX) return false;
        ++members[side];
    }
    VariableReadCutReader reader;
    if (!variables.BeginPendingVariableGroupReprepare(*this, producer, attempt, anchor, &reader)) return false;
    auto* child = PreparePendingVariableGroupFactory(producer, attempt, anchor, true);
    if (child == nullptr) return false;
    const auto refuse = [&]() noexcept {
        (void)CancelPendingVariableGroupChildren(*group);
        return false;
    };
    if (tops.size() > child->variableControlChildren.size() ||
        leaves.size() > child->variableControlLeafChildren.size()) return refuse();
    if (!PrepareNativeVoiceSide(*child, false, static_cast<std::uint32_t>(leaves.size()))) return refuse();
    auto& row = *producer.row;
    const VariablePlaybackOrder order{anchor, row.ticket, row.Invocation().actionExecutionOrdinal};
    for (std::uint32_t index = 0; index < tops.size(); ++index) {
        const auto& top = tops[index];
        if (top.side != VariableControlSide::Discrete && top.side != VariableControlSide::Continuous) return refuse();
        const auto side = top.side == VariableControlSide::Discrete ? 0u : 1u;
        if (!scope->sides_[side] || (top.hasLogicalCompletion && top.logicalCompletionOffset > UINT64_MAX - anchor))
            return refuse();
        const auto kind = top.root.kind == PlayableKindV1::Sound ? PlayableKind::Sound
            : top.root.kind == PlayableKindV1::Track ? PlayableKind::Track
            : top.root.kind == PlayableKindV1::Container ? PlayableKind::Container : PlayableKind::Segment;
        if (top.root.kind != PlayableKindV1::Sound && top.root.kind != PlayableKindV1::Track &&
            top.root.kind != PlayableKindV1::Segment && top.root.kind != PlayableKindV1::Container) return refuse();
        child->variableControlChildCount = child->pendingVariableReplacementTopCount = index + 1u;
        child->variableControlChildKinds[index] = kind;
        child->pendingVariableReplacementTops[index] = top;
        child->pendingVariableReplacementTops[index].weight.decision = scope->next_[side];
        auto& instance = child->variableControlChildren[index];
        if (!playableInstances.PrepareAcquire(kind, row.ownerInstance, &instance) ||
            !child->playableTreeExecutor.AdoptPreparedInstanceReservation(&instance)) return refuse();
        ObservePreparedContent(*this, instance, MonitorVariableControlContentFor(*this, row, top.root));
    }
    const auto authority = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
        ? PlayableExecutionAuthority::Pack(row.Invocation().packPlaybackView)
        : PlayableExecutionAuthority::Current(row.variableControlWorldUsesCurrentAuthority
            ? variables.CurrentPlayableWorld() : row.VariableControlWorld());
    for (std::uint32_t policyIndex = 0; policyIndex < child->frontierPolicyCount; ++policyIndex) {
        auto& node = child->storage.frontierPolicies[policyIndex];
        std::uint32_t tokenIndex = UINT32_MAX;
        if (node.parentIndex == UINT32_MAX) {
            for (std::uint32_t top = 0; top < tops.size(); ++top)
                if (tops[top].frontierPolicyIndex == policyIndex) { tokenIndex = top; break; }
            node.parent = row.ownerInstance;
            node.parentEpoch = row.ownerEpoch;
        } else {
            if (node.parentIndex >= policyIndex) return refuse();
            const auto& parent = child->storage.frontierPolicies[node.parentIndex];
            node.parent = parent.instance;
            node.parentEpoch = parent.instanceEpoch;
            tokenIndex = child->variableControlChildCount;
            const auto kind = node.authored.kind == PlayableKindV1::Container ? PlayableKind::Container
                : node.authored.kind == PlayableKindV1::Track ? PlayableKind::Track
                : node.authored.kind == PlayableKindV1::Segment ? PlayableKind::Segment : PlayableKind::Sound;
            if (tokenIndex >= child->variableControlChildren.size()) return refuse();
            auto& instance = child->variableControlChildren[tokenIndex];
            child->variableControlChildKinds[tokenIndex] = kind;
            ++child->variableControlChildCount;
            if (!playableInstances.PrepareAcquire(kind, node.parent, &instance) ||
                !child->playableTreeExecutor.AdoptPreparedInstanceReservation(&instance)) return refuse();
        }
        if (tokenIndex >= child->variableControlChildCount) return refuse();
        node.instance = child->variableControlChildren[tokenIndex].Handle();
        node.instanceEpoch = child->variableControlChildren[tokenIndex].ScheduleEpoch();
        ObservePreparedContent(*this, child->variableControlChildren[tokenIndex],
            MonitorVariableControlContentFor(*this, row, node.authored));
        if (node.authored.kind != PlayableKindV1::Container) continue;
        const ContainerProgramViewV3* program = nullptr;
        const bool resolved = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
            ? ResolveSharedContainerProgram(authority, row.Invocation().packPlaybackView, node.authored, &program)
            : ResolveSharedContainerProgram(authority, row.variableControlWorldUsesCurrentAuthority
                ? variables.CurrentPlayableWorld() : row.VariableControlWorld(), node.authored, &program);
        if (!resolved || program == nullptr ||
            (program->mode != ContainerModeV1::Random && program->mode != ContainerModeV1::Sequence &&
             program->mode != ContainerModeV1::VariableControl && program->mode != ContainerModeV1::SequenceQueue &&
             program->mode != ContainerModeV1::RandomQueue) ||
            child->variableControlContainerRowCount >= child->variableControlContainerRows.size() ||
            child->variableControlNestedFrontierCount >= child->variableControlNestedParentIndices.size()) return refuse();
        auto& container = child->variableControlContainerRows[child->variableControlContainerRowCount++];
        const auto loopLimit = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
            ? ReadPlayableLoopCount(row.Invocation().packPlaybackView, program->containerStableId)
            : ReadPlayableLoopCount(row.variableControlWorldUsesCurrentAuthority
                ? variables.CurrentPlayableWorld() : row.VariableControlWorld(), program->containerStableId);
        if (!containerPlayback.Prepare(playableInstances, node.instance, node.instanceEpoch,
                program->containerStableId, program->programSemanticFingerprint, static_cast<std::uint8_t>(program->mode),
                loopLimit, &container) || !child->playableTreeExecutor.AdoptPreparedContainerReservation(&container)) return refuse();
        const auto nested = child->variableControlNestedFrontierCount++;
        child->variableControlNestedParentIndices[nested] = static_cast<std::uint16_t>(tokenIndex);
        child->variableControlNestedPathOrdinals[nested] = node.occurrenceOrdinal;
        child->variableControlNestedModes[nested] = static_cast<std::uint8_t>(program->mode);
        auto* parent = &row;
        for (auto policy = node.parentIndex; policy != UINT32_MAX;
             policy = child->storage.frontierPolicies[policy].parentIndex) {
            const auto& ancestor = child->storage.frontierPolicies[policy];
            if (!ancestor.service.Valid()) continue;
            parent = ResolvePlayableService(ancestor.service);
            break;
        }
        if (parent == nullptr) return refuse();
        if (program->mode == ContainerModeV1::VariableControl) {
            if (!node.controlBank.Valid() || !PrepareNestedVariableControlInitialResources(*this,
                    *child, *parent, node.instance, program, row.Invocation().worldGeneration,
                    node.controlBank, node.controlBank)) return refuse();
            auto* service = ResolvePlayableService(child->variableControlNestedServices[
                child->variableControlNestedVariableControlCount - 1u]);
            if (service == nullptr || !ConfigureNestedVariableControlInitialPolicy(*service, row,
                    *child, policyIndex, *program, row.variableControlEmitter, anchor, row.ticket)) return refuse();
            continue;
        }
        auto* service = PrepareFrontierPathService(*this, *child, *parent,
            node.instance, node.instanceEpoch, *program);
        if (service == nullptr) return refuse();
        node.service = PlayableServiceReference(*service);
        service->parentChildOrdinal = node.occurrenceOrdinal;
        service->startFrame = anchor;
        service->ticket = row.ticket;
        service->activeLeafInstance = 0;
        service->frontierChildService = {};
        if (!SetNestedVariableControlPropertyPath(*service, row, child->storage.frontierPolicies,
                child->frontierPolicyCount, policyIndex, true)) return refuse();
        if (program->mode == ContainerModeV1::SequenceQueue || program->mode == ContainerModeV1::RandomQueue) {
            SharedInitialFrontier frontier{};
            const auto fingerprint = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
                ? row.Invocation().packPlaybackView.WorldSemanticFingerprint()
                : (row.variableControlWorldUsesCurrentAuthority
                    ? variables.CurrentPlayableWorld() : row.VariableControlWorld()).identity.runtimeSemanticFingerprint;
            const SharedInitialFrontierRequest request{
                {row.Invocation().worldGeneration, fingerprint, row.root.stableId,
                 row.Invocation().invocationEmitter, child->storage.initialSelection.identity.callerSeed, row.ticket},
                service->selectedChildOrdinals.data(), service->selectionCount - 1u, config.mixRate.SampleRate(),
                config.maxKnownScheduleLeaves, kSelectionPathNodeCapacity};
            const auto status = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
                ? PrepareSharedInitialFrontier(*this, row.Invocation().packPlaybackView, node.authored, program,
                    nullptr, request, &frontier)
                : PrepareSharedInitialFrontier(*this, row.variableControlWorldUsesCurrentAuthority
                    ? variables.CurrentPlayableWorld() : row.VariableControlWorld(), node.authored, program,
                    nullptr, request, &frontier);
            if ((status != SharedInitialFrontierStatus::Ok && status != SharedInitialFrontierStatus::ZeroWork) ||
                frontier.authoredChild == nullptr ||
                frontier.queue.frontier.initial.currentChildOrdinal != node.selectedOrdinal ||
                !PrepareFrontierQueueMode(*this, *child, *service, *program, frontier.queue.frontier.initial,
                    frontier.queue.frontier.resetInitial, frontier.queue.frontier.next, frontier.queue.randomSeed,
                    frontier.queue.frontier.status == QueueSequenceStepStatus::Successor)) return refuse();
            service->queueInitialCohortEntryFrame = anchor;
        }
        if (parent != &row && !parent->variableControlInstance.Valid())
            parent->frontierChildService = node.service;
    }
    const auto resolveNested = [&](const PlayableRefV1& ref) noexcept -> const ContainerProgramViewV3* {
        const ContainerProgramViewV3* program = nullptr;
        const bool resolved = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
            ? ResolveSharedContainerProgram(authority, row.Invocation().packPlaybackView, ref, &program)
            : ResolveSharedContainerProgram(authority, row.variableControlWorldUsesCurrentAuthority
                ? variables.CurrentPlayableWorld() : row.VariableControlWorld(), ref, &program);
        return resolved ? program : nullptr;
    };
    if (!PopulateNestedVariableControlInitialChildren(*this, *child, anchor, resolveNested) ||
        !RegisterNestedVariableControlInitialOwners(*this, *child, nullptr)) return refuse();
    if (pendingVariableGroupPoliciesPreparedHookForTest != nullptr)
        pendingVariableGroupPoliciesPreparedHookForTest(*this, *child,
            pendingVariableGroupPoliciesPreparedContextForTest);
    // Root indices retain the outer logical mapping; nested indices name native side owners.
    if (child->pendingVariableReplacementControls.size() < 2u || child->pendingVariableReplacementGroups.size() < 3u)
        return refuse();
    child->pendingVariableReplacementControlCount = 2;
    for (std::uint32_t side = 0; side < 2; ++side) {
        auto& control = child->pendingVariableReplacementControls[side];
        control.service = PlayableServiceReference(row);
        control.instance = row.variableControlInstance;
        control.side = side == 0 ? VariableControlSide::Discrete : VariableControlSide::Continuous;
        control.decision = scope->next_[side];
        control.bank = side == 0 ? row.variableControlDiscreteBank : row.variableControlContinuousBank;
        control.input = group->initialDecisionInputs[side];
    }
    for (std::uint32_t index = 0; index < child->variableControlNestedVariableControlCount; ++index) {
        auto* service = ResolvePlayableService(child->variableControlNestedServices[index]);
        if (service == nullptr) return refuse();
        for (const auto side : {VariableControlSide::Discrete, VariableControlSide::Continuous}) {
            auto& reservation = side == VariableControlSide::Continuous &&
                    !child->variableControlNestedDecisionContinuous[index]
                ? child->storage.nestedContinuousDecisions[index] : child->variableControlNestedDecisions[index];
            const auto decision = side == VariableControlSide::Discrete
                ? service->variableControlDiscreteDecision : service->variableControlContinuousDecision;
            if (!decision.Valid()) continue;
            const auto slot = child->pendingVariableReplacementControlCount;
            if (slot >= child->pendingVariableReplacementControls.size() || !reservation.Valid() ||
                !SameCanonicalDecision(reservation.Token(), decision)) return refuse();
            auto& control = child->pendingVariableReplacementControls[slot];
            control.service = child->variableControlNestedServices[index];
            control.instance = service->variableControlInstance;
            control.side = side;
            control.decision = decision;
            control.bank = side == VariableControlSide::Discrete
                ? service->variableControlDiscreteBank : service->variableControlContinuousBank;
            control.input = reservation.OriginalRequest();
            control.preparationIndex = index;
            if (!variableControlInstances.IssueOriginalInitialSideReceipt(
                    child->variableControlNestedVariableControls[index], side, &control.original)) return refuse();
            const auto* baseline = ResolveOriginalSingleDecisionBaseline(this, decisions, decision);
            if (baseline == nullptr || !decisions.MatchesOriginalDecisionFactory(*baseline, control.input)) return refuse();
            ++child->pendingVariableReplacementControlCount;
        }
    }
    for (std::uint32_t policy = 0; policy < child->frontierPolicyCount; ++policy) {
        const auto& node = child->storage.frontierPolicies[policy];
        if (node.authored.kind != PlayableKindV1::Track && node.authored.kind != PlayableKindV1::Segment) continue;
        auto* resource = ResolvePreparedResourceService(*this, row, node.instance,
            child->variableControlChildren, child->variableControlLeafChildren);
        if (resource == nullptr) return refuse();
        if (resource == &row) continue;
        resource->activeLeafInstance = node.instance;
        MaterializedScheduleSet materialized{};
        const auto status = !row.variableControlWorldUsesCurrentAuthority && row.Invocation().packLease.leaseToken != 0
            ? MaterializeSchedule(row.Invocation().packPlaybackView, node.authored, config.mixRate.SampleRate(),
                config.maxKnownScheduleLeaves, kSelectionPathNodeCapacity, &materialized)
            : MaterializeSchedule(row.variableControlWorldUsesCurrentAuthority
                ? variables.CurrentPlayableWorld() : row.VariableControlWorld(), node.authored,
                config.mixRate.SampleRate(), &materialized);
        if (status == ScheduleMaterializeStatus::ZeroWork) {
            if (materialized.zeroWorkCompletionOffsetFrames > UINT64_MAX - anchor) return refuse();
            resource->hasZeroWorkCompletion = true;
            resource->zeroWorkCompletionFrame = anchor + materialized.zeroWorkCompletionOffsetFrames;
            resource->zeroWorkMarker = true;
            resource->startFrame = resource->zeroWorkCompletionFrame;
            resource->pendingFutureCount = 1;
        } else if (status != ScheduleMaterializeStatus::Ok) return refuse();
    }
    members = {};
    std::array<std::uint16_t, EngineActionPlayScratch::kPendingVariableReplacementControlCapacity> nativeMembers{};
    for (std::uint32_t index = 0; index < leaves.size(); ++index) {
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
        if (harken::detail::RefusePendingVariablePrepareForTest(*this, *child,
                harken::detail::PendingVariablePrepareStageForTest::VoiceInstall, index)) return refuse();
#endif
        const auto& leaf = leaves[index];
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        const auto top = leaf.topIndex == UINT32_MAX ? index : leaf.topIndex;
        if (top >= tops.size() || leaf.side != tops[top].side ||
            leaf.authoredChildOrdinal != tops[top].authoredChildOrdinal) return refuse();
        auto* instance = &child->variableControlChildren[top];
        auto kind = child->variableControlChildKinds[top];
        if (leaf.frontierPolicyIndex != UINT32_MAX) {
            if (leaf.frontierPolicyIndex >= child->frontierPolicyCount) return refuse();
            const auto& node = child->storage.frontierPolicies[leaf.frontierPolicyIndex];
            const auto found = std::find_if(child->variableControlChildren.begin(),
                child->variableControlChildren.begin() + child->variableControlChildCount,
                [&](const auto& candidate) { return candidate.Handle() == node.instance; });
            if (found == child->variableControlChildren.begin() + child->variableControlChildCount) return refuse();
            instance = &*found;
            kind = child->variableControlChildKinds[static_cast<std::size_t>(found - child->variableControlChildren.begin())];
        }
        if (kind != PlayableKind::Sound) {
            const auto slot = child->variableControlLeafChildCount++;
            if (slot >= child->variableControlLeafChildren.size()) return refuse();
            const auto parent = instance->Handle();
            instance = &child->variableControlLeafChildren[slot];
            if (!playableInstances.PrepareAcquire(PlayableKind::Sound, parent, instance) ||
                !child->playableTreeExecutor.AdoptPreparedInstanceReservation(instance)) return refuse();
        }
        ObservePreparedContent(*this, *instance, MonitorVariableControlContentFor(*this, row, leaf.leaf));
        child->variableControlLeafHandles[index] = instance->Handle();
        child->variableControlLeafEpochs[index] = instance->ScheduleEpoch();
        auto& start = child->voiceStarts[index];
        child->voiceStartCount = index + 1u;
        auto cut = group->cut;
        const bool ownedWeight = leaf.side == VariableControlSide::Continuous &&
            row.variableControlIndependentFrontier;
        PreparedVariableControlLeafBinding binding{};
        if (!ResolveVariableControlLeafBinding(*this, child->storage.frontierPolicies,
                child->frontierPolicyCount, leaf.frontierPolicyIndex, anchor, &binding)) return refuse();
        auto controlIndex = side;
        auto controlOrdinal = leaf.authoredChildOrdinal;
        if (binding.memberCount != 0) {
            const auto& member = binding.members[0];
            const auto actualSide = member.discrete ? VariableControlSide::Discrete : VariableControlSide::Continuous;
            controlIndex = UINT32_MAX;
            for (std::uint32_t control = 2; control < child->pendingVariableReplacementControlCount; ++control) {
                const auto& candidate = child->pendingVariableReplacementControls[control];
                if (candidate.side == actualSide && ResolvePlayableService(candidate.service) == member.owner) {
                    if (controlIndex != UINT32_MAX) return refuse();
                    controlIndex = control;
                }
            }
            if (controlIndex == UINT32_MAX) return refuse();
            controlOrdinal = member.ordinal;
        }
        if (ownedWeight) {
            if (binding.weightCount >= binding.weights.size()) return refuse();
            auto& weight = binding.weights[binding.weightCount++];
            weight.owner = {row.ownerInstance, row.ownerEpoch, 1};
            weight.segment = leaf.weight;
            weight.segment.decision = scope->next_[side];
        }
        const auto& control = child->pendingVariableReplacementControls[controlIndex];
        const auto nativeMember = nativeMembers[controlIndex]++;
        auto& mirror = child->pendingVariableReplacementLeaves[index];
        mirror.side = leaf.side;
        mirror.memberOrdinal = members[side]++;
        mirror.controlIndex = controlIndex;
        mirror.controlChildOrdinal = controlOrdinal;
        mirror.frontierPolicyIndex = leaf.frontierPolicyIndex;
        mirror.nativeMemberOrdinal = nativeMember;
        mirror.authoredOffset = leaf.authoredOffset;
        auto* resource = ResolvePreparedResourceService(*this, *producer.row, instance->Handle(),
            child->variableControlChildren, child->variableControlLeafChildren);
        if (resource == nullptr) return refuse();
        std::size_t memberSlot = 0;
        if (!PreparePlayableMemberStorage(*this, *resource,
                StorageBasesForRow(*this, *producer.row).member + index,
                instance->Handle(), instance->ScheduleEpoch(), &memberSlot, &mirror.storageReference)) return refuse();
        auto* memberProgram = AcquireMemberProgram(*resource, mirror.storageReference);
        if (memberProgram == nullptr) return refuse();
        mirror.program = {instance->Handle(), &memberProgram->runtime};
        if (resource != producer.row) {
            auto terminal = instance->Parent();
            resource->activeLeafInstance = kind == PlayableKind::Sound ? instance->Handle() : terminal;
        }
        auto captures = child->voiceStarts.Captures();
        if (index >= captures.size() ||
            CaptureTimelineVoiceInstall(leaf.voice, &captures[index].voice, true) != PlayableStartStatus::Accepted)
            return refuse();
        const auto installed = InstallTimelineVoiceStart(*this, captures[index].voice.Input(), instance->Handle(),
            anchor + leaf.authoredOffset, row.ownerInstance, row.rootInstance, nullptr, nullptr,
            {control.decision}, nativeMember, ownedWeight || binding.weightCount != 0 ? nullptr : &leaf.weight,
            &start, nullptr, resource,
            nullptr, true, false, false, true, &cut, order, true, leaf.authoredOffset);
        if (start.prepared && !RegisterCurrentFrontierVoiceOwners(*this, *child)) return refuse();
        if (installed.status != VN_OK || !start.prepared) return refuse();
        if (binding.weightCount != 0 &&
            !voices.PrepareVariableWeightControls(installed.renderHandle, binding.weights.data(), binding.weightCount))
            return refuse();
    }
    members = {};
    // Queue completion preparation reads the physical storage and changes voice facts.
    // Finish it before capturing voice/ledger proofs or the command batch.
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& leaf = leaves[index];
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        const auto instance = child->variableControlLeafHandles[index];
        const auto epoch = child->variableControlLeafEpochs[index];
        const auto& start = child->voiceStarts[index];
        auto& mirror = child->pendingVariableReplacementLeaves[index];
        mirror.leaf = leaf.leaf;
        mirror.authoredChildOrdinal = leaf.authoredChildOrdinal;
        mirror.weight = leaf.weight;
        mirror.side = leaf.side;
        mirror.memberOrdinal = members[side]++;
        mirror.authoredOffset = leaf.authoredOffset;
        std::size_t slot = 0;
        EnginePlayableServiceRow* resource = nullptr;
        if (!ResolvePlayableMember(mirror.storageReference, &resource, &slot)) return refuse();
        const auto storageBases = StorageBasesForRow(*this, *resource);
        auto* record = ResolveMemberProgram(mirror.storageReference);
        if (record == nullptr || mirror.program.program != &record->runtime) return refuse();
        auto& payload = record->payloads[0];
        auto& event = record->events[0];
        auto& runtime = record->runtime;
        auto& schedule = record->schedule;
        mirror.target = leaf.voice.target;
        mirror.sequence = (*scope->proofs_)[side].Sequence();
        mirror.program = {instance, &runtime};
        payload = {};
        payload.kind = TimelineEventKind::Start;
        payload.target = mirror.target;
        payload.reserved = kTimelineEventTransientStartArm;
        event = {};
        event.logicCommitSequence = mirror.sequence;
        event.executionOrdinal = row.Invocation().actionExecutionOrdinal;
        event.eventIndex = index;
        event.transactionOrdinal = index;
        event.subeventPhase = 20;
        event.frameOffsetFromEntry = static_cast<std::int64_t>(leaf.authoredOffset);
        event.armToken = start.arm;
        runtime = {};
        runtime.readFence = &record->readFence;
        runtime.generation = instance;
        runtime.payloads = &payload;
        runtime.payloadCount = 1;
        schedule = {};
        schedule.ownerInstance = instance;
        schedule.ownerInstanceScheduleEpoch = epoch;
        schedule.transactionId = mirror.sequence;
        schedule.entryAnchorFrame = anchor;
        schedule.events = &event;
        schedule.eventCount = 1;
        schedule.runtimeProgram = mirror.program;
        schedule.armToken = start.arm;
        child->voiceStarts.Captures()[index].Stage(MutablePlayableMember(slot).voice);
        MutablePlayableMember(slot).leaf = mirror.leaf;
        MutablePlayableMember(slot).arm = start.arm;
        MutablePlayableMember(slot).render = start.renderHandle;
        MutablePlayableMember(slot).release = start.releaseObserver;
        MutablePlayableMember(slot).startFrame = anchor + leaf.authoredOffset;
        SetPlayableMemberCompletion(slot, {instance, epoch, start.sourceTerminal});
        MutablePlayableMember(slot).monitorSelection = start.monitorSelection;
        MutablePlayableMember(slot).dynamic = 0;
        if (resource != producer.row && !resource->variableControlIndependentFrontier) {
            const auto member = resource->scheduleLeafCount;
            if (member >= playableStorage.memberStride) return refuse();
            if (member == 0) {
                resource->leaf = leaf.leaf;
                resource->arm = start.arm;
                resource->renderHandle = start.renderHandle;
                resource->releaseObserver = start.releaseObserver;
                resource->schedule = schedule;
            }
            if (!SetPlayableMemberReference(storageBases.member + member, mirror.storageReference)) return refuse();
            ++resource->scheduleLeafCount;
            ++resource->pendingFutureCount;
        }
    }
    child->pendingVariableReplacementLeafCount = child->voiceStartCount;
    VnResult queueResult = VN_OK;
    bool queueProgramCapacityRefused = false;
    if (!PreparePendingVariableReplacementQueueFutures(producer, attempt, *child,
            queueResult, queueProgramCapacityRefused)) return refuse();
    auto* nativeAttempt = FindImmediateEntryAttempt(*this, attempt.root);
    if (nativeAttempt != &attempt) return refuse();
    for (std::uint32_t index = 2; index < child->pendingVariableReplacementControlCount; ++index) {
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
        if (harken::detail::RefusePendingVariablePrepareForTest(*this, *child,
                harken::detail::PendingVariablePrepareStageForTest::NestedGroupReserve, index)) return refuse();
#endif
        auto& control = child->pendingVariableReplacementControls[index];
        std::array<TimelineArmToken, kMaxKnownScheduleLeaves> arms{};
        std::uint16_t count = 0;
        for (std::uint32_t leafIndex = 0; leafIndex < child->voiceStartCount; ++leafIndex) {
            const auto& leaf = child->pendingVariableReplacementLeaves[leafIndex];
            if (leaf.controlIndex != index) continue;
            const auto& start = child->voiceStarts[leafIndex];
            if (!start.prepared || count >= arms.size() || leaf.nativeMemberOrdinal != count ||
                !SameCanonicalDecision(start.armPreparation.parentGroup.decision, control.decision) ||
                start.armPreparation.memberIndex != count) return refuse();
            arms[count++] = start.arm;
        }
        if (count != nativeMembers[index] || !variableControlInstances.MatchesOriginalInitialSideReceipt(
                control.original, control.instance, control.side, control.decision, control.bank) ||
            decisions.PrepareFrontierControlProgram(control.decision, producer.storage.generation) == nullptr)
            return refuse();
        Plan03GroupSliceInput input{};
        input.executeFrame = anchor;
        input.decision = control.decision;
        input.immediateEntry = {&nativeAttempt->gate, attempt.generation};
        input.members = arms.data();
        input.memberCount = count;
        if (!ReserveOriginalQueueLaneGroup(attempt.root, anchor, input, timelineArms,
                &child->pendingVariableReplacementGroups[index + 1u])) return refuse();
        control.nativeMemberCount = count;
        if (!armGroups.Reserve(control.decision, arms.data(), count, &control.armGroup)) return refuse();
    }
    if (pendingVariableGroupVoicesPreparedHookForTest != nullptr)
        pendingVariableGroupVoicesPreparedHookForTest(*this, *child, pendingVariableGroupVoicesPreparedContextForTest);
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::PreparedGroups, 0)) return refuse();
#endif
    child->frontierOwnerLedgerComplete = true;
    if (child->selectionPlayCount != 0 &&
        child->storage.initialSelection.preparation.mode == EngineSelectionPreparationMode::Legacy &&
        !RegisterInitialSelectionOwners(*this, *child)) return refuse();
    if (!child->playableTreeExecutor.ProveInstanceCommits()) return refuse();
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::InstanceProofs, 0)) return refuse();
#endif
    if (!tops.empty() && !child->playableTreeExecutor.ProveParentLinks(playableInstances)) return refuse();
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::ParentProofs, 0)) return refuse();
#endif
    if (!leaves.empty() && !ProvePreparedFrontierVoiceCommits(*this, *child)) return refuse();
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::VoiceProofs, 0)) return refuse();
#endif
    if (!CapturePendingVariableReplacementTopology(*child, leaves)) return refuse();
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::TopologyCaptured, 0)) return refuse();
#endif
    if (child->variableControlContainerRowCount != 0 &&
        !child->playableTreeExecutor.ProveContainerCommits(&containerPlayback,
            &child->variableControlContainerRows[0])) return refuse();
    const auto* links = child->playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
    if (tops.empty() ? !PendingVariableReplacementEmptyCensus(*child) : links == nullptr)
        return refuse();
    if (links != nullptr) {
        if (!PrepareQueueFutureFactoryOutputs(*this, *child, *links)) return refuse();
        for (std::uint32_t queueIndex = 0; queueIndex < child->frontierQueueCount; ++queueIndex) {
            const auto& queue = child->storage.frontierQueues[queueIndex];
            if (!MatchesPendingVariableReplacementQueueIssuer(*child, queue, attempt.root, attempt.generation) ||
                (queue.prepared.Valid() && !JoinOriginalQueueFactoryLifetime(queue.prepared, *links))) return refuse();
        }
    }
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::ContainerProofs, 0)) return refuse();
#endif
    if (!CapturePendingVariableReplacementFutureTopology(*child)) return refuse();
    std::uint32_t commandCount = 0;
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& voice = child->voiceStarts[index];
        if (voice.commandCount > actionPlayCommandScratch.size() - commandCount) return refuse();
        std::copy_n(voice.commands.begin(), voice.commandCount, actionPlayCommandScratch.begin() + commandCount);
        commandCount += voice.commandCount;
    }
    if (!AppendPreparedQueueFutureCommands(*this, *child, commandCount)) return refuse();
    child->pendingVariableReplacementCommandCount = commandCount;
    const bool registered = group->reprepare_.cohortHead != nullptr;
    if (commandCount == 0 && child->voiceStartCount != 0) return refuse();
    if (!registered && commandCount != 0) {
        if (!AdmitCommandBatch(*this, commandCount) ||
            !commands.ReserveBatch(commandCount, &child->directCommandReservation)) return refuse();
        child->directCommandsReserved = true;
        if (!PrepareVoiceCommandBatch(*this, &child->directCommandReservation,
                {actionPlayCommandScratch.data(), commandCount})) {
            child->directCommandsReserved = false;
            return refuse();
        }
    } else if (registered) {
        for (std::uint32_t side = 0; side < scope->sides_.size(); ++side) {
            if (!scope->sides_[side]) continue;
            const auto* baseline = ResolveOriginalSingleDecisionBaseline(this, decisions, scope->next_[side]);
            if (baseline == nullptr || !baseline->Borrow(&child->pendingVariableReplacementSideLifetimes[side]))
                return refuse();
        }
    }
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::CommandBatchPrepared, 0)) return refuse();
#endif
    if (!registered && !PreparePendingReplacementQueueCurrentFactoryOutputs(*this, *child, producer, attempt))
        return refuse();
    members = {};
    nativeMembers = {};
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& leaf = leaves[index];
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        const auto& start = child->voiceStarts[index];
        const auto& owner = child->voiceStarts.Owners()[index];
        const auto& mirror = child->pendingVariableReplacementLeaves[index];
        if (!MatchesPendingVariableReplacementControl(*child, *group, mirror.controlIndex)) return refuse();
        const auto& control = child->pendingVariableReplacementControls[mirror.controlIndex];
        if (start.arm.slot >= pendingVariableLeafSources.size()) return refuse();
        const auto& source = pendingVariableLeafSources[start.arm.slot];
        if (source.group != nullptr || source.cut.Valid() || source.parent != row.ownerInstance ||
            start.ledgerPreparation.parent.internalToken != row.ownerInstance ||
            start.ledgerPreparation.parent.previewHandle != 0 ||
            source.programGeneration != child->variableControlLeafHandles[index] ||
            start.armPreparation.programGeneration != source.programGeneration ||
            source.preparedStartFrame != anchor + leaf.authoredOffset ||
            !OriginalSourceSubmissionRegistry::SameToken(source.arm, start.arm) ||
            source.physicalRelease.slot != start.releaseObserver.slot ||
            source.physicalRelease.targetSequence != start.releaseObserver.targetSequence ||
            mirror.memberOrdinal != members[side]++ ||
            mirror.nativeMemberOrdinal != nativeMembers[mirror.controlIndex]++ ||
            !SameCanonicalDecision(start.armPreparation.parentGroup.decision, control.decision) ||
            start.armPreparation.memberIndex != mirror.nativeMemberOrdinal ||
            !playableInstances.MatchesPreparedOriginalAncestry(*links, source.programGeneration, row.ownerInstance) ||
            !variables.MatchesPreparedTimelineReadUse(start.initialVariableReadUse, group->cut,
                start.renderHandle, owner.armCommitProof, originalSourceSubmissions, leaf.authoredOffset) ||
            (!registered && !originalSourceSubmissions.MatchesPreparedInitialGroupSourcePair(source.source, source.body,
                owner.armCommitProof, owner.voiceCommitProof, start.voicePreparation,
                preparedVoiceCommandBatchProof, start.arm, source.sourceIdentity))) return refuse();
        const auto nativeUse = voices.TimelineVariableSourceRead(start.arm.renderSlot, start.arm.renderGeneration);
        if (nativeUse.slot != start.initialVariableReadUse.slot ||
            nativeUse.generation != start.initialVariableReadUse.generation) return refuse();
        for (std::uint32_t previous = 0; previous < index; ++previous)
            if (child->voiceStarts[previous].arm.slot == start.arm.slot ||
                child->voiceStarts[previous].renderHandle == start.renderHandle ||
                (child->voiceStarts[previous].initialVariableReadUse.slot == start.initialVariableReadUse.slot &&
                 child->voiceStarts[previous].initialVariableReadUse.generation == start.initialVariableReadUse.generation)) return refuse();
    }
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::SourcePairsPrepared, 0)) return refuse();
#endif
    if (child->storage.initialSelection.preparation.mode == EngineSelectionPreparationMode::PendingReplacement) {
        auto& batch = group->initialSelectionBatch;
        if (batch.SealReplacement(anchor, child->storage.initialSelection.materializedOrdinals.data(),
                child->selectionPlayCount) != SelectionMemoryStatusV1::Ok ||
            batch.CanInstallReplacement() != SelectionMemoryStatusV1::Ok ||
            batch.InstallReplacement() != SelectionMemoryStatusV1::Ok) return refuse();
    }
    child->prepared = true;
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (detail::RefusePendingVariablePrepareForTest(*this, *child,
            detail::PendingVariablePrepareStageForTest::ReplacementPrepared, 0)) return refuse();
#endif
    return true;
}

bool Engine::MatchesPendingVariableReplacementControl(const EngineActionPlayScratch& child,
    const OriginalPendingVariableGroupHolder& group, std::uint32_t index) noexcept {
    if (index >= child.pendingVariableReplacementControlCount ||
        child.pendingVariableReplacementControlCount > child.pendingVariableReplacementControls.size() ||
        child.pendingVariableReplacementService.token != group.reference.token ||
        child.pendingVariableReplacementCut != group.cut) return false;
    const auto& control = child.pendingVariableReplacementControls[index];
    const auto* service = ResolvePlayableService(control.service);
    const auto* root = ResolvePlayableService(child.pendingVariableReplacementService);
    if (service == nullptr || root == nullptr ||
        (control.side != VariableControlSide::Discrete && control.side != VariableControlSide::Continuous) ||
        control.instance.slot != service->variableControlInstance.slot ||
        control.instance.generation != service->variableControlInstance.generation ||
        !control.decision.Valid() || !control.bank.Valid()) return false;
    const auto bank = control.side == VariableControlSide::Discrete
        ? service->variableControlDiscreteBank : service->variableControlContinuousBank;
    if (control.bank.slot != bank.slot || control.bank.generation != bank.generation) return false;
    if (index < 2u) {
        if (service != root || control.preparationIndex != UINT32_MAX ||
            control.side != (index == 0 ? VariableControlSide::Discrete : VariableControlSide::Continuous)) return false;
        const auto* scope = activePendingVariableGroupReplacement_;
        if (scope != nullptr) {
            return pendingVariableGroupReplacementActive && scope->group_ == &group &&
                scope->cut_ == group.cut && scope->sides_[index] && (*scope->held_)[index].Valid() &&
                (*scope->proofs_)[index].Valid() && (*scope->proofs_)[index].Sequence() == root->ticket &&
                SameCanonicalDecision(scope->next_[index], control.decision) &&
                SameCanonicalDecision((*scope->proofs_)[index].Token(), control.decision) &&
                scope->producer_ != nullptr && scope->attempt_ != nullptr &&
                MatchesPendingVariableReplacementProducer(child, *scope->producer_, *scope->attempt_);
        }
        return SameCanonicalDecision(control.decision, control.side == VariableControlSide::Discrete
                ? service->variableControlDiscreteDecision : service->variableControlContinuousDecision) &&
            variableControlInstances.MatchesOriginalInitialSideReceipt(group.initialSides[index],
                control.instance, control.side, control.decision, control.bank);
    }
    const auto nested = control.preparationIndex;
    if (nested >= child.variableControlNestedVariableControlCount ||
        ResolvePlayableService(child.variableControlNestedServices[nested]) != service ||
        !SameCanonicalDecision(control.decision, control.side == VariableControlSide::Discrete
            ? service->variableControlDiscreteDecision : service->variableControlContinuousDecision) ||
        !IsPlayableServiceDescendant(*this, *service, *root) ||
        &service->Invocation() != &root->Invocation()) return false;
    const auto* baseline = ResolveOriginalSingleDecisionBaseline(this, decisions, control.decision);
    return baseline != nullptr && decisions.MatchesOriginalDecisionFactory(*baseline, control.input) &&
        variableControlInstances.MatchesOriginalInitialSideReceipt(control.original,
            control.instance, control.side, control.decision, control.bank);
}

bool Engine::CapturePendingVariableReplacementControlOwner(const EngineActionPlayScratch& child,
    std::uint32_t index, FrontierOwnerIdentity* out) noexcept {
    if (out == nullptr || index >= child.pendingVariableReplacementControlCount ||
        child.pendingVariableReplacementControlCount > child.pendingVariableReplacementControls.size()) return false;
    const auto* service = ResolvePlayableService(child.pendingVariableReplacementControls[index].service);
    const auto* root = ResolvePlayableService(child.pendingVariableReplacementService);
    if (service == nullptr || root == nullptr) return false;
    const auto invocation = playableInstances.Classify(root->rootInstance);
    if (!invocation.live) return false;
    PlayableInstanceHandle parent = 0;
    std::uint64_t parentEpoch = 0;
    if (index < 2u) {
        const auto owner = playableInstances.Classify(service->ownerInstance);
        if (service != root || !owner.live || owner.scheduleEpoch != service->ownerEpoch) return false;
        parent = owner.parent;
        const auto view = playableInstances.Classify(parent);
        if (parent != 0 && !view.live) return false;
        parentEpoch = parent == 0 ? 0 : view.scheduleEpoch;
    } else {
        const auto& topology = child.pendingVariableReplacementTopology;
        if (!topology.sealed || topology.nodeCount > topology.nodes.size()) return false;
        const auto end = topology.nodes.begin() + topology.nodeCount;
        const auto owner = std::find_if(topology.nodes.begin(), end,
            [&](const auto& node) { return node.handle == service->ownerInstance; });
        if (owner == end || owner->epoch != service->ownerEpoch || owner->kind != PlayableKind::Container ||
            !playableInstances.IsOriginalLifetimeCurrent(owner->original)) return false;
        parent = owner->parent;
        if (parent == root->ownerInstance) parentEpoch = root->ownerEpoch;
        else {
            const auto ancestor = std::find_if(topology.nodes.begin(), end,
                [parent](const auto& node) { return node.handle == parent; });
            if (ancestor == end || !playableInstances.IsOriginalLifetimeCurrent(ancestor->original)) return false;
            parentEpoch = ancestor->epoch;
        }
    }
    const FrontierOwnerIdentity identity{service->ownerInstance, service->ownerEpoch, parent, parentEpoch,
        root->rootInstance, invocation.scheduleEpoch, service->identity.slot, service->identity.generation};
    if (!identity.Valid()) return false;
    *out = identity;
    return true;
}

bool Engine::MatchesPendingVariableReplacementBoundSide(const EngineActionPlayScratch& child,
    const OriginalPendingVariableGroupHolder& group, std::uint32_t index,
    const FrontierGroupBinding& binding) noexcept {
    if (!MatchesPendingVariableReplacementControl(child, group, index)) return false;
    const auto& control = child.pendingVariableReplacementControls[index];
    FrontierOwnerIdentity owner{};
    VariableControlActivationProof proof{};
    Plan03PageGroupView native{};
    if (!CapturePendingVariableReplacementControlOwner(child, index, &owner) ||
        !binding.Valid() || binding.role != FrontierGroupRole::EntryMember ||
        binding.operation.kind != FrontierOperationKind::Entry || binding.operation.owner != owner ||
        binding.entry != child.frontierDescriptor.entry || binding.primary != child.frontierDescriptor.primary ||
        binding.operation.group != child.pendingVariableReplacementGroups[index + 1u] ||
        binding.operation.world != child.frontierDescriptor.worldGeneration ||
        binding.operation.transport != timelinePool.Epoch() ||
        binding.transition.Valid() || binding.queueInitial.Valid() || binding.queueConditional.Valid() ||
        !binding.queueDescendant.Empty() || binding.prerequisite.Valid() || binding.prerequisiteMember.Valid() ||
        binding.initialVariables.Valid() ||
        !timelinePool.ResolvePlan03GroupSliceProducer(binding.operation.group, &native) || native.frontier != &binding ||
        native.lease == nullptr || native.lease->Capture().state != AudioSliceState::Ready ||
        !timelinePool.PrivateImmediateLaneFrontierRollbackReady(binding.operation.group) ||
        !variableControlInstances.ProveActivation(control.instance, control.decision, &proof)) return false;
    const FrontierVariableSideIdentity expected{proof.instance.slot, proof.instance.generation,
        static_cast<std::uint8_t>(proof.side), proof.sideGeneration, proof.bank.slot, proof.bank.generation};
    if (binding.variableSide != expected) return false;
    if (index < 2u) return variableControlInstances.MatchesPrivateInitialFrontierSide(
        group.initialSides[index], binding, timelinePool, decisions);
    const auto* service = ResolvePlayableService(control.service);
    VariableControlInstanceSnapshot snapshot{};
    return service != nullptr && variableControlInstances.Capture(control.instance, &snapshot) &&
        snapshot.world == binding.operation.world && snapshot.rootInstance == owner.child &&
        snapshot.containerStableId == service->root.stableId &&
        snapshot.programSemanticFingerprint == service->root.expectedProgramSemanticFingerprint;
}

bool Engine::MatchesPendingVariableReplacementMemberStorage(const EngineActionPlayScratch& child,
    std::uint32_t index) noexcept {
    if (index >= child.voiceStartCount ||
        index >= child.pendingVariableReplacementLeaves.size()) return false;
    const auto& leaf = child.pendingVariableReplacementLeaves[index];
    const auto& start = child.voiceStarts[index];
    EnginePlayableServiceRow* owner = nullptr;
    std::size_t slot = 0;
    auto* controller = ResolvePlayableService(child.pendingVariableReplacementService);
    if (!ResolvePlayableMember(leaf.storageReference, &owner, &slot) ||
        controller == nullptr || !IsPlayableServiceDescendant(*this, *owner, *controller) ||
        ResolvePreparedResourceService(*this, *controller, leaf.storageReference.leaf,
            child.variableControlChildren, child.variableControlLeafChildren) != owner ||
        leaf.storageReference.memberOffset >= playableStorage.currentEventStride ||
        leaf.storageReference.memberOffset >= playableStorage.initialProgramStride) return false;
    const auto* record = ResolveMemberProgram(leaf.storageReference);
    if (record == nullptr) return false;
    const auto& payload = record->payloads[0];
    const auto& event = record->events[0];
    const auto& runtime = record->runtime;
    const auto& schedule = record->schedule;
    const auto& completion = ReadPlayableMember(slot).completion;
    return leaf.program.program == &runtime && leaf.program.programGeneration == leaf.storageReference.leaf &&
        runtime.payloads == &payload && runtime.payloadCount == 1 &&
        runtime.generation == leaf.storageReference.leaf &&
        schedule.events == &event && schedule.eventCount == 1 &&
        schedule.runtimeProgram.program == &runtime &&
        schedule.runtimeProgram.programGeneration == runtime.generation &&
        schedule.ownerInstance == leaf.storageReference.leaf &&
        schedule.ownerInstanceScheduleEpoch == leaf.storageReference.leafEpoch &&
        schedule.entryAnchorFrame == child.pendingVariableReplacementAnchorFrame &&
        schedule.transactionId == leaf.sequence &&
        SameOriginalSingleArm(schedule.armToken, start.arm) &&
        SameOriginalSingleArm(event.armToken, start.arm) &&
        SameOriginalSingleArm(ReadPlayableMember(slot).arm, start.arm) &&
        event.logicCommitSequence == leaf.sequence &&
        event.executionOrdinal == controller->Invocation().actionExecutionOrdinal && event.eventIndex == index &&
        event.transactionOrdinal == index && event.subeventPhase == 20 &&
        event.frameOffsetFromEntry == static_cast<std::int64_t>(leaf.authoredOffset) && event.payload == 0 &&
        payload.kind == TimelineEventKind::Start && payload.reserved == kTimelineEventTransientStartArm &&
        payload.target == leaf.target &&
        ReadPlayableMember(slot).voice.Facts().target == leaf.target &&
        ReadPlayableMember(slot).voice.Facts().soundId == leaf.leaf.stableId &&
        ReadPlayableMember(slot).render == start.renderHandle &&
        ReadPlayableMember(slot).release.slot == start.releaseObserver.slot &&
        ReadPlayableMember(slot).release.targetSequence == start.releaseObserver.targetSequence &&
        completion.source.slot == start.sourceTerminal.slot &&
        completion.source.generation == start.sourceTerminal.generation && !completion.resourcesRetired;
}

bool Engine::MatchesPendingVariableReplacementProducer(const EngineActionPlayScratch& child,
    const EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt) noexcept {
    const auto token = child.pendingVariableReplacementProducer;
    return actionPlayScratch.IsConstructed(token.slot) && &actionPlayScratch[token.slot] == &producer &&
        token.generation == producer.storage.generation &&
        child.pendingVariableReplacementEntryGeneration == attempt.generation;
}

bool Engine::MatchesPendingVariableReplacementQueueIssuer(EngineActionPlayScratch& child,
    const EngineFrontierQueueOwnerContext& queue, ActionFiringHandle root,
    std::uint64_t attemptGeneration) noexcept {
    auto* producer = FindFrontierAttempt(*this, child.pendingVariableReplacementProducer);
    const auto* attempt = FindImmediateEntryAttempt(*this, root);
    if (producer == nullptr || attempt == nullptr || !attempt->active || attempt->generation != attemptGeneration ||
        child.pendingVariableReplacementEntryGeneration != attemptGeneration ||
        !MatchesPendingVariableReplacementProducer(child, *producer, *attempt)) return false;
    const auto reference = child.pendingVariableReplacementService;
    if (!reference.Valid() || !acceptedPendingVariableGroups.IsConstructed(reference.token.slot)) return false;
    auto* group = &acceptedPendingVariableGroups[reference.token.slot];
    const auto& issued = group->reprepare_;
    const auto& retention = producer->storage.originalPendingVariableProducer;
    if (group->engine != this || !group->accepted || !group->producer.Valid() ||
        group->producer.original_ != &retention || group->producer.marker_ != retention.marker_ ||
        retention.engine_ != this || retention.storage_ != &producer->storage ||
        retention.storageGeneration_ != producer->storage.generation ||
        issued.engine != this || issued.storage != &producer->storage || issued.attempt != attempt ||
        issued.storageGeneration != producer->storage.generation || issued.attemptGeneration != attemptGeneration ||
        issued.producerMarker != retention.marker_ || issued.cut != group->cut ||
        issued.phase == OriginalPendingVariableGroupHolder::InitialReprepare::Phase::None ||
        !MatchesOriginalPlayableServiceLifetime(group->service) ||
        FindFrontierAttempt(*this, issued.replacementChildren) != &child ||
        child.pendingVariableReplacementCut != group->cut ||
        !SameVariableControlRollbackService(child.pendingVariableReplacementService, group->reference) ||
        child.pendingVariableReplacementAnchorFrame == UINT64_MAX ||
        (child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildren &&
         child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenSourcesCommitting &&
         child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenSourcesPrivateCommitted &&
         child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenCancelPending) ||
        child.frontierQueueCount > child.storage.frontierQueues.size()) return false;
    std::uint32_t matches = 0;
    for (std::uint32_t index = 0; index < child.frontierQueueCount; ++index)
        matches += &child.storage.frontierQueues[index] == &queue;
    const auto* service = ResolvePlayableService(queue.service);
    const auto* original = ResolvePlayableService(group->reference);
    const auto queueToken = queue.prepared.Valid() ? queue.prepared.Token()
        : queue.committed && service != nullptr ? service->queueInstance : QueueInstanceToken{};
    return matches == 1 && queue.engine == this && queue.program != nullptr && service != nullptr &&
        original != nullptr && service->InvocationValid() && original->InvocationValid() &&
        service->invocation == original->invocation &&
        service->invocationGeneration == original->invocationGeneration &&
        service->Invocation().actionFiring == root && service->PendingImmediateCohortRoot() == root &&
        service->queueInitialCohortEntryFrame == child.pendingVariableReplacementAnchorFrame &&
        playablePartitions.Owns(service->partition, service->identity) && queueToken.Valid() &&
        queueToken.slot == service->queueInstance.slot && queueToken.generation == service->queueInstance.generation;
}

bool Engine::MatchesFinishedPendingVariableCohortSides(const EngineActionPlayScratch& child,
    EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt, bool requireOpen) noexcept {
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (pendingVariableGroupReplacementActive || group == nullptr || !group->ReprepareReady() ||
        !MatchesRegisteredPendingVariableCohortReprepare(producer, attempt) ||
        FindFrontierAttempt(*this, group->reprepare_.replacementChildren) != &child ||
        !child.prepared || child.row != producer.row ||
        !MatchesPendingVariableReplacementProducer(child, producer, attempt) ||
        child.pendingVariableReplacementCut != group->cut ||
        child.pendingVariableReplacementService.token != group->reference.token ||
        child.pendingVariableReplacementService.owner != group->reference.owner ||
        child.pendingVariableReplacementService.epoch != group->reference.epoch ||
        child.pendingVariableReplacementService.invocationGeneration != group->reference.invocationGeneration)
        return false;
    const auto& row = *producer.row;
    const std::array<DecisionToken, 2> sides{row.variableControlDiscreteDecision, row.variableControlContinuousDecision};
    const std::array<BankVersionToken, 2> banks{row.variableControlDiscreteBank, row.variableControlContinuousBank};
    for (std::uint32_t side = 0; side < sides.size(); ++side) {
        const auto& lifetime = child.pendingVariableReplacementSideLifetimes[side];
        if (!sides[side].Valid()) {
            if (banks[side].Valid() || lifetime.Valid()) return false;
            continue;
        }
        auto input = group->initialDecisionInputs[side];
        input.ticket.sequence = row.ticket;
        TimelineTransactionProgramRef control{};
        if (!variableControlInstances.MatchesOriginalInitialSideReceipt(group->initialSides[side],
                row.variableControlInstance, side == 0 ? VariableControlSide::Discrete : VariableControlSide::Continuous,
                sides[side], banks[side]) || !decisions.IsOriginalDecisionLifetimePinFor(lifetime, sides[side]) ||
            !decisions.MatchesOriginalDecisionFactory(lifetime, group->initialDecisionInputs[side]) ||
            (requireOpen && !decisions.MatchesOpenReservation(sides[side], input)) ||
            !decisions.CaptureFrontierControlProgram(sides[side], &control) ||
            control.programGeneration != producer.storage.generation) return false;
    }
    return true;
}

const EngineActionPlayScratch* Engine::OriginalStagedPendingVariableCohortChildren(
    EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt) noexcept {
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (group == nullptr) return nullptr;
    const auto* child = FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
    if (child == nullptr || !MatchesFinishedPendingVariableCohortSides(*child, producer, attempt) ||
        child->storage.phase != EngineFrontierAttemptPhase::PendingVariableChildren ||
        child->directCommandsReserved ||
        child->voiceStartCount > child->voiceStarts.size() ||
        !MatchesPendingVariableReplacementTopology(*child, false) ||
        child->voiceStartCount != child->pendingVariableReplacementLeafCount) return nullptr;
    const auto& row = *producer.row;
    const std::array<DecisionToken, 2> sides{row.variableControlDiscreteDecision, row.variableControlContinuousDecision};
    const auto* links = child->playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
    if (child->variableControlChildCount == 0 ? !PendingVariableReplacementEmptyCensus(*child) : links == nullptr)
        return nullptr;
    std::array<std::uint16_t, 2> members{};
    std::array<std::uint16_t, EngineActionPlayScratch::kPendingVariableReplacementControlCapacity> nativeMembers{};
    std::uint32_t commandsCount = 0;
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& start = child->voiceStarts[index];
        const auto& leaf = child->pendingVariableReplacementLeaves[index];
        const auto& owner = child->voiceStarts.Owners()[index];
        if (leaf.side != VariableControlSide::Discrete && leaf.side != VariableControlSide::Continuous) return nullptr;
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        if (!MatchesPendingVariableReplacementControl(*child, *group, leaf.controlIndex)) return nullptr;
        const auto& control = child->pendingVariableReplacementControls[leaf.controlIndex];
        if (!start.prepared || owner.engine != this || owner.token != &start || owner.committed ||
            !owner.armCommitProof.Valid() || !owner.voiceCommitProof.Valid() || !owner.EffectsProved() ||
            (HasOriginalQueueLedgerCommit(start) ? owner.ledgerCommitProof.Valid()
                : !ledger.MatchesPreparedPlayableCommit(owner.ledgerCommitProof, start.ledgerPreparation)) ||
            start.arm.slot >= pendingVariableLeafSources.size() ||
            !MatchesPendingVariableReplacementMemberStorage(*child, index) ||
            leaf.memberOrdinal != members[side]++ || !SameCanonicalDecision(leaf.weight.decision, sides[side]) ||
            leaf.nativeMemberOrdinal != nativeMembers[leaf.controlIndex]++ ||
            !SameCanonicalDecision(start.armPreparation.parentGroup.decision, control.decision) ||
            start.armPreparation.memberIndex != leaf.nativeMemberOrdinal ||
            start.commandCount > actionPlayCommandScratch.size() - commandsCount) return nullptr;
        commandsCount += start.commandCount;
        const auto& source = pendingVariableLeafSources[start.arm.slot];
        const auto* terminal = sourceTerminals.Resolve(start.sourceTerminal);
        EnginePlayableServiceRow* resource = nullptr;
        std::size_t slot = 0;
        if (!ResolvePlayableMember(leaf.storageReference, &resource, &slot)) return nullptr;
        if (source.group != nullptr || source.cut.Valid() || source.parent != row.ownerInstance ||
            source.programGeneration != child->variableControlLeafHandles[index] ||
            source.preparedStartFrame != child->pendingVariableReplacementAnchorFrame + leaf.authoredOffset ||
            !SameOriginalSingleArm(source.arm, start.arm) || !source.source.Valid() || !source.body.Valid() ||
            terminal == nullptr || terminal->leaf != leaf.storageReference.leaf ||
            terminal->acceptedEpoch != leaf.storageReference.leafEpoch || terminal->render != start.renderHandle ||
            terminal->release.slot != start.releaseObserver.slot ||
            terminal->release.targetSequence != start.releaseObserver.targetSequence ||
            terminal->controller != resource->rootInstance || ResolveSourceResourceOwner(terminal->resourceOwner) != resource ||
            !playableInstances.MatchesPreparedOriginalAncestry(*links, source.programGeneration, row.ownerInstance) ||
            !variables.MatchesPreparedTimelineReadUse(start.initialVariableReadUse, group->cut, start.renderHandle,
                owner.armCommitProof, originalSourceSubmissions, leaf.authoredOffset)) return nullptr;
        for (std::uint32_t prior = 0; prior < index; ++prior)
            if (child->voiceStarts[prior].arm.slot == start.arm.slot ||
                child->voiceStarts[prior].renderHandle == start.renderHandle ||
                (child->voiceStarts[prior].initialVariableReadUse.slot == start.initialVariableReadUse.slot &&
                 child->voiceStarts[prior].initialVariableReadUse.generation == start.initialVariableReadUse.generation))
                return nullptr;
    }
    if (child->queueFutureAttemptCount > child->storage.queueFutureAttempts.size()) return nullptr;
    const auto addCommands = [&](const EngineActionPlayScratch& future) noexcept {
        if (future.queueSuccessorVoiceStartCount > future.queueSuccessorVoiceStarts.size()) return false;
        for (std::uint32_t voice = 0; voice < future.queueSuccessorVoiceStartCount; ++voice) {
            const auto& start = future.queueSuccessorVoiceStarts[voice];
            if (!start.prepared || !ValidatePreparedTimelineVoiceStartRoutingV1(*this, start) ||
                start.commandCount > actionPlayCommandScratch.size() - commandsCount) return false;
            commandsCount += start.commandCount;
        }
        if (future.queueSourceCommandCount > actionPlayCommandScratch.size() - commandsCount) return false;
        commandsCount += future.queueSourceCommandCount;
        return true;
    };
    if (!addCommands(*child)) return nullptr;
    for (std::uint32_t index = 0; index < child->queueFutureAttemptCount; ++index) {
        const auto* future = FindFrontierAttempt(*this, child->storage.queueFutureAttempts[index]);
        if (future == nullptr || !future->queueFutureExecution ||
            FindFrontierAttempt(*this, future->queueFutureParent) != child || !addCommands(*future)) return nullptr;
    }
    return commandsCount == child->pendingVariableReplacementCommandCount ? child : nullptr;
}

bool Engine::MatchesPendingVariableReplacementBatch(const EngineActionPlayScratch& child,
    const EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt) noexcept {
    if (!MatchesPendingVariableReplacementProducer(child, producer, attempt)) return false;
    if (attempt.privateVcProducerCount == 0) {
        if (child.pendingVariableReplacementCommandCount == 0)
            return child.voiceStartCount == 0 && !child.directCommandsReserved && !preparedVoiceCommandBatchProof.Valid();
        return child.directCommandsReserved && commands.PreparedBatchMatches(preparedVoiceCommandBatchProof,
            &child.directCommandReservation, child.pendingVariableReplacementCommandCount);
    }
    if (child.directCommandsReserved || !MatchesRegisteredPendingVariableCohortReprepare(producer, attempt))
        return false;
    const auto* head = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    if (head == nullptr || head->row == nullptr) return false;
    const auto& root = acceptedPendingVariableGroups[head->row->identity.slot].reprepare_;
    if (root.replacementCommandCount == 0 ? root.replacementCommandsReserved || preparedVoiceCommandBatchProof.Valid()
        : !root.replacementCommandsReserved || !commands.PreparedBatchMatches(preparedVoiceCommandBatchProof,
            &root.replacementCommandReservation, root.replacementCommandCount)) return false;
    auto token = attempt.privateVcProducerHead;
    std::uint32_t count = 0;
    bool found = false;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        const auto* member = FindFrontierAttempt(*this, token);
        if (member == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*member, attempt)) return false;
        const auto& group = acceptedPendingVariableGroups[member->row->identity.slot];
        const auto* prepared = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (prepared != nullptr) {
            if (!MatchesPendingVariableReplacementProducer(*prepared, *member, attempt) ||
                prepared->pendingVariableReplacementCut != group.cut || prepared->directCommandsReserved ||
                prepared->pendingVariableReplacementCommandCount > root.replacementCommandCount - count) return false;
            count += prepared->pendingVariableReplacementCommandCount;
            found |= prepared == &child && member == &producer;
        } else if (group.reprepare_.replacementChildren.Valid() || member->row->pendingCancellationIntent == 0) return false;
        token = group.reprepare_.cohortNext;
    }
    return !token.Valid() && found && count == root.replacementCommandCount;
}

bool Engine::MatchesPendingVariableReplacementLane(const EngineActionPlayScratch& child,
    const EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt) noexcept {
    if (!MatchesPendingVariableReplacementProducer(child, producer, attempt) || !attempt.lane.Valid() ||
        child.pendingVariableReplacementLane.slot != attempt.lane.slot ||
        child.pendingVariableReplacementLane.generation != attempt.lane.generation) return false;
    if (attempt.privateVcProducerCount == 0)
        return child.pendingVariableReplacementPlacedEventCount == child.pendingVariableReplacementDemand.events;
    if (!MatchesRegisteredPendingVariableCohortReprepare(producer, attempt)) return false;
    const auto* head = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    const auto& root = acceptedPendingVariableGroups[head->row->identity.slot].reprepare_;
    if (root.replacementLane.slot != attempt.lane.slot || root.replacementLane.generation != attempt.lane.generation ||
        root.replacementDemand.events == 0 || root.replacementDemand.events > pendingImmediateLaneEventsScratch.size() ||
        child.pendingVariableReplacementPlacedEventCount != root.replacementDemand.events) return false;
    ImmediateLaneDemand total{};
    auto token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        const auto* member = FindFrontierAttempt(*this, token);
        if (member == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*member, attempt)) return false;
        const auto& group = acceptedPendingVariableGroups[member->row->identity.slot];
        const auto* candidate = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (candidate != nullptr) {
            const auto& demand = candidate->pendingVariableReplacementDemand;
            if (!MatchesPendingVariableReplacementProducer(*candidate, *member, attempt) ||
                candidate->pendingVariableReplacementLane.slot != attempt.lane.slot ||
                candidate->pendingVariableReplacementLane.generation != attempt.lane.generation ||
                candidate->pendingVariableReplacementPlacedEventCount != root.replacementDemand.events ||
                demand.events > root.replacementDemand.events - total.events ||
                demand.groups > root.replacementDemand.groups - total.groups ||
                demand.members > root.replacementDemand.members - total.members ||
                demand.buckets > root.replacementDemand.buckets - total.buckets) return false;
            total.events += demand.events;
            total.groups += demand.groups;
            total.members += demand.members;
            total.buckets += demand.buckets;
        } else if (group.reprepare_.replacementChildren.Valid() || member->row->pendingCancellationIntent == 0) return false;
        token = group.reprepare_.cohortNext;
    }
    return !token.Valid() && total.events == root.replacementDemand.events && total.groups == root.replacementDemand.groups &&
        total.members == root.replacementDemand.members && total.buckets == root.replacementDemand.buckets;
}

bool Engine::PrepareRegisteredPendingVariableCohortCommandBatch(EngineImmediateEntryAttempt& attempt) noexcept {
    if (pendingVariableGroupReplacementActive || preparedVoiceCommandBatchProof.Valid() || attempt.lane.Valid() ||
        attempt.producerAbortPending) return false;
    auto* head = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    if (head == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*head, attempt)) return false;
    auto& root = acceptedPendingVariableGroups[head->row->identity.slot].reprepare_;
    if (root.replacementCommandsReserved || root.replacementCommandCount != 0) return false;
    auto token = attempt.privateVcProducerHead;
    std::uint32_t count = 0;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto* producer = FindFrontierAttempt(*this, token);
        if (producer == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*producer, attempt)) return false;
        const auto& group = acceptedPendingVariableGroups[producer->row->identity.slot];
        if (!group.ReprepareReady()) return false;
        if (producer->row->pendingCancellationIntent != 0) {
            if (group.reprepare_.replacementChildren.Valid()) return false;
        } else {
            const auto* child = OriginalStagedPendingVariableCohortChildren(*producer, attempt);
            if (child == nullptr) return false;
            for (std::uint32_t leaf = 0; leaf < child->voiceStartCount; ++leaf) {
                const auto& start = child->voiceStarts[leaf];
                if (start.commandCount == 0 || start.commandCount > start.commands.size() ||
                    start.commandCount > actionPlayCommandScratch.size() - count) return false;
                const auto& source = pendingVariableLeafSources[start.arm.slot];
                const auto& header = start.commands[0];
                // Reject a foreign header before it can overwrite the native Source body.
                if (header.opcode != kOpcodePlay ||
                    !SameOriginalSingleArm(OriginalSourceSubmissionRegistry::TokenOf(header), start.arm) ||
                    header.payload.play.batch.batchCommandCount != start.commandCount ||
                    !originalSourceSubmissions.IsOriginalSourceLifetimePinFor(source.source, start.arm) ||
                    !voices.IsOriginalSourceBodyLifetimePinFor(source.body, start.arm,
                        header.payload.play.sourceIdentity)) return false;
                std::copy_n(start.commands.begin(), start.commandCount, actionPlayCommandScratch.begin() + count);
                count += start.commandCount;
            }
            if (!AppendPreparedQueueFutureCommands(*this, *child, count)) return false;
        }
        token = group.reprepare_.cohortNext;
    }
    if (token.Valid()) return false;
    if (count == 0) return true;
    if (!AdmitCommandBatch(*this, count) ||
        !commands.ReserveBatch(count, &root.replacementCommandReservation)) return false;
    root.replacementCommandsReserved = true;
    root.replacementCommandCount = count;
    if (!PrepareVoiceCommandBatch(*this, &root.replacementCommandReservation,
            {actionPlayCommandScratch.data(), count})) {
        commands.CancelReservedBatch(&root.replacementCommandReservation);
        preparedVoiceCommandBatchProof.Release();
        root.replacementCommandsReserved = false;
        root.replacementCommandCount = 0;
        return false;
    }
    const auto refuse = [&]() noexcept {
        (void)CancelRegisteredPendingVariableCohortCommandBatch(attempt);
        return false;
    };
    token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto& producer = *FindFrontierAttempt(*this, token);
        const auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr) {
            if (!MatchesPendingVariableReplacementBatch(*child, producer, attempt) ||
                !PreparePendingReplacementQueueCurrentFactoryOutputs(*this, *child, producer, attempt)) return refuse();
            for (std::uint32_t leaf = 0; leaf < child->voiceStartCount; ++leaf) {
                const auto& start = child->voiceStarts[leaf];
                const auto& owner = child->voiceStarts.Owners()[leaf];
                const auto& source = pendingVariableLeafSources[start.arm.slot];
                if (!originalSourceSubmissions.MatchesPreparedInitialGroupSourcePair(source.source, source.body,
                        owner.armCommitProof, owner.voiceCommitProof, start.voicePreparation,
                        preparedVoiceCommandBatchProof, start.arm, source.sourceIdentity)) return refuse();
            }
        }
        token = group.reprepare_.cohortNext;
    }
    return !token.Valid() ? true : refuse();
}

bool Engine::CancelRegisteredPendingVariableCohortCommandBatch(const EngineImmediateEntryAttempt& attempt) noexcept {
    auto* head = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    if (head == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*head, attempt)) return false;
    auto& root = acceptedPendingVariableGroups[head->row->identity.slot].reprepare_;
    if (!root.replacementCommandsReserved) return root.replacementCommandCount == 0;
    if (!commands.PreparedBatchMatches(preparedVoiceCommandBatchProof,
            &root.replacementCommandReservation, root.replacementCommandCount)) return false;
    auto token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto* producer = FindFrontierAttempt(*this, token);
        if (producer == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*producer, attempt)) return false;
        const auto& group = acceptedPendingVariableGroups[producer->row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr) {
            if (!MatchesPendingVariableReplacementProducer(*child, *producer, attempt)) return false;
            ReleasePreparedTimelineVoiceProofs(*child);
        } else if (group.reprepare_.replacementChildren.Valid()) return false;
        token = group.reprepare_.cohortNext;
    }
    if (token.Valid() || !commands.CancelReservedBatchExact(&root.replacementCommandReservation)) return false;
    preparedVoiceCommandBatchProof.Release();
    root.replacementCommandsReserved = false;
    root.replacementCommandCount = 0;
    return true;
}

bool Engine::CanClosePendingVariableCohortGroup(const OriginalPendingVariableGroupHolder& group) noexcept {
    const auto& abort = group.boundAbort;
    if (abort.captured) {
        if (abort.attempt == nullptr || !abort.attempt->producerAbortClosing ||
            abort.attemptGeneration != abort.attempt->generation || abort.storage == nullptr ||
            abort.storageGeneration != abort.storage->generation || abort.queueCount > abort.queues.size()) return false;
        for (std::uint32_t index = 0; index < abort.queueCount; ++index) {
            const auto& queue = abort.queues[index];
            if (!queue.readersReturned || !queue.recordReturned || !queue.controlReturned ||
                !queue.physicalReturned || !queue.decisionsReturned || !queue.factoriesReturned) return false;
        }
    }
    const auto& issued = group.reprepare_;
    if (issued.replacementCommandsReserved || issued.replacementCommandCount != 0 ||
        issued.replacementLane.Valid() || issued.replacementDemand.events != 0) return false;
    if (issued.cohortHead == nullptr) return true;
    const auto& head = *issued.cohortHead;
    if (&group == &head) {
        for (const auto& other : acceptedPendingVariableGroups)
            if (&other != &group && other.engine == this && other.reprepare_.engine == this &&
                other.reprepare_.cohortHead == &group) return false;
    }
    return head.engine == this && head.reprepare_.cohortHead == &head &&
        head.reprepare_.cohortPhase == OriginalPendingVariableGroupHolder::InitialReprepare::CohortPhase::Closing &&
        !head.reprepare_.replacementCommandsReserved && head.reprepare_.replacementCommandCount == 0 &&
        !head.reprepare_.replacementLane.Valid() && head.reprepare_.replacementDemand.events == 0;
}

bool Engine::CapturePendingVariableReplacementQueueOwner(const EngineActionPlayScratch& child,
    const EnginePlayableServiceRow& service, FrontierOwnerIdentity* out) noexcept {
    const auto* outer = ResolvePlayableService(child.pendingVariableReplacementService);
    const auto& topology = child.pendingVariableReplacementTopology;
    if (out == nullptr || outer == nullptr || &service.Invocation() != &outer->Invocation() ||
        !topology.sealed || topology.nodeCount > topology.nodes.size()) return false;
    const auto invocation = playableInstances.Classify(outer->rootInstance);
    if (!invocation.live) return false;
    const auto end = topology.nodes.begin() + topology.nodeCount;
    const auto owner = std::find_if(topology.nodes.begin(), end,
        [&](const auto& node) { return node.handle == service.ownerInstance; });
    if (owner == end || owner->epoch != service.ownerEpoch || owner->kind != PlayableKind::Container ||
        !playableInstances.IsOriginalLifetimeCurrent(owner->original) ||
        std::count_if(topology.nodes.begin(), end,
            [&](const auto& node) { return node.handle == service.ownerInstance; }) != 1) return false;
    std::uint64_t parentEpoch = 0;
    if (owner->parent == outer->ownerInstance) {
        const auto parent = playableInstances.Classify(outer->ownerInstance);
        if (!parent.live || parent.scheduleEpoch != outer->ownerEpoch) return false;
        parentEpoch = outer->ownerEpoch;
    } else {
        const auto ancestor = std::find_if(topology.nodes.begin(), end,
            [&](const auto& node) { return node.handle == owner->parent; });
        if (ancestor == end || !playableInstances.IsOriginalLifetimeCurrent(ancestor->original) ||
            std::count_if(topology.nodes.begin(), end,
                [&](const auto& node) { return node.handle == owner->parent; }) != 1) return false;
        parentEpoch = ancestor->epoch;
    }
    const FrontierOwnerIdentity identity{service.ownerInstance, service.ownerEpoch, owner->parent, parentEpoch,
        outer->rootInstance, invocation.scheduleEpoch, service.identity.slot, service.identity.generation};
    if (!identity.Valid()) return false;
    *out = identity;
    return true;
}

bool Engine::PreparePendingVariableReplacementQueueLaneGroups(EngineActionPlayScratch& child,
    EngineActionPlayScratch& producer, EngineImmediateEntryAttempt& attempt) noexcept {
    if (!MatchesPendingVariableReplacementProducer(child, producer, attempt) ||
        !child.prepared || child.storage.phase != EngineFrontierAttemptPhase::PendingVariableChildren ||
        child.pendingVariableReplacementQueueLaneCount != 0 || attempt.lane.Valid() ||
        child.frontierQueueCount > child.storage.frontierQueues.size() ||
        child.frontierQueueCount > child.pendingVariableReplacementQueueLanes.size()) return false;
    for (std::uint32_t index = 0; index < child.frontierQueueCount; ++index) {
        auto& queue = child.storage.frontierQueues[index];
        if (!MatchesPendingVariableReplacementQueueIssuer(child, queue, attempt.root, attempt.generation)) return false;
        auto* holder = ResolvePlayableService(queue.service);
        if (holder == nullptr || &holder->Invocation() != &producer.row->Invocation() ||
            holder->PendingImmediateCohortRoot() != attempt.root || holder->queueTimingFinalized) return false;
        if (!holder->queueTimingPending || IsInitialQueueTimingOnlyCurrent(*holder)) continue;
        const bool continuation = holder->queueFirstContinuationLane;
        const bool natural = holder->QueueFiling().queueSourceControlArmCount == 1u;
        const auto groupCount = continuation && natural ? 3u : 2u;
        if (holder->QueuePayload().queueUnplacedGroupCount != groupCount ||
            (natural ? !holder->QueueFiling().queueTransition.Valid() || holder->QueueFiling().queueTransitionGroupArmCount != 2u :
                holder->QueueFiling().queueSourceControlArmCount != 0u || !continuation) ||
            holder->queueInitialCohortEntryFrame != child.pendingVariableReplacementAnchorFrame ||
            holder->QueuePayload().queueUnplacedGroupFrames[0] < child.pendingVariableReplacementAnchorFrame ||
            holder->QueuePayload().queueUnplacedGroupFrames[1] <= holder->QueuePayload().queueUnplacedGroupFrames[0]) return false;
        std::uint32_t futureMatches = 0;
        for (std::uint32_t futureIndex = 0; futureIndex < child.queueFutureAttemptCount; ++futureIndex) {
            auto* future = FindFrontierAttempt(*this, child.storage.queueFutureAttempts[futureIndex]);
            if (future == nullptr || futureIndex >= child.storage.queueFutureOwners.size()) return false;
            if (future->continuationService.token != holder->identity) continue;
            const auto& owner = child.storage.queueFutureOwners[futureIndex];
            if (owner.engine != this || owner.committed || owner.child.slot != child.storage.queueFutureAttempts[futureIndex].slot ||
                owner.child.generation != future->storage.generation ||
                owner.parent.slot != actionPlayScratch.IndexOf(child) ||
                owner.parent.generation != child.storage.generation ||
                future->queueFutureParent.slot != owner.parent.slot || future->queueFutureParent.generation != owner.parent.generation ||
                future->continuationService.owner != holder->ownerInstance ||
                future->continuationService.epoch != holder->ownerEpoch ||
                future->continuationService.invocationGeneration != holder->invocationGeneration ||
                future->continuationPartition.slot != holder->partition.slot ||
                future->continuationPartition.generation != holder->partition.generation ||
                future->queueFuturePreparedQueue != &queue.prepared || !future->prepared ||
                future->storage.phase != EngineFrontierAttemptPhase::Preparing) return false;
            ++futureMatches;
        }
        if (futureMatches != 1) return false;
        const auto offset = child.pendingVariableReplacementControlCount + 1u +
            4u * child.pendingVariableReplacementQueueLaneCount;
        if (offset + groupCount + 1u > child.pendingVariableReplacementGroups.size()) return false;
        auto& owned = child.pendingVariableReplacementQueueLanes[child.pendingVariableReplacementQueueLaneCount];
        owned.queueIndex = index;
        owned.groupOffset = static_cast<std::uint32_t>(offset);
        owned.groupCount = groupCount + 1u;
        owned.continuation = continuation;
        owned.natural = natural;
        auto* continuationRecord = continuation ? AcquireQueueContinuationRecord(*this, attempt, *holder) : nullptr;
        auto* futureRecord = continuation ? nullptr : AcquireQueueFutureRecord(*this, attempt, *holder);
        if (continuation ? continuationRecord == nullptr : futureRecord == nullptr) { owned = {}; return false; }
        owned.recordIndex = continuation ? static_cast<std::uint32_t>(continuationRecord - queueContinuationRecords.data())
            : static_cast<std::uint32_t>(futureRecord - queueFutureRecords.data());
        owned.recordGeneration = continuation ? continuationRecord->generation : futureRecord->generation;
        ++child.pendingVariableReplacementQueueLaneCount;
        auto& reservation = continuation ? continuationRecord->coordinatorReservation : futureRecord->coordinatorReservation;
        auto& armGroup = continuation ? continuationRecord->coordinatorArmGroup : futureRecord->coordinatorArmGroup;
        auto& prepared = continuation ? continuationRecord->coordinatorArmGroupPrepared : futureRecord->coordinatorArmGroupPrepared;
        auto& primary = continuation ? continuationRecord->primaryGroup : futureRecord->primaryGroup;
        DecisionReserveRequest request{};
        request.world = holder->Invocation().worldGeneration;
        request.transport = timelinePool.Epoch();
        request.expectedContinuationGeneration = attempt.generation;
        request.sliceCount = 1;
        if (!PrepareOriginalQueueDecisionReservation(request, &reservation) ||
            !armGroups.Prepare(reservation.Token(), nullptr, 0, &armGroup)) return false;
        prepared = true;
        Plan03GroupSliceInput input{};
        input.executeFrame = holder->QueuePayload().queueUnplacedGroupFrames[continuation ? 1u : 0u];
        input.decision = reservation.Token();
        input.immediateEntry = {&attempt.gate, attempt.generation};
        if (!ReserveOriginalQueueLaneGroup(attempt.root, child.pendingVariableReplacementAnchorFrame,
                input, timelineArms, &child.pendingVariableReplacementGroups[offset])) return false;
        primary = child.pendingVariableReplacementGroups[offset];
        for (std::uint32_t slice = 0; slice < groupCount; ++slice) {
            const bool initial = continuation && slice == 0;
            input = {};
            input.executeFrame = holder->QueuePayload().queueUnplacedGroupFrames[slice];
            input.decision = initial ? holder->initialQueueEntryDecision
                : continuation ? holder->QueueFiling().queueDecision : holder->initialQueueEntryDecision;
            input.sliceIndex = static_cast<std::uint16_t>(initial ? 0u : continuation ? slice - 1u : slice);
            input.members = initial ? holder->QueuePayload().queueInitialCurrentDelayedArms.data() : holder->QueueFiling().queueTransitionGroupArms.data();
            const auto members = initial ? holder->QueuePayload().queueInitialCurrentDelayedCount : holder->QueueFiling().queueTransitionGroupArmCount;
            if (members > UINT16_MAX || holder->QueueFiling().queueSourceControlArmCount > UINT16_MAX) return false;
            input.memberCount = static_cast<std::uint16_t>(members);
            input.sourceControlCount = initial ? 0u : static_cast<std::uint16_t>(holder->QueueFiling().queueSourceControlArmCount);
            input.immediateEntry = {&attempt.gate, attempt.generation};
            auto& native = child.pendingVariableReplacementGroups[offset + slice + 1u];
            if (!ReserveOriginalQueueLaneGroup(attempt.root, child.pendingVariableReplacementAnchorFrame,
                    input, timelineArms, &native)) return false;
            if (continuation) {
                (initial ? continuationRecord->prerequisiteMember : slice == 1u ?
                    continuationRecord->conditionalMember : continuationRecord->targetMember) = native;
                if (initial && !timelinePool.AcquirePlan03GroupReader(native,
                        &continuationRecord->prerequisiteMemberPin)) return false;
            } else (slice == 0 ? futureRecord->sourceMember : futureRecord->targetMember) = native;
        }
    }
    return true;
}

bool Engine::ReturnPendingVariableReplacementQueueLaneReaders(EngineActionPlayScratch& child,
    EngineImmediateEntryAttempt& attempt) noexcept {
    if (child.pendingVariableReplacementQueueLaneCount > child.pendingVariableReplacementQueueLanes.size()) return false;
    for (std::uint32_t index = 0; index < child.pendingVariableReplacementQueueLaneCount; ++index) {
        const auto& owned = child.pendingVariableReplacementQueueLanes[index];
        if (owned.queueIndex >= child.frontierQueueCount || owned.groupCount < 3u || owned.groupCount > 4u ||
            owned.groupOffset + owned.groupCount > child.pendingVariableReplacementGroups.size())
            return false;
        const auto service = child.storage.frontierQueues[owned.queueIndex].service;
        const auto release = [&](auto& record) noexcept {
            return record.occupied && record.generation == owned.recordGeneration && record.root == attempt.root &&
                record.attemptGeneration == attempt.generation && record.service == service.token &&
                record.ownerInstance == service.owner && record.ownerEpoch == service.epoch &&
                (!record.coordinator.Valid() || (decisions.IsOpen(record.coordinator) &&
                    decisions.ResolveFrontierActivation(record.coordinator) == nullptr)) &&
                (!record.coordinatorReservation.Valid() ||
                 decisions.ResolveFrontierActivation(record.coordinatorReservation.Token()) == nullptr) &&
                (!record.prerequisiteMemberPin.Valid() || record.prerequisiteMemberPin.Release(0));
        };
        if (owned.continuation ? owned.recordIndex >= queueContinuationRecords.size() || !release(queueContinuationRecords[owned.recordIndex])
            : owned.recordIndex >= queueFutureRecords.size() || !release(queueFutureRecords[owned.recordIndex])) return false;
        if (!owned.continuation) {
            auto& record = queueFutureRecords[owned.recordIndex];
            if (record.parentPin.Valid() && !record.parentPin.Release()) return false;
        }
    }
    return true;
}

bool Engine::CancelPendingVariableReplacementQueueLaneRecords(EngineActionPlayScratch& child,
    EngineImmediateEntryAttempt& attempt) noexcept {
    if (!ReturnPendingVariableReplacementQueueLaneReaders(child, attempt)) return false;
    while (child.pendingVariableReplacementQueueLaneCount != 0) {
        auto& owned = child.pendingVariableReplacementQueueLanes[child.pendingVariableReplacementQueueLaneCount - 1u];
        for (std::uint32_t native = 0; native < owned.groupCount; ++native) {
            const auto& identity = child.pendingVariableReplacementGroups[owned.groupOffset + native];
            Plan03PageGroupView live{};
            if (identity.Valid() && (timelinePool.ResolvePlan03GroupSliceProducer(identity, &live) ||
                    identity.committedRow >= originalQueueGroupHolders.size() || originalQueueGroupHolders[identity.committedRow].Valid()))
                return false;
        }
        const auto cancel = [&](auto& records, std::uint32_t& head, std::uint32_t& count) noexcept {
            auto& record = records[owned.recordIndex];
            if (record.sourceTransitionBinding.Valid()) return false;
            auto* link = &head;
            std::uint32_t traversed = 0;
            while (*link != owned.recordIndex && *link != UINT32_MAX && traversed++ < count) {
                if (*link >= records.size() || !records[*link].occupied || records[*link].root != attempt.root ||
                    records[*link].attemptGeneration != attempt.generation) return false;
                link = &records[*link].next;
            }
            if (*link != owned.recordIndex || count == 0) return false;
            if (record.coordinatorArmGroupPrepared) {
                if (!armGroups.CancelPrepared(record.coordinatorArmGroup)) return false;
                record.coordinatorArmGroupPrepared = false;
                record.coordinatorArmGroup = {};
            }
            if (record.coordinatorReservation.Valid() && !decisions.CancelPreparedReservation(&record.coordinatorReservation))
                return false;
            if (record.coordinator.Valid()) {
                if (owned.activationPrepared || owned.coordinatorCommitted ||
                    std::any_of(owned.groupBound.begin(), owned.groupBound.end(), [](bool bound) { return bound; }) ||
                    std::any_of(owned.decisionBound.begin(), owned.decisionBound.end(), [](bool bound) { return bound; })) return false;
                if (record.coordinatorArmGroup.Valid()) {
                    if (!armGroups.CancelBeforePublication(record.coordinatorArmGroup)) return false;
                    record.coordinatorArmGroup = {};
                }
                auto* baseline = ResolveOriginalSingleDecisionBaseline(this, decisions, record.coordinator);
                if (baseline == nullptr || (decisions.IsOpen(record.coordinator) && !decisions.Cancel(record.coordinator)) ||
                    !decisions.ReclaimCancelled(record.coordinator, baseline)) return false;
                record.coordinator = {};
            }
            *link = record.next;
            --count;
            record.primaryGroup = {};
            record.prerequisiteMember = {};
            record.descriptor = {};
            record.service = {};
            record.queue = {};
            record.memberDecision = {};
            record.initialDecision = {};
            record.ownerInstance = 0;
            record.ownerEpoch = 0;
            record.root = 0;
            record.attemptGeneration = 0;
            record.next = UINT32_MAX;
            record.occupied = false;
            return true;
        };
        if (owned.continuation ? !cancel(queueContinuationRecords, attempt.queueContinuationHead, attempt.queueContinuationCount)
            : !cancel(queueFutureRecords, attempt.queueFutureHead, attempt.queueFutureCount)) return false;
        if (owned.continuation) {
            auto& record = queueContinuationRecords[owned.recordIndex];
            record.conditionalMember = {};
            record.targetMember = {};
            record.version = {};
            record.failed = false;
            record.abortRetireCommittedCoordinator = false;
        } else {
            auto& record = queueFutureRecords[owned.recordIndex];
            record.sourceMember = {};
            record.targetMember = {};
        }
        for (std::uint32_t native = 0; native < owned.groupCount; ++native)
            child.pendingVariableReplacementGroups[owned.groupOffset + native] = {};
        owned = {};
        --child.pendingVariableReplacementQueueLaneCount;
    }
    return true;
}

bool Engine::PreparePendingVariableGroupLaneEvents(EngineActionPlayScratch& producer,
    EngineImmediateEntryAttempt& attempt, std::uint32_t firstEvent) noexcept {
    const auto* scope = activePendingVariableGroupReplacement_;
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    auto* child = group == nullptr ? nullptr : FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
    const bool registered = attempt.privateVcProducerCount != 0;
    if (group == nullptr || child == nullptr || !group->ReprepareReady() || attempt.lane.Valid() ||
        (registered ? !MatchesFinishedPendingVariableCohortSides(*child, producer, attempt) :
        (!pendingVariableGroupReplacementActive || scope == nullptr ||
        scope->group_ != group || scope->producer_ != &producer || scope->attempt_ != &attempt ||
        scope->producerGeneration_ != producer.storage.generation || scope->attemptGeneration_ != attempt.generation ||
        scope->cut_ != group->cut))) return false;
    if (child->storage.phase != EngineFrontierAttemptPhase::PendingVariableChildren ||
        !child->prepared || child->row != producer.row || child->pendingVariableReplacementCut != group->cut ||
        !MatchesPendingVariableReplacementProducer(*child, producer, attempt) ||
        child->pendingVariableReplacementLane.Valid() || child->pendingVariableReplacementCoordinator.Valid() ||
        child->pendingVariableReplacementLeafCount != child->voiceStartCount ||
        child->voiceStartCount > child->pendingVariableReplacementLeaves.size()) return false;
    const auto& row = *producer.row;
    const std::array<DecisionToken, 2> sides{row.variableControlDiscreteDecision, row.variableControlContinuousDecision};
    const auto anchor = child->pendingVariableReplacementAnchorFrame;
    const auto nextSides = registered ? sides : scope->next_;
    std::array<std::uint16_t, EngineActionPlayScratch::kPendingVariableReplacementControlCapacity> counts{};
    std::array<std::array<TimelineArmToken, kMaxKnownScheduleLeaves>, 2> arms{};
    std::array<TimelineTransactionProgramRef, EngineActionPlayScratch::kPendingVariableReplacementControlCapacity> controls{};
    if (child->pendingVariableReplacementControlCount < 2u ||
        child->pendingVariableReplacementControlCount > counts.size() ||
        child->pendingVariableReplacementControlCount > child->pendingVariableReplacementControls.size() ||
        child->pendingVariableReplacementControlCount >= child->pendingVariableReplacementGroups.size()) return false;
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& mirror = child->pendingVariableReplacementLeaves[index];
        const auto side = mirror.side == VariableControlSide::Discrete ? 0u : 1u;
        const auto controlIndex = mirror.controlIndex;
        if ((!registered && (!scope->sides_[side] || !(*scope->held_)[side].Valid() ||
            !(*scope->proofs_)[side].Valid() || !SameCanonicalDecision((*scope->proofs_)[side].Token(), nextSides[side]))) ||
            !MatchesPendingVariableReplacementControl(*child, *group, controlIndex) ||
            !MatchesPendingVariableReplacementMemberStorage(*child, index) ||
            child->pendingVariableReplacementAnchorFrame != anchor || mirror.nativeMemberOrdinal != counts[controlIndex] ||
            !SameCanonicalDecision(child->voiceStarts[index].armPreparation.parentGroup.decision,
                child->pendingVariableReplacementControls[controlIndex].decision) ||
            child->voiceStarts[index].armPreparation.memberIndex != counts[controlIndex]) return false;
        if (controlIndex < 2u) arms[controlIndex][counts[controlIndex]] = child->voiceStarts[index].arm;
        ++counts[controlIndex];
    }
    std::uint32_t sideCount = 0;
    for (std::uint32_t index = 0; index < child->pendingVariableReplacementControlCount; ++index) {
        auto& control = child->pendingVariableReplacementControls[index];
        if (!control.decision.Valid()) {
            if (index >= 2u || counts[index] != 0) return false;
            continue;
        }
        if (!MatchesPendingVariableReplacementControl(*child, *group, index) ||
            !decisions.CaptureFrontierControlProgram(control.decision, &controls[index]) ||
            controls[index].program == nullptr || controls[index].programGeneration != producer.storage.generation)
            return false;
        if (index >= 2u) {
            Plan03PageGroupView native{};
            ArmGroupSnapshot held{};
            if (!SameCanonicalDecision(child->pendingVariableReplacementGroups[index + 1u].decision, control.decision) ||
                !timelinePool.ResolvePlan03GroupSliceProducer(child->pendingVariableReplacementGroups[index + 1u], &native) ||
                native.memberCount != counts[index] || counts[index] != control.nativeMemberCount ||
                !armGroups.Capture(control.armGroup, &held) ||
                !SameCanonicalDecision(held.parent, control.decision) || held.memberCount != counts[index] ||
                held.ackedCount != 0 || held.tombstonedCount != 0 || held.maxTombstoneSequence != 0) return false;
            for (std::uint32_t leaf = 0; leaf < child->voiceStartCount; ++leaf) {
                const auto& mirror = child->pendingVariableReplacementLeaves[leaf];
                if (mirror.controlIndex != index) continue;
                ArmGroupMemberSnapshot member{};
                if (native.members == nullptr || mirror.nativeMemberOrdinal >= native.memberCount ||
                    !armGroups.CaptureMember(control.armGroup, mirror.nativeMemberOrdinal, &member) ||
                    member.acked || member.tombstoned ||
                    !SameOriginalSingleArm(native.members[mirror.nativeMemberOrdinal], child->voiceStarts[leaf].arm) ||
                    !SameOriginalSingleArm(member.token, child->voiceStarts[leaf].arm)) return false;
            }
        } else control.nativeMemberCount = counts[index];
        ++sideCount;
    }
    const auto refuse = []() noexcept { return false; };
    for (std::uint32_t side = 0; side < nextSides.size(); ++side) {
        if (!nextSides[side].Valid()) continue;
        if (registered) continue;
        const auto* baseline = ResolveOriginalSingleDecisionBaseline(this, decisions, nextSides[side]);
        if (baseline == nullptr || !baseline->Borrow(&child->pendingVariableReplacementSideLifetimes[side]))
            return refuse();
    }
    DecisionReserveRequest coordinatorInput{};
    coordinatorInput.world = row.Invocation().worldGeneration;
    coordinatorInput.transport = timelinePool.Epoch();
    coordinatorInput.expectedContinuationGeneration = producer.storage.generation;
    coordinatorInput.sliceCount = 1;
    if (!PrepareOriginalDecisionReservation(coordinatorInput, &child->pendingVariableReplacementCoordinator))
        return refuse();
    const auto coordinator = child->pendingVariableReplacementCoordinator.Token();
    const auto* coordinatorProgram = decisions.PrepareFrontierControlProgram(coordinator, producer.storage.generation);
    if (coordinatorProgram == nullptr) return refuse();
    auto& groups = child->pendingVariableReplacementGroups;
    Plan03GroupSliceInput input{};
    input.executeFrame = anchor;
    input.decision = coordinator;
    input.immediateEntry = {&attempt.gate, attempt.generation};
    if (!ReserveOriginalQueueLaneGroup(attempt.root, anchor, input, timelineArms, &groups[0])) return refuse();
    for (std::uint32_t side = 0; side < nextSides.size(); ++side) {
        if (!nextSides[side].Valid()) continue;
        input.decision = nextSides[side];
        input.members = arms[side].data();
        input.memberCount = counts[side];
        if (!ReserveOriginalQueueLaneGroup(attempt.root, anchor, input, timelineArms, &groups[side + 1u]))
            return refuse();
    }
    if (!PreparePendingVariableReplacementQueueLaneGroups(*child, producer, attempt)) return refuse();
    std::uint32_t currentQueues = 0, queueGroups = 0;
    for (std::uint32_t index = 0; index < child->pendingVariableReplacementQueueLaneCount; ++index) {
        const auto& owned = child->pendingVariableReplacementQueueLanes[index];
        currentQueues += owned.continuation;
        queueGroups += owned.groupCount;
    }
    std::uint32_t eventCount = 1u + sideCount + child->voiceStartCount + currentQueues;
    std::uint32_t memberCount = child->voiceStartCount;
    const auto owner = playableInstances.Classify(row.ownerInstance);
    const auto parent = playableInstances.Classify(owner.parent);
    const auto root = playableInstances.Classify(row.rootInstance);
    const FrontierOwnerIdentity identity{row.ownerInstance, row.ownerEpoch,
        owner.parent, owner.parent == 0 ? 0 : parent.scheduleEpoch, row.rootInstance, root.scheduleEpoch,
        row.identity.slot, row.identity.generation};
    auto& descriptor = child->frontierDescriptor;
    descriptor = {};
    descriptor.entry = {coordinator, producer.storage.generation, identity};
    descriptor.primary = groups[0];
    descriptor.worldGeneration = row.Invocation().worldGeneration;
    descriptor.worldSemanticFingerprint = row.root.expectedProgramSemanticFingerprint;
    descriptor.programGeneration = coordinatorProgram->generation;
    descriptor.expectedMemberCount = sideCount + currentQueues;
    auto& events = pendingImmediateLaneEventsScratch;
    if (firstEvent > events.size() || eventCount > events.size() - firstEvent) return refuse();
    std::uint32_t written = 0;
    const auto addEvent = [&](TimelineTransactionProgramRef program, TimelineArmToken arm,
        const Plan03GroupSliceIdentity& nativeGroup, const FrontierOwnerIdentity& controlOwner,
        const EngineActionPlayScratch::PendingVariableReplacementLeaf* leaf) {
        auto& lane = events[firstEvent + written];
        lane = {};
        lane.relativeFrame = leaf == nullptr ? 0 : leaf->authoredOffset;
        lane.futureGroupedStart = lane.relativeFrame != 0;
        lane.armProgramGeneration = leaf == nullptr ? 0 : leaf->program.programGeneration;
        auto& event = lane.event;
        event.logicCommitSequence = row.ticket;
        event.executionOrdinal = row.Invocation().actionExecutionOrdinal;
        event.eventIndex = written;
        event.transactionOrdinal = written;
        event.subeventPhase = leaf == nullptr ? 10u : 20u;
        event.rowSequence = written + 1u;
        event.armToken = arm;
        event.frontier.kind = lane.futureGroupedStart ? FrontierOperationKind::Dependent : FrontierOperationKind::Entry;
        event.frontier.entry = descriptor.entry;
        event.frontier.owner = controlOwner;
        event.frontier.group = nativeGroup;
        event.frontier.transport = timelinePool.Epoch();
        event.frontier.world = descriptor.worldGeneration;
        event.frontier.operationEventCount = 1;
        event.frontier.entryEventOrdinal = descriptor.expectedEntryEventCount;
        if (!lane.futureGroupedStart) ++descriptor.expectedEntryEventCount;
        event.transactionId = row.ticket;
        event.program = program;
        event.ownerInstanceHandle = leaf == nullptr ? controlOwner.child : leaf->storageReference.leaf;
        event.ownerInstanceScheduleEpoch = leaf == nullptr ? controlOwner.childEpoch : leaf->storageReference.leafEpoch;
        event.frozenTxnValid = true;
        ++written;
    };
    addEvent({coordinatorProgram->generation, coordinatorProgram}, {}, groups[0], identity, nullptr);
    std::array<FrontierOwnerIdentity, EngineActionPlayScratch::kPendingVariableReplacementControlCapacity> identities{};
    for (std::uint32_t index = 0; index < child->pendingVariableReplacementControlCount; ++index) {
        const auto& control = child->pendingVariableReplacementControls[index];
        if (!control.decision.Valid()) continue;
        if (!CapturePendingVariableReplacementControlOwner(*child, index, &identities[index])) return refuse();
        addEvent(controls[index], {}, groups[index + 1u], identities[index], nullptr);
    }
    for (std::uint32_t index = 0; index < child->pendingVariableReplacementQueueLaneCount; ++index) {
        const auto& owned = child->pendingVariableReplacementQueueLanes[index];
        if (!owned.continuation) continue;
        if (owned.recordIndex >= queueContinuationRecords.size()) return refuse();
        const auto& record = queueContinuationRecords[owned.recordIndex];
        const auto* holder = ResolvePlayableService(record.service, record.ownerInstance, record.ownerEpoch);
        FrontierOwnerIdentity queueOwner{};
        const auto* control = decisions.PrepareFrontierControlProgram(record.initialDecision, attempt.generation);
        if (holder == nullptr || control == nullptr || firstEvent + written >= events.size() ||
            !CapturePendingVariableReplacementQueueOwner(*child, *holder, &queueOwner)) return refuse();
        addEvent({control->generation, control}, {}, record.prerequisiteMember, queueOwner, nullptr);
    }
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& leaf = child->pendingVariableReplacementLeaves[index];
        addEvent(leaf.program, child->voiceStarts[index].arm,
            groups[leaf.controlIndex + 1u], identities[leaf.controlIndex], &leaf);
    }
    const auto& event = events[firstEvent].event;
    descriptor.order = {anchor, event.logicCommitSequence, event.executionOrdinal, event.eventIndex,
        event.transactionOrdinal, event.subeventPhase, event.rowSequence};
    for (std::uint32_t queueIndex = 0; queueIndex < child->pendingVariableReplacementQueueLaneCount; ++queueIndex) {
        const auto& owned = child->pendingVariableReplacementQueueLanes[queueIndex];
        auto borrowed = BorrowQueueLaneRecord(*this, owned.continuation, owned.recordIndex);
        if (!borrowed) return refuse();
        auto& record = *borrowed;
        auto* holder = ResolvePlayableService(record.service, record.ownerInstance, record.ownerEpoch);
        if (holder == nullptr || !record.coordinatorReservation.Valid() || record.coordinator.Valid() ||
            record.generation != owned.recordGeneration || record.root != attempt.root ||
            record.attemptGeneration != attempt.generation ||
            (owned.continuation && !record.prerequisiteMemberPin.Valid()) ||
            holder->QueuePayload().queueUnplacedGroupFrames[owned.continuation ? 1u : 0u] <= anchor) return refuse();
        const auto* control = decisions.PrepareFrontierControlProgram(record.coordinatorReservation.Token(), attempt.generation);
        FrontierOwnerIdentity queueOwner{};
        if (control == nullptr || !CapturePendingVariableReplacementQueueOwner(*child, *holder, &queueOwner)) return refuse();
        auto& next = record.descriptor;
        next = {};
        next.entry = {record.coordinatorReservation.Token(), attempt.generation, queueOwner};
        next.primary = record.primaryGroup;
        next.worldGeneration = holder->Invocation().worldGeneration;
        next.worldSemanticFingerprint = holder->root.expectedProgramSemanticFingerprint;
        next.programGeneration = control->generation;
        next.expectedMemberCount = 1;
        next.expectedEntryEventCount = owned.natural ? 2u : 1u;
        next.order = {holder->QueuePayload().queueUnplacedGroupFrames[owned.continuation ? 1u : 0u], row.ticket, row.Invocation().actionExecutionOrdinal,
            0, 0, 10, firstEvent + written + 1u};
        if (!CapturePendingVariableQueueTimingOrdinal(*holder, next.order.executeFrame,
                &next.order.executionOrdinal)) return refuse();
        if (!next.Valid() || firstEvent + written >= events.size()) return refuse();
        auto& controller = events[firstEvent + written++];
        controller = {};
        controller.relativeFrame = next.order.executeFrame - anchor;
        auto& key = controller.event;
        key.logicCommitSequence = row.ticket;
        key.executionOrdinal = next.order.executionOrdinal;
        key.subeventPhase = 10;
        key.rowSequence = next.order.rowSequence;
        key.transactionId = row.ticket;
        key.program = {control->generation, control};
        key.ownerInstanceHandle = queueOwner.child;
        key.ownerInstanceScheduleEpoch = queueOwner.childEpoch;
        key.frozenTxnValid = true;
        key.frontier.kind = FrontierOperationKind::Entry;
        key.frontier.entry = next.entry;
        key.frontier.owner = queueOwner;
        key.frontier.group = next.primary;
        key.frontier.transport = timelinePool.Epoch();
        key.frontier.world = next.worldGeneration;
        key.frontier.entryEventOrdinal = 0;
        key.frontier.operationEventCount = next.expectedEntryEventCount;
        auto* bank = holder->QueueFiling().queueSuccessorProgramBank;
        if (bank == nullptr || !bank->occupied || bank->published || bank->programCount > bank->schedules.size()) return refuse();
        std::uint32_t starts = 0, targetEvents = 0, sourceEvents = 0;
        for (std::uint32_t programIndex = 0; programIndex < bank->programCount; ++programIndex) {
            const auto& schedule = bank->schedules[programIndex];
            const auto* program = schedule.runtimeProgram.program;
            if ((schedule.eventCount != 1 && schedule.eventCount != 2) || schedule.events == nullptr ||
                program == nullptr || program->payloads == nullptr || program->role != TimelineProgramRole::Voice) return refuse();
            for (std::uint32_t eventIndex = 0; eventIndex < schedule.eventCount; ++eventIndex) {
            const auto& frozen = schedule.events[eventIndex];
            if (frozen.frameOffsetFromEntry < 0 || frozen.payload >= program->payloadCount) return refuse();
            const auto* payload = &program->payloads[frozen.payload];
            const bool startEvent = eventIndex == 0 && payload->kind == TimelineEventKind::Start;
            const bool fadeEvent = eventIndex == 1 && payload->kind == TimelineEventKind::Envelope &&
                payload->envelopeDirection == TimelineEnvelopeDirection::FadeIn && holder->QueueFiling().queueTransition.Valid();
            const bool sourceEvent = owned.natural &&
                schedule.runtimeProgram.programGeneration == holder->QueueFiling().queueSourceSchedule.runtimeProgram.programGeneration &&
                schedule.runtimeProgram.program == holder->QueueFiling().queueSourceSchedule.runtimeProgram.program &&
                SameOriginalSingleArm(schedule.armToken, holder->QueueFiling().queueTransitionGroupArms[0]) && schedule.eventCount == 1 &&
                eventIndex == 0 && payload->kind == TimelineEventKind::Envelope &&
                payload->envelopeDirection == TimelineEnvelopeDirection::FadeOut &&
                payload->reserved == kTimelineEventTransientControlArm;
            if ((!startEvent && !fadeEvent && !sourceEvent) || firstEvent + written >= events.size()) return refuse();
            TimelineEventPayload* originalPayload = nullptr;
            for (std::uint32_t payloadIndex = 0; payloadIndex < bank->eventCount; ++payloadIndex)
                if (&bank->payloads[payloadIndex] == payload) originalPayload = &bank->payloads[payloadIndex];
            if (originalPayload == nullptr || (!sourceEvent && originalPayload->reserved != 0 &&
                    originalPayload->reserved != kTimelineEventTransientStartArm)) return refuse();
            if (!sourceEvent && holder->QueueFiling().queueTransition.Valid() && owned.continuation) {
                if (originalPayload->reserved != 0) return refuse();
            } else if (startEvent) originalPayload->reserved = kTimelineEventTransientStartArm;
            const auto offset = static_cast<std::uint64_t>(frozen.frameOffsetFromEntry);
            if (offset > UINT64_MAX - schedule.entryAnchorFrame) return refuse();
            const auto absoluteExecute = schedule.entryAnchorFrame + offset;
            if (absoluteExecute < anchor || absoluteExecute < next.order.executeFrame) return refuse();
            const auto relative = absoluteExecute - anchor;
            auto& lane = events[firstEvent + written++];
            lane = {};
            lane.relativeFrame = relative;
            lane.futureGroupedStart = startEvent;
            lane.armProgramGeneration = schedule.runtimeProgram.programGeneration;
            auto& start = lane.event;
            start.logicCommitSequence = row.ticket;
            start.executionOrdinal = frozen.executionOrdinal;
            start.eventIndex = frozen.eventIndex;
            start.transactionOrdinal = frozen.transactionOrdinal;
            start.subeventPhase = frozen.subeventPhase;
            start.rowSequence = firstEvent + written;
            start.armToken = frozen.armToken;
            start.program = schedule.runtimeProgram;
            start.payload = frozen.payload;
            start.transactionId = schedule.transactionId;
            start.ownerInstanceHandle = schedule.ownerInstance;
            start.ownerInstanceScheduleEpoch = schedule.ownerInstanceScheduleEpoch;
            start.authoredFadeOutCandidate = frozen.authoredFadeOutCandidate;
            start.frozenTxnValid = true;
            start.frontier.kind = FrontierOperationKind::Dependent;
            start.frontier.entry = next.entry;
            start.frontier.owner = queueOwner;
            start.frontier.group = owned.natural && !sourceEvent ? record.targetMember : record.conditionalMember;
            start.frontier.transport = timelinePool.Epoch();
            start.frontier.world = next.worldGeneration;
            start.frontier.entryEventOrdinal = sourceEvent ? 1u : owned.natural ? targetEvents :
                holder->QueueFiling().queueTransition.Valid() ? 1u + targetEvents : targetEvents;
            start.frontier.operationEventCount = sourceEvent ? 2u :
                owned.natural ? schedule.eventCount : 1u;
            sourceEvents += sourceEvent;
            targetEvents += !sourceEvent;
            starts += startEvent;
            }
        }
        if (sourceEvents != (owned.natural ? 1u : 0u) ||
            starts + sourceEvents != holder->QueueFiling().queueTransitionGroupArmCount || starts != 1) return refuse();
        if (holder->QueueFiling().queueTransition.Valid() && !owned.natural) {
            next.expectedEntryEventCount = 1u + targetEvents;
            for (std::uint32_t ordinal = firstEvent; ordinal < firstEvent + written; ++ordinal)
                if (events[ordinal].event.frontier.entry == next.entry)
                    events[ordinal].event.frontier.operationEventCount = next.expectedEntryEventCount;
        }
        eventCount += 1u + targetEvents + sourceEvents;
        memberCount += owned.natural ? 4u : starts;
    }
    child->pendingVariableReplacementDemand = {eventCount,
        1u + sideCount + queueGroups, memberCount, eventCount};
    return written == eventCount && descriptor.Valid();
}

bool Engine::DeclarePendingVariableGroupLane(EngineActionPlayScratch& child,
    EngineImmediateEntryAttempt& attempt, std::uint32_t placedEventCount) noexcept {
    child.pendingVariableReplacementLane = attempt.lane;
    child.pendingVariableReplacementPlacedEventCount = placedEventCount;
    for (std::uint32_t slot = 0; slot <= child.pendingVariableReplacementControlCount; ++slot) {
        const auto& nativeGroup = child.pendingVariableReplacementGroups[slot];
        if (nativeGroup.Valid() &&
            (!timelinePool.BindImmediateLaneGroupOwner(nativeGroup, immediateActionLane,
                attempt.root, attempt.lane.slot, attempt.lane.generation) ||
             !immediateActionLane.DeclareGroup(attempt.lane, {nativeGroup, 0}))) return false;
    }
    for (std::uint32_t index = 0; index < child.voiceStartCount; ++index) {
        const auto& leaf = child.pendingVariableReplacementLeaves[index];
        ImmediateLaneMemberManifest member{};
        if (leaf.controlIndex >= child.pendingVariableReplacementControlCount) return false;
        member.group = child.pendingVariableReplacementGroups[leaf.controlIndex + 1u];
        member.arm = child.voiceStarts[index].arm;
        member.memberIndex = leaf.nativeMemberOrdinal;
        member.future = leaf.authoredOffset != 0;
        member.relativeFrame = leaf.authoredOffset;
        member.programGeneration = leaf.program.programGeneration;
        member.target = leaf.target;
        member.ownerInstance = leaf.storageReference.leaf;
        member.ownerEpoch = leaf.storageReference.leafEpoch;
        if (!immediateActionLane.DeclareMember(attempt.lane, member)) return false;
    }
    for (std::uint32_t index = 0; index < child.pendingVariableReplacementQueueLaneCount; ++index) {
        const auto& owned = child.pendingVariableReplacementQueueLanes[index];
        auto borrowed = BorrowQueueLaneRecord(*this, owned.continuation, owned.recordIndex);
        if (!borrowed) return false;
        const auto& record = *borrowed;
        auto* holder = ResolvePlayableService(record.service, record.ownerInstance, record.ownerEpoch);
        if (holder == nullptr || record.generation != owned.recordGeneration || !record.descriptor.Valid()) return false;
        for (std::uint32_t native = 0; native < owned.groupCount; ++native) {
            const auto& identity = child.pendingVariableReplacementGroups[owned.groupOffset + native];
            const auto executeFrame = native == 0u ? record.descriptor.order.executeFrame :
                holder->QueuePayload().queueUnplacedGroupFrames[native - 1u];
            if (executeFrame < child.pendingVariableReplacementAnchorFrame) return false;
            const auto relative = executeFrame - child.pendingVariableReplacementAnchorFrame;
            if (!timelinePool.BindImmediateLaneGroupOwner(identity, immediateActionLane,
                    attempt.root, attempt.lane.slot, attempt.lane.generation) ||
                !immediateActionLane.DeclareGroup(attempt.lane, {identity, relative})) return false;
        }
        std::uint32_t members = 0;
        for (std::uint32_t eventIndex = 0; eventIndex < placedEventCount; ++eventIndex) {
            const auto& event = pendingImmediateLaneEventsScratch[eventIndex];
            if (event.event.frontier.entry != record.descriptor.entry || !event.event.armToken.Valid()) continue;
            const auto* program = event.event.program.program;
            if (program == nullptr || program->payloads == nullptr ||
                event.event.payload >= program->payloadCount) return false;
            const auto& payload = program->payloads[event.event.payload];
            const bool sourceEvent = owned.natural && payload.kind == TimelineEventKind::Envelope &&
                payload.envelopeDirection == TimelineEnvelopeDirection::FadeOut;
            if (payload.kind == TimelineEventKind::Envelope && !sourceEvent) continue;
            const auto declare = [&](ImmediateLaneMemberKind kind, const Plan03GroupSliceIdentity& group,
                const Plan03GroupSliceIdentity& related, std::uint16_t ordinal, std::uint16_t span) noexcept {
                ImmediateLaneMemberManifest member{};
                member.kind = kind;
                member.group = group;
                member.relatedGroup = related;
                member.arm = event.event.armToken;
                member.memberIndex = ordinal;
                member.eventSpanCount = span;
                member.relativeFrame = event.relativeFrame;
                member.programGeneration = event.armProgramGeneration;
                member.target = payload.target;
                member.ownerInstance = event.event.ownerInstanceHandle;
                member.ownerEpoch = event.event.ownerInstanceScheduleEpoch;
                return immediateActionLane.DeclareMember(attempt.lane, member);
            };
            if (owned.natural) {
                if (sourceEvent) {
                    if (event.futureGroupedStart ||
                        !declare(ImmediateLaneMemberKind::CurrentEventSpan, record.conditionalMember, {}, 0u, 1u) ||
                        !declare(ImmediateLaneMemberKind::HistoricalSourceCompletion, record.targetMember,
                            record.conditionalMember, 0u, 1u)) return false;
                } else {
                    if (payload.kind != TimelineEventKind::Start || !event.futureGroupedStart ||
                        !declare(ImmediateLaneMemberKind::FrozenFutureTarget, record.conditionalMember,
                            record.targetMember, 1u, static_cast<std::uint16_t>(program->payloadCount)) ||
                        !declare(ImmediateLaneMemberKind::CurrentEventSpan, record.targetMember, {}, 1u,
                            static_cast<std::uint16_t>(program->payloadCount))) return false;
                }
                ++members;
                continue;
            }
            if (payload.kind != TimelineEventKind::Start || !event.futureGroupedStart) return false;
            ImmediateLaneMemberManifest member{};
            member.group = record.conditionalMember;
            member.arm = event.event.armToken;
            member.memberIndex = static_cast<std::uint16_t>(members++);
            member.future = !holder->QueueFiling().queueTransition.Valid();
            if (holder->QueueFiling().queueTransition.Valid()) {
                member.kind = ImmediateLaneMemberKind::CurrentEventSpan;
                if (program->payloadCount == 0 || program->payloadCount > 2) return false;
                member.eventSpanCount = static_cast<std::uint16_t>(program->payloadCount);
            }
            member.relativeFrame = event.relativeFrame;
            member.programGeneration = event.armProgramGeneration;
            member.target = program->payloads[event.event.payload].target;
            member.ownerInstance = event.event.ownerInstanceHandle;
            member.ownerEpoch = event.event.ownerInstanceScheduleEpoch;
            if (!immediateActionLane.DeclareMember(attempt.lane, member)) return false;
        }
        if (members != holder->QueueFiling().queueTransitionGroupArmCount) return false;
    }
    return true;
}

bool Engine::PrepareRegisteredPendingVariableCohortLane(EngineImmediateEntryAttempt& attempt,
    PrivateImmediateLanePlacementProof* placement) noexcept {
    auto* head = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    if (head == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*head, attempt) ||
        pendingVariableGroupReplacementActive || attempt.producerAbortPending || attempt.lane.Valid() ||
        placement == nullptr || placement->Valid()) return false;
    auto& root = acceptedPendingVariableGroups[head->row->identity.slot].reprepare_;
    if ((root.replacementCommandCount == 0
            ? root.replacementCommandsReserved || preparedVoiceCommandBatchProof.Valid()
            : !root.replacementCommandsReserved) ||
        root.replacementLane.Valid() || root.replacementDemand.events != 0)
        return false;
    const auto refuse = [&]() noexcept {
        placement->Release();
        (void)CancelRegisteredPendingVariableCohortLane(attempt);
        return false;
    };
    ImmediateLaneDemand total{};
    std::uint64_t anchor = 0;
    auto token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto* producer = FindFrontierAttempt(*this, token);
        if (producer == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*producer, attempt)) return refuse();
        const auto& group = acceptedPendingVariableGroups[producer->row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr) {
            if (OriginalStagedPendingVariableCohortChildren(*producer, attempt) != child ||
                !MatchesPendingVariableReplacementBatch(*child, *producer, attempt) ||
                !PreparePendingVariableGroupLaneEvents(*producer, attempt, total.events)) return refuse();
            const auto& demand = child->pendingVariableReplacementDemand;
            const auto childAnchor = child->frontierDescriptor.order.executeFrame;
            if ((total.events != 0 && childAnchor != anchor) || demand.events > UINT32_MAX - total.events ||
                demand.groups > UINT32_MAX - total.groups || demand.members > UINT32_MAX - total.members ||
                demand.buckets > UINT32_MAX - total.buckets) return refuse();
            anchor = childAnchor;
            total.events += demand.events;
            total.groups += demand.groups;
            total.members += demand.members;
            total.buckets += demand.buckets;
        } else if (group.reprepare_.replacementChildren.Valid() || producer->row->pendingCancellationIntent == 0)
            return refuse();
        token = group.reprepare_.cohortNext;
    }
    if (token.Valid() || total.events == 0 || total.events > pendingImmediateLaneEventsScratch.size() ||
        !ReserveOriginalImmediateEntryLane(attempt, total, true)) return refuse();
    root.replacementLane = attempt.lane;
    root.replacementDemand = total;
    token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto& producer = *FindFrontierAttempt(*this, token);
        const auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr && !DeclarePendingVariableGroupLane(*child, attempt, total.events)) return refuse();
        token = group.reprepare_.cohortNext;
    }
    if (!immediateActionLane.Prepare(attempt.lane, pendingImmediateLaneEventsScratch.data(), total.events) ||
        !immediateActionLane.TryPlaceExactPrivate(attempt.lane, anchor, placement) ||
        !timelinePool.RebaseImmediateLaneGroups(attempt.root, anchor)) return refuse();
    return true;
}

bool Engine::CancelRegisteredPendingVariableCohortLane(EngineImmediateEntryAttempt& attempt) noexcept {
    auto* head = FindFrontierAttempt(*this, attempt.privateVcProducerHead);
    if (head == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*head, attempt)) return false;
    auto& root = acceptedPendingVariableGroups[head->row->identity.slot].reprepare_;
    auto& census = initialQueueLaneGroupsScratch;
    std::size_t expectedGroups = 0;
    auto token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto* producer = FindFrontierAttempt(*this, token);
        if (producer == nullptr || !MatchesRegisteredPendingVariableCohortReprepare(*producer, attempt)) return false;
        auto& group = acceptedPendingVariableGroups[producer->row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr) {
            if (!MatchesPendingVariableReplacementProducer(*child, *producer, attempt)) return false;
            for (const auto& native : child->pendingVariableReplacementGroups) {
                if (!native.Valid()) continue;
                if (native.committedRow >= originalQueueGroupHolders.size() ||
                    !timelinePool.IsOriginalQueueFutureGroupRegistrationFor(
                        originalQueueGroupHolders[native.committedRow], native, attempt.root)) return false;
                ++expectedGroups;
            }
        } else if (group.reprepare_.replacementChildren.Valid()) return false;
        token = group.reprepare_.cohortNext;
    }
    if (token.Valid()) return false;
    if (expectedGroups == 0 && !root.replacementLane.Valid()) {
        token = attempt.privateVcProducerHead;
        for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
            auto& producer = *FindFrontierAttempt(*this, token);
            auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
            auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
            if (child != nullptr) {
                if (!CancelPendingVariableReplacementQueueLaneRecords(*child, attempt)) return false;
                std::fill(child->pendingVariableReplacementGroups.begin(), child->pendingVariableReplacementGroups.end(),
                    Plan03GroupSliceIdentity{});
                child->pendingVariableReplacementLane = {};
                child->pendingVariableReplacementPlacedEventCount = 0;
            }
            token = group.reprepare_.cohortNext;
        }
        root.replacementDemand = {};
        return CancelRegisteredPendingVariableCohortCommandBatch(attempt);
    }
    const auto count = timelinePool.CaptureLiveImmediateLaneCohortGroups(attempt.root, census.data(), census.size());
    if (count != expectedGroups || count > census.size()) return false;
    for (std::size_t native = 0; native < count; ++native) {
        std::uint32_t matches = 0;
        token = attempt.privateVcProducerHead;
        for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
            auto& producer = *FindFrontierAttempt(*this, token);
            const auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
            const auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
            if (child != nullptr)
                matches += static_cast<std::uint32_t>(std::count(child->pendingVariableReplacementGroups.begin(),
                    child->pendingVariableReplacementGroups.end(), census[native].identity));
            token = group.reprepare_.cohortNext;
        }
        if (matches != 1) return false;
    }
    if (root.replacementLane.Valid()) {
        if (attempt.lane.slot != root.replacementLane.slot || attempt.lane.generation != root.replacementLane.generation)
            return false;
        // Retry a partial PinGroups rollback; Retire proves all remaining lane pins returned.
        if (immediateActionLane.PrivatePinGroupCount(attempt.lane) != 0)
            (void)immediateActionLane.ReleasePrivatePinGroupOwnership(attempt.lane, timelinePool);
        if (!immediateActionLane.Cancel(attempt.lane) ||
            !RetireOriginalImmediateEntryLane(attempt, mixer.BlocksRendered())) return false;
        attempt.lane = {};
        root.replacementLane = {};
    }
    // Lane publication readers return before unbinding the PendingApply admission.
    token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto& producer = *FindFrontierAttempt(*this, token);
        auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr && (!CancelPrivatePendingVariableGroupEntry(group, *child) ||
                !ReturnPendingVariableReplacementQueueLaneReaders(*child, attempt))) return false;
        token = group.reprepare_.cohortNext;
    }
    const bool groupsReturned = expectedGroups == 0 || CancelOriginalQueueLaneGroups(attempt.root, mixer.BlocksRendered());
    const auto remaining = timelinePool.CaptureLiveImmediateLaneCohortGroups(attempt.root, census.data(), census.size());
    if (remaining > expectedGroups || remaining > census.size()) return false;
    std::size_t kept = 0;
    token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto& producer = *FindFrontierAttempt(*this, token);
        const auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr) {
            for (auto& identity : child->pendingVariableReplacementGroups) {
                if (!identity.Valid()) continue;
                std::size_t matches = 0;
                for (std::size_t native = 0; native < remaining; ++native)
                    matches += census[native].identity == identity;
                if (matches == 1) { ++kept; continue; }
                Plan03PageGroupView returned{};
                if (matches != 0 || timelinePool.ResolvePlan03GroupSliceProducer(identity, &returned) ||
                    originalQueueGroupHolders[identity.committedRow].Valid()) return false;
                // The exact native cancellation above returned this original registration.
                identity = {};
            }
        }
        token = group.reprepare_.cohortNext;
    }
    if (kept != remaining || !groupsReturned || remaining != 0) return false;
    token = attempt.privateVcProducerHead;
    for (std::uint32_t index = 0; index < attempt.privateVcProducerCount; ++index) {
        auto& producer = *FindFrontierAttempt(*this, token);
        const auto& group = acceptedPendingVariableGroups[producer.row->identity.slot];
        auto* child = FindFrontierAttempt(*this, group.reprepare_.replacementChildren);
        if (child != nullptr) {
            if (!CancelPendingVariableReplacementQueueLaneRecords(*child, attempt)) return false;
            std::fill(child->pendingVariableReplacementGroups.begin(), child->pendingVariableReplacementGroups.end(),
                Plan03GroupSliceIdentity{});
            child->pendingVariableReplacementLane = {};
            child->pendingVariableReplacementPlacedEventCount = 0;
        }
        token = group.reprepare_.cohortNext;
    }
    root.replacementDemand = {};
    return CancelRegisteredPendingVariableCohortCommandBatch(attempt);
}

bool Engine::PreparePendingVariableGroupLane(EngineActionPlayScratch& producer,
    EngineImmediateEntryAttempt& attempt, PrivateImmediateLanePlacementProof* placement) noexcept {
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (group == nullptr || attempt.privateVcProducerCount != 0 || placement == nullptr || placement->Valid()) return false;
    const auto refuse = [&]() noexcept {
        placement->Release();
        (void)CancelPendingVariableGroupChildren(*group);
        return false;
    };
    if (!PreparePendingVariableGroupLaneEvents(producer, attempt, 0)) return refuse();
    auto& child = *FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
    const auto written = child.pendingVariableReplacementDemand.events;
    const auto anchor = child.frontierDescriptor.order.executeFrame;
    if (!ReserveOriginalImmediateEntryLane(attempt, child.pendingVariableReplacementDemand, true)) return refuse();
    if (!DeclarePendingVariableGroupLane(child, attempt, written)) return refuse();
    if (!immediateActionLane.Prepare(attempt.lane, pendingImmediateLaneEventsScratch.data(), written)) return refuse();
    if (!immediateActionLane.TryPlaceExactPrivate(attempt.lane, anchor, placement)) return refuse();
    if (!timelinePool.RebaseImmediateLaneGroups(attempt.root, anchor)) return refuse();
    return true;
}

const EngineActionPlayScratch* Engine::OriginalPreparedPendingVariableGroupChildren(
    EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt,
    const PrivateImmediateLanePlacementProof& placement) noexcept {
    const auto* scope = activePendingVariableGroupReplacement_;
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    const auto* child = group == nullptr ? nullptr : FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
    const bool registered = attempt.privateVcProducerCount != 0;
    if (group == nullptr || child == nullptr || !group->ReprepareReady() ||
        (registered ? !MatchesFinishedPendingVariableCohortSides(*child, producer, attempt) :
        (!pendingVariableGroupReplacementActive || scope == nullptr ||
        scope->group_ != group || scope->producer_ != &producer || scope->attempt_ != &attempt ||
        scope->producerGeneration_ != producer.storage.generation || scope->attemptGeneration_ != attempt.generation ||
        scope->cut_ != group->cut)) ||
        !immediateActionLane.IsPrivatePlacementProofFor(placement, attempt.lane, attempt.root)) return nullptr;
    std::uint64_t anchor = 0;
    if (child == nullptr || child->storage.phase != EngineFrontierAttemptPhase::PendingVariableChildren ||
        !child->prepared || child->row != producer.row || child->pendingVariableReplacementCut != group->cut ||
        child->pendingVariableReplacementService.token != group->reference.token ||
        !MatchesPendingVariableReplacementProducer(*child, producer, attempt) ||
        child->pendingVariableReplacementLane.slot != attempt.lane.slot ||
        child->pendingVariableReplacementLane.generation != attempt.lane.generation ||
        child->voiceStartCount > child->voiceStarts.size() ||
        child->voiceStartCount != child->pendingVariableReplacementLeafCount ||
        !MatchesPendingVariableReplacementTopology(*child, false) ||
        !MatchesPendingVariableReplacementBatch(*child, producer, attempt) ||
        !MatchesPendingVariableReplacementLane(*child, producer, attempt) ||
        !placement.CaptureAnchorFrame(&anchor)) return nullptr;
    const std::array<DecisionToken, 2> sides = registered
        ? std::array<DecisionToken, 2>{producer.row->variableControlDiscreteDecision, producer.row->variableControlContinuousDecision}
        : scope->next_;
    const auto* links = child->playableTreeExecutor.OriginalPreparedParentLinks(playableInstances);
    if (child->variableControlChildCount == 0 ? !PendingVariableReplacementEmptyCensus(*child) : links == nullptr)
        return nullptr;
    std::array<std::uint16_t, 2> members{};
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& leaf = child->pendingVariableReplacementLeaves[index];
        const auto& start = child->voiceStarts[index];
        const auto& owner = child->voiceStarts.Owners()[index];
        if (leaf.side != VariableControlSide::Discrete && leaf.side != VariableControlSide::Continuous) return nullptr;
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        if ((!registered && (!scope->sides_[side] || !(*scope->held_)[side].Valid() ||
            !(*scope->proofs_)[side].Valid() || !SameCanonicalDecision((*scope->proofs_)[side].Token(), sides[side]) ||
            (*scope->proofs_)[side].Sequence() != producer.row->ticket)) || !start.prepared ||
            !start.initialVariableReadUse.Valid() || start.arm.slot >= pendingVariableLeafSources.size() ||
            leaf.memberOrdinal != members[side]++ || leaf.authoredOffset > UINT64_MAX - anchor ||
            child->pendingVariableReplacementAnchorFrame != anchor || !MatchesPendingVariableReplacementMemberStorage(*child, index) ||
            leaf.program.programGeneration != start.armPreparation.programGeneration ||
            !MatchesPendingVariableReplacementControl(*child, *group, leaf.controlIndex) ||
            !SameCanonicalDecision(start.armPreparation.parentGroup.decision,
                child->pendingVariableReplacementControls[leaf.controlIndex].decision) ||
            start.armPreparation.memberIndex != leaf.nativeMemberOrdinal) return nullptr;
        const auto& source = pendingVariableLeafSources[start.arm.slot];
        if (source.group != nullptr || source.cut.Valid() || source.parent != producer.row->ownerInstance ||
            start.ledgerPreparation.parent.internalToken != source.parent ||
            source.programGeneration != child->variableControlLeafHandles[index] ||
            source.preparedStartFrame != anchor + leaf.authoredOffset ||
            !OriginalSourceSubmissionRegistry::SameToken(source.arm, start.arm) ||
            !playableInstances.MatchesPreparedOriginalAncestry(*links, source.programGeneration, source.parent) ||
            !originalSourceSubmissions.MatchesPreparedInitialGroupSourcePair(source.source, source.body,
                owner.armCommitProof, owner.voiceCommitProof, start.voicePreparation,
                preparedVoiceCommandBatchProof, start.arm, source.sourceIdentity)) return nullptr;
        const auto nativeUse = voices.TimelineVariableSourceRead(start.arm.renderSlot, start.arm.renderGeneration);
        if (nativeUse.slot != start.initialVariableReadUse.slot ||
            nativeUse.generation != start.initialVariableReadUse.generation) return nullptr;
        for (std::uint32_t previous = 0; previous < index; ++previous)
            if (child->voiceStarts[previous].arm.slot == start.arm.slot ||
                child->voiceStarts[previous].renderHandle == start.renderHandle ||
                (child->voiceStarts[previous].initialVariableReadUse.slot == start.initialVariableReadUse.slot &&
                 child->voiceStarts[previous].initialVariableReadUse.generation == start.initialVariableReadUse.generation))
                return nullptr;
    }
    return child;
}

bool Engine::CommitPrivatePendingVariableGroupSources(EngineActionPlayScratch& producer,
    const EngineImmediateEntryAttempt& attempt, const PrivateImmediateLanePlacementProof& placement) noexcept {
    VariableReadCutReader reader;
    if (!variables.BeginPreparedPendingVariableGroupPlacement(*this, producer, attempt, placement, &reader)) return false;
    const auto* prepared = OriginalPreparedPendingVariableGroupChildren(producer, attempt, placement);
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (prepared == nullptr || group == nullptr) return false;
    for (std::uint32_t index = 0; index < prepared->voiceStartCount; ++index)
        if (!variables.PendingTimelineReadUseFrozen(prepared->voiceStarts[index].initialVariableReadUse)) return false;
    auto* child = FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
    if (child != prepared) return false;
    child->storage.phase = EngineFrontierAttemptPhase::PendingVariableChildrenSourcesCommitting;
    if (child->voiceStartCount == 0 &&
        (!MatchesPendingVariableReplacementTopology(*child, false) ||
         !child->storage.ownerLedger.Validate(child->storage.generation))) {
        (void)CancelPendingVariableGroupChildren(*group);
        return false;
    }
    if (!child->playableTreeExecutor.Commit(playableInstances, producer.row->ticket) ||
        !PublishCommittedQueueFutureRootLinks(*this, *child)) {
        (void)CancelPendingVariableGroupChildren(*group);
        return false;
    }
    if (child->voiceStartCount == 0 && !child->frontierOwnerBatchRegistered &&
        !child->storage.ownerLedger.Commit(child->storage.generation, producer.row->ticket)) {
        (void)CancelPendingVariableGroupChildren(*group);
        return false;
    }
    for (std::uint32_t index = 0; index < child->variableControlContainerRowCount; ++index) {
        const auto container = child->variableControlContainerRows[index].Instance();
        ContainerPlaybackRow controller{};
        if (!containerPlayback.Capture(container, &controller)) {
            (void)CancelPendingVariableGroupChildren(*group);
            return false;
        }
        if (controller.mode == static_cast<std::uint8_t>(ContainerModeV1::VariableControl)) continue;
        PlayableInstanceHandle active = 0;
        for (std::uint32_t policy = 0; policy < child->frontierPolicyCount; ++policy) {
            const auto& node = child->storage.frontierPolicies[policy];
            if (node.parent == container) {
                if (active != 0) { (void)CancelPendingVariableGroupChildren(*group); return false; }
                active = node.instance;
            }
        }
        if (active == 0 || !containerPlayback.SetActiveChild(container, active, playableInstances.Classify(active).scheduleEpoch)) {
            (void)CancelPendingVariableGroupChildren(*group);
            return false;
        }
    }
    child->storage.phase = EngineFrontierAttemptPhase::PendingVariableChildrenSourcesPrivateCommitted;
    if (OriginalPrivateCommittedPendingVariableGroupChildren(producer, attempt, placement) == child) return true;
    (void)CancelPendingVariableGroupChildren(*group);
    return false;
}

const EngineActionPlayScratch* Engine::OriginalPrivateCommittedPendingVariableGroupChildren(
    EngineActionPlayScratch& producer, const EngineImmediateEntryAttempt& attempt,
    const PrivateImmediateLanePlacementProof& placement) noexcept {
    auto* group = OriginalPendingVariableGroupForReprepare(producer, attempt);
    if (group == nullptr || !group->ReprepareReady() ||
        !immediateActionLane.IsPrivatePlacementProofFor(placement, attempt.lane, attempt.root)) return nullptr;
    const auto* child = FindFrontierAttempt(*this, group->reprepare_.replacementChildren);
    std::uint64_t anchor = 0;
    if (child == nullptr || child->storage.phase != EngineFrontierAttemptPhase::PendingVariableChildrenSourcesPrivateCommitted ||
        !child->prepared || child->row != producer.row || child->pendingVariableReplacementCut != group->cut ||
        child->pendingVariableReplacementService.token != group->reference.token ||
        child->pendingVariableReplacementService.owner != group->reference.owner ||
        child->pendingVariableReplacementService.epoch != group->reference.epoch ||
        child->pendingVariableReplacementService.invocationGeneration != group->reference.invocationGeneration ||
        !MatchesPendingVariableReplacementProducer(*child, producer, attempt) ||
        child->pendingVariableReplacementLane.slot != attempt.lane.slot ||
        child->pendingVariableReplacementLane.generation != attempt.lane.generation ||
        child->voiceStartCount > child->voiceStarts.size() ||
        child->voiceStartCount != child->pendingVariableReplacementLeafCount ||
        !MatchesPendingVariableReplacementTopology(*child, true) || !child->playableTreeExecutor.Committed() ||
        !MatchesPendingVariableReplacementBatch(*child, producer, attempt) ||
        !MatchesPendingVariableReplacementLane(*child, producer, attempt) ||
        !placement.CaptureAnchorFrame(&anchor)) return nullptr;
    if (!variables.MatchesPublishedPendingVariableGroupReadCut(*this, producer, attempt, *child, placement, false))
        return nullptr;
    if (child->voiceStartCount == 0 && !child->storage.ownerLedger.CanTransfer(child->storage.generation)) return nullptr;
    std::array<std::uint16_t, 2> members{};
    for (std::uint32_t index = 0; index < child->voiceStartCount; ++index) {
        const auto& leaf = child->pendingVariableReplacementLeaves[index];
        const auto& start = child->voiceStarts[index];
        const auto& owner = child->voiceStarts.Owners()[index];
        if (leaf.side != VariableControlSide::Discrete && leaf.side != VariableControlSide::Continuous) return nullptr;
        const auto side = leaf.side == VariableControlSide::Discrete ? 0u : 1u;
        if (owner.engine != this || owner.token != &start || !owner.committed || start.prepared ||
            owner.armCommitProof.Valid() || owner.ledgerCommitProof.Valid() || owner.voiceCommitProof.Valid() ||
            !start.initialVariableReadUse.Valid() || start.arm.slot >= pendingVariableLeafSources.size() ||
            leaf.memberOrdinal != members[side]++ || leaf.authoredOffset > UINT64_MAX - anchor ||
            child->pendingVariableReplacementAnchorFrame != anchor ||
            !MatchesPendingVariableReplacementMemberStorage(*child, index)) return nullptr;
        const auto& source = pendingVariableLeafSources[start.arm.slot];
        const auto instance = playableInstances.Classify(source.programGeneration);
        const auto ledgerOwner = ledger.OwnerForRender(start.renderHandle);
        const auto* native = timelineArms.Resolve(start.arm);
        if (source.group != nullptr || source.cut.Valid() || source.parent != producer.row->ownerInstance ||
            source.programGeneration != child->variableControlLeafHandles[index] ||
            source.preparedStartFrame != anchor + leaf.authoredOffset || !instance.live ||
            !MatchesPendingVariableReplacementLeafOrigin(*child, index) ||
            !ledgerOwner.live || ledgerOwner.ledgerSlot != start.ledgerSlot ||
            ledgerOwner.visibility != VoiceLedger::PublicVisibility::PlayableOwnedInternal ||
            ledgerOwner.parent.internalToken != source.parent || ledgerOwner.parent.previewHandle != 0 ||
            !MatchesPendingVariableReplacementControl(*child, *group, leaf.controlIndex) ||
            native == nullptr || native->programGeneration != source.programGeneration ||
            native->memberIndex != leaf.nativeMemberOrdinal ||
            !SameCanonicalDecision(native->parentGroup.decision,
                child->pendingVariableReplacementControls[leaf.controlIndex].decision) ||
            !originalSourceSubmissions.MatchesPrivateCommittedInitialGroupSourcePair(source.source, source.body,
                preparedVoiceCommandBatchProof, start.arm, source.sourceIdentity) ||
            !variables.MatchesPrivateCommittedTimelineReadUse(start.initialVariableReadUse, group->cut, start.renderHandle,
                timelineArms, start.arm, originalSourceSubmissions, anchor, leaf.authoredOffset)) return nullptr;
        const auto nativeUse = voices.TimelineVariableSourceRead(start.arm.renderSlot, start.arm.renderGeneration);
        if (nativeUse.slot != start.initialVariableReadUse.slot || nativeUse.generation != start.initialVariableReadUse.generation)
            return nullptr;
    }
    return child;
}

