// Releases a render slot's voice-send mirror at reuse: decrements the live count
// for each active slot, then clears the row. Called wherever a slot's per-voice
// logic mirrors are reset (each play path).
void ResetVoiceSendMirror(harken::Engine& engine, std::uint32_t slot) {
    if (slot >= engine.voiceSendConfig.size()) {
        return;
    }
    for (harken::VoiceSendConfig& c : engine.voiceSendConfig[slot]) {
        if (c.active && engine.voiceSendActive > 0) {
            --engine.voiceSendActive;
        }
    }
    engine.voiceSendConfig[slot].fill(harken::VoiceSendConfig{});
}

// Applies one voice send to a live render slot: updates the logic mirror (and
// the live count on a newly active slot), then pushes the set-voice-send
// command. Shared by the live setter and the pending/return replays. Logic
// thread only.
template <typename Writer>
void ApplyVoiceSendLiveWith(
    harken::Engine& engine, VnVoiceHandle render, std::uint32_t sendSlot,
    std::uint32_t targetBusIndex, float levelDb, Writer& writer) {
    const std::uint32_t slot = static_cast<std::uint32_t>(render);
    if (slot < engine.voiceSendConfig.size()) {
        harken::VoiceSendConfig& c = engine.voiceSendConfig[slot][sendSlot];
        if (!c.active) {
            ++engine.voiceSendActive;
        }
        c.active = true;
        c.targetBusIndex = targetBusIndex;
        c.targetBusGeneration =
            engine.buses.GenerationAt(targetBusIndex);
        c.levelDb = levelDb;
    }
    harken::CommandRecord cmd{};
    cmd.opcode = harken::kOpcodeSetVoiceSend;
    cmd.payload.setVoiceSend.handle = render;
    cmd.payload.setVoiceSend.sendSlot = sendSlot;
    cmd.payload.setVoiceSend.targetBusIndex = targetBusIndex;
    cmd.payload.setVoiceSend.targetBusGeneration =
        engine.buses.GenerationAt(targetBusIndex);
    cmd.payload.setVoiceSend.levelDb = levelDb;
    (void)writer.Push(cmd);
    UpdateSendHighWater(engine);
}

void ApplyVoiceSendLive(harken::Engine& engine, VnVoiceHandle render,
                        std::uint32_t sendSlot, std::uint32_t targetBusIndex,
                        float levelDb) {
    CommandQueueWriter writer(engine);
    ApplyVoiceSendLiveWith(engine, render, sendSlot, targetBusIndex, levelDb,
                           writer);
}

void ApplyVoiceSendLive(harken::Engine& engine, VnVoiceHandle render,
                        std::uint32_t sendSlot, std::uint32_t targetBusIndex,
                        float levelDb, AdmittedCommandWriter& writer) {
    ApplyVoiceSendLiveWith(engine, render, sendSlot, targetBusIndex, levelDb,
                           writer);
}

bool DynamicInfluenceReaches(
    harken::Engine& engine, std::uint32_t fromBus,
    std::uint32_t targetBus,
    const harken::DynamicRouteDefinition* routeReplacement) {
    const std::uint32_t count = engine.buses.BusCount();
    if (fromBus >= count || targetBus >= count) {
        return false;
    }
    std::fill_n(engine.influenceVisited.data(), count,
                static_cast<std::uint8_t>(0));
    std::uint32_t stackSize = 0;
    engine.influenceVisited[fromBus] = 1;
    engine.influenceStack[stackSize++] = fromBus;
    const std::uint32_t sendSlots = engine.config.busSendSlotsPerBus;
    while (stackSize != 0) {
        const std::uint32_t bus = engine.influenceStack[--stackSize];
        if (bus == targetBus) {
            return true;
        }
        const auto visit = [&](std::uint32_t next) {
            if (next < count && engine.influenceVisited[next] == 0) {
                engine.influenceVisited[next] = 1;
                engine.influenceStack[stackSize++] = next;
            }
        };
        if (bus != 0) {
            visit(engine.buses.ParentOf(bus));
        }
        const std::uint32_t base = bus * sendSlots;
        for (std::uint32_t slot = 0; slot < sendSlots; ++slot) {
            const std::uint32_t target = engine.busSendAdj[base + slot];
            if (target != harken::kInvalidBusIndex) {
                visit(target);
            }
        }
        bool replacementSeen = false;
        engine.dynamicRoutes.ForEachDefinition(
            [&](const harken::DynamicRouteDefinition& live) {
                const harken::DynamicRouteDefinition* selected = &live;
                if (routeReplacement != nullptr &&
                    live.tableIndex == routeReplacement->tableIndex) {
                    replacementSeen = true;
                    selected = routeReplacement;
                }
                if (selected->sourceKind == VN_DYNAMIC_SOURCE_BUS &&
                    selected->sourceIndex == bus) {
                    visit(selected->targetBusIndex);
                }
            });
        if (routeReplacement != nullptr && !replacementSeen &&
            routeReplacement->sourceKind == VN_DYNAMIC_SOURCE_BUS &&
            routeReplacement->sourceIndex == bus) {
            visit(routeReplacement->targetBusIndex);
        }
    }
    return false;
}

// The per-call session-trace hook. Tracing OFF costs exactly the recorder
// null test — the one branch per API call the trace contract allows on the
// logic thread; the stateful variant additionally closes the Vn_TraceStart
// gate with an unconditional flag store. Returned by value: the temporary's
// destructor commits the record at the end of the hook expression. Kept
// outside the extern "C" blocks: these return a C++ type and must carry C++
// language linkage.
harken::TraceCallScribe TraceQuery(harken::Engine* engine,
                                  std::uint16_t callId) noexcept {
    harken::TraceRecorder* recorder =
        (engine->trace != nullptr && engine->trace->Active())
            ? engine->trace.get()
            : nullptr;
    return harken::TraceCallScribe(recorder, callId);
}

harken::TraceCallScribe TraceStateful(harken::Engine* engine,
                                     std::uint16_t callId) noexcept {
    engine->statefulCallSeen = true;
    engine->traceOriginWorldProbeOnly = false;
    return TraceQuery(engine, callId);
}

void JournalCanonicalPackVintage2(
    harken::TraceCallScribe& trace, const harken::Engine& engine,
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t expectedContentHash, std::uint32_t providerTag,
    const std::vector<harken::PackDependencyEdge>* incomingEdges,
    VnPackHandle returnedHandle, bool recordReturnedHandle) noexcept {
    trace.U32(2)
        .U64(packStableId)
        .U64(contentRevision)
        .U64(expectedContentHash)
        .U32(providerTag)
        .U32(0);
    std::vector<std::pair<std::uint64_t, std::uint64_t>> closures;
    if (incomingEdges != nullptr) {
        const auto* published = engine.packComposition.Published();
        const harken::PackCanonicalImage* catalog =
            published != nullptr && published->hasCatalog ? &published->catalog
                                                          : nullptr;
        for (const harken::PackDependencyEdge& edge : *incomingEdges) {
            if (edge.required01 == 0 || edge.prerequisitePackStableId == 0) {
                continue;
            }
            std::uint64_t prerequisiteHash = 0;
            if (catalog != nullptr) {
                for (const auto& row : catalog->catalogRows) {
                    if (row.ownerPackStableId == edge.prerequisitePackStableId) {
                        prerequisiteHash = row.expectedContentHash;
                        break;
                    }
                }
            }
            closures.emplace_back(edge.prerequisitePackStableId,
                                  prerequisiteHash);
        }
    }
    trace.U32(static_cast<std::uint32_t>(closures.size()));
    for (const auto& closure : closures) {
        trace.U64(closure.first).U64(closure.second);
    }
    if (recordReturnedHandle) {
        trace.U64(returnedHandle);
    }
    const auto* published = engine.packComposition.Published();
    const std::uint64_t generation =
        published != nullptr ? published->compositeGeneration : 0;
    std::uint32_t ownerCount = 0;
    if (published != nullptr) {
        for (const auto& owner : published->owners) {
            if (owner.readiness == harken::PackOwnerReadiness::Active) {
                ++ownerCount;
            }
        }
    }
    trace.U64(generation).U32(ownerCount);
}

void FinishCaptureTrace(harken::TraceCallScribe& trace, VnResult result,
                        const std::uint32_t* requiredCount) noexcept {
    const std::uint32_t recordedRequired =
        result == VN_OK && requiredCount != nullptr
            ? *requiredCount
            : harken::kTraceRequiredCountUnavailable;
    trace.U32(harken::kTraceCaptureResultFeature)
        .U32(harken::kTraceCaptureResultVintage)
        .U32(static_cast<std::uint32_t>(result))
        .U32(recordedRequired);
}

void RecordCurrentWorldLoadTrace(
    harken::Engine* engine, const char* utf8Path, VnResult result,
    const VnCurrentWorldLoadReport& report,
    harken::TraceCurrentWorldImageTagV1 imageTag,
    harken::TraceCurrentWorldCaptureDispositionV1 disposition,
    bool observedLengthKnown, bool wholeArtifactHashKnown,
    std::uint64_t observedFileBytes, std::uint64_t wholeArtifactHash,
    const std::uint8_t* capturedPrefix, std::size_t capturedPrefixBytes,
    const std::uint8_t* capturedSuffix = nullptr,
    std::size_t capturedSuffixBytes = 0) noexcept {
    const std::size_t capturedBytes =
        capturedPrefixBytes + capturedSuffixBytes;
    harken::TraceCallScribe trace =
        TraceStateful(engine, harken::kTraceCallLoadCurrentWorld);
    trace.U32(1)
        .Str(utf8Path)
        .U32(static_cast<std::uint32_t>(result))
        .U32(report.structSize)
        .U32(report.status)
        .U32(static_cast<std::uint32_t>(report.result))
        .U32(report.reserved0)
        .U64(report.priorGeneration)
        .U64(report.resultGeneration)
        .U64(report.runtimeSemanticFingerprint)
        .U64(report.capabilityMask)
        .U64(report.bodyBytes)
        .U64(report.bodyChecksum)
        .U32(static_cast<std::uint32_t>(imageTag))
        .U32(static_cast<std::uint32_t>(disposition))
        .U32(observedLengthKnown ? 1u : 0u)
        .U32(wholeArtifactHashKnown ? 1u : 0u)
        .U64(observedFileBytes)
        .U64(wholeArtifactHash)
        .U64(capturedBytes)
        .Bytes(capturedPrefix, capturedPrefixBytes)
        .Bytes(capturedSuffix, capturedSuffixBytes);
}

