bool ObserveCurrentPlaybackPaths(
    void (*visitor)(const PlaybackPathObservation&, void*), void* context) noexcept {
    const Engine* engine = detail::ActiveEngine();
    if (engine == nullptr || visitor == nullptr) return false;
    for (const auto& path : engine->playbackPaths) {
        if (path.pathRowCount == 0) continue;
        const auto state = engine->voices.RenderedState(path.voiceInstance);
        if (state != VN_VOICE_STATE_ACTIVE && state != VN_VOICE_STATE_DRAINING) continue;
        const auto owner = engine->ledger.OwnerForRender(path.voiceInstance);
        if (owner.live && owner.visibility == VoiceLedger::PublicVisibility::PlayableOwnedInternal) {
            const auto observation = path.Capture();
            visitor(observation, context);
        }
    }
    return true;
}

VnResult RefreshPreviewVoiceBindings(std::uint64_t render) noexcept {
    Engine* engine = detail::ActiveEngine();
    if (engine == nullptr || engine->callbackFatalSticky) return VN_NOT_INITIALIZED;
    const auto owner = engine->ledger.OwnerForRender(render);
    if (!owner.live || owner.visibility != VoiceLedger::PublicVisibility::PlayableOwnedInternal
        || engine->voices.CheckLive(render) != VN_OK) return VN_STALE_HANDLE;
    CompletionMutationBinding binding{};
    const bool allowPitch = engine->ledger.CaptureCompletionMutationForSlot(owner.ledgerSlot, &binding)
        && !CompletionMutationBindingBlocks(*engine, binding);
    return engine->params.RefreshPreviewBindings(render, engine->bindings, allowPitch)
        ? VN_OK : VN_BACKPRESSURE;
}

VnResult SetPreviewVoiceProperty(std::uint64_t render,
    playableproperties::PlayablePropertyIdV1 property, float value,
    VnObjectId sendBusId) noexcept {
    Engine* engine = detail::ActiveEngine();
    if (engine == nullptr || engine->callbackFatalSticky) return VN_NOT_INITIALIZED;
    if (!std::isfinite(value)) return VN_INVALID_ARG;
    const auto owner = engine->ledger.OwnerForRender(render);
    if (!owner.live || owner.visibility != VoiceLedger::PublicVisibility::PlayableOwnedInternal
        || engine->voices.CheckLive(render) != VN_OK) return VN_STALE_HANDLE;
    using Property = playableproperties::PlayablePropertyIdV1;
    std::uint32_t target = kBuiltinTargetCount;
    float direct = value;
    switch (property) {
    case Property::Volume:
        target = kTargetVoiceVolume;
        direct -= engine->params.AuthoredBase(render, target);
        if (!TryVolumeGainFromDb(engine->params.ReduceWithSlot(render, target, kSlotApiDirect, direct)))
            return VN_INVALID_ARG;
        break;
    case Property::Pitch: {
        if (value < -7200.0f || value > 7200.0f) return VN_INVALID_ARG;
        target = kTargetVoicePitch;
        direct -= engine->params.AuthoredBase(render, target);
        CompletionMutationBinding binding{};
        if (!engine->ledger.CaptureCompletionMutationForSlot(owner.ledgerSlot, &binding)
            || CompletionMutationBindingBlocks(*engine, binding)) return VN_BACKPRESSURE;
        break;
    }
    case Property::SpatialPanning:
        if (value < -1.0f || value > 1.0f) return VN_INVALID_ARG;
        target = kTargetVoicePan;
        break;
    case Property::SpatialSpread:
        if (!IsValidAuthoredSpreadPercent(value)) return VN_INVALID_ARG;
        target = kTargetVoiceWidth;
        direct = AuthoredSpreadPercentToRuntimeWidth(value);
        break;
    case Property::SpatializationMix:
        if (value < 0.0f || value > 1.0f) return VN_INVALID_ARG;
        break;
    case Property::OutputBusVolume:
        if (!TryVolumeGainFromDb(value)) return VN_INVALID_ARG;
        break;
    case Property::SpatialAttenuationDistanceScaling:
        if (value < 0.01f || value > 100.0f) return VN_INVALID_ARG;
        engine->spatial.SetVoiceDistanceScale(render, value);
        return VN_OK;
    case Property::Sends: {
        if (!TryVolumeGainFromDb(value)) return VN_INVALID_ARG;
        auto& path = engine->playbackPaths[static_cast<std::uint32_t>(render)];
        for (std::uint32_t slot = 0; slot < path.sendCount; ++slot) {
            if (path.sends[slot].targetBusId != sendBusId) continue;
            const auto& pinned = engine->timelineVoiceInstallIdentities[static_cast<std::uint32_t>(render)].voiceSends;
            if (slot >= pinned.size()) return VN_INVALID_ARG;
            if (!AdmitSingleCommand(*engine)) return VN_BACKPRESSURE;
            ApplyVoiceSendLive(*engine, render, slot, pinned[slot].targetBusIndex, value);
            path.sends[slot].levelDb = value;
            return VN_OK;
        }
        return VN_UNKNOWN_ID;
    }
    default:
        return VN_INVALID_ARG;
    }
    if (target < kBuiltinTargetCount && engine->params.ForeignClaim(render, target))
        return VN_BACKPRESSURE;
    if (!AdmitSingleCommand(*engine)) return VN_BACKPRESSURE;
    constexpr std::uint32_t rampMs = 10;
    const float resolved = target < kBuiltinTargetCount
        ? engine->params.SetApiDirect(render, target, direct,
            property == Property::Volume ? rampMs : 0) : value;
    CommandRecord command{};
    switch (property) {
    case Property::Volume:
    case Property::OutputBusVolume:
        command.opcode = kOpcodeSetVoiceVolume;
        command.payload.setVoiceVolume.handle = render;
        command.payload.setVoiceVolume.volumeDb = resolved;
        command.payload.setVoiceVolume.rampMs = rampMs;
        command.payload.setVoiceVolume.outputOnly = property == Property::OutputBusVolume;
        break;
    case Property::Pitch:
        command.opcode = kOpcodeSetVoicePitch;
        command.payload.setVoicePitch.handle = render;
        command.payload.setVoicePitch.ratio = WireRatioFromCents(resolved);
        break;
    case Property::SpatialPanning: {
        const auto gains = ResolvePanGains(engine->config.mixChannelLayout, resolved);
        command.opcode = kOpcodeSetVoicePan;
        command.payload.setVoicePan.handle = render;
        command.payload.setVoicePan.pan = gains.pan;
        command.payload.setVoicePan.pan2d = engine->params.ReduceWithSlot(
            render, harken::kTargetVoicePan, harken::kSlotAttenuation, 0.0f);
        command.payload.setVoicePan.gain0 = gains.gain0;
        command.payload.setVoicePan.gain1 = gains.gain1;
        command.payload.setVoicePan.channel0 = gains.channel0;
        command.payload.setVoicePan.channel1 = gains.channel1;
        break;
    }
    case Property::SpatialSpread:
        command.opcode = kOpcodeSetVoiceSpatialScalar;
        command.payload.setVoiceSpatialScalar.handle = render;
        command.payload.setVoiceSpatialScalar.kind = kSpatialScalarKindWidth;
        command.payload.setVoiceSpatialScalar.value = resolved;
        break;
    case Property::SpatializationMix:
        command.opcode = kOpcodeSetVoiceSpatialScalar;
        command.payload.setVoiceSpatialScalar.handle = render;
        command.payload.setVoiceSpatialScalar.kind =
            kSpatialScalarKindSpatializationMix;
        command.payload.setVoiceSpatialScalar.value = resolved;
        engine->spatial.SetVoiceSpatializationMix(render, resolved);
        break;
    default:
        return VN_INVALID_ARG;
    }
    (void)engine->commands.TryPush(command);
    return VN_OK;
}

void RecordPreviewPlayPlayable(
    bool argsReadable, std::uint32_t structSize, std::uint32_t kind,
    VnObjectId stableId, std::uint64_t emitter, std::uint32_t flags,
    std::uint32_t reserved, std::int32_t result,
    std::uint32_t returnedKind, std::uint64_t handle) noexcept {
    Engine* engine = detail::ActiveEngine();
    if (engine == nullptr) return;
    VariableOperationScope variableOperation(engine);
    monitor::ObserveOperation(VN_MONITOR_OPERATION_PLAY_PREVIEW, result,
        VN_MONITOR_ENTITY_PLAYABLE, stableId, handle, emitter, kind);
    engine->statefulCallSeen = true;
    engine->traceOriginWorldProbeOnly = false;
    if (engine->trace != nullptr && engine->trace->Active()) {
        engine->trace->RecordPreviewPlayPlayable(
            argsReadable, structSize, kind, stableId, emitter, flags,
            reserved, result, returnedKind, handle);
    }
}

