TimelineRuntimeInstallResult InstallTimelineProgram(
    const TimelineProgramInstallView& install) noexcept {
    TimelineRuntimeInstallResult result{};
    Engine* engine = detail::g_engine;
    if (engine == nullptr) {
        result.status = TimelineRuntimeInstallStatus::NotInitialized;
        return result;
    }
    if (engine->runtimeRecreateRequired) {
        result.status = TimelineRuntimeInstallStatus::RuntimeRecreateRequired;
        return result;
    }
    if (install.program == nullptr || install.occurrences == nullptr ||
        install.occurrenceCount == 0 ||
        install.program->payloads == nullptr ||
        install.program->payloadCount == 0) {
        result.status = TimelineRuntimeInstallStatus::InvalidProgram;
        return result;
    }
    std::size_t audibleOccurrenceCount = 0;
    for (std::size_t i = 0; i < install.occurrenceCount; ++i) {
        const TimelineOccurrenceInstallView& source = install.occurrences[i];
        if (source.kind == TimelineOccurrenceInstallKind::LogicalOnly) {
            continue;
        }
        if (source.kind != TimelineOccurrenceInstallKind::Audible ||
            source.schedule == nullptr || source.schedule->events == nullptr ||
            source.schedule->eventCount == 0 || source.voice.soundId == VnObjectId{} ||
            source.voice.outputBusId == VnObjectId{}) {
            result.status = TimelineRuntimeInstallStatus::InvalidProgram;
            return result;
        }
        ++audibleOccurrenceCount;
    }
    if (audibleOccurrenceCount == 0) {
        result.status = TimelineRuntimeInstallStatus::InvalidProgram;
        return result;
    }
    try {
        auto set = std::make_unique<EngineTimelineProgramSet>();
        set->programs.programs.emplace_back();
        OwningTimelineProgram& program = set->programs.programs.back();
        program.payloads.assign(install.program->payloads,
                                install.program->payloads +
                                    install.program->payloadCount);
        set->occurrences.reserve(audibleOccurrenceCount);
        for (std::size_t i = 0; i < install.occurrenceCount; ++i) {
            const TimelineOccurrenceInstallView& source = install.occurrences[i];
            if (source.kind == TimelineOccurrenceInstallKind::LogicalOnly) {
                continue;
            }
            set->occurrences.emplace_back();
            EngineTimelineOccurrence& occurrence = set->occurrences.back();
            occurrence.events.assign(source.schedule->events,
                                     source.schedule->events +
                                         source.schedule->eventCount);
            occurrence.schedule = *source.schedule;
            occurrence.schedule.events = occurrence.events.data();
            const auto captureStatus = CaptureTimelineVoiceInstall(source.voice, &occurrence.voice);
            if (captureStatus != PlayableStartStatus::Accepted) {
                result.status = captureStatus == PlayableStartStatus::InvalidInput
                    ? TimelineRuntimeInstallStatus::InvalidProgram
                    : TimelineRuntimeInstallStatus::ProgramCapacity;
                return result;
            }
        }
        if (set->occurrences.empty()) {
            result.status = TimelineRuntimeInstallStatus::InvalidProgram;
            return result;
        }
        if (!engine->ledger.PrepareBacking(static_cast<std::uint32_t>(std::min<std::size_t>(
                audibleOccurrenceCount, engine->ledger.Capacity())), &set->ledgerBacking) ||
            !engine->ledger.PrepareMonitorSelectionBacking(static_cast<std::uint32_t>(std::min<std::size_t>(
                audibleOccurrenceCount, engine->ledger.MonitorSelectionCapacity())), &set->monitorBacking)) {
            result.status = TimelineRuntimeInstallStatus::ProgramCapacity;
            return result;
        }
        const auto rollbackIdentities = [&]() {
            for (EngineTimelineOccurrence& occurrence : set->occurrences) {
                RetireTimelineOccurrence(*engine, occurrence);
            }
        };
        for (EngineTimelineOccurrence& occurrence : set->occurrences) {
            occurrence.ownerInstance =
                engine->playableInstances.Acquire(PlayableKind::Segment, 0);
            if (occurrence.ownerInstance == 0) {
                rollbackIdentities();
                result.status = TimelineRuntimeInstallStatus::ProgramCapacity;
                return result;
            }
            const PlayableInstanceView owner =
                engine->playableInstances.Classify(occurrence.ownerInstance);
            OccurrenceKey key{};
            key.arrangingInstance = occurrence.ownerInstance;
            key.clipId = occurrence.voice.Facts().target.clipId;
            key.loopIteration = occurrence.voice.Facts().target.loopIteration;
            key.occurrenceOrdinal = occurrence.voice.Facts().target.occurrenceOrdinal;
            if (!engine->timelineOccurrences.Acquire(
                    key, &occurrence.occurrenceToken)) {
                rollbackIdentities();
                result.status = TimelineRuntimeInstallStatus::ProgramCapacity;
                return result;
            }
            const std::uint64_t occurrenceEpoch =
                engine->timelineOccurrences.ScheduleEpochOf(
                    occurrence.occurrenceToken);
            (void)engine->timelineOccurrences.Advance(
                occurrence.occurrenceToken, OccurrenceStage::Active);
            occurrence.schedule.ownerInstance = occurrence.ownerInstance;
            occurrence.schedule.ownerInstanceScheduleEpoch = owner.scheduleEpoch;
            occurrence.schedule.occurrence = {
                true, occurrence.occurrenceToken, occurrenceEpoch,
                owner.scheduleEpoch};
        }
        const std::uint64_t audioSequence = engine->mixer.BlocksRendered();
        const std::size_t candidateSetSlot =
            static_cast<std::size_t>(
                engine->timelinePrograms.Current() + 1u) & 1u;
        if (engine->timelineProgramSets[candidateSetSlot] != nullptr) {
            rollbackIdentities();
            result.status = TimelineRuntimeInstallStatus::ProgramCapacity;
            return result;
        }
        const ProgramGeneration previous = engine->timelinePrograms.Current();
        const ProgramGeneration generation = engine->timelinePrograms.Publish(
            reinterpret_cast<std::uint64_t>(set.get()), audioSequence);
        if (generation == 0) {
            rollbackIdentities();
            result.status = engine->timelinePrograms.GenerationExhausted()
                                ? TimelineRuntimeInstallStatus::
                                      RuntimeRecreateRequired
                                : TimelineRuntimeInstallStatus::ProgramCapacity;
            engine->runtimeRecreateRequired =
                engine->timelinePrograms.GenerationExhausted();
            return result;
        }
        if (previous != 0) {
            for (const std::unique_ptr<EngineTimelineProgramSet>& retained :
                 engine->timelineProgramSets) {
                if (retained != nullptr && retained->generation == previous) {
                    retained->supersededAtAudioSequence = audioSequence;
                    break;
                }
            }
        }
        set->generation = generation;
        program.Seal(generation);
        for (EngineTimelineOccurrence& occurrence : set->occurrences) {
            occurrence.schedule.runtimeProgram = {generation, &program.view};
        }
        const std::size_t setSlot = generation & 1u;
        if (setSlot != candidateSetSlot) {
            rollbackIdentities();
            result.status = TimelineRuntimeInstallStatus::ProgramCapacity;
            return result;
        }
        engine->timelineProgramSets[setSlot] = std::move(set);
        result.status = TimelineRuntimeInstallStatus::Installed;
        result.generation = generation;
        result.occurrenceCount = static_cast<std::uint32_t>(
            engine->timelineProgramSets[setSlot]->occurrences.size());
        return result;
    } catch (...) {
        result.status = TimelineRuntimeInstallStatus::ProgramCapacity;
        return result;
    }
}

