#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
namespace harken::test {
bool PrepareNativeQueueResetResourcesForTest(Engine& engine, std::uint32_t serviceSlot,
    std::uint32_t scratchSlot, const QueueInstanceTable::PreparedCatalogResetScope& scope,
    const PreparedQueueReplacementOrder& order) noexcept {
    if (serviceSlot >= engine.playableServices.size() ||
        scratchSlot >= engine.actionQueueReplacementScratch.size()) return false;
    ImmediateActionPlan plan{};
    plan.engine = &engine;
    return PrepareImmediateActionQueueReplacement(plan, engine.playableServices[serviceSlot],
        engine.actionQueueReplacementScratch[scratchSlot], &scope, &order);
}
void AbandonNativeQueueResetResourcesForTest(Engine& engine, std::uint32_t count) noexcept {
    ImmediateActionPlan plan{};
    plan.engine = &engine;
    plan.queueResetCount = 1;
    plan.queueReplacementCount = count;
    plan.nativeResetBatchPrepared = true;
    ReleaseImmediateActionQueueReplacements(&plan, 1);
}
bool CancelNativeQueueResetResourcesForTest(Engine& engine, std::uint32_t scratchSlot) noexcept {
    return scratchSlot < engine.actionQueueReplacementScratch.size() &&
        ReleaseImmediateActionQueueReplacement(engine, engine.actionQueueReplacementScratch[scratchSlot]);
}
}
#endif

