VnResult Vn_SetBusFaderPoint(VnBusId busId, uint32_t faderAfterSlot) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetBusFaderPoint)
        .ObjectId(busId)
        .U32(faderAfterSlot);
    // The split may sit at any boundary from all-post-fader (0) to all-pre-fader
    // (fxSlotsPerBus, the default), inclusive.
    if (faderAfterSlot > engine->config.fxSlotsPerBus) {
        return VN_INVALID_ARG;
    }
    std::uint32_t busIndex = harken::kInvalidBusIndex;
    const VnResult mutableBus = ResolveMutableBusProperties(*engine, busId, busIndex);
    if (mutableBus != VN_OK) return mutableBus;
    // Ordinary per-bus audio-thread state, like a send level: its own command,
    // applied at the block boundary; republishes no topology plan.
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetBusFaderPoint;
    command.payload.setBusFaderPoint.busIndex = busIndex;
    command.payload.setBusFaderPoint.faderAfterSlot = faderAfterSlot;
    command.payload.setBusFaderPoint.busGeneration =
        engine->buses.GenerationAt(busIndex);
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    (void)engine->commands.TryPush(command); // space verified above
    engine->busFaderAfterSlots[busIndex] = faderAfterSlot;
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

VnResult Vn_SetBusOutputVolume(VnBusId busId, float volumeDb, uint32_t rampMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr || engine->callbackFatalSticky) return VN_NOT_INITIALIZED;
    TraceStateful(engine, harken::kTraceCallSetBusOutputVolume)
        .ObjectId(busId).F32(volumeDb).U32(rampMs);
    if (!std::isfinite(volumeDb)) return VN_INVALID_ARG;
    const std::uint32_t index = engine->buses.FindIndex(busId);
    if (index == harken::kInvalidBusIndex) return VN_UNKNOWN_ID;
    // Preview occupying Master still allows mixdown Output Volume overlay.
    // Output Volume is PLAN-09 independent mixdown trim, not topology ownership.
    // Mute/Volume/Solo/Effect/Layout/Downmix keep ResolveMutableBusProperties.
    const float prospective = engine->busTargets.ReduceWithSlot(
        index, harken::kBusTargetBusOutputVolume,
        harken::BusTargetStore::kSlotApiDirectIndex, volumeDb);
    if (!harken::TryVolumeGainFromDb(prospective)) return VN_INVALID_ARG;
    if (engine->busTargets.ForeignClaim(
            index, harken::kBusTargetBusOutputVolume)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    engine->busTargets.SetSlot(
        index, harken::kBusTargetBusOutputVolume,
        harken::BusTargetStore::kSlotApiDirectIndex, volumeDb);
    const float resolved = engine->busTargets.Reduce(
        index, harken::kBusTargetBusOutputVolume);
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetBusVolume;
    command.payload.setBusVolume.busIndex = index;
    command.payload.setBusVolume.busGeneration = engine->buses.GenerationAt(index);
    command.payload.setBusVolume.volumeDb = resolved;
    command.payload.setBusVolume.rampMs = rampMs;
    command.payload.setBusVolume.outputOnly = 1;
    (void)engine->commands.TryPush(command);
    engine->busTargets.NoteApiDirect(
        index, harken::kBusTargetBusOutputVolume, volumeDb, rampMs, resolved);
    return VN_OK;
    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }
}

VnResult Vn_SetBusVolume(VnBusId busId, float volumeDb, uint32_t rampMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetBusVolume)
        .ObjectId(busId)
        .F32(volumeDb)
        .U32(rampMs);
    // A non-finite dB value would poison the linear conversion when the
    // command applies; refuse it up front like the voice-side gain.
    if (!std::isfinite(volumeDb)) {
        return VN_INVALID_ARG;
    }
    std::uint32_t busIndex = harken::kInvalidBusIndex;
    const VnResult mutableBus = ResolveMutableBusProperties(*engine, busId, busIndex);
    if (mutableBus != VN_OK) return mutableBus;
    const float prospective = engine->busTargets.ReduceWithSlot(
        busIndex, harken::kBusTargetBusVolume,
        harken::BusTargetStore::kSlotApiDirectIndex, volumeDb);
    if (!harken::TryVolumeGainFromDb(prospective)) {
        return VN_INVALID_ARG;
    }
    // A bus target claimed by a prepared Variable bank cut refuses ordinary
    // writes until the slice applies (or the claim releases).
    if (engine->busTargets.ForeignClaim(busIndex,
                                        harken::kBusTargetBusVolume)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    // Queue admission BEFORE any combine-slot write, so a refused call has
    // zero side effects — the direct setters' pre-checked immediate
    // admission, unchanged in latency (section 10.3).
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    // Combine (section 8): this call retargets the API-direct slot and
    // commits the REDUCED value — neutral base + authored + API-direct +
    // Variable + MeterProbe. With no other slots active the reduction IS
    // the caller's value, so the no-binding path pushes exactly the
    // pre-M6 command. Its own rampMs governs API-direct changes as
    // always, and is additionally stamped for the tick's section-9.2
    // aggregation should binding contributions on this target also
    // change before the flush.
    engine->busTargets.SetSlot(busIndex, harken::kBusTargetBusVolume,
                               harken::BusTargetStore::kSlotApiDirectIndex,
                               volumeDb);
    const float resolved =
        engine->busTargets.Reduce(busIndex, harken::kBusTargetBusVolume);
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetBusVolume;
    command.payload.setBusVolume.volumeDb =
        WireBusVolumeDb(*engine, busIndex, resolved);
    command.payload.setBusVolume.busIndex = busIndex;
    command.payload.setBusVolume.rampMs = rampMs;
    command.payload.setBusVolume.busGeneration =
        engine->buses.GenerationAt(busIndex);
    (void)engine->commands.TryPush(command); // space verified above
    engine->busTargets.NoteApiDirect(busIndex, harken::kBusTargetBusVolume,
                                     volumeDb, rampMs, resolved);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

bool FillBusFilterCommand(const harken::Engine& engine, std::uint32_t busIndex,
                          uint32_t filterKind, float cutoffHz, float q,
                          uint32_t enable01, uint32_t rampMs,
                          uint32_t outputOnly, harken::CommandRecord* out) {
    if (out == nullptr) {
        return false;
    }
    const bool lowpass = filterKind == harken::kFilterKindLowpass;
    const float sampleRate =
        static_cast<float>(engine.config.mixRate.SampleRate());
    const float nyquist = 0.5f * sampleRate;
    bool enable = enable01 != 0;
    float cutoff = cutoffHz;
    harken::BiquadCoeffs coeffs{};
    std::uint32_t tailFrames = 0;
    if (enable) {
        enable = lowpass ? cutoff < nyquist : cutoff > 0.0f;
    }
    if (enable) {
        const float maxCutoff = 0.499f * sampleRate;
        if (!(cutoff >= 1.0f)) {
            cutoff = 1.0f;
        } else if (cutoff > maxCutoff) {
            cutoff = maxCutoff;
        }
        coeffs = lowpass ? harken::MakeLowpass(sampleRate, cutoff, q)
                         : harken::MakeHighpass(sampleRate, cutoff, q);
        if (!harken::IsBiquadStable(coeffs)) {
            return false;
        }
        tailFrames = harken::EstimateBiquadTailFrames(coeffs);
    }
    const std::uint64_t transitionFrames =
        static_cast<std::uint64_t>(rampMs) *
        engine.config.mixRate.SampleRate() / 1000u;
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetBusFilter;
    command.payload.setBusFilter.busIndex = busIndex;
    command.payload.setBusFilter.busGeneration =
        engine.buses.GenerationAt(busIndex);
    command.payload.setBusFilter.filterKind = filterKind;
    command.payload.setBusFilter.enable = enable ? 1u : 0u;
    command.payload.setBusFilter.cutoffHz = enable ? cutoff : 0.0f;
    command.payload.setBusFilter.q = q;
    command.payload.setBusFilter.outputOnly = outputOnly;
    command.payload.setBusFilter.coeffs = harken::PrepareBiquadCoeffs(coeffs);
    command.payload.setBusFilter.tailFrames = tailFrames;
    command.payload.setBusFilter.transitionFrames =
        transitionFrames > (std::numeric_limits<std::uint32_t>::max)()
            ? (std::numeric_limits<std::uint32_t>::max)()
            : static_cast<std::uint32_t>(transitionFrames);
    *out = command;
    return true;
}

VnResult Vn_SetBusFilter(VnBusId busId, uint32_t filterKind, float cutoffHz,
                         float q, uint32_t enable01, uint32_t rampMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetBusFilter)
        .ObjectId(busId)
        .U32(filterKind)
        .F32(cutoffHz)
        .F32(q)
        .U32(enable01)
        .U32(rampMs);
    if (filterKind != harken::kFilterKindLowpass &&
        filterKind != harken::kFilterKindHighpass) {
        return VN_INVALID_ARG;
    }
    if (enable01 > 1u) {
        return VN_INVALID_ARG;
    }
    if (!std::isfinite(cutoffHz) || !std::isfinite(q)) {
        return VN_INVALID_ARG;
    }
    if (enable01 == 1u && !(q > 0.0f)) {
        return VN_INVALID_ARG;
    }
    std::uint32_t busIndex = harken::kInvalidBusIndex;
    const VnResult mutableBus =
        ResolveMutableBusProperties(*engine, busId, busIndex);
    if (mutableBus != VN_OK) {
        return mutableBus;
    }
    harken::CommandRecord command{};
    if (!FillBusFilterCommand(*engine, busIndex, filterKind, cutoffHz, q,
                              enable01, rampMs, 0, &command)) {
        return VN_INVALID_ARG;
    }
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    (void)engine->commands.TryPush(command);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

