VnResult Vn_SetBusMute(VnBusId busId, uint32_t mute01, uint32_t fadeMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetBusMute)
        .ObjectId(busId)
        .U32(mute01)
        .U32(fadeMs);
    if (mute01 > 1u) {
        return VN_INVALID_ARG;
    }
    std::uint32_t busIndex = harken::kInvalidBusIndex;
    const VnResult mutableBus = ResolveMutableBusProperties(*engine, busId, busIndex);
    if (mutableBus != VN_OK) return mutableBus;
    if (engine->busMuted[busIndex] == static_cast<std::uint8_t>(mute01)) {
        return VN_OK; // state already held: benign no-op, nothing publishes
    }
    // The flip publishes a gain only when effective audibility changes (a
    // bus already silenced by solo scope just records the flag). Computed
    // against the prospective mute value BEFORE any mutation, so a refused
    // admission leaves the flag untouched.
    const bool audibleBefore = BusEffectivelyAudible(*engine, busIndex);
    const bool audibleAfter =
        mute01 == 0 &&
        (engine->busSoloActiveCount == 0 ||
         BusOnSoloPathWith(*engine, busIndex, harken::kInvalidBusIndex, 0));
    if (audibleBefore != audibleAfter) {
        if (BusVolumeClaimed(*engine, busIndex)) {
            engine->commands.NoteBackpressure();
            return VN_BACKPRESSURE;
        }
        if (!AdmitSingleCommand(*engine)) {
            engine->commands.NoteBackpressure();
            return VN_BACKPRESSURE;
        }
    }
    engine->busMuted[busIndex] = static_cast<std::uint8_t>(mute01);

    {
        harken::MonitorBusFacts facts{};
        facts.mute01 = mute01;
        facts.solo01 = engine->busSoloed[busIndex];
        facts.routeBusId = engine->buses.IdAt(engine->buses.ParentOf(busIndex));
        harken::ObserveMonitorBus(busIndex + 1u, engine->buses.GenerationAt(busIndex), busId,
                          facts);
    }
    if (audibleBefore == audibleAfter) {
        return VN_OK;
    }
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetBusVolume;
    command.payload.setBusVolume.busIndex = busIndex;
    command.payload.setBusVolume.volumeDb =
        audibleAfter
            ? engine->busTargets.Reduce(busIndex, harken::kBusTargetBusVolume)
            : kBusMuteFloorDb;
    command.payload.setBusVolume.rampMs = fadeMs;
    command.payload.setBusVolume.busGeneration =
        engine->buses.GenerationAt(busIndex);
    (void)engine->commands.TryPush(command); // space verified above
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

VnResult Vn_SetBusSolo(VnBusId busId, uint32_t solo01, uint32_t fadeMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetBusSolo)
        .ObjectId(busId)
        .U32(solo01)
        .U32(fadeMs);
    if (solo01 > 1u) {
        return VN_INVALID_ARG;
    }
    std::uint32_t busIndex = harken::kInvalidBusIndex;
    const VnResult mutableBus = ResolveMutableBusProperties(*engine, busId, busIndex);
    if (mutableBus != VN_OK) return mutableBus;
    if (engine->busSoloed[busIndex] == static_cast<std::uint8_t>(solo01)) {
        return VN_OK; // state already held: benign no-op, nothing publishes
    }
    // Collect every bus whose effective audibility the flip changes, all
    // against the prospective solo state — nothing mutates before the whole
    // batch is admitted, so a refusal has zero side effects. Logic-side
    // scratch heap, like the topology sort.
    const std::uint8_t newValue = static_cast<std::uint8_t>(solo01);
    const std::uint32_t newActive = solo01 != 0
                                        ? engine->busSoloActiveCount + 1
                                        : engine->busSoloActiveCount - 1;
    const std::uint32_t count = engine->buses.BusCount();
    std::vector<std::uint32_t> flipped;
    flipped.reserve(count);
    for (std::uint32_t i = 0; i < count; ++i) {
        const bool before = BusEffectivelyAudible(*engine, i);
        const bool after = BusEffectivelyAudibleWith(*engine, i, busIndex,
                                                     newValue, newActive);
        if (before != after) {
            flipped.push_back(i);
        }
    }
    if (AnyBusVolumeClaimed(*engine, flipped)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    if (!flipped.empty() &&
        !AdmitCommandBatch(*engine,
                           static_cast<std::uint32_t>(flipped.size()))) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    engine->busSoloed[busIndex] = newValue;
    engine->busSoloActiveCount = newActive;

    {
        harken::MonitorBusFacts facts{};
        facts.mute01 = engine->busMuted[busIndex];
        facts.solo01 = solo01;
        facts.routeBusId = engine->buses.IdAt(engine->buses.ParentOf(busIndex));
        harken::ObserveMonitorBus(busIndex + 1u, engine->buses.GenerationAt(busIndex), busId,
                          facts);
    }
    for (const std::uint32_t i : flipped) {
        harken::CommandRecord command{};
        command.opcode = harken::kOpcodeSetBusVolume;
        command.payload.setBusVolume.busIndex = i;
        command.payload.setBusVolume.volumeDb =
            BusEffectivelyAudible(*engine, i)
                ? engine->busTargets.Reduce(i, harken::kBusTargetBusVolume)
                : kBusMuteFloorDb;
        command.payload.setBusVolume.rampMs = fadeMs;
        command.payload.setBusVolume.busGeneration =
            engine->buses.GenerationAt(i);
        (void)engine->commands.TryPush(command); // batch admitted above
    }
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_BACKPRESSURE;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

/* Voice parameter setters share one shape: validate the value, verify the
 * handle is live, check queue admission BEFORE touching any combine slot
 * (a refused call has zero side effects), then write the API-direct slot,
 * reduce, and commit the resolved value in the same call. */

VnResult Vn_SetVoiceOutputVolume(VnVoiceHandle handle, float volumeDb,
                                uint32_t rampMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr || engine->callbackFatalSticky) return VN_NOT_INITIALIZED;
    TraceStateful(engine, harken::kTraceCallSetVoiceOutputVolume)
        .U64(handle).F32(volumeDb).U32(rampMs);
    if (!harken::TryVolumeGainFromDb(volumeDb)) return VN_INVALID_ARG;
    const auto resolved = engine->ledger.Classify(handle);
    if (resolved.kind == harken::VoiceLedger::HandleKind::Pending) {
        engine->pendingStarts[resolved.ledgerSlot].outputBusVolumeDb = volumeDb;
        return VN_OK;
    }
    if (resolved.kind == harken::VoiceLedger::HandleKind::Parked) {
        engine->parkRecords[resolved.ledgerSlot].facts.outputBusVolumeDb = volumeDb;
        return VN_OK;
    }
    const VnVoiceHandle render =
        resolved.kind == harken::VoiceLedger::HandleKind::Live
            ? resolved.renderHandle : 0;
    const VnResult live = engine->voices.CheckLive(render);
    if (live != VN_OK) return live;
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetVoiceVolume;
    command.payload.setVoiceVolume.handle = render;
    command.payload.setVoiceVolume.volumeDb = volumeDb;
    command.payload.setVoiceVolume.rampMs = rampMs;
    command.payload.setVoiceVolume.outputOnly = 1;
    (void)engine->commands.TryPush(command);
    engine->voicePlayFacts[static_cast<std::uint32_t>(render)].outputBusVolumeDb = volumeDb;
    return VN_OK;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }
}

VnResult Vn_SetVoiceVolume(VnVoiceHandle handle, float volumeDb,
                           uint32_t rampMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetVoiceVolume)
        .U64(handle)
        .F32(volumeDb)
        .U32(rampMs);
    if (!std::isfinite(volumeDb)) {
        return VN_INVALID_ARG;
    }
    // A pending-start voice stages the value; it is applied against the
    // combine model when the deferred start acquires a render slot.
    const harken::VoiceLedger::Resolved resolved =
        engine->ledger.Classify(handle);
    if (resolved.kind == harken::VoiceLedger::HandleKind::Pending) {
        if (!harken::TryVolumeGainFromDb(volumeDb)) {
            return VN_INVALID_ARG;
        }
        harken::PendingStartRecord& rec =
            engine->pendingStarts[resolved.ledgerSlot];
        if (!harken::TryVolumeGainFromDb(rec.baseVolumeDb + volumeDb)) {
            return VN_INVALID_ARG;
        }
        rec.hasVolume = true;
        rec.volumeDb = volumeDb;
        return VN_OK;
    }
    if (resolved.kind == harken::VoiceLedger::HandleKind::Parked) {
        // A parked voice holds no render slot; mutate the captured replay state
        // the return will apply. Volume is part of the frozen non-spatial term
        // of the parked audibility metric, so shift that term by the change from
        // the currently captured volume — the metric (and thus return and
        // hysteresis) then tracks the new volume.
        if (!harken::TryVolumeGainFromDb(volumeDb)) {
            return VN_INVALID_ARG;
        }
        harken::ParkRecord& rec = engine->parkRecords[resolved.ledgerSlot];
        float previous = 0.0f;
        for (const harken::ParamSystem::ApiDirectState& a : rec.apiDirect) {
            if (a.targetId == harken::kTargetVoiceVolume) {
                previous = a.value;
                break;
            }
        }
        if (rec.bindings.empty() &&
            !harken::TryVolumeGainFromDb(rec.facts.baseVolumeDb + volumeDb +
                                        rec.instanceVolumeDb)) {
            return VN_INVALID_ARG;
        }
        SetParkedApiDirect(rec, harken::kTargetVoiceVolume, volumeDb);
        rec.frozenNonSpatialDb += (volumeDb - previous);
        return VN_OK;
    }
    const VnVoiceHandle render =
        (resolved.kind == harken::VoiceLedger::HandleKind::Live)
            ? resolved.renderHandle
            : 0;
    const VnResult live = engine->voices.CheckLive(render);
    if (live != VN_OK) {
        return live;
    }
    const float prospective = engine->params.ReduceWithSlot(
        render, harken::kTargetVoiceVolume, harken::kSlotApiDirect, volumeDb);
    if (!harken::TryVolumeGainFromDb(prospective)) {
        return VN_INVALID_ARG;
    }
    // A target claimed by a prepared Variable bank cut cannot be overwritten
    // by an ordinary setter: the claim's snapshot is already frozen for the
    // audio slice, so the write refuses with zero side effects.
    if (engine->params.ForeignClaim(render, harken::kTargetVoiceVolume)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    // The rampMs is recorded for the tick's target-level aggregation
    // (section 9.2): if bindings on this target also change before the
    // flush, its single published command carries the max of their
    // transitions and this ramp.
    const float resolvedDb = engine->params.SetApiDirect(
        render, harken::kTargetVoiceVolume, volumeDb, rampMs);
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetVoiceVolume;
    command.payload.setVoiceVolume.handle = render;
    command.payload.setVoiceVolume.volumeDb = resolvedDb;
    command.payload.setVoiceVolume.rampMs = rampMs;
    (void)engine->commands.TryPush(command);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

bool VoiceFilterSectionStable(const harken::Engine& engine,
                              std::uint32_t filterKind, float cutoffHz,
                              float q) {
    const float sampleRate =
        static_cast<float>(engine.config.mixRate.SampleRate());
    const float nyquist = 0.5f * sampleRate;
    const bool lowpass = filterKind == harken::kFilterKindLowpass;
    const bool enable =
        lowpass ? cutoffHz < nyquist : cutoffHz > 0.0f;
    if (!enable) {
        return true;
    }
    const float maxCutoff = 0.499f * sampleRate;
    float cutoff = cutoffHz;
    if (!(cutoff >= 1.0f)) {
        cutoff = 1.0f;
    } else if (cutoff > maxCutoff) {
        cutoff = maxCutoff;
    }
    const harken::BiquadCoeffs coeffs =
        lowpass ? harken::MakeLowpass(sampleRate, cutoff, q)
                : harken::MakeHighpass(sampleRate, cutoff, q);
    return harken::IsBiquadStable(coeffs);
}

VnResult Vn_SetVoiceFilter(VnVoiceHandle handle, uint32_t filterKind,
                           float cutoffHz, float q, uint32_t enable01,
                           uint32_t rampMs) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetVoiceFilter)
        .U64(handle)
        .U32(filterKind)
        .F32(cutoffHz)
        .F32(q)
        .U32(enable01)
        .U32(rampMs);
    if (filterKind != harken::kFilterKindLowpass &&
        filterKind != harken::kFilterKindHighpass) {
        return VN_INVALID_ARG;
    }
    if (enable01 > 1u) {
        return VN_INVALID_ARG;
    }
    if (!std::isfinite(cutoffHz) || !std::isfinite(q)) {
        return VN_INVALID_ARG;
    }
    if (enable01 == 1u && !(q > 0.0f)) {
        return VN_INVALID_ARG;
    }
    const bool lowpass = filterKind == harken::kFilterKindLowpass;
    const std::uint32_t cutoffTarget =
        lowpass ? harken::kTargetVoiceLowpassCutoff
                : harken::kTargetVoiceHighpassCutoff;
    const std::uint32_t qTarget =
        lowpass ? harken::kTargetVoiceLowpassQ : harken::kTargetVoiceHighpassQ;
    const float cutoffValue =
        enable01 == 0u
            ? (lowpass ? harken::kLowpassOpenHz : harken::kHighpassClosedHz)
            : cutoffHz;
    const harken::VoiceLedger::Resolved resolved =
        engine->ledger.Classify(handle);
    if (resolved.kind == harken::VoiceLedger::HandleKind::Pending) {
        if (!VoiceFilterSectionStable(*engine, filterKind, cutoffValue, q)) {
            return VN_INVALID_ARG;
        }
        harken::PendingStartRecord& rec =
            engine->pendingStarts[resolved.ledgerSlot];
        if (lowpass) {
            rec.hasLowpass = true;
            rec.lowpassCutoffHz = cutoffValue;
            rec.lowpassQ = q;
            rec.lowpassRampMs = rampMs;
        } else {
            rec.hasHighpass = true;
            rec.highpassCutoffHz = cutoffValue;
            rec.highpassQ = q;
            rec.highpassRampMs = rampMs;
        }
        return VN_OK;
    }
    if (resolved.kind == harken::VoiceLedger::HandleKind::Parked) {
        if (!VoiceFilterSectionStable(*engine, filterKind, cutoffValue, q)) {
            return VN_INVALID_ARG;
        }
        harken::ParkRecord& rec = engine->parkRecords[resolved.ledgerSlot];
        SetParkedApiDirect(rec, cutoffTarget, cutoffValue);
        SetParkedApiDirect(rec, qTarget, q);
        return VN_OK;
    }
    const VnVoiceHandle render =
        (resolved.kind == harken::VoiceLedger::HandleKind::Live)
            ? resolved.renderHandle
            : 0;
    const VnResult live = engine->voices.CheckLive(render);
    if (live != VN_OK) {
        return live;
    }
    const float prospectiveCutoff = engine->params.ReduceWithSlot(
        render, cutoffTarget, harken::kSlotApiDirect, cutoffValue);
    const float prospectiveQ = engine->params.ReduceWithSlot(
        render, qTarget, harken::kSlotApiDirect, q);
    if (!VoiceFilterSectionStable(*engine, filterKind, prospectiveCutoff,
                                  prospectiveQ)) {
        return VN_INVALID_ARG;
    }
    if (engine->params.ForeignClaim(render, cutoffTarget) ||
        engine->params.ForeignClaim(render, qTarget)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    engine->params.SetApiDirect(render, cutoffTarget, cutoffValue, rampMs);
    engine->params.SetApiDirect(render, qTarget, q, rampMs);
    harken::ParamCommit commit;
    commit.handle = render;
    commit.targetId = cutoffTarget;
    commit.resolved = engine->params.ResolvedValue(render, cutoffTarget);
    commit.rampMs = rampMs;
    harken::CommandRecord command{};
    if (!MakeParamCommand(*engine, commit, &command)) {
        return VN_INVALID_ARG;
    }
    (void)engine->commands.TryPush(command);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

VnResult Vn_SetVoicePitch(VnVoiceHandle handle, float ratio) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetVoicePitch)
        .U64(handle)
        .F32(ratio);
    // The ratio enters the combine model as cents (1200 * log2(ratio)), so
    // zero and negative values are structurally meaningless here — unlike
    // The raw-Voice descriptor, where zero means "field not filled in".
    if (!std::isfinite(ratio) || ratio <= 0.0f || ratio > 64.0f) {
        return VN_INVALID_ARG;
    }
    // A pending-start voice stages the ratio; applied at deferred start.
    const harken::VoiceLedger::Resolved resolved =
        engine->ledger.Classify(handle);
    if (resolved.kind == harken::VoiceLedger::HandleKind::Pending) {
        const VnResult guard = GuardCompletionMutation(*engine, handle);
        if (guard != VN_OK) {
            return guard;
        }
        harken::PendingStartRecord& rec =
            engine->pendingStarts[resolved.ledgerSlot];
        rec.hasPitch = true;
        rec.pitchRatio = static_cast<double>(ratio);
        return VN_OK;
    }
    if (resolved.kind == harken::VoiceLedger::HandleKind::Parked) {
        const VnResult guard = GuardCompletionMutation(*engine, handle);
        if (guard != VN_OK) {
            return guard;
        }
        // Adjust the captured resolved pitch by the API-direct DELTA in cents so
        // any binding contribution folded into it at park is preserved, then
        // wire-clamp for the virtual advance rate (as the render path clamps).
        harken::ParkRecord& rec = engine->parkRecords[resolved.ledgerSlot];
        const double newCents = harken::RatioToCents(static_cast<double>(ratio));
        double oldCents = 0.0;
        for (const harken::ParamSystem::ApiDirectState& a : rec.apiDirect) {
            if (a.targetId == harken::kTargetVoicePitch) {
                oldCents = static_cast<double>(a.value);
                break;
            }
        }
        const double resolvedPitchCents =
            rec.resolvedPitchCents + (newCents - oldCents);
        // The wire-clamped virtual rate is the non-instance cents plus
        // the live instance pitch term (kept current by the per-tick
        // parked re-evaluation).
        const double resolvedPitchRatio =
            WireRatioFromCents(resolvedPitchCents + rec.instancePitchCents);
        SetParkedApiDirect(rec, harken::kTargetVoicePitch,
                           static_cast<float>(newCents));
        rec.resolvedPitchCents = resolvedPitchCents;
        rec.resolvedPitchRatio = resolvedPitchRatio;
        return VN_OK;
    }
    const VnVoiceHandle render =
        (resolved.kind == harken::VoiceLedger::HandleKind::Live)
            ? resolved.renderHandle
            : 0;
    const VnResult live = engine->voices.CheckLive(render);
    if (live != VN_OK) {
        return live;
    }
    const VnResult guard = GuardCompletionMutation(*engine, handle);
    if (guard != VN_OK) {
        return guard;
    }
    if (engine->params.ForeignClaim(render, harken::kTargetVoicePitch)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    const float cents = static_cast<float>(
        harken::RatioToCents(static_cast<double>(ratio)));
    const float resolvedCents = engine->params.SetApiDirect(
        render, harken::kTargetVoicePitch, cents);
    // The setter validated ITS argument, but the reduction may add
    // binding contributions on top; the shared wire clamp keeps the final
    // ratio inside the supported span on this path too.
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetVoicePitch;
    command.payload.setVoicePitch.handle = render;
    command.payload.setVoicePitch.ratio =
        WireRatioFromCents(static_cast<double>(resolvedCents));
    command.payload.setVoicePitch.rampMs = 0;
    (void)engine->commands.TryPush(command);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

VnResult Vn_SetVoicePosition(VnVoiceHandle handle, VnVec3 position) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetVoicePosition)
        .U64(handle)
        .Vec3(position);
    // Precedence: an attached voice derives its position from the emitter, so
    // that refusal (VN_EMITTER_ATTACHED — one owner per fact) outranks argument
    // validation; a caller learns the voice is emitter-owned whatever it
    // passed. Below the gate a bad value is still reported before a stale
    // handle (value-before-handle), matching the other voice setters. Pending
    // checks the staged emitter; live checks the mirror's emitter.
    const harken::VoiceLedger::Resolved resolved =
        engine->ledger.Classify(handle);
    if (resolved.kind == harken::VoiceLedger::HandleKind::Pending) {
        harken::PendingStartRecord& rec =
            engine->pendingStarts[resolved.ledgerSlot];
        if (engine->emitters.Context(rec.emitterHandle).spatialEmitter != 0) {
            return VN_EMITTER_ATTACHED;
        }
        if (!std::isfinite(position.x) || !std::isfinite(position.y) ||
            !std::isfinite(position.z)) {
            return VN_INVALID_ARG;
        }
        // A pending-start voice stages the position; applied at deferred start.
        rec.hasPosition = true;
        rec.setPosX = position.x;
        rec.setPosY = position.y;
        rec.setPosZ = position.z;
        rec.source.posX = position.x;
        rec.source.posY = position.y;
        rec.source.posZ = position.z;
        return VN_OK;
    }
    if (resolved.kind == harken::VoiceLedger::HandleKind::Parked) {
        // Attachment refusal outranks value/handle, as for a live voice; then a
        // bad value is refused. The captured position feeds both the return and
        // the parked audibility metric (distance attenuation), so moving a parked
        // voice can change whether it returns.
        harken::ParkRecord& rec = engine->parkRecords[resolved.ledgerSlot];
        if (rec.spatial.emitterHandle != 0 &&
            engine->emitters.IsLive(rec.spatial.emitterHandle)) {
            return VN_EMITTER_ATTACHED;
        }
        if (!std::isfinite(position.x) || !std::isfinite(position.y) ||
            !std::isfinite(position.z)) {
            return VN_INVALID_ARG;
        }
        rec.spatial.posX = position.x;
        rec.spatial.posY = position.y;
        rec.spatial.posZ = position.z;
        return VN_OK;
    }
    const VnVoiceHandle render =
        (resolved.kind == harken::VoiceLedger::HandleKind::Live)
            ? resolved.renderHandle
            : 0;
    const VnResult live = engine->voices.CheckLive(render);
    if (live == VN_OK) {
        const VnEmitterHandle attached =
            engine->spatial.AttachedEmitter(render);
        if (attached != 0 && engine->emitters.IsLive(attached)) {
            return VN_EMITTER_ATTACHED;
        }
    }
    if (!std::isfinite(position.x) || !std::isfinite(position.y) ||
        !std::isfinite(position.z)) {
        return VN_INVALID_ARG;
    }
    if (live != VN_OK) {
        return live;
    }
    // Position is stored, not combined: it is not a curve target, so it
    // bypasses the combine model and travels as a plain value. The
    // logic-side mirror updates only after queue admission so a refused
    // call has zero side effects; acoustic consequences (for spatialized
    // voices) evaluate from the mirror at the next Vn_Update.
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetVoicePosition;
    command.payload.setVoicePosition.handle = render;
    command.payload.setVoicePosition.x = position.x;
    command.payload.setVoicePosition.y = position.y;
    command.payload.setVoicePosition.z = position.z;
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    (void)engine->commands.TryPush(command); // space verified above
    engine->spatial.SetVoicePosition(render, position.x, position.y,
                                     position.z);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

