VnResult Vn_SetVoicePan(VnVoiceHandle handle, float pan) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    TraceStateful(engine, harken::kTraceCallSetVoicePan).U64(handle).F32(pan);
    if (!std::isfinite(pan) || pan < -1.0f || pan > 1.0f) {
        return VN_INVALID_ARG;
    }
    const harken::VoiceLedger::Resolved resolved =
        engine->ledger.Classify(handle);
    if (resolved.kind == harken::VoiceLedger::HandleKind::Pending) {
        harken::PendingStartRecord& rec =
            engine->pendingStarts[resolved.ledgerSlot];
        rec.hasPan = true;
        rec.pan = pan;
        return VN_OK;
    }
    if (resolved.kind == harken::VoiceLedger::HandleKind::Parked) {
        SetParkedApiDirect(engine->parkRecords[resolved.ledgerSlot],
                           harken::kTargetVoicePan, pan);
        return VN_OK;
    }
    const VnVoiceHandle render =
        (resolved.kind == harken::VoiceLedger::HandleKind::Live)
            ? resolved.renderHandle
            : 0;
    const VnResult live = engine->voices.CheckLive(render);
    if (live != VN_OK) {
        return live;
    }
    if (engine->params.ForeignClaim(render, harken::kTargetVoicePan)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    if (!AdmitSingleCommand(*engine)) {
        engine->commands.NoteBackpressure();
        return VN_BACKPRESSURE;
    }
    const float resolvedPan =
        engine->params.SetApiDirect(render, harken::kTargetVoicePan, pan);
    const harken::ResolvedPanGains gains =
        harken::ResolvePanGains(engine->config.mixChannelLayout, resolvedPan);
    harken::CommandRecord command{};
    command.opcode = harken::kOpcodeSetVoicePan;
    command.payload.setVoicePan.handle = render;
    command.payload.setVoicePan.pan = gains.pan;
    command.payload.setVoicePan.pan2d = engine->params.ReduceWithSlot(
        render, harken::kTargetVoicePan, harken::kSlotAttenuation, 0.0f);
    command.payload.setVoicePan.gain0 = gains.gain0;
    command.payload.setVoicePan.gain1 = gains.gain1;
    command.payload.setVoicePan.channel0 = gains.channel0;
    command.payload.setVoicePan.channel1 = gains.channel1;
    (void)engine->commands.TryPush(command);
    return VN_OK;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

