static VnResult SetValueObserved(VnVariableId variableId, float value,
    const harken::MonitorRequestContext& request) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->runtimeTransportResetActive) {
        return VN_BACKPRESSURE;
    }
    harken::VariableOperationScope variableOperation(engine);
    harken::TraceCallScribe trace =
        TraceStateful(engine, harken::kTraceCallSetValue);
    trace.ObjectId(variableId).F32(value);
    const harken::VariableCallObservation observation =
        ObserveVariableCall(*engine);
    const harken::VariableAcceptResult accepted =
        engine->variables.AcceptGlobal(
            variableId, value, observation, engine->params,
            engine->bindings, engine->busTargets);
    trace.U64(accepted.observation.world)
        .U64(accepted.observation.transport)
        .U64(accepted.observation.publicationFrontierFrame)
        .U64(accepted.observation.requestedEffectiveFrame)
        .U64(accepted.ticket.sequence)
        .U32(static_cast<std::uint32_t>(accepted.result))
        .U32(0);
    if (accepted.result == VN_OK)
        engine->variables.BindMonitorRequest(accepted, request,
            engine->monitorEmitters.CaptureOrigin(0), engine->CurrentProjectId());
    return accepted.result;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

static VnResult SetValuesObserved(const VnVariableBatchDescV1* desc,
                      VnVariableTicketV1* outTicket,
                      const harken::MonitorRequestContext& request) {
    try {
    if (harken::detail::CanonicalSetMutationBlocked()) { return VN_IN_USE; }
    harken::Engine* engine = harken::detail::g_engine;
    if (engine == nullptr) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->callbackFatalSticky) {
        return VN_NOT_INITIALIZED;
    }
    if (engine->runtimeTransportResetActive) {
        return VN_BACKPRESSURE;
    }
    harken::VariableOperationScope variableOperation(engine);
    harken::TraceCallScribe trace =
        TraceStateful(engine, harken::kTraceCallSetValues);
    TraceVariableBatch(trace, desc);
    if (!VariableBatchDescUsable(desc)) {
        harken::VariableAcceptResult refused{};
        refused.result = VN_INVALID_ARG;
        TraceVariableAccept(trace, refused);
        return VN_INVALID_ARG;
    }
    const harken::VariableCallObservation observation =
        ObserveVariableCall(*engine);
    const harken::VariableAcceptResult accepted =
        engine->variables.AcceptGlobalBatch(
            desc->writes, desc->writeCount, observation, engine->params,
            engine->bindings, engine->busTargets);
    TraceVariableAccept(trace, accepted);
    FillVariableTicket(accepted, outTicket);
    if (accepted.result == VN_OK)
        engine->variables.BindMonitorRequest(accepted, request,
            engine->monitorEmitters.CaptureOrigin(0), engine->CurrentProjectId());
    return accepted.result;

    } catch (const std::bad_alloc&) {
        return VN_DEVICE_ERROR;
    } catch (...) {
        return VN_DEVICE_ERROR;
    }}

